import { NavLink } from 'react-router-dom';
import { useNavAccess } from '@/hooks/useNavAccess';
import { useGeneratedPages } from '@/hooks/useGeneratedPages';
import { navGroups } from '@/config/nav';

interface SidebarProps {
  open: boolean;
  onClose: () => void;
}

export default function Sidebar({ open, onClose }: SidebarProps) {
  const { canAccess, isDemo } = useNavAccess();
  // 运行时生成的动态页面:落地后会自动出现在导航中
  const { pages: genPages } = useGeneratedPages();

  return (
    <>
      {open ? (
        <div
          className="fixed inset-0 z-30 bg-foreground-950/40 lg:hidden animate-fade-in"
          onClick={onClose}
          aria-hidden="true"
        />
      ) : null}

      <aside
        className={`fixed inset-y-0 left-0 z-40 w-[248px] flex flex-col bg-background-50 border-r border-background-200 transition-transform duration-300 lg:translate-x-0 ${
          open ? 'translate-x-0' : '-translate-x-full'
        }`}
      >
        <div className="h-16 flex items-center gap-2.5 px-5 border-b border-background-200">
          <div className="w-9 h-9 rounded-lg bg-primary-500 text-background-50 flex items-center justify-center dark:text-foreground-950">
            <i className="ri-flashlight-fill text-lg"></i>
          </div>
          <div className="leading-tight">
            <p className="text-sm font-semibold text-foreground-950">HuaanAdmin</p>
            <p className="text-[11px] text-foreground-500">华安后台框架</p>
          </div>
          {isDemo ? (
            <span className="ml-auto inline-flex items-center gap-1 text-[10px] px-2 py-0.5 rounded-full bg-accent-100 text-accent-900 whitespace-nowrap">
              <i className="ri-eye-line"></i>
              演示
            </span>
          ) : null}
        </div>

        <nav className="flex-1 overflow-y-auto px-3 py-4 space-y-5">
          {navGroups.map((group) => {
            const items = group.items.filter((item) => canAccess(item.permission));
            if (items.length === 0) return null;
            return (
              <div key={group.key}>
                <div className="flex items-center gap-1.5 px-2 mb-1.5">
                  <i className={`${group.icon} text-[13px] text-foreground-400`}></i>
                  <span className="text-[11px] font-medium tracking-wide text-foreground-400">
                    {group.label}
                  </span>
                </div>
                <ul className="space-y-0.5">
                  {items.map((item) => (
                    <li key={item.key}>
                      <NavLink
                        to={item.path}
                        end={item.path === '/'}
                        onClick={onClose}
                        className={({ isActive }) =>
                          `group relative flex items-center gap-2.5 px-2.5 py-2 rounded-md text-sm transition-colors cursor-pointer ${
                            isActive
                              ? 'bg-primary-50 text-primary-700 font-medium'
                              : 'text-foreground-700 hover:bg-background-100'
                          }`
                        }
                      >
                        {({ isActive }) => (
                          <>
                            {isActive ? (
                              <span className="absolute left-0 top-1/2 -translate-y-1/2 w-0.5 h-5 rounded-full bg-primary-500" />
                            ) : null}
                            <i
                              className={`${
                                item.ready ? 'ri-checkbox-blank-circle-line' : 'ri-time-line'
                              } text-[13px] ${isActive ? 'text-primary-600' : 'text-foreground-400'}`}
                            ></i>
                            <span className="flex-1">{item.label}</span>
                            {!item.ready ? (
                              <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-secondary-100 text-secondary-900">
                                规划中
                              </span>
                            ) : null}
                          </>
                        )}
                      </NavLink>
                    </li>
                  ))}
                </ul>
              </div>
            );
          })}

          {genPages.filter((p) => canAccess(p.permission_code ?? '')).length > 0 ? (
            <div>
              <div className="flex items-center gap-1.5 px-2 mb-1.5">
                <i className="ri-sparkling-2-line text-[13px] text-foreground-400"></i>
                <span className="text-[11px] font-medium tracking-wide text-foreground-400">动态页面</span>
              </div>
              <ul className="space-y-0.5">
                {genPages
                  .filter((p) => canAccess(p.permission_code ?? ''))
                  .map((p) => (
                    <li key={p.id}>
                      <NavLink
                        to={`/generated/${p.slug}`}
                        onClick={onClose}
                        className={({ isActive }) =>
                          `group relative flex items-center gap-2.5 px-2.5 py-2 rounded-md text-sm transition-colors cursor-pointer ${
                            isActive
                              ? 'bg-primary-50 text-primary-700 font-medium'
                              : 'text-foreground-700 hover:bg-background-100'
                          }`
                        }
                      >
                        {({ isActive }) => (
                          <>
                            {isActive ? (
                              <span className="absolute left-0 top-1/2 -translate-y-1/2 w-0.5 h-5 rounded-full bg-primary-500" />
                            ) : null}
                            <i
                              className={`${p.icon || 'ri-layout-4-line'} text-[13px] ${
                                isActive ? 'text-primary-600' : 'text-foreground-400'
                              }`}
                            ></i>
                            <span className="flex-1 truncate">{p.title}</span>
                            <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-secondary-100 text-secondary-900 whitespace-nowrap">
                              生成
                            </span>
                          </>
                        )}
                      </NavLink>
                    </li>
                  ))}
              </ul>
            </div>
          ) : null}
        </nav>

        <div className="px-4 py-3 border-t border-background-200">
          <div className="flex items-center gap-2 text-[11px] text-foreground-500">
            <span className="w-1.5 h-1.5 rounded-full bg-primary-500 animate-pulse-soft" />
            <span>系统运行正常</span>
            <span className="ml-auto font-label">v1.0.0</span>
          </div>
        </div>
      </aside>
    </>
  );
}