interface RoleBadge {
  id: string;
  name: string;
  code: string | null;
  description?: string | null;
}

interface PermRow {
  id: string;
  name: string;
  code: string | null;
  type: string;
}

interface PermissionCardProps {
  roles: RoleBadge[];
  permissions: PermRow[];
  isSuper: boolean;
  loading: boolean;
}

const typeMeta: Record<string, { label: string; tone: string; icon: string }> = {
  menu: { label: '菜单权限', tone: 'bg-primary-100 text-primary-800', icon: 'ri-layout-top-line' },
  button: { label: '按钮权限', tone: 'bg-accent-100 text-accent-900', icon: 'ri-cursor-line' },
  api: { label: '接口权限', tone: 'bg-secondary-200 text-secondary-900', icon: 'ri-code-s-slash-line' },
};

export default function PermissionCard({ roles, permissions, isSuper, loading }: PermissionCardProps) {
  const groups = ['menu', 'button', 'api'].map((type) => ({
    type,
    meta: typeMeta[type],
    items: permissions.filter((p) => p.type === type),
  }));

  return (
    <section className="rounded-lg bg-background-50 border border-background-200 p-4 md:p-5">
      <div className="flex items-center justify-between gap-3">
        <div>
          <h3 className="text-sm font-semibold text-foreground-950">我的角色与权限</h3>
          <p className="text-xs text-foreground-500 mt-0.5">
            共 {permissions.length} 项权限资源
            {isSuper ? '(超级管理员拥有全部权限)' : ''}
          </p>
        </div>
        {isSuper ? (
          <span className="inline-flex items-center gap-1 text-[11px] px-2 py-0.5 rounded-full bg-accent-100 text-accent-900">
            <i className="ri-vip-crown-2-line"></i>
            超级管理员
          </span>
        ) : null}
      </div>

      <div className="mt-4">
        <p className="text-xs font-medium text-foreground-700 mb-2">已分配角色</p>
        <div className="flex flex-wrap gap-2">
          {roles.length === 0 ? (
            <span className="text-xs text-foreground-400">暂无角色</span>
          ) : (
            roles.map((r) => (
              <div key={r.id} className="rounded-md border border-background-200 px-3 py-2">
                <div className="flex items-center gap-2">
                  <i className="ri-shield-user-line text-foreground-500"></i>
                  <span className="text-sm text-foreground-900">{r.name}</span>
                  {r.code ? (
                    <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-secondary-100 text-secondary-900 font-label">
                      {r.code}
                    </span>
                  ) : null}
                </div>
                {r.description ? (
                  <p className="mt-0.5 text-[11px] text-foreground-500 line-clamp-1">{r.description}</p>
                ) : null}
              </div>
            ))
          )}
        </div>
      </div>

      <div className="mt-5 space-y-4">
        {loading ? (
          <div className="space-y-3">
            {[0, 1, 2].map((n) => (
              <div key={n} className="h-16 rounded-md bg-background-100 animate-pulse-soft" />
            ))}
          </div>
        ) : (
          groups.map((group) => (
            <div key={group.type}>
              <div className="flex items-center gap-2 mb-2">
                <span className={`w-6 h-6 rounded-md flex items-center justify-center ${group.meta.tone}`}>
                  <i className={`${group.meta.icon} text-xs`}></i>
                </span>
                <span className="text-xs font-medium text-foreground-700">{group.meta.label}</span>
                <span className="text-[11px] text-foreground-400">{group.items.length} 项</span>
              </div>
              {group.items.length === 0 ? (
                <p className="text-[11px] text-foreground-400 pl-8">暂无该项权限</p>
              ) : (
                <div className="flex flex-wrap gap-1.5 pl-8">
                  {group.items.map((p) => (
                    <span
                      key={p.id}
                      className="inline-flex items-center gap-1 text-[11px] px-2 py-0.5 rounded-md bg-background-100 border border-background-200 text-foreground-700"
                      title={p.code ?? ''}
                    >
                      <i className="ri-check-line text-primary-600 text-[10px]"></i>
                      {p.name}
                    </span>
                  ))}
                </div>
              )}
            </div>
          ))
        )}
      </div>
    </section>
  );
}