import { useEffect, useRef, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { useAuth } from '@/contexts/AuthContext';
import { useTenant } from '@/contexts/TenantContext';
import { findNavItemByPath } from '@/config/nav';
import GlobalSearch from '@/components/feature/GlobalSearch';
import NotificationMenu from '@/components/feature/NotificationMenu';
import { recordLogoutLog } from '@/lib/loginLog';

interface TopbarProps {
  onOpenSidebar: () => void;
}

export default function Topbar({ onOpenSidebar }: TopbarProps) {
  const { profile, roleCodes, signOut } = useAuth();
  const { tenants, currentTenantId, currentTenant, setCurrentTenantId } = useTenant();
  const location = useLocation();
  const navigate = useNavigate();
  const [menuOpen, setMenuOpen] = useState(false);
  const [tenantOpen, setTenantOpen] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);
  const tenantRef = useRef<HTMLDivElement>(null);

  const current = findNavItemByPath(location.pathname);

  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
        setMenuOpen(false);
      }
      if (tenantRef.current && !tenantRef.current.contains(e.target as Node)) {
        setTenantOpen(false);
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  const displayName = profile?.full_name || profile?.email || '未登录用户';
  const initials = displayName.slice(0, 1).toUpperCase();
  const primaryRole = roleCodes[0] ?? 'member';

  return (
    <header className="sticky top-0 z-20 h-16 flex items-center gap-3 px-4 md:px-6 bg-background-50/90 backdrop-blur border-b border-background-200">
      <button
        type="button"
        onClick={onOpenSidebar}
        className="lg:hidden w-9 h-9 flex items-center justify-center rounded-md text-foreground-700 hover:bg-background-100 cursor-pointer"
        aria-label="打开菜单"
      >
        <i className="ri-menu-line text-xl"></i>
      </button>

      <div className="min-w-0">
        <h1 className="text-base font-semibold text-foreground-950 truncate">
          {current?.label ?? '工作台'}
        </h1>
        <p className="hidden sm:block text-xs text-foreground-500 truncate">
          华安后台开发框架 · 权限与资源中心
        </p>
      </div>

      <div className="ml-auto flex items-center gap-1.5 md:gap-2">
        <GlobalSearch className="hidden md:block w-56" />

        <div className="relative" ref={tenantRef}>
          <button
            type="button"
            onClick={() => setTenantOpen((v) => !v)}
            className="flex items-center gap-2 h-9 pl-2.5 pr-2 rounded-md bg-background-100 border border-background-200 hover:bg-background-200 cursor-pointer max-w-[180px]"
            title="切换租户"
          >
            <i className="ri-building-2-line text-foreground-500 text-sm"></i>
            <span className="hidden sm:block text-xs text-foreground-800 truncate">
              {currentTenant ? currentTenant.name : '全部租户'}
            </span>
            <i className="ri-arrow-down-s-line text-foreground-400"></i>
          </button>

          {tenantOpen ? (
            <div className="absolute right-0 mt-2 w-64 rounded-lg bg-background-50 border border-background-200 py-1.5 animate-fade-up z-30">
              <p className="px-3 py-1.5 text-[11px] text-foreground-400">选择租户,数据将按租户隔离展示</p>
              <button
                type="button"
                onClick={() => {
                  setCurrentTenantId('all');
                  setTenantOpen(false);
                }}
                className={`w-full flex items-center gap-2 px-3 py-2 text-sm cursor-pointer ${
                  currentTenantId === 'all'
                    ? 'bg-primary-50 text-primary-700'
                    : 'text-foreground-700 hover:bg-background-100'
                }`}
              >
                <i className="ri-apps-2-line"></i>
                全部租户
                {currentTenantId === 'all' ? <i className="ri-check-line ml-auto"></i> : null}
              </button>
              <div className="my-1 border-t border-background-200" />
              <div className="max-h-64 overflow-y-auto">
                {tenants.map((t) => (
                  <button
                    key={t.id}
                    type="button"
                    onClick={() => {
                      setCurrentTenantId(t.id);
                      setTenantOpen(false);
                    }}
                    className={`w-full flex items-center gap-2 px-3 py-2 text-sm cursor-pointer ${
                      currentTenantId === t.id
                        ? 'bg-primary-50 text-primary-700'
                        : 'text-foreground-700 hover:bg-background-100'
                    }`}
                  >
                    <span
                      className={`w-1.5 h-1.5 rounded-full ${
                        t.status === 'active' ? 'bg-primary-500' : 'bg-foreground-400'
                      }`}
                    />
                    <span className="truncate">{t.name}</span>
                    <span className="ml-auto text-[10px] font-label text-foreground-400 uppercase">
                      {t.plan}
                    </span>
                  </button>
                ))}
              </div>
            </div>
          ) : null}
        </div>

        <NotificationMenu />

        <div className="relative" ref={menuRef}>
          <button
            type="button"
            onClick={() => setMenuOpen((v) => !v)}
            className="flex items-center gap-2 h-9 pl-1 pr-2 rounded-md hover:bg-background-100 cursor-pointer"
          >
            <span className="w-7 h-7 rounded-full bg-primary-100 text-primary-700 flex items-center justify-center text-xs font-semibold">
              {initials}
            </span>
            <span className="hidden sm:block text-sm text-foreground-800 max-w-[120px] truncate">
              {displayName}
            </span>
            <i className="ri-arrow-down-s-line text-foreground-400"></i>
          </button>

          {menuOpen ? (
            <div className="absolute right-0 mt-2 w-56 rounded-lg bg-background-50 border border-background-200 py-1.5 animate-fade-up">
              <div className="px-3 py-2">
                <p className="text-sm font-medium text-foreground-950 truncate">{displayName}</p>
                <p className="text-xs text-foreground-500 truncate">{profile?.email}</p>
                <span className="inline-flex mt-1.5 text-[11px] px-2 py-0.5 rounded-full bg-accent-100 text-accent-900 font-label">
                  {primaryRole}
                </span>
              </div>
              <div className="my-1 border-t border-background-200" />
              <button
                type="button"
                onClick={() => {
                  setMenuOpen(false);
                  navigate('/account');
                }}
                className="w-full flex items-center gap-2 px-3 py-2 text-sm text-foreground-700 hover:bg-background-100 cursor-pointer"
              >
                <i className="ri-user-settings-line"></i>
                个人设置
              </button>
              <button
                type="button"
                onClick={async () => {
                  setMenuOpen(false);
                  await recordLogoutLog();
                  await signOut();
                  navigate('/auth');
                }}
                className="w-full flex items-center gap-2 px-3 py-2 text-sm text-foreground-700 hover:bg-background-100 cursor-pointer"
              >
                <i className="ri-logout-box-r-line"></i>
                退出登录
              </button>
            </div>
          ) : null}
        </div>
      </div>
    </header>
  );
}