import { useCallback, useEffect, useRef, useState, type ChangeEvent } from 'react';
import { supabase } from '@/lib/supabase';
import { useAuth } from '@/contexts/AuthContext';

const BUCKET = 'media';
const NAME_PATTERN = /^[a-z0-9][a-z0-9._-]{0,62}$/;

interface MediaFile {
  name: string;
  size: number | null;
  mime: string | null;
  updatedAt: string | null;
  signedUrl: string | null;
}

function isImage(file: MediaFile) {
  if (file.mime?.startsWith('image/')) return true;
  return /\.(png|jpe?g|gif|webp|svg|avif)$/i.test(file.name);
}

function formatSize(bytes: number | null) {
  if (!bytes) return '—';
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / 1024 / 1024).toFixed(2)} MB`;
}

export default function MediaLibraryPage() {
  const { hasPermission } = useAuth();
  const canManage = hasPermission('media:manage');

  const [files, setFiles] = useState<MediaFile[]>([]);
  const [loading, setLoading] = useState(true);
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const [preview, setPreview] = useState<MediaFile | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const { data, error: err } = await supabase.storage.from(BUCKET).list('', {
        limit: 100,
        sortBy: { column: 'name', order: 'asc' },
      });
      if (err) throw err;
      const entries = (data ?? []).filter((f) => f.name && !f.name.endsWith('/'));
      const withUrls: MediaFile[] = await Promise.all(
        entries.map(async (f) => {
          const { data: signed } = await supabase.storage.from(BUCKET).createSignedUrl(f.name, 3600);
          return {
            name: f.name,
            size: (f.metadata?.size as number) ?? null,
            mime: (f.metadata?.mimetype as string) ?? null,
            updatedAt: (f.updated_at as string) ?? null,
            signedUrl: signed?.signedUrl ?? null,
          };
        }),
      );
      setFiles(withUrls);
    } catch (err) {
      console.error(err);
      setError('加载媒体库失败,请重试');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  useEffect(() => {
    if (!notice) return;
    const timer = setTimeout(() => setNotice(''), 2600);
    return () => clearTimeout(timer);
  }, [notice]);

  const totalSize = files.reduce((sum, f) => sum + (f.size ?? 0), 0);

  const handleUpload = async (e: ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const name = file.name.toLowerCase();
    if (!NAME_PATTERN.test(name)) {
      setError('文件名需为 1-63 位小写字母或数字,可含 . _ -,请重命名后再上传(不支持中文/空格/大写)');
      if (inputRef.current) inputRef.current.value = '';
      return;
    }
    setUploading(true);
    setError('');
    try {
      const { error: err } = await supabase.storage
        .from(BUCKET)
        .upload(name, file, { upsert: false, contentType: file.type || undefined });
      if (err) throw err;
      setNotice(`已上传 ${name}`);
      await load();
    } catch (err) {
      console.error(err);
      setError('上传失败,可能文件已存在或无权限');
    } finally {
      setUploading(false);
      if (inputRef.current) inputRef.current.value = '';
    }
  };

  const handleDelete = async (file: MediaFile) => {
    try {
      const { error: err } = await supabase.storage.from(BUCKET).remove([file.name]);
      if (err) throw err;
      setNotice(`已删除 ${file.name}`);
      setPreview(null);
      await load();
    } catch (err) {
      console.error(err);
      setError('删除失败,可能权限不足');
    }
  };

  const copyLink = async (file: MediaFile) => {
    if (!file.signedUrl) return;
    try {
      await navigator.clipboard.writeText(file.signedUrl);
      setNotice('已复制临时访问链接(1 小时有效)');
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div className="space-y-4">
      <div className="flex flex-col md:flex-row md:items-center gap-3">
        <div>
          <h2 className="text-lg font-semibold text-foreground-950">媒体库</h2>
          <p className="text-sm text-foreground-500 mt-0.5">
            统一管理上传的图片与文件,支持预览、复制访问链接与删除
          </p>
        </div>
        <div className="md:ml-auto flex items-center gap-2">
          <span className="text-xs text-foreground-500 whitespace-nowrap">
            {files.length} 个文件 · {formatSize(totalSize)}
          </span>
          <button
            type="button"
            onClick={() => inputRef.current?.click()}
            disabled={!canManage || uploading}
            className="h-9 px-3.5 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 disabled:opacity-50 cursor-pointer whitespace-nowrap flex items-center gap-1.5 dark:text-foreground-950"
          >
            <i className="ri-upload-cloud-2-line"></i>
            {uploading ? '上传中…' : '上传文件'}
          </button>
          <input
            ref={inputRef}
            type="file"
            onChange={handleUpload}
            className="hidden"
            accept="image/*,.pdf,.txt,.csv,.json,.zip"
          />
        </div>
      </div>

      {notice ? (
        <div className="flex items-center gap-2 px-3 py-2.5 rounded-md bg-primary-50 text-primary-800 text-sm animate-fade-up">
          <i className="ri-checkbox-circle-line"></i>
          {notice}
        </div>
      ) : null}
      {error ? (
        <div className="flex items-center justify-between gap-3 px-3 py-2.5 rounded-md bg-accent-100 text-accent-900 text-sm">
          {error}
          <button type="button" onClick={load} className="text-xs underline cursor-pointer whitespace-nowrap">
            重试
          </button>
        </div>
      ) : null}

      {loading ? (
        <div className="grid grid-cols-2 md:grid-cols-4 xl:grid-cols-6 gap-3">
          {[0, 1, 2, 3, 4, 5].map((n) => (
            <div key={n} className="h-32 rounded-lg bg-background-50 border border-background-200 animate-pulse-soft" />
          ))}
        </div>
      ) : files.length === 0 ? (
        <div className="rounded-lg bg-background-50 border border-background-200 py-20 text-center text-foreground-500">
          <i className="ri-image-add-line text-3xl block mb-2"></i>
          还没有媒体文件,点击右上角上传
        </div>
      ) : (
        <div className="grid grid-cols-2 md:grid-cols-4 xl:grid-cols-6 gap-3">
          {files.map((file) => (
            <div key={file.name} className="rounded-lg bg-background-50 border border-background-200 overflow-hidden group">
              <button
                type="button"
                onClick={() => setPreview(file)}
                className="block w-full h-28 bg-background-100 overflow-hidden cursor-pointer"
              >
                {isImage(file) && file.signedUrl ? (
                  <img
                    src={file.signedUrl}
                    alt={file.name}
                    title={`${file.name} 媒体预览`}
                    className="w-full h-full object-cover object-top"
                  />
                ) : (
                  <span className="w-full h-full flex items-center justify-center text-foreground-400">
                    <i className="ri-file-3-line text-2xl"></i>
                  </span>
                )}
              </button>
              <div className="p-2">
                <p className="text-xs text-foreground-900 truncate" title={file.name}>
                  {file.name}
                </p>
                <p className="text-[10px] text-foreground-400 mt-0.5">{formatSize(file.size)}</p>
                <div className="flex items-center gap-1 mt-1.5">
                  <button
                    type="button"
                    onClick={() => copyLink(file)}
                    title="复制链接"
                    className="flex-1 h-7 rounded-md bg-background-100 text-foreground-600 hover:bg-background-200 cursor-pointer flex items-center justify-center gap-1 text-[11px]"
                  >
                    <i className="ri-link"></i>
                  </button>
                  <button
                    type="button"
                    onClick={() => handleDelete(file)}
                    disabled={!canManage}
                    title="删除"
                    className="w-7 h-7 rounded-md text-foreground-500 hover:bg-secondary-200 hover:text-secondary-900 disabled:opacity-40 cursor-pointer flex items-center justify-center"
                  >
                    <i className="ri-delete-bin-line text-xs"></i>
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {preview ? (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-foreground-950/50 animate-fade-in" onClick={() => setPreview(null)} aria-hidden="true" />
          <div className="relative w-full max-w-3xl rounded-lg bg-background-50 border border-background-200 animate-fade-up">
            <div className="flex items-center justify-between gap-3 px-5 py-3.5 border-b border-background-200">
              <div className="min-w-0">
                <p className="text-sm font-medium text-foreground-950 truncate">{preview.name}</p>
                <p className="text-[11px] text-foreground-500">{formatSize(preview.size)}</p>
              </div>
              <button
                type="button"
                onClick={() => setPreview(null)}
                className="w-8 h-8 flex items-center justify-center rounded-md text-foreground-500 hover:bg-background-100 cursor-pointer"
              >
                <i className="ri-close-line text-lg"></i>
              </button>
            </div>
            <div className="p-4 flex items-center justify-center bg-background-100 max-h-[60vh] overflow-auto">
              {isImage(preview) && preview.signedUrl ? (
                <img src={preview.signedUrl} alt={preview.name} className="max-h-[56vh] object-contain" />
              ) : (
                <div className="py-16 text-center text-foreground-500">
                  <i className="ri-file-3-line text-4xl block mb-2"></i>
                  该类型文件暂不支持预览
                </div>
              )}
            </div>
            <div className="flex items-center justify-end gap-2 px-5 py-3.5 border-t border-background-200">
              <button
                type="button"
                onClick={() => copyLink(preview)}
                className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
              >
                复制链接
              </button>
              <button
                type="button"
                onClick={() => handleDelete(preview)}
                disabled={!canManage}
                className="h-9 px-4 rounded-md bg-secondary-700 text-background-50 text-sm hover:bg-secondary-800 disabled:opacity-50 cursor-pointer whitespace-nowrap"
              >
                删除
              </button>
            </div>
          </div>
        </div>
      ) : null}
    </div>
  );
}