import type { PluginRow } from '@/pages/plugins/types';

interface PluginCardProps {
  plugin: PluginRow;
  installedMap: Record<string, PluginRow>;
  canManage: boolean;
  busy: boolean;
  onToggle: (plugin: PluginRow) => void;
  onDetail: (plugin: PluginRow) => void;
  onTemplate: (plugin: PluginRow) => void;
  onUpdate: (plugin: PluginRow) => void;
  onDelete: (plugin: PluginRow) => void;
}

const categoryTone: Record<string, string> = {
  开发工具: 'bg-primary-100 text-primary-800',
  国际化: 'bg-accent-100 text-accent-900',
  运维: 'bg-secondary-200 text-secondary-900',
  安全: 'bg-secondary-200 text-secondary-900',
  流程: 'bg-primary-100 text-primary-800',
  数据: 'bg-accent-100 text-accent-900',
  存储: 'bg-primary-100 text-primary-800',
  通讯: 'bg-accent-100 text-accent-900',
};

export default function PluginCard({
  plugin,
  installedMap,
  canManage,
  busy,
  onToggle,
  onDetail,
  onTemplate,
  onUpdate,
  onDelete,
}: PluginCardProps) {
  const deps = plugin.dependencies ?? [];
  const enabled = Boolean(plugin.enabled);
  const tone = categoryTone[plugin.category ?? ''] ?? 'bg-background-200 text-foreground-700';

  return (
    <article className="flex flex-col rounded-lg bg-background-50 border border-background-200 p-4 md:p-5">
      <div className="flex items-start gap-3">
        <div className="w-11 h-11 rounded-lg bg-primary-100 text-primary-700 flex items-center justify-center shrink-0">
          <i className="ri-plug-2-line text-xl"></i>
        </div>
        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-2">
            <h3 className="text-sm font-semibold text-foreground-950 truncate">{plugin.name}</h3>
            {plugin.has_update ? (
              <span className="shrink-0 inline-flex items-center gap-1 text-[10px] px-1.5 py-0.5 rounded-full bg-accent-100 text-accent-900">
                <i className="ri-arrow-up-circle-line"></i>
                可更新
              </span>
            ) : null}
          </div>
          <div className="mt-0.5 flex items-center gap-2 text-[11px] text-foreground-500">
            <span className="font-label">{plugin.code}</span>
            <span>·</span>
            <span className="font-label">v{plugin.version}</span>
          </div>
        </div>
        <span className={`shrink-0 text-[10px] px-2 py-0.5 rounded-full ${tone}`}>{plugin.category}</span>
      </div>

      <p className="mt-3 text-xs text-foreground-600 leading-relaxed line-clamp-2 min-h-[32px]">
        {plugin.description || '暂无描述'}
      </p>

      <div className="mt-3 flex flex-wrap items-center gap-x-4 gap-y-1.5 text-[11px] text-foreground-500">
        <span className="inline-flex items-center gap-1">
          <i className="ri-user-3-line"></i>
          {plugin.author}
        </span>
        <span className="inline-flex items-center gap-1">
          <i className="ri-download-2-line"></i>
          {(plugin.downloads ?? 0).toLocaleString()}
        </span>
        <span className="inline-flex items-center gap-1">
          <i className="ri-link"></i>
          {deps.length} 依赖
        </span>
      </div>

      {deps.length > 0 ? (
        <div className="mt-2.5 flex flex-wrap gap-1.5">
          {deps.map((d) => {
            const target = installedMap[d.code];
            const satisfied = target && target.enabled;
            return (
              <span
                key={d.code}
                title={`${d.name} ${d.version}${d.required ? '(必需)' : '(可选)'}`}
                className={`inline-flex items-center gap-1 text-[10px] px-1.5 py-0.5 rounded-md border ${
                  satisfied
                    ? 'bg-background-100 border-background-200 text-foreground-700'
                    : 'bg-accent-100 border-accent-200 text-accent-900'
                }`}
              >
                <i className={satisfied ? 'ri-check-line' : 'ri-error-warning-line'}></i>
                {d.name}
                {d.required ? <span className="text-accent-700">*</span> : null}
              </span>
            );
          })}
        </div>
      ) : null}

      <div className="mt-4 pt-3.5 border-t border-background-200 flex items-center gap-1.5">
        <button
          type="button"
          onClick={() => onDetail(plugin)}
          className="h-8 px-2.5 rounded-md bg-background-100 border border-background-300 text-xs text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap inline-flex items-center gap-1"
        >
          <i className="ri-information-line"></i>
          详情
        </button>
        <button
          type="button"
          onClick={() => onTemplate(plugin)}
          className="h-8 px-2.5 rounded-md bg-background-100 border border-background-300 text-xs text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap inline-flex items-center gap-1"
        >
          <i className="ri-file-code-line"></i>
          模板
        </button>
        {plugin.has_update ? (
          <button
            type="button"
            onClick={() => onUpdate(plugin)}
            disabled={!canManage}
            className="h-8 px-2.5 rounded-md bg-accent-500 text-background-50 text-xs hover:bg-accent-600 disabled:opacity-50 cursor-pointer whitespace-nowrap inline-flex items-center gap-1"
          >
            <i className="ri-refresh-line"></i>
            热更新
          </button>
        ) : null}

        <button
          type="button"
          onClick={() => onDelete(plugin)}
          disabled={!canManage}
          title="删除插件"
          className="w-8 h-8 flex items-center justify-center rounded-md text-foreground-500 hover:bg-secondary-200 hover:text-secondary-900 disabled:opacity-40 cursor-pointer"
        >
          <i className="ri-delete-bin-line"></i>
        </button>

        <button
          type="button"
          onClick={() => onToggle(plugin)}
          disabled={!canManage || busy}
          className={`ml-auto inline-flex items-center gap-1.5 h-8 pl-2 pr-2.5 rounded-full text-xs cursor-pointer whitespace-nowrap disabled:opacity-50 ${
            enabled
              ? 'bg-primary-100 text-primary-800'
              : 'bg-background-200 text-foreground-600'
          }`}
        >
          <span className="relative w-8 h-4 rounded-full transition-colors" style={{ backgroundColor: 'transparent' }}>
            <span
              className={`absolute inset-0 rounded-full ${enabled ? 'bg-primary-500' : 'bg-background-400'}`}
            />
            <span
              className={`absolute top-0.5 w-3 h-3 rounded-full bg-background-50 transition-all ${
                enabled ? 'left-4' : 'left-0.5'
              }`}
            />
          </span>
          {busy ? '处理中' : enabled ? '已启用' : '已停用'}
        </button>
      </div>
    </article>
  );
}