import { useEffect, useMemo, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useNavAccess } from '@/hooks/useNavAccess';
import { navGroups } from '@/config/nav';

interface GlobalSearchProps {
  /** 移动端隐藏,交给顶部其它入口 */
  className?: string;
}

export default function GlobalSearch({ className = '' }: GlobalSearchProps) {
  const { canAccess } = useNavAccess();
  const navigate = useNavigate();
  const [keyword, setKeyword] = useState('');
  const [open, setOpen] = useState(false);
  const wrapRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const accessible = useMemo(
    () =>
      navGroups.flatMap((group) =>
        group.items
          .filter((item) => canAccess(item.permission))
          .map((item) => ({ ...item, groupKey: group.key, groupLabel: group.label })),
      ),
    [canAccess],
  );

  const results = useMemo(() => {
    const kw = keyword.trim().toLowerCase();
    if (!kw) return accessible;
    return accessible.filter(
      (item) => item.label.toLowerCase().includes(kw) || item.path.toLowerCase().includes(kw),
    );
  }, [accessible, keyword]);

  useEffect(() => {
    const onClick = (e: MouseEvent) => {
      if (wrapRef.current && !wrapRef.current.contains(e.target as Node)) setOpen(false);
    };
    const onKey = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') {
        e.preventDefault();
        inputRef.current?.focus();
        setOpen(true);
      }
      if (e.key === 'Escape') setOpen(false);
    };
    document.addEventListener('mousedown', onClick);
    document.addEventListener('keydown', onKey);
    return () => {
      document.removeEventListener('mousedown', onClick);
      document.removeEventListener('keydown', onKey);
    };
  }, []);

  const go = (path: string) => {
    setOpen(false);
    setKeyword('');
    navigate(path);
  };

  return (
    <div className={`relative ${className}`} ref={wrapRef}>
      <div className="flex items-center gap-2 h-9 pl-3 pr-2 rounded-md bg-background-100 border border-background-200 w-full">
        <i className="ri-search-line text-foreground-400 text-sm"></i>
        <input
          ref={inputRef}
          type="text"
          value={keyword}
          onChange={(e) => {
            setKeyword(e.target.value);
            setOpen(true);
          }}
          onFocus={() => setOpen(true)}
          placeholder="搜索菜单 / 功能…"
          className="flex-1 bg-transparent text-sm text-foreground-900 placeholder:text-foreground-400 focus:outline-none"
        />
        <span className="font-label text-[10px] text-foreground-400 border border-background-300 rounded px-1 py-0.5">
          ⌘K
        </span>
      </div>

      {open ? (
        <div className="absolute left-0 right-0 mt-2 rounded-lg bg-background-50 border border-background-200 py-1.5 animate-fade-up z-30 max-h-80 overflow-y-auto">
          {results.length === 0 ? (
            <p className="px-3 py-3 text-sm text-foreground-500">没有匹配的功能</p>
          ) : (
            results.map((item) => (
              <button
                key={item.key}
                type="button"
                onClick={() => go(item.path)}
                className="w-full flex items-center gap-2.5 px-3 py-2 text-left hover:bg-background-100 cursor-pointer"
              >
                <span className="w-7 h-7 rounded-md bg-background-100 text-foreground-600 flex items-center justify-center">
                  <i className="ri-window-2-line text-sm"></i>
                </span>
                <span className="min-w-0 flex-1">
                  <span className="block text-sm text-foreground-900 truncate">{item.label}</span>
                  <span className="block text-[11px] text-foreground-500 font-label truncate">{item.path}</span>
                </span>
                <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-secondary-100 text-secondary-900 whitespace-nowrap">
                  {item.groupLabel}
                </span>
              </button>
            ))
          )}
        </div>
      ) : null}
    </div>
  );
}