import LineChart from '@/pages/dashboard/components/LineChart';

interface MetricCardProps {
  label: string;
  value: string;
  unit: string;
  change: number;
  icon: string;
  tone: string;
  color: string;
  data: number[];
  lowerIsBetter?: boolean;
  minValue?: number;
}

export default function MetricCard({
  label,
  value,
  unit,
  change,
  icon,
  tone,
  color,
  data,
  lowerIsBetter = false,
  minValue,
}: MetricCardProps) {
  const isGood = lowerIsBetter ? change <= 0 : change >= 0;
  const deltaTone = isGood ? 'text-primary-700' : 'text-secondary-800';
  const deltaIcon = change >= 0 ? 'ri-arrow-up-line' : 'ri-arrow-down-line';

  return (
    <div className="rounded-lg bg-background-50 border border-background-200 p-4">
      <div className="flex items-center justify-between gap-2">
        <span className={`w-9 h-9 rounded-md flex items-center justify-center ${tone}`}>
          <i className={`${icon} text-lg`}></i>
        </span>
        <span className={`inline-flex items-center gap-0.5 text-[11px] font-label ${deltaTone}`}>
          <i className={deltaIcon}></i>
          {Math.abs(change).toFixed(1)}%
        </span>
      </div>
      <p className="mt-3 text-xl font-semibold text-foreground-950 font-heading tabular-nums">
        {value}
        <span className="ml-1 text-xs font-normal text-foreground-500">{unit}</span>
      </p>
      <p className="mt-0.5 text-xs text-foreground-500">{label}</p>
      <div className="mt-2 -mb-1">
        <LineChart series={[{ name: label, color, data }]} height={46} minValue={minValue} />
      </div>
    </div>
  );
}