import { useState } from 'react';
import { buildCurl, methodStyle, type EndpointDef } from '@/pages/api-docs/types';
import TryItOutPanel from '@/pages/api-docs/components/TryItOutPanel';

interface EndpointDetailProps {
  endpoint: EndpointDef | null;
}

function CodeBlock({ code, label }: { code: string; label: string }) {
  const [copied, setCopied] = useState(false);
  const copy = async () => {
    try {
      await navigator.clipboard.writeText(code);
      setCopied(true);
      setTimeout(() => setCopied(false), 1600);
    } catch (err) {
      console.error(err);
    }
  };
  return (
    <div className="rounded-md border border-background-200 overflow-hidden">
      <div className="flex items-center justify-between px-3 py-1.5 bg-background-100 border-b border-background-200">
        <span className="text-[11px] font-medium text-foreground-500">{label}</span>
        <button
          type="button"
          onClick={copy}
          className="inline-flex items-center gap-1 text-[11px] text-foreground-600 hover:text-foreground-900 cursor-pointer whitespace-nowrap"
        >
          <i className={copied ? 'ri-check-line' : 'ri-file-copy-line'}></i>
          {copied ? '已复制' : '复制'}
        </button>
      </div>
      <pre className="px-3 py-3 text-xs leading-relaxed font-label text-foreground-800 bg-background-50 overflow-x-auto">
        {code}
      </pre>
    </div>
  );
}

export default function EndpointDetail({ endpoint }: EndpointDetailProps) {
  const [tryOpen, setTryOpen] = useState(false);

  if (!endpoint) {
    return (
      <div className="rounded-lg bg-background-50 border border-background-200 flex items-center justify-center min-h-[420px] text-foreground-500">
        <div className="text-center">
          <i className="ri-code-box-line text-3xl block mb-2"></i>
          <p className="text-sm">从左侧选择一个接口查看详情</p>
        </div>
      </div>
    );
  }

  return (
    <div className="rounded-lg bg-background-50 border border-background-200 max-h-[calc(100vh-190px)] overflow-y-auto">
      <div className="p-4 md:p-5 border-b border-background-200">
        <div className="flex items-center gap-2 flex-wrap">
          <span className={`text-xs font-label px-2 py-0.5 rounded ${methodStyle[endpoint.method]}`}>
            {endpoint.method}
          </span>
          <span className="text-sm font-label text-foreground-900 break-all">{endpoint.path}</span>
        </div>
        <h3 className="mt-2 text-base font-semibold text-foreground-950">{endpoint.summary}</h3>
        <p className="mt-1 text-xs text-foreground-500">
          权限码 <span className="font-label text-foreground-700">{endpoint.code}</span>
        </p>
        <div className="mt-3 flex flex-wrap items-center gap-2">
          <span className="inline-flex items-center gap-1 text-[11px] px-2 py-0.5 rounded-full bg-background-100 text-foreground-700">
            <i className="ri-shield-check-line"></i>
            返回 {endpoint.statusCode}
          </span>
          <span
            className={`inline-flex items-center gap-1 text-[11px] px-2 py-0.5 rounded-full ${
              endpoint.auth ? 'bg-accent-100 text-accent-900' : 'bg-primary-100 text-primary-800'
            }`}
          >
            <i className={endpoint.auth ? 'ri-lock-line' : 'ri-lock-unlock-line'}></i>
            {endpoint.auth ? '需要 Bearer Token' : '公开接口'}
          </span>
          <span className="inline-flex items-center gap-1 text-[11px] px-2 py-0.5 rounded-full bg-secondary-100 text-secondary-900">
            <i className="ri-price-tag-3-line"></i>
            {endpoint.moduleLabel}
          </span>
          <button
            type="button"
            onClick={() => setTryOpen((v) => !v)}
            className="ml-auto inline-flex items-center gap-1.5 h-7 px-3 rounded-full text-[11px] bg-primary-500 text-background-50 hover:bg-primary-600 cursor-pointer whitespace-nowrap dark:text-foreground-950"
          >
            <i className={tryOpen ? 'ri-close-line' : 'ri-terminal-box-line'}></i>
            {tryOpen ? '关闭调试' : '在线调试'}
          </button>
        </div>
      </div>

      <div className="p-4 md:p-5 space-y-5">
        <section>
          <h4 className="text-sm font-semibold text-foreground-950 mb-2.5">请求参数</h4>
          {endpoint.params.length === 0 ? (
            <p className="text-xs text-foreground-500">无需请求参数</p>
          ) : (
            <div className="rounded-md border border-background-200 overflow-hidden">
              <table className="w-full text-left">
                <thead className="bg-background-100">
                  <tr className="text-[11px] text-foreground-500">
                    <th className="px-3 py-2 font-medium">参数</th>
                    <th className="px-3 py-2 font-medium">位置</th>
                    <th className="px-3 py-2 font-medium">类型</th>
                    <th className="px-3 py-2 font-medium">必填</th>
                    <th className="px-3 py-2 font-medium">说明</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-background-200">
                  {endpoint.params.map((p) => (
                    <tr key={`${p.in}-${p.name}`} className="text-xs">
                      <td className="px-3 py-2 font-label text-foreground-900">{p.name}</td>
                      <td className="px-3 py-2 text-foreground-600">{p.in === 'path' ? '路径' : '查询'}</td>
                      <td className="px-3 py-2 text-foreground-600 font-label">{p.type}</td>
                      <td className="px-3 py-2">
                        <span className={p.required ? 'text-secondary-800' : 'text-foreground-500'}>
                          {p.required ? '是' : '否'}
                        </span>
                      </td>
                      <td className="px-3 py-2 text-foreground-600">{p.description}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </section>

        <section className="space-y-2.5">
          <h4 className="text-sm font-semibold text-foreground-950">请求示例</h4>
          {endpoint.requestBody ? (
            <CodeBlock label="Request Body" code={JSON.stringify(endpoint.requestBody, null, 2)} />
          ) : null}
          <CodeBlock label="cURL" code={buildCurl(endpoint)} />
        </section>

        <section>
          <h4 className="text-sm font-semibold text-foreground-950 mb-2.5">响应示例</h4>
          <CodeBlock label={`Response · ${endpoint.statusCode}`} code={JSON.stringify(endpoint.responseBody, null, 2)} />
        </section>

        {tryOpen ? <TryItOutPanel endpoint={endpoint} /> : null}
      </div>
    </div>
  );
}