/**
 * Resolve a StyleSystem oklch channel token (e.g. --primary-500) into a
 * concrete CSS color string that canvas 2D can parse.
 */
export function cssVar(name: string, fallback = '#6b7280'): string {
  if (typeof window === 'undefined') return fallback;
  const raw = getComputedStyle(document.documentElement).getPropertyValue(name).trim();
  return raw ? `oklch(${raw})` : fallback;
}

/** Add an alpha channel to an oklch(color) string produced by cssVar. */
export function withAlpha(color: string, alpha: number): string {
  if (color.startsWith('oklch(')) {
    return color.replace(')', ` / ${alpha})`);
  }
  return color;
}