import { supabase } from '@/lib/supabase';

export interface DepartmentRow {
  id: string;
  name: string;
  code: string | null;
  parent_id: string | null;
  tenant_id: string | null;
  leader: string | null;
  status: string | null;
  sort_order: number | null;
  created_at: string | null;
}

export interface DeptNode extends DepartmentRow {
  children: DeptNode[];
  depth: number;
}

export async function fetchDepartments(): Promise<DepartmentRow[]> {
  const { data, error } = await supabase
    .from('departments')
    .select('*')
    .order('sort_order', { ascending: true })
    .order('created_at', { ascending: true });
  if (error) throw error;
  return (data as DepartmentRow[]) ?? [];
}

export function buildDeptTree(rows: DepartmentRow[]): DeptNode[] {
  const map = new Map<string, DeptNode>();
  rows.forEach((r) => map.set(r.id, { ...r, children: [], depth: 0 }));

  const roots: DeptNode[] = [];
  map.forEach((node) => {
    if (node.parent_id && map.has(node.parent_id)) {
      map.get(node.parent_id)!.children.push(node);
    } else {
      roots.push(node);
    }
  });

  const sortNodes = (nodes: DeptNode[], depth: number) => {
    nodes.sort(
      (a, b) => (a.sort_order ?? 0) - (b.sort_order ?? 0) || a.name.localeCompare(b.name),
    );
    nodes.forEach((n) => {
      n.depth = depth;
      sortNodes(n.children, depth + 1);
    });
  };
  sortNodes(roots, 0);
  return roots;
}

export function flattenDeptTree(nodes: DeptNode[]): DeptNode[] {
  const out: DeptNode[] = [];
  const walk = (list: DeptNode[]) => {
    list.forEach((n) => {
      out.push(n);
      walk(n.children);
    });
  };
  walk(nodes);
  return out;
}

/** Collect a department id together with every descendant department id. */
export function collectDescendantIds(rows: DepartmentRow[], rootId: string): string[] {
  const childrenMap = new Map<string, string[]>();
  rows.forEach((r) => {
    if (r.parent_id) {
      const arr = childrenMap.get(r.parent_id) ?? [];
      arr.push(r.id);
      childrenMap.set(r.parent_id, arr);
    }
  });

  const result: string[] = [];
  const seen = new Set<string>();
  const stack = [rootId];
  while (stack.length > 0) {
    const cur = stack.pop() as string;
    if (seen.has(cur)) continue;
    seen.add(cur);
    result.push(cur);
    (childrenMap.get(cur) ?? []).forEach((child) => stack.push(child));
  }
  return result;
}

/** Build an "id -> full label" map where nested names are indented for select options. */
export function buildDeptLabelMap(nodes: DeptNode[]): Map<string, string> {
  const map = new Map<string, string>();
  const walk = (list: DeptNode[]) => {
    list.forEach((n) => {
      map.set(n.id, n.name);
      walk(n.children);
    });
  };
  walk(nodes);
  return map;
}

/** Find a node anywhere in the tree by its id. */
export function findNodeById(nodes: DeptNode[], id: string): DeptNode | null {
  for (const n of nodes) {
    if (n.id === id) return n;
    const found = findNodeById(n.children, id);
    if (found) return found;
  }
  return null;
}

/** Walk up the parent chain and return every ancestor id (nearest first). */
export function getAncestorIds(rows: DepartmentRow[], id: string): string[] {
  const parentMap = new Map<string, string | null>();
  rows.forEach((r) => parentMap.set(r.id, r.parent_id ?? null));
  const out: string[] = [];
  let cur = parentMap.get(id) ?? null;
  let guard = 0;
  while (cur && guard < 100) {
    out.push(cur);
    cur = parentMap.get(cur) ?? null;
    guard += 1;
  }
  return out;
}

export interface SiblingReorderUpdate {
  id: string;
  parent_id: string | null;
  sort_order: number;
}

/**
 * Plan a sibling reorder: drop `dragId` before/after `targetId` among the
 * siblings that share the target's parent. Returns normalized sort_order
 * updates (spaced by 10) for every affected sibling.
 */
export function planSiblingReorder(
  rows: DepartmentRow[],
  dragId: string,
  targetId: string,
  position: 'before' | 'after',
): SiblingReorderUpdate[] {
  const drag = rows.find((r) => r.id === dragId);
  const target = rows.find((r) => r.id === targetId);
  if (!drag || !target || dragId === targetId) return [];

  const parentId = target.parent_id ?? null;

  const siblings = rows
    .filter((r) => (r.parent_id ?? null) === parentId && r.id !== dragId)
    .sort((a, b) => (a.sort_order ?? 0) - (b.sort_order ?? 0) || a.name.localeCompare(b.name));

  const idx = siblings.findIndex((r) => r.id === targetId);
  if (idx < 0) return [];

  const ordered: DepartmentRow[] = [...siblings];
  ordered.splice(position === 'before' ? idx : idx + 1, 0, { ...drag, parent_id: parentId });

  return ordered.map((r, i) => ({ id: r.id, parent_id: parentId, sort_order: (i + 1) * 10 }));
}