import { useState } from 'react';
import { Outlet, useNavigate } from 'react-router-dom';
import Sidebar from '@/components/feature/Sidebar';
import Topbar from '@/components/feature/Topbar';
import OnboardingGuide from '@/components/feature/OnboardingGuide';
import { useAuth } from '@/contexts/AuthContext';
import { useSchedulerHeartbeat } from '@/hooks/useSchedulerHeartbeat';

export default function AdminLayout() {
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const { isReadOnly, signOut } = useAuth();
  const navigate = useNavigate();

  // 后台心跳:控制台打开期间,定时任务到点自动触发
  useSchedulerHeartbeat();

  const handleLeaveDemo = async () => {
    await signOut();
    navigate('/auth');
  };

  return (
    <div className="min-h-screen bg-background-100">
      <Sidebar open={sidebarOpen} onClose={() => setSidebarOpen(false)} />
      <div className="lg:pl-[248px] flex flex-col min-h-screen">
        <Topbar onOpenSidebar={() => setSidebarOpen(true)} />
        {isReadOnly ? (
          <div className="sticky top-16 z-10 flex flex-wrap items-center gap-x-3 gap-y-1.5 px-4 md:px-6 py-2.5 bg-accent-100 border-b border-accent-300/70">
            <span className="w-6 h-6 rounded-full bg-accent-500 text-background-50 flex items-center justify-center shrink-0 dark:text-foreground-950">
              <i className="ri-eye-line text-xs"></i>
            </span>
            <p className="text-xs text-accent-900 leading-relaxed">
              <span className="font-medium">只读演示模式</span>
              · 你正在浏览完整后台的全部菜单,可以自由查看数据,但无法新增、修改或删除内容。
            </p>
            <button
              type="button"
              onClick={handleLeaveDemo}
              className="ml-auto h-7 px-3 rounded-md bg-background-50 border border-accent-300 text-xs text-accent-900 hover:bg-background-100 cursor-pointer whitespace-nowrap flex items-center gap-1.5"
            >
              <i className="ri-logout-box-r-line"></i>
              退出并注册正式账号
            </button>
          </div>
        ) : null}
        <main className="flex-1 px-4 md:px-6 py-5 md:py-6">
          <div className="mx-auto w-full max-w-[1400px] animate-fade-up">
            <Outlet />
          </div>
        </main>
      </div>
      <OnboardingGuide />
    </div>
  );
}