import { useEffect, useState } from 'react';
import Modal from '@/components/base/Modal';
import type { TenantRow } from '@/contexts/TenantContext';

export const planMeta: Record<string, { label: string; tone: string }> = {
  trial: { label: '试用版', tone: 'bg-secondary-100 text-secondary-900' },
  standard: { label: '标准版', tone: 'bg-background-200 text-foreground-700' },
  pro: { label: '专业版', tone: 'bg-primary-100 text-primary-800' },
  enterprise: { label: '企业版', tone: 'bg-accent-100 text-accent-900' },
};

export const planOptions = ['trial', 'standard', 'pro', 'enterprise'];

export interface TenantFormValues {
  name: string;
  code: string;
  plan: string;
  status: string;
  seats: number;
  owner: string;
  contact_email: string;
  expires_at: string;
  storage_quota_gb: number;
  api_quota: number;
}

interface TenantFormModalProps {
  open: boolean;
  editing: boolean;
  initial: TenantFormValues | null;
  saving: boolean;
  onClose: () => void;
  onSubmit: (values: TenantFormValues) => void;
}

const blank: TenantFormValues = {
  name: '',
  code: '',
  plan: 'standard',
  status: 'active',
  seats: 10,
  owner: '',
  contact_email: '',
  expires_at: '',
  storage_quota_gb: 50,
  api_quota: 100000,
};

export default function TenantFormModal({
  open,
  editing,
  initial,
  saving,
  onClose,
  onSubmit,
}: TenantFormModalProps) {
  const [values, setValues] = useState<TenantFormValues>(blank);
  const [error, setError] = useState('');

  useEffect(() => {
    if (open) {
      setValues(initial ?? blank);
      setError('');
    }
  }, [open, initial]);

  const set = <K extends keyof TenantFormValues>(key: K, value: TenantFormValues[K]) => {
    setValues((prev) => ({ ...prev, [key]: value }));
  };

  const submit = () => {
    if (!values.name.trim()) {
      setError('请填写租户名称');
      return;
    }
    if (!values.code.trim()) {
      setError('请填写租户标识');
      return;
    }
    onSubmit(values);
  };

  const inputCls =
    'w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400';

  return (
    <Modal
      open={open}
      title={editing ? '编辑租户' : '新增租户'}
      subtitle="配置租户基础信息、套餐与资源配额"
      onClose={onClose}
      width="max-w-2xl"
      footer={
        <>
          <button
            type="button"
            onClick={onClose}
            className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
          >
            取消
          </button>
          <button
            type="button"
            onClick={submit}
            disabled={saving}
            className="h-9 px-4 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 disabled:opacity-60 cursor-pointer whitespace-nowrap dark:text-foreground-950"
          >
            {saving ? '保存中…' : '保存'}
          </button>
        </>
      }
    >
      <div className="space-y-3.5">
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
          <div>
            <label className="block text-xs font-medium text-foreground-700 mb-1.5">租户名称</label>
            <input
              type="text"
              value={values.name}
              onChange={(e) => set('name', e.target.value)}
              placeholder="例如:云启科技"
              className={inputCls}
            />
          </div>
          <div>
            <label className="block text-xs font-medium text-foreground-700 mb-1.5">租户标识</label>
            <input
              type="text"
              value={values.code}
              onChange={(e) => set('code', e.target.value)}
              placeholder="例如:yunqi"
              className={`${inputCls} font-label`}
            />
          </div>
          <div>
            <label className="block text-xs font-medium text-foreground-700 mb-1.5">套餐</label>
            <select
              value={values.plan}
              onChange={(e) => set('plan', e.target.value)}
              className={`${inputCls} cursor-pointer`}
            >
              {planOptions.map((p) => (
                <option key={p} value={p}>
                  {planMeta[p].label}
                </option>
              ))}
            </select>
          </div>
          <div>
            <label className="block text-xs font-medium text-foreground-700 mb-1.5">状态</label>
            <select
              value={values.status}
              onChange={(e) => set('status', e.target.value)}
              className={`${inputCls} cursor-pointer`}
            >
              <option value="active">正常</option>
              <option value="disabled">已冻结</option>
            </select>
          </div>
          <div>
            <label className="block text-xs font-medium text-foreground-700 mb-1.5">负责人</label>
            <input
              type="text"
              value={values.owner}
              onChange={(e) => set('owner', e.target.value)}
              placeholder="例如:陈立"
              className={inputCls}
            />
          </div>
          <div>
            <label className="block text-xs font-medium text-foreground-700 mb-1.5">联系邮箱</label>
            <input
              type="email"
              value={values.contact_email}
              onChange={(e) => set('contact_email', e.target.value)}
              placeholder="name@company.com"
              className={inputCls}
            />
          </div>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
          <div>
            <label className="block text-xs font-medium text-foreground-700 mb-1.5">席位配额</label>
            <input
              type="number"
              min={1}
              value={values.seats}
              onChange={(e) => set('seats', Number(e.target.value))}
              className={inputCls}
            />
          </div>
          <div>
            <label className="block text-xs font-medium text-foreground-700 mb-1.5">存储配额 (GB)</label>
            <input
              type="number"
              min={1}
              value={values.storage_quota_gb}
              onChange={(e) => set('storage_quota_gb', Number(e.target.value))}
              className={inputCls}
            />
          </div>
          <div>
            <label className="block text-xs font-medium text-foreground-700 mb-1.5">API 配额 (次/月)</label>
            <input
              type="number"
              min={0}
              value={values.api_quota}
              onChange={(e) => set('api_quota', Number(e.target.value))}
              className={inputCls}
            />
          </div>
        </div>

        <div>
          <label className="block text-xs font-medium text-foreground-700 mb-1.5">到期时间</label>
          <input
            type="date"
            value={values.expires_at ? values.expires_at.slice(0, 10) : ''}
            onChange={(e) => set('expires_at', e.target.value)}
            className={inputCls}
          />
        </div>

        {error ? (
          <div className="flex items-start gap-2 px-3 py-2.5 rounded-md bg-accent-100 text-accent-900 text-xs">
            <i className="ri-error-warning-line mt-0.5"></i>
            <span>{error}</span>
          </div>
        ) : null}
      </div>
    </Modal>
  );
}