import { useCallback, useEffect, useMemo, useState } from 'react';
import Modal from '@/components/base/Modal';
import MarketDetailModal from '@/pages/plugins/components/MarketDetailModal';
import MarketMyPanel from '@/pages/plugins/components/MarketMyPanel';
import { useAuth } from '@/contexts/AuthContext';
import { supabase } from '@/lib/supabase';
import { useRecentPlugins } from '@/pages/plugins/hooks/useRecentPlugins';
import { marketPlugins, recommendedBundles, type MarketPlugin } from '@/pages/plugins/marketCatalog';

interface MarketplaceModalProps {
  open: boolean;
  installedCodes: string[];
  installedMap: Record<string, { enabled: boolean; name: string }>;
  canManage: boolean;
  onClose: () => void;
  onInstall: (plugins: MarketPlugin[]) => Promise<void>;
}

interface MarkRow {
  plugin_code: string;
  favorited: boolean | null;
  purchased: boolean | null;
  purchased_at: string | null;
}

const categoryTone: Record<string, string> = {
  开发工具: 'bg-primary-100 text-primary-800',
  数据: 'bg-accent-100 text-accent-900',
  安全: 'bg-secondary-200 text-secondary-900',
  通讯: 'bg-accent-100 text-accent-900',
  运维: 'bg-secondary-200 text-secondary-900',
};

const sortOptions = [
  { key: 'recommend', label: '推荐', icon: 'ri-sparkling-line' },
  { key: 'downloads', label: '下载量', icon: 'ri-download-2-line' },
  { key: 'rating', label: '评分', icon: 'ri-star-line' },
  { key: 'name', label: '名称', icon: 'ri-sort-alphabet-asc' },
];

const viewOptions = [
  { key: 'all', label: '可安装', icon: 'ri-store-2-line', badge: true },
  { key: 'favorites', label: '我的收藏', icon: 'ri-star-line', badge: true },
  { key: 'owned', label: '已购', icon: 'ri-shopping-bag-3-line', badge: true },
  { key: 'mine', label: '我的', icon: 'ri-user-heart-line', badge: false },
];

function Stars({ rating }: { rating: number }) {
  return (
    <span className="inline-flex items-center gap-0.5">
      {[1, 2, 3, 4, 5].map((n) => (
        <i
          key={n}
          className={`text-[11px] ${
            rating >= n - 0.25
              ? 'ri-star-fill text-accent-500'
              : rating >= n - 0.75
                ? 'ri-star-half-fill text-accent-500'
                : 'ri-star-line text-foreground-300'
          }`}
        ></i>
      ))}
    </span>
  );
}

export default function MarketplaceModal({
  open,
  installedCodes,
  installedMap,
  canManage,
  onClose,
  onInstall,
}: MarketplaceModalProps) {
  const { user } = useAuth();
  const userId = user?.id ?? '';
  const { recent: recentViews, record: recordView, clear: clearViews } = useRecentPlugins(userId);

  const [keyword, setKeyword] = useState('');
  const [category, setCategory] = useState('全部');
  const [sort, setSort] = useState('recommend');
  const [view, setView] = useState('all');
  const [favorites, setFavorites] = useState<string[]>([]);
  const [owned, setOwned] = useState<string[]>([]);
  const [ownedAt, setOwnedAt] = useState<Record<string, string>>({});
  const [marksLoading, setMarksLoading] = useState(false);
  const [marksError, setMarksError] = useState('');
  const [lastSyncedAt, setLastSyncedAt] = useState('');
  const [installing, setInstalling] = useState<string | null>(null);
  const [detailTarget, setDetailTarget] = useState<MarketPlugin | null>(null);

  // 打开详情时记录浏览足迹,供「我的」页签串联
  const openDetail = useCallback(
    (plugin: MarketPlugin) => {
      recordView(plugin.code);
      setDetailTarget(plugin);
    },
    [recordView],
  );

  const loadMarks = useCallback(async () => {
    if (!userId) {
      setFavorites([]);
      setOwned([]);
      setLastSyncedAt('');
      return;
    }
    setMarksLoading(true);
    setMarksError('');
    try {
      const { data, error } = await supabase
        .from('plugin_user_marks')
        .select('plugin_code, favorited, purchased, purchased_at')
        .eq('user_id', userId);
      if (error) throw error;
      const rows = (data as MarkRow[]) ?? [];
      setFavorites(rows.filter((r) => r.favorited).map((r) => r.plugin_code));
      const ownedRows = rows.filter((r) => r.purchased);
      setOwned(ownedRows.map((r) => r.plugin_code));
      const at: Record<string, string> = {};
      ownedRows.forEach((r) => {
        if (r.purchased_at) at[r.plugin_code] = r.purchased_at;
      });
      setOwnedAt(at);
      setLastSyncedAt(new Date().toISOString());
    } catch (err) {
      console.error(err);
      setMarksError('账号数据同步失败');
    } finally {
      setMarksLoading(false);
    }
  }, [userId]);

  useEffect(() => {
    if (open) loadMarks();
  }, [open, loadMarks]);

  const installedSet = useMemo(() => new Set(installedCodes), [installedCodes]);
  const favoriteSet = useMemo(() => new Set(favorites), [favorites]);
  const ownedSet = useMemo(() => new Set(owned), [owned]);

  const toggleFavorite = async (code: string) => {
    if (!userId) return;
    const next = !favoriteSet.has(code);
    setMarksError('');
    // 乐观更新
    setFavorites((prev) => (next ? [...prev, code] : prev.filter((c) => c !== code)));
    try {
      const now = new Date().toISOString();
      const { error } = await supabase.from('plugin_user_marks').upsert(
        {
          user_id: userId,
          plugin_code: code,
          favorited: next,
          favorited_at: next ? now : null,
          updated_at: now,
        },
        { onConflict: 'user_id,plugin_code' },
      );
      if (error) throw error;
      setLastSyncedAt(now);
    } catch (err) {
      console.error(err);
      // 回滚
      setFavorites((prev) => (next ? prev.filter((c) => c !== code) : [...prev, code]));
      setMarksError('收藏失败,请重试');
    }
  };

  const categories = useMemo(
    () => ['全部', ...Array.from(new Set(marketPlugins.map((p) => p.category)))],
    [],
  );

  const viewCounts = useMemo(
    () => ({
      all: marketPlugins.filter((p) => !ownedSet.has(p.code)).length,
      favorites: marketPlugins.filter((p) => favoriteSet.has(p.code)).length,
      owned: marketPlugins.filter((p) => ownedSet.has(p.code)).length,
    }),
    [ownedSet, favoriteSet],
  );

  const available = useMemo(() => {
    const kw = keyword.trim().toLowerCase();
    let pool = marketPlugins;
    if (view === 'favorites') {
      pool = marketPlugins.filter((p) => favoriteSet.has(p.code));
    } else if (view === 'owned') {
      pool = marketPlugins.filter((p) => ownedSet.has(p.code));
    } else {
      pool = marketPlugins.filter((p) => !ownedSet.has(p.code));
    }

    const list = pool
      .filter((p) => category === '全部' || p.category === category)
      .filter(
        (p) =>
          !kw ||
          p.name.toLowerCase().includes(kw) ||
          p.code.toLowerCase().includes(kw) ||
          p.description.toLowerCase().includes(kw),
      );

    const sorted = [...list];
    if (sort === 'downloads') {
      sorted.sort((a, b) => b.downloads - a.downloads);
    } else if (sort === 'rating') {
      sorted.sort((a, b) => b.rating - a.rating || b.reviewCount - a.reviewCount);
    } else if (sort === 'name') {
      sorted.sort((a, b) => a.name.localeCompare(b.name, 'zh-Hans-CN'));
    }
    // 收藏的插件置顶显示,其余保持当前排序
    sorted.sort((a, b) => Number(favoriteSet.has(b.code)) - Number(favoriteSet.has(a.code)));
    return sorted;
  }, [view, category, keyword, sort, favoriteSet, ownedSet]);

  const topRated = useMemo(
    () => [...marketPlugins].sort((a, b) => b.rating - a.rating)[0],
    [],
  );

  const runInstall = async (plugins: MarketPlugin[], label: string) => {
    if (plugins.length === 0) return;
    setInstalling(label);
    setMarksError('');
    try {
      await onInstall(plugins);
      // 安装成功后把「已购」标记同步到当前账号
      if (userId) {
        const now = new Date().toISOString();
        const rows = plugins.map((p) => ({
          user_id: userId,
          plugin_code: p.code,
          purchased: true,
          purchased_at: now,
          updated_at: now,
        }));
        const { error } = await supabase
          .from('plugin_user_marks')
          .upsert(rows, { onConflict: 'user_id,plugin_code' });
        if (error) throw error;
        setLastSyncedAt(now);
        setOwned((prev) => Array.from(new Set([...prev, ...plugins.map((p) => p.code)])));
        setOwnedAt((prev) => {
          const next = { ...prev };
          plugins.forEach((p) => {
            next[p.code] = now;
          });
          return next;
        });
      }
    } catch (err) {
      console.error(err);
      setMarksError('安装或同步失败,请重试');
    } finally {
      setInstalling(null);
    }
  };

  return (
    <>
      <Modal
        open={open}
        title="插件市场"
        subtitle="挑选并一键安装官方与第三方插件,收藏与已购按账号同步,换设备也不丢"
        onClose={onClose}
        width="max-w-3xl"
        footer={
          <button
            type="button"
            onClick={onClose}
            className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
          >
            关闭
          </button>
        }
      >
        <div className="space-y-5">
          <div>
            <div className="flex items-center gap-1.5 mb-2.5">
              <i className="ri-sparkling-2-line text-accent-600 text-sm"></i>
              <span className="text-sm font-medium text-foreground-950">推荐组合</span>
              <span className="text-[11px] text-foreground-400">成套安装,配合更默契</span>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
              {recommendedBundles.map((bundle) => {
                const members = bundle.codes
                  .map((code) => marketPlugins.find((p) => p.code === code))
                  .filter((p): p is MarketPlugin => Boolean(p) && !ownedSet.has((p as MarketPlugin).code));
                const allInstalled = bundle.codes.every((code) => ownedSet.has(code));
                const busy = installing === bundle.key;
                return (
                  <div key={bundle.key} className="rounded-lg border border-background-200 bg-background-50 p-3.5 flex flex-col">
                    <span className="w-8 h-8 rounded-md flex items-center justify-center bg-accent-100 text-accent-800">
                      <i className={`${bundle.icon} text-base`}></i>
                    </span>
                    <p className="mt-2.5 text-sm font-medium text-foreground-950">{bundle.title}</p>
                    <p className="mt-1 text-[11px] text-foreground-500 leading-relaxed flex-1">{bundle.desc}</p>
                    <button
                      type="button"
                      onClick={() => runInstall(members, bundle.key)}
                      disabled={!canManage || allInstalled || busy}
                      className="mt-3 h-8 px-3 rounded-md bg-accent-500 text-background-50 text-xs hover:bg-accent-600 disabled:opacity-50 cursor-pointer whitespace-nowrap inline-flex items-center justify-center gap-1.5 dark:text-foreground-950"
                    >
                      <i className={busy ? 'ri-loader-4-line animate-spin' : allInstalled ? 'ri-check-line' : 'ri-add-circle-line'}></i>
                      {allInstalled ? '已全部安装' : busy ? '安装中' : `一键安装 (${members.length})`}
                    </button>
                  </div>
                );
              })}
            </div>
          </div>

          <div className="flex flex-wrap items-center gap-2">
            <div className="flex items-center gap-1 bg-background-100 border border-background-200 rounded-full p-1 w-fit">
              {viewOptions.map((v) => (
                <button
                  key={v.key}
                  type="button"
                  onClick={() => setView(v.key)}
                  className={`h-7 px-3 rounded-full text-xs whitespace-nowrap cursor-pointer transition-colors inline-flex items-center gap-1.5 ${
                    view === v.key
                      ? 'bg-primary-500 text-background-50 font-medium dark:text-foreground-950'
                      : 'text-foreground-600 hover:text-foreground-900'
                  }`}
                >
                  <i className={v.icon}></i>
                  {v.label}
                  {v.badge ? (
                    <span
                      className={`text-[10px] px-1.5 rounded-full ${
                        view === v.key
                          ? 'bg-background-50/25 text-background-50 dark:text-foreground-950'
                          : 'bg-background-200 text-foreground-600'
                      }`}
                    >
                      {viewCounts[v.key as keyof typeof viewCounts]}
                    </span>
                  ) : null}
                </button>
              ))}
            </div>
            {marksError ? (
              <span className="inline-flex items-center gap-1.5 text-[11px] text-accent-900">
                <i className="ri-error-warning-line"></i>
                {marksError}
                <button type="button" onClick={loadMarks} className="underline cursor-pointer whitespace-nowrap">
                  重试
                </button>
              </span>
            ) : (
              <span className="inline-flex items-center gap-1.5 text-[11px] text-foreground-400">
                <i className={marksLoading ? 'ri-loader-4-line animate-spin' : 'ri-cloud-line'}></i>
                {marksLoading ? '正在同步账号数据…' : '收藏与已购已按账号同步'}
              </span>
            )}
          </div>

          {view === 'mine' ? (
            <MarketMyPanel
              favorites={favorites}
              owned={owned}
              ownedAt={ownedAt}
              recentViews={recentViews}
              lastSyncedAt={lastSyncedAt}
              onOpenDetail={openDetail}
              onToggleFavorite={toggleFavorite}
              onGoView={setView}
              onClearViews={clearViews}
            />
          ) : (
            <>
          <div className="flex flex-col sm:flex-row sm:items-center gap-2">
            <div className="flex items-center gap-2 h-9 px-3 rounded-md bg-background-100 border border-background-200 w-full sm:w-52">
              <i className="ri-search-line text-foreground-400 text-sm"></i>
              <input
                type="text"
                value={keyword}
                onChange={(e) => setKeyword(e.target.value)}
                placeholder="搜索插件名称或标识"
                className="flex-1 bg-transparent text-sm text-foreground-900 placeholder:text-foreground-400 focus:outline-none"
              />
            </div>
            <div className="flex items-center gap-1 bg-background-100 border border-background-200 rounded-full p-1 overflow-x-auto">
              {categories.map((c) => (
                <button
                  key={c}
                  type="button"
                  onClick={() => setCategory(c)}
                  className={`h-7 px-2.5 rounded-full text-xs whitespace-nowrap cursor-pointer transition-colors ${
                    category === c
                      ? 'bg-background-50 text-foreground-950 font-medium'
                      : 'text-foreground-600 hover:text-foreground-900'
                  }`}
                >
                  {c}
                </button>
              ))}
            </div>
          </div>

          <div className="flex flex-wrap items-center gap-2">
            <span className="text-[11px] text-foreground-500 inline-flex items-center gap-1">
              <i className="ri-sort-desc"></i>
              排序
            </span>
            <div className="flex items-center gap-1 bg-background-100 border border-background-200 rounded-full p-1">
              {sortOptions.map((o) => (
                <button
                  key={o.key}
                  type="button"
                  onClick={() => setSort(o.key)}
                  className={`h-7 px-2.5 rounded-full text-xs whitespace-nowrap cursor-pointer transition-colors inline-flex items-center gap-1 ${
                    sort === o.key
                      ? 'bg-primary-500 text-background-50 font-medium dark:text-foreground-950'
                      : 'text-foreground-600 hover:text-foreground-900'
                  }`}
                >
                  <i className={o.icon}></i>
                  {o.label}
                </button>
              ))}
            </div>
            {topRated ? (
              <span className="ml-auto inline-flex items-center gap-1 text-[11px] text-foreground-500">
                <i className="ri-award-line text-accent-600"></i>
                评分最高:{topRated.name} {topRated.rating.toFixed(1)}
              </span>
            ) : null}
          </div>

          {available.length === 0 ? (
            <div className="rounded-lg border border-dashed border-background-300 py-12 text-center text-sm text-foreground-500">
              <i className="ri-store-2-line text-2xl block mb-2"></i>
              {view === 'favorites'
                ? '还没有收藏的插件,点卡片右上角的星标收藏吧'
                : view === 'owned'
                  ? '暂无已购插件,去「可安装」里挑一个吧'
                  : '该分类下的插件都已安装,或没有匹配结果'}
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
              {available.map((plugin) => {
                const busy = installing === plugin.code;
                const tone = categoryTone[plugin.category] ?? 'bg-background-200 text-foreground-700';
                const isFav = favoriteSet.has(plugin.code);
                const isOwned = ownedSet.has(plugin.code);
                const globallyInstalled = installedSet.has(plugin.code);
                return (
                  <div
                    key={plugin.code}
                    className={`rounded-lg border bg-background-50 p-4 flex flex-col ${
                      isFav ? 'border-accent-300' : 'border-background-200'
                    }`}
                  >
                    <div className="flex items-start gap-2.5">
                      <span className="w-9 h-9 rounded-md flex items-center justify-center bg-primary-100 text-primary-700 shrink-0">
                        <i className="ri-plug-2-line text-lg"></i>
                      </span>
                      <div className="min-w-0 flex-1">
                        <div className="flex items-center gap-2">
                          <p className="text-sm font-semibold text-foreground-950 truncate">{plugin.name}</p>
                          <span className={`shrink-0 text-[10px] px-1.5 py-0.5 rounded-full ${tone}`}>{plugin.category}</span>
                          {isFav ? (
                            <span className="shrink-0 text-[10px] px-1.5 py-0.5 rounded-full bg-accent-100 text-accent-900 inline-flex items-center gap-0.5">
                              <i className="ri-star-fill text-[9px]"></i>
                              收藏
                            </span>
                          ) : null}
                          {isOwned ? (
                            <span className="shrink-0 text-[10px] px-1.5 py-0.5 rounded-full bg-secondary-200 text-secondary-900 inline-flex items-center gap-0.5">
                              <i className="ri-shopping-bag-3-line text-[9px]"></i>
                              已购
                            </span>
                          ) : null}
                        </div>
                        <p className="mt-0.5 text-[11px] text-foreground-500 font-label truncate">
                          {plugin.code} · v{plugin.version}
                        </p>
                      </div>
                      <button
                        type="button"
                        onClick={() => toggleFavorite(plugin.code)}
                        aria-label={isFav ? '取消收藏' : '收藏插件'}
                        title={isFav ? '取消收藏' : '收藏插件'}
                        className={`shrink-0 w-7 h-7 rounded-md flex items-center justify-center cursor-pointer transition-colors ${
                          isFav
                            ? 'bg-accent-100 text-accent-600'
                            : 'text-foreground-300 hover:bg-background-100 hover:text-accent-500'
                        }`}
                      >
                        <i className={isFav ? 'ri-star-fill' : 'ri-star-line'}></i>
                      </button>
                    </div>
                    <p className="mt-2.5 text-xs text-foreground-600 leading-relaxed line-clamp-2 flex-1">
                      {plugin.description}
                    </p>
                    <div className="mt-2.5 flex items-center gap-2">
                      <Stars rating={plugin.rating} />
                      <span className="text-[11px] font-medium text-foreground-800 font-label">
                        {plugin.rating.toFixed(1)}
                      </span>
                      <span className="text-[10px] text-foreground-400">({plugin.reviewCount})</span>
                    </div>
                    <div className="mt-2.5 pt-3 border-t border-background-200 flex items-center gap-2">
                      <span className="inline-flex items-center gap-1 text-[11px] text-foreground-500">
                        <i className="ri-download-2-line"></i>
                        {plugin.downloads.toLocaleString()}
                      </span>
                      <span className="inline-flex items-center gap-1 text-[11px] text-foreground-500 truncate">
                        <i className="ri-user-3-line"></i>
                        {plugin.author}
                      </span>
                      <button
                        type="button"
                        onClick={() => openDetail(plugin)}
                        className="ml-auto h-8 px-2.5 rounded-md bg-background-100 border border-background-300 text-xs text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap inline-flex items-center gap-1"
                      >
                        <i className="ri-information-line"></i>
                        详情
                      </button>
                      {isOwned ? (
                        <span className="h-8 px-3 rounded-md bg-primary-100 text-primary-800 text-xs whitespace-nowrap inline-flex items-center gap-1.5">
                          <i className="ri-check-line"></i>
                          已购
                        </span>
                      ) : (
                        <button
                          type="button"
                          onClick={() => runInstall([plugin], plugin.code)}
                          disabled={!canManage || busy}
                          className="h-8 px-3 rounded-md bg-primary-500 text-background-50 text-xs hover:bg-primary-600 disabled:opacity-50 cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5 dark:text-foreground-950"
                        >
                          <i className={busy ? 'ri-loader-4-line animate-spin' : globallyInstalled ? 'ri-shopping-bag-3-line' : 'ri-install-line'}></i>
                          {busy ? '安装中' : globallyInstalled ? '收下' : '安装'}
                        </button>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          )}

            </>
          )}

          {!canManage ? (
            <p className="text-[11px] text-foreground-400 flex items-center gap-1.5">
              <i className="ri-lock-line"></i>
              当前账号没有插件管理权限,可查看但无法安装
            </p>
          ) : null}
        </div>
      </Modal>

      <MarketDetailModal
        open={Boolean(detailTarget)}
        plugin={detailTarget}
        installedMap={installedMap}
        canManage={canManage}
        onClose={() => setDetailTarget(null)}
        onInstall={async (plugin) => {
          await runInstall([plugin], plugin.code);
        }}
      />
    </>
  );
}