import { useMemo, useState } from 'react';
import Modal from '@/components/base/Modal';
import BlockPreview from '@/pages/builder/components/BlockPreview';
import type { BuilderBlock } from '@/pages/builder/types';

interface PreviewModalProps {
  open: boolean;
  blocks: BuilderBlock[];
  onClose: () => void;
}

export default function PreviewModal({ open, blocks, onClose }: PreviewModalProps) {
  const [tab, setTab] = useState<'preview' | 'json'>('preview');
  const [copied, setCopied] = useState(false);

  const json = useMemo(
    () =>
      JSON.stringify(
        {
          version: '1.0.0',
          generatedBy: 'HuaanAdmin 页面设计器',
          blockCount: blocks.length,
          blocks: blocks.map((b) => ({ type: b.type, props: b.props })),
        },
        null,
        2,
      ),
    [blocks],
  );

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(json);
      setCopied(true);
      setTimeout(() => setCopied(false), 1800);
    } catch (err) {
      console.error(err);
    }
  };

  const download = () => {
    const blob = new Blob([json], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'page-structure.json';
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <Modal
      open={open}
      title="页面预览与导出"
      subtitle={`共 ${blocks.length} 个组件`}
      onClose={onClose}
      width="max-w-3xl"
      footer={
        <>
          <button
            type="button"
            onClick={copy}
            className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5"
          >
            <i className={copied ? 'ri-check-line' : 'ri-file-copy-line'}></i>
            {copied ? '已复制' : '复制 JSON'}
          </button>
          <button
            type="button"
            onClick={download}
            className="h-9 px-4 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5 dark:text-foreground-950"
          >
            <i className="ri-download-2-line"></i>
            导出结构
          </button>
        </>
      }
    >
      <div className="flex items-center gap-1 p-1 mb-4 rounded-full bg-background-100 border border-background-200 w-fit">
        {[
          { key: 'preview' as const, label: '页面预览', icon: 'ri-eye-line' },
          { key: 'json' as const, label: '结构 JSON', icon: 'ri-code-s-slash-line' },
        ].map((t) => (
          <button
            key={t.key}
            type="button"
            onClick={() => setTab(t.key)}
            className={`px-3 py-1.5 rounded-full text-xs cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5 ${
              tab === t.key
                ? 'bg-background-50 text-foreground-950 font-medium'
                : 'text-foreground-600 hover:text-foreground-900'
            }`}
          >
            <i className={t.icon}></i>
            {t.label}
          </button>
        ))}
      </div>

      {blocks.length === 0 ? (
        <div className="py-16 text-center text-foreground-400">
          <i className="ri-layout-masonry-line text-3xl block mb-2"></i>
          画布为空,先去添加一些组件吧
        </div>
      ) : tab === 'preview' ? (
        <div className="mx-auto max-w-[680px] rounded-lg bg-background-50 border border-background-200 p-5 md:p-7 space-y-4">
          {blocks.map((b) => (
            <BlockPreview key={b.id} block={b} />
          ))}
        </div>
      ) : (
        <pre className="rounded-md bg-foreground-950 text-background-200 px-4 py-3.5 font-label text-[12px] leading-relaxed overflow-x-auto max-h-[460px] overflow-y-auto">
          {json}
        </pre>
      )}
    </Modal>
  );
}