import CodeBlock from '@/pages/docs/components/CodeBlock';
import {
  defaultSdkStack,
  defaultSdkVersion,
  snippetCodeFor,
  snippetFilenameFor,
  snippetHasStack,
  snippetHasVariant,
  type SdkSnippet,
} from '@/pages/docs/sdkSnippets';

interface SnippetCardProps {
  snippet: SdkSnippet;
  version: string;
  stack: string;
  versionLabel: string;
  stackLabel: string;
  favorited: boolean;
  highlighted?: boolean;
  category?: { icon: string; label: string } | null;
  onToggleFavorite: (id: string) => void;
}

export default function SnippetCard({
  snippet,
  version,
  stack,
  versionLabel,
  stackLabel,
  favorited,
  highlighted = false,
  category = null,
  onToggleFavorite,
}: SnippetCardProps) {
  const hasVariant = snippetHasVariant(snippet, version);
  const hasStack = snippetHasStack(snippet, stack);

  return (
    <div
      id={`sdk-snippet-${snippet.id}`}
      className={`rounded-lg border bg-background-50 p-4 transition-all ${
        highlighted ? 'border-accent-400 ring-2 ring-accent-300' : 'border-background-200'
      }`}
    >
      <div className="flex items-start gap-2.5">
        <span className="w-7 h-7 rounded-md flex items-center justify-center bg-primary-100 text-primary-700 shrink-0">
          <i className="ri-code-line text-sm"></i>
        </span>
        <div className="min-w-0 flex-1">
          <div className="flex flex-wrap items-center gap-2">
            <p className="text-sm font-medium text-foreground-950">{snippet.title}</p>
            {category ? (
              <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-secondary-100 text-secondary-900 inline-flex items-center gap-0.5">
                <i className={`${category.icon} text-[9px]`}></i>
                {category.label}
              </span>
            ) : null}
            {favorited ? (
              <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-accent-100 text-accent-900 inline-flex items-center gap-0.5">
                <i className="ri-star-fill text-[9px]"></i>
                已收藏
              </span>
            ) : null}
            {highlighted ? (
              <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-accent-100 text-accent-900 inline-flex items-center gap-0.5">
                <i className="ri-focus-3-line text-[9px]"></i>
                已定位
              </span>
            ) : null}
            {stack !== defaultSdkStack ? (
              hasStack ? (
                <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-primary-100 text-primary-800">
                  {stackLabel} 写法
                </span>
              ) : (
                <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-background-200 text-foreground-600">
                  该技术栈写法一致
                </span>
              )
            ) : version !== defaultSdkVersion ? (
              hasVariant ? (
                <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-primary-100 text-primary-800">
                  {versionLabel} 写法
                </span>
              ) : (
                <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-background-200 text-foreground-600">
                  该版本写法一致
                </span>
              )
            ) : null}
          </div>
          <p className="mt-0.5 text-[12.5px] text-foreground-600 leading-relaxed">{snippet.desc}</p>
        </div>
        <button
          type="button"
          onClick={() => onToggleFavorite(snippet.id)}
          aria-label={favorited ? '取消收藏片段' : '收藏片段'}
          title={favorited ? '取消收藏片段' : '收藏片段,收藏后置顶'}
          className={`shrink-0 w-7 h-7 rounded-md flex items-center justify-center cursor-pointer transition-colors ${
            favorited
              ? 'bg-accent-100 text-accent-600'
              : 'text-foreground-300 hover:bg-background-100 hover:text-accent-500'
          }`}
        >
          <i className={favorited ? 'ri-star-fill' : 'ri-star-line'}></i>
        </button>
      </div>
      <CodeBlock
        code={snippetCodeFor(snippet, version, stack)}
        language={snippet.language}
        filename={snippetFilenameFor(snippet, stack)}
        className="mt-3"
      />
    </div>
  );
}