import { useCallback } from 'react';
import { useAuth } from '@/contexts/AuthContext';

/**
 * 统一的菜单可见性判断。
 *
 * - 普通账号:按自身的权限点过滤菜单
 * - 体验(演示)账号:可浏览全部菜单,方便访客看到完整后台的样子
 *   (写操作仍会被按钮权限与数据库策略拦截,因此是只读演示)
 */
export function useNavAccess() {
  const { hasPermission, isDemo } = useAuth();

  const canAccess = useCallback(
    (permission: string) => (isDemo ? true : hasPermission(permission)),
    [isDemo, hasPermission],
  );

  return { canAccess, isDemo };
}