import { supabase } from '@/lib/supabase';

export interface AppSettingRow {
  id: number;
  category: string | null;
  config_key: string;
  label: string;
  value: string | null;
  value_type: string | null;
  options: string[] | null;
  description: string | null;
  editable: boolean;
  sort_order: number | null;
}

/** Read a single setting from the config center by its config_key. */
export async function fetchSetting(configKey: string): Promise<AppSettingRow | null> {
  const { data, error } = await supabase
    .from('system_settings')
    .select('*')
    .eq('config_key', configKey)
    .maybeSingle();
  if (error) throw error;
  return (data as AppSettingRow) ?? null;
}

/** Persist a setting value back to the config center. */
export async function saveSettingValue(configKey: string, value: string): Promise<void> {
  const { error } = await supabase
    .from('system_settings')
    .update({ value, updated_at: new Date().toISOString() })
    .eq('config_key', configKey);
  if (error) throw error;
}

/** Read a numeric setting, falling back when missing or invalid. */
export async function fetchNumberSetting(configKey: string, fallback: number): Promise<number> {
  const row = await fetchSetting(configKey);
  const raw = row?.value ?? '';
  const num = Number(raw);
  return raw !== '' && !Number.isNaN(num) ? num : fallback;
}

export interface ThresholdHistoryRow {
  id: number;
  threshold: number;
  previous_threshold: number | null;
  changed_by_name: string | null;
  created_at: string | null;
}

/** Latest alert-threshold changes, newest first. */
export async function fetchThresholdHistory(limit = 20): Promise<ThresholdHistoryRow[]> {
  const { data, error } = await supabase
    .from('task_alert_threshold_history')
    .select('*')
    .order('created_at', { ascending: false })
    .limit(limit);
  if (error) throw error;
  return (data as ThresholdHistoryRow[]) ?? [];
}

/** Append a threshold change to the history log (best-effort, non-blocking). */
export async function logThresholdChange(threshold: number, previous: number | null): Promise<void> {
  const { data: authData } = await supabase.auth.getUser();
  let name: string | null = authData.user?.email ?? null;
  if (authData.user?.id) {
    const { data: profile } = await supabase
      .from('profiles')
      .select('full_name')
      .eq('id', authData.user.id)
      .maybeSingle();
    if (profile?.full_name) name = profile.full_name as string;
  }
  const { error } = await supabase.from('task_alert_threshold_history').insert({
    threshold,
    previous_threshold: previous,
    changed_by: authData.user?.id ?? null,
    changed_by_name: name,
  });
  if (error) throw error;
}