import { useCallback, useEffect, useMemo, useState } from 'react';
import { supabase } from '@/lib/supabase';
import LogDetailModal, { type DetailRow } from '@/pages/system/logs/components/LogDetailModal';

interface AuditLog {
  id: string;
  user_id: string | null;
  user_name: string | null;
  action: string | null;
  module: string | null;
  level: string | null;
  detail: string | null;
  ip: string | null;
  created_at: string;
}

interface LoginLog {
  id: string;
  user_name: string | null;
  email: string | null;
  status: string | null;
  ip: string | null;
  location: string | null;
  device: string | null;
  browser: string | null;
  message: string | null;
  created_at: string;
}

const PAGE_SIZE = 12;

const auditLevelMeta: Record<string, { label: string; badge: string; dot: string }> = {
  info: { label: '信息', badge: 'bg-primary-100 text-primary-800', dot: 'bg-primary-500' },
  warn: { label: '警告', badge: 'bg-accent-100 text-accent-900', dot: 'bg-accent-500' },
  error: { label: '错误', badge: 'bg-secondary-200 text-secondary-900', dot: 'bg-secondary-600' },
};

const loginStatusMeta: Record<string, { label: string; badge: string; dot: string }> = {
  success: { label: '成功', badge: 'bg-primary-100 text-primary-800', dot: 'bg-primary-500' },
  failed: { label: '失败', badge: 'bg-secondary-200 text-secondary-900', dot: 'bg-secondary-600' },
  logout: { label: '登出', badge: 'bg-background-200 text-foreground-700', dot: 'bg-foreground-400' },
};

const timeRanges = [
  { value: 'all', label: '全部时间', ms: 0 },
  { value: '1h', label: '最近 1 小时', ms: 3600 * 1000 },
  { value: '24h', label: '最近 24 小时', ms: 24 * 3600 * 1000 },
  { value: '7d', label: '最近 7 天', ms: 7 * 24 * 3600 * 1000 },
  { value: '30d', label: '最近 30 天', ms: 30 * 24 * 3600 * 1000 },
];

function formatDateTime(iso: string) {
  const d = new Date(iso);
  const p = (n: number) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}`;
}

function downloadCsv(filename: string, header: string[], rows: string[][]) {
  const escape = (value: string) => `"${String(value ?? '').replace(/"/g, '""')}"`;
  const csv = [header, ...rows].map((row) => row.map(escape).join(',')).join('\n');
  const blob = new Blob([`\ufeff${csv}`], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  link.click();
  URL.revokeObjectURL(url);
}

export default function LogsPage() {
  const [tab, setTab] = useState<'operation' | 'login'>('operation');
  const [auditLogs, setAuditLogs] = useState<AuditLog[]>([]);
  const [loginLogs, setLoginLogs] = useState<LoginLog[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  const [levelFilter, setLevelFilter] = useState('all');
  const [statusFilter, setStatusFilter] = useState('all');
  const [moduleFilter, setModuleFilter] = useState('all');
  const [timeRange, setTimeRange] = useState('all');
  const [keyword, setKeyword] = useState('');
  const [page, setPage] = useState(1);

  const [detail, setDetail] = useState<{ title: string; badge?: { text: string; className: string }; rows: DetailRow[] } | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const [auditRes, loginRes] = await Promise.all([
        supabase
          .from('audit_logs')
          .select('*')
          .order('created_at', { ascending: false })
          .limit(500),
        supabase
          .from('login_logs')
          .select('*')
          .order('created_at', { ascending: false })
          .limit(500),
      ]);
      if (auditRes.error) throw auditRes.error;
      if (loginRes.error) throw loginRes.error;
      setAuditLogs((auditRes.data as AuditLog[]) ?? []);
      setLoginLogs((loginRes.data as LoginLog[]) ?? []);
    } catch (err) {
      console.error(err);
      setError('加载日志数据失败,请重试');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  useEffect(() => {
    setPage(1);
  }, [tab, levelFilter, statusFilter, moduleFilter, timeRange, keyword]);

  const moduleOptions = useMemo(() => {
    const set = new Set<string>();
    auditLogs.forEach((log) => {
      if (log.module) set.add(log.module);
    });
    return Array.from(set);
  }, [auditLogs]);

  const rangeMs = useMemo(() => timeRanges.find((r) => r.value === timeRange)?.ms ?? 0, [timeRange]);

  const inRange = useCallback(
    (iso: string) => {
      if (!rangeMs) return true;
      return Date.now() - new Date(iso).getTime() <= rangeMs;
    },
    [rangeMs],
  );

  const filteredAudit = useMemo(() => {
    const kw = keyword.trim().toLowerCase();
    return auditLogs.filter((log) => {
      const matchLevel = levelFilter === 'all' || (log.level ?? 'info') === levelFilter;
      const matchModule = moduleFilter === 'all' || log.module === moduleFilter;
      const matchTime = inRange(log.created_at);
      const haystack = `${log.user_name ?? ''} ${log.action ?? ''} ${log.module ?? ''} ${log.detail ?? ''} ${log.ip ?? ''}`.toLowerCase();
      const matchKw = !kw || haystack.includes(kw);
      return matchLevel && matchModule && matchTime && matchKw;
    });
  }, [auditLogs, levelFilter, moduleFilter, keyword, inRange]);

  const filteredLogin = useMemo(() => {
    const kw = keyword.trim().toLowerCase();
    return loginLogs.filter((log) => {
      const matchStatus = statusFilter === 'all' || (log.status ?? 'success') === statusFilter;
      const matchTime = inRange(log.created_at);
      const haystack = `${log.user_name ?? ''} ${log.email ?? ''} ${log.ip ?? ''} ${log.location ?? ''} ${log.device ?? ''} ${log.message ?? ''}`.toLowerCase();
      const matchKw = !kw || haystack.includes(kw);
      return matchStatus && matchTime && matchKw;
    });
  }, [loginLogs, statusFilter, keyword, inRange]);

  const currentTotal = tab === 'operation' ? filteredAudit.length : filteredLogin.length;
  const totalPages = Math.max(1, Math.ceil(currentTotal / PAGE_SIZE));
  const safePage = Math.min(page, totalPages);

  const pagedAudit = useMemo(
    () => filteredAudit.slice((safePage - 1) * PAGE_SIZE, safePage * PAGE_SIZE),
    [filteredAudit, safePage],
  );
  const pagedLogin = useMemo(
    () => filteredLogin.slice((safePage - 1) * PAGE_SIZE, safePage * PAGE_SIZE),
    [filteredLogin, safePage],
  );

  const stats = useMemo(() => {
    const warn = auditLogs.filter((l) => l.level === 'warn').length;
    const err = auditLogs.filter((l) => l.level === 'error').length;
    const failed = loginLogs.filter((l) => l.status === 'failed').length;
    return { warn, err, failed };
  }, [auditLogs, loginLogs]);

  const openAuditDetail = (log: AuditLog) => {
    const meta = auditLevelMeta[log.level ?? 'info'] ?? auditLevelMeta.info;
    setDetail({
      title: log.action ?? '操作日志',
      badge: { text: meta.label, className: meta.badge },
      rows: [
        { label: '时间', value: formatDateTime(log.created_at), mono: true },
        { label: '操作人', value: log.user_name ?? '系统' },
        { label: '动作', value: log.action ?? '—' },
        { label: '模块', value: log.module ?? '—' },
        {
          label: '级别',
          value: meta.label,
        },
        { label: 'IP', value: log.ip ?? '—', mono: true },
        { label: '详情', value: log.detail ?? '—' },
      ],
    });
  };

  const openLoginDetail = (log: LoginLog) => {
    const meta = loginStatusMeta[log.status ?? 'success'] ?? loginStatusMeta.success;
    setDetail({
      title: `${log.user_name ?? log.email ?? '未知用户'} 的登录记录`,
      badge: { text: meta.label, className: meta.badge },
      rows: [
        { label: '时间', value: formatDateTime(log.created_at), mono: true },
        { label: '用户', value: log.user_name ?? '—' },
        { label: '邮箱', value: log.email ?? '—' },
        { label: '状态', value: meta.label },
        { label: 'IP', value: log.ip ?? '—', mono: true },
        { label: '归属地', value: log.location ?? '—' },
        { label: '设备', value: log.device ?? '—' },
        { label: '浏览器', value: log.browser ?? '—' },
        { label: '说明', value: log.message ?? '—' },
      ],
    });
  };

  const handleExport = () => {
    if (tab === 'operation') {
      downloadCsv(
        `操作日志_${Date.now()}.csv`,
        ['时间', '操作人', '动作', '模块', '级别', 'IP', '详情'],
        filteredAudit.map((l) => [
          formatDateTime(l.created_at),
          l.user_name ?? '系统',
          l.action ?? '',
          l.module ?? '',
          auditLevelMeta[l.level ?? 'info']?.label ?? '',
          l.ip ?? '',
          l.detail ?? '',
        ]),
      );
    } else {
      downloadCsv(
        `登录日志_${Date.now()}.csv`,
        ['时间', '用户', '邮箱', '状态', 'IP', '归属地', '设备', '浏览器', '说明'],
        filteredLogin.map((l) => [
          formatDateTime(l.created_at),
          l.user_name ?? '',
          l.email ?? '',
          loginStatusMeta[l.status ?? 'success']?.label ?? '',
          l.ip ?? '',
          l.location ?? '',
          l.device ?? '',
          l.browser ?? '',
          l.message ?? '',
        ]),
      );
    }
  };

  return (
    <div className="space-y-4">
      <div className="flex flex-col md:flex-row md:items-center gap-3">
        <div>
          <h2 className="text-lg font-semibold text-foreground-950">日志审计</h2>
          <p className="text-sm text-foreground-500 mt-0.5">
            记录系统操作与登录行为,支持按级别、模块、时间与关键字检索
          </p>
        </div>
        <div className="md:ml-auto flex flex-wrap items-center gap-2">
          <button
            type="button"
            onClick={load}
            className="h-9 px-3.5 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-800 hover:bg-background-100 cursor-pointer whitespace-nowrap flex items-center gap-1.5"
          >
            <i className="ri-refresh-line"></i>
            刷新
          </button>
          <button
            type="button"
            onClick={handleExport}
            className="h-9 px-3.5 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 cursor-pointer whitespace-nowrap flex items-center gap-1.5 dark:text-foreground-950"
          >
            <i className="ri-download-2-line"></i>
            导出 CSV
          </button>
        </div>
      </div>

      {/* Stat strip */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
        {[
          { label: '操作日志', value: auditLogs.length, icon: 'ri-file-list-3-line', tone: 'bg-primary-100 text-primary-700' },
          { label: '登录日志', value: loginLogs.length, icon: 'ri-login-box-line', tone: 'bg-accent-100 text-accent-800' },
          { label: '警告记录', value: stats.warn, icon: 'ri-alert-line', tone: 'bg-accent-100 text-accent-800' },
          { label: '错误 / 失败登录', value: stats.err + stats.failed, icon: 'ri-error-warning-line', tone: 'bg-secondary-200 text-secondary-900' },
        ].map((card) => (
          <div key={card.label} className="rounded-lg bg-background-50 border border-background-200 p-4 flex items-center gap-3">
            <span className={`w-10 h-10 rounded-md flex items-center justify-center ${card.tone}`}>
              <i className={`${card.icon} text-lg`}></i>
            </span>
            <div>
              <p className="text-xl font-semibold text-foreground-950 font-heading">{card.value}</p>
              <p className="text-xs text-foreground-500">{card.label}</p>
            </div>
          </div>
        ))}
      </div>

      {error ? (
        <div className="flex items-center justify-between gap-3 rounded-lg bg-accent-100 border border-accent-200 px-4 py-3">
          <span className="text-sm text-accent-900">{error}</span>
          <button
            type="button"
            onClick={load}
            className="h-8 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-800 hover:bg-background-100 cursor-pointer whitespace-nowrap"
          >
            重试
          </button>
        </div>
      ) : null}

      <div className="rounded-lg bg-background-50 border border-background-200">
        {/* Tabs + filters */}
        <div className="flex flex-col xl:flex-row xl:items-center gap-3 px-4 md:px-5 py-3.5 border-b border-background-200">
          <div className="inline-flex p-1 rounded-full bg-background-200/70 shrink-0">
            {[
              { key: 'operation' as const, label: '操作日志', count: auditLogs.length },
              { key: 'login' as const, label: '登录日志', count: loginLogs.length },
            ].map((t) => (
              <button
                key={t.key}
                type="button"
                onClick={() => setTab(t.key)}
                className={`px-3.5 py-1.5 text-xs rounded-full cursor-pointer whitespace-nowrap ${
                  tab === t.key ? 'bg-background-50 text-foreground-950 font-medium' : 'text-foreground-600'
                }`}
              >
                {t.label}
                <span className="ml-1.5 text-[10px] text-foreground-400">{t.count}</span>
              </button>
            ))}
          </div>

          <div className="flex flex-wrap items-center gap-2 xl:ml-auto">
            {tab === 'operation' ? (
              <>
                <select
                  value={levelFilter}
                  onChange={(e) => setLevelFilter(e.target.value)}
                  className="h-9 px-3 rounded-md bg-background-50 border border-background-200 text-sm text-foreground-800 focus:outline-none cursor-pointer"
                >
                  <option value="all">全部级别</option>
                  <option value="info">信息</option>
                  <option value="warn">警告</option>
                  <option value="error">错误</option>
                </select>
                <select
                  value={moduleFilter}
                  onChange={(e) => setModuleFilter(e.target.value)}
                  className="h-9 px-3 rounded-md bg-background-50 border border-background-200 text-sm text-foreground-800 focus:outline-none cursor-pointer"
                >
                  <option value="all">全部模块</option>
                  {moduleOptions.map((m) => (
                    <option key={m} value={m}>
                      {m}
                    </option>
                  ))}
                </select>
              </>
            ) : (
              <select
                value={statusFilter}
                onChange={(e) => setStatusFilter(e.target.value)}
                className="h-9 px-3 rounded-md bg-background-50 border border-background-200 text-sm text-foreground-800 focus:outline-none cursor-pointer"
              >
                <option value="all">全部状态</option>
                <option value="success">成功</option>
                <option value="failed">失败</option>
                <option value="logout">登出</option>
              </select>
            )}

            <select
              value={timeRange}
              onChange={(e) => setTimeRange(e.target.value)}
              className="h-9 px-3 rounded-md bg-background-50 border border-background-200 text-sm text-foreground-800 focus:outline-none cursor-pointer"
            >
              {timeRanges.map((r) => (
                <option key={r.value} value={r.value}>
                  {r.label}
                </option>
              ))}
            </select>

            <div className="flex items-center gap-2 h-9 px-3 rounded-md bg-background-100 border border-background-200 w-full sm:w-56">
              <i className="ri-search-line text-foreground-400 text-sm"></i>
              <input
                type="text"
                value={keyword}
                onChange={(e) => setKeyword(e.target.value)}
                placeholder={tab === 'operation' ? '搜索操作人 / 动作 / 详情' : '搜索用户 / 邮箱 / IP'}
                className="flex-1 bg-transparent text-sm text-foreground-900 placeholder:text-foreground-400 focus:outline-none"
              />
            </div>
          </div>
        </div>

        {/* Table */}
        <div className="overflow-x-auto">
          {tab === 'operation' ? (
            <table className="w-full min-w-[860px] text-sm">
              <thead>
                <tr className="bg-background-100 text-left text-xs text-foreground-500">
                  <th className="px-4 py-3 font-medium">时间</th>
                  <th className="px-4 py-3 font-medium">操作人</th>
                  <th className="px-4 py-3 font-medium">动作</th>
                  <th className="px-4 py-3 font-medium">模块</th>
                  <th className="px-4 py-3 font-medium">级别</th>
                  <th className="px-4 py-3 font-medium">IP</th>
                  <th className="px-4 py-3 font-medium text-right">详情</th>
                </tr>
              </thead>
              <tbody>
                {loading ? (
                  [0, 1, 2, 3, 4].map((n) => (
                    <tr key={n} className="border-t border-background-200">
                      <td colSpan={7} className="px-4 py-3">
                        <div className="h-7 rounded-md bg-background-100 animate-pulse-soft" />
                      </td>
                    </tr>
                  ))
                ) : pagedAudit.length === 0 ? (
                  <tr className="border-t border-background-200">
                    <td colSpan={7} className="px-4 py-14 text-center text-foreground-500">
                      <i className="ri-file-search-line text-2xl block mb-2"></i>
                      没有匹配的操作日志
                    </td>
                  </tr>
                ) : (
                  pagedAudit.map((log) => {
                    const meta = auditLevelMeta[log.level ?? 'info'] ?? auditLevelMeta.info;
                    return (
                      <tr
                        key={log.id}
                        onClick={() => openAuditDetail(log)}
                        className="border-t border-background-200 hover:bg-background-100/60 cursor-pointer"
                      >
                        <td className="px-4 py-3 text-foreground-600 font-label text-xs whitespace-nowrap">
                          {formatDateTime(log.created_at)}
                        </td>
                        <td className="px-4 py-3 text-foreground-900 whitespace-nowrap">{log.user_name ?? '系统'}</td>
                        <td className="px-4 py-3 text-foreground-900">{log.action ?? '—'}</td>
                        <td className="px-4 py-3">
                          <span className="text-[11px] px-2 py-0.5 rounded-full bg-secondary-100 text-secondary-900">
                            {log.module ?? '—'}
                          </span>
                        </td>
                        <td className="px-4 py-3">
                          <span className={`inline-flex items-center gap-1.5 text-[11px] px-2 py-0.5 rounded-full ${meta.badge}`}>
                            <span className={`w-1.5 h-1.5 rounded-full ${meta.dot}`} />
                            {meta.label}
                          </span>
                        </td>
                        <td className="px-4 py-3 text-foreground-600 font-label text-xs whitespace-nowrap">
                          {log.ip ?? '—'}
                        </td>
                        <td className="px-4 py-3 text-right">
                          <span className="inline-flex items-center gap-1 text-xs text-primary-700 whitespace-nowrap">
                            查看
                            <i className="ri-arrow-right-s-line"></i>
                          </span>
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          ) : (
            <table className="w-full min-w-[860px] text-sm">
              <thead>
                <tr className="bg-background-100 text-left text-xs text-foreground-500">
                  <th className="px-4 py-3 font-medium">时间</th>
                  <th className="px-4 py-3 font-medium">用户</th>
                  <th className="px-4 py-3 font-medium">状态</th>
                  <th className="px-4 py-3 font-medium">IP / 归属地</th>
                  <th className="px-4 py-3 font-medium">设备</th>
                  <th className="px-4 py-3 font-medium">说明</th>
                  <th className="px-4 py-3 font-medium text-right">详情</th>
                </tr>
              </thead>
              <tbody>
                {loading ? (
                  [0, 1, 2, 3, 4].map((n) => (
                    <tr key={n} className="border-t border-background-200">
                      <td colSpan={7} className="px-4 py-3">
                        <div className="h-7 rounded-md bg-background-100 animate-pulse-soft" />
                      </td>
                    </tr>
                  ))
                ) : pagedLogin.length === 0 ? (
                  <tr className="border-t border-background-200">
                    <td colSpan={7} className="px-4 py-14 text-center text-foreground-500">
                      <i className="ri-file-search-line text-2xl block mb-2"></i>
                      没有匹配的登录日志
                    </td>
                  </tr>
                ) : (
                  pagedLogin.map((log) => {
                    const meta = loginStatusMeta[log.status ?? 'success'] ?? loginStatusMeta.success;
                    return (
                      <tr
                        key={log.id}
                        onClick={() => openLoginDetail(log)}
                        className="border-t border-background-200 hover:bg-background-100/60 cursor-pointer"
                      >
                        <td className="px-4 py-3 text-foreground-600 font-label text-xs whitespace-nowrap">
                          {formatDateTime(log.created_at)}
                        </td>
                        <td className="px-4 py-3">
                          <p className="text-foreground-900 whitespace-nowrap">{log.user_name ?? '未知'}</p>
                          <p className="text-[11px] text-foreground-500 whitespace-nowrap">{log.email ?? '—'}</p>
                        </td>
                        <td className="px-4 py-3">
                          <span className={`inline-flex items-center gap-1.5 text-[11px] px-2 py-0.5 rounded-full ${meta.badge}`}>
                            <span className={`w-1.5 h-1.5 rounded-full ${meta.dot}`} />
                            {meta.label}
                          </span>
                        </td>
                        <td className="px-4 py-3">
                          <p className="text-foreground-700 font-label text-xs whitespace-nowrap">{log.ip ?? '—'}</p>
                          <p className="text-[11px] text-foreground-500 whitespace-nowrap">{log.location ?? '—'}</p>
                        </td>
                        <td className="px-4 py-3 text-foreground-700 text-xs whitespace-nowrap">
                          {log.device ?? '—'}
                          <span className="text-foreground-400"> · {log.browser ?? '—'}</span>
                        </td>
                        <td className="px-4 py-3 text-foreground-700 max-w-[220px] truncate">{log.message ?? '—'}</td>
                        <td className="px-4 py-3 text-right">
                          <span className="inline-flex items-center gap-1 text-xs text-primary-700 whitespace-nowrap">
                            查看
                            <i className="ri-arrow-right-s-line"></i>
                          </span>
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          )}
        </div>

        {/* Pagination */}
        <div className="flex flex-col sm:flex-row sm:items-center gap-3 px-4 md:px-5 py-3.5 border-t border-background-200">
          <p className="text-xs text-foreground-500">
            共 <span className="text-foreground-900 font-medium">{currentTotal}</span> 条记录,第 {safePage} / {totalPages} 页
          </p>
          <div className="sm:ml-auto flex items-center gap-1.5">
            <button
              type="button"
              onClick={() => setPage((p) => Math.max(1, p - 1))}
              disabled={safePage <= 1}
              className="h-8 px-3 rounded-md bg-background-100 border border-background-300 text-xs text-foreground-800 hover:bg-background-200 disabled:opacity-40 cursor-pointer whitespace-nowrap"
            >
              <i className="ri-arrow-left-s-line mr-0.5"></i>
              上一页
            </button>
            <button
              type="button"
              onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
              disabled={safePage >= totalPages}
              className="h-8 px-3 rounded-md bg-background-100 border border-background-300 text-xs text-foreground-800 hover:bg-background-200 disabled:opacity-40 cursor-pointer whitespace-nowrap"
            >
              下一页
              <i className="ri-arrow-right-s-line ml-0.5"></i>
            </button>
          </div>
        </div>
      </div>

      <LogDetailModal
        open={Boolean(detail)}
        title={detail?.title ?? ''}
        badge={detail?.badge}
        rows={detail?.rows ?? []}
        onClose={() => setDetail(null)}
      />
    </div>
  );
}