import { supabase } from '@/lib/supabase';

export interface RecyclePayload {
  module: string;
  itemId: string;
  itemName: string;
  snapshot?: Record<string, unknown>;
}

/**
 * Move a deleted record into the recycle bin (soft delete).
 * Returns true when the record was recorded successfully.
 */
export async function moveToRecycleBin({
  module,
  itemId,
  itemName,
  snapshot,
}: RecyclePayload): Promise<boolean> {
  try {
    const { data: authData } = await supabase.auth.getUser();
    const user = authData.user;
    let operatorName = user?.email ?? null;

    if (user) {
      const { data: prof } = await supabase
        .from('profiles')
        .select('full_name')
        .eq('id', user.id)
        .maybeSingle();
      if (prof?.full_name) operatorName = prof.full_name as string;
    }

    const { error } = await supabase.from('recycle_bin').insert({
      module,
      item_id: itemId,
      item_name: itemName,
      snapshot: snapshot ?? {},
      deleted_by: user?.id ?? null,
      deleted_by_name: operatorName,
    });
    if (error) throw error;
    return true;
  } catch (err) {
    console.error('moveToRecycleBin failed', err);
    return false;
  }
}

export interface RecycleRow {
  id: string;
  module: string;
  item_id: string;
  item_name: string;
  snapshot: Record<string, unknown> | null;
  deleted_by: string | null;
  deleted_by_name: string | null;
  deleted_at: string | null;
}

const restoreTable: Record<string, string> = {
  user: 'profiles',
  role: 'roles',
  tenant: 'tenants',
  plugin: 'plugins',
  department: 'departments',
  member: 'members',
  task: 'scheduled_tasks',
};

export const moduleMeta: Record<string, { label: string; icon: string; tone: string }> = {
  user: { label: '用户', icon: 'ri-user-3-line', tone: 'bg-primary-100 text-primary-800' },
  role: { label: '角色', icon: 'ri-shield-user-line', tone: 'bg-accent-100 text-accent-900' },
  tenant: { label: '租户', icon: 'ri-building-2-line', tone: 'bg-secondary-200 text-secondary-900' },
  plugin: { label: '插件', icon: 'ri-puzzle-2-line', tone: 'bg-primary-100 text-primary-800' },
  department: { label: '部门', icon: 'ri-node-tree', tone: 'bg-accent-100 text-accent-900' },
  member: { label: '会员', icon: 'ri-vip-crown-line', tone: 'bg-primary-100 text-primary-800' },
  task: { label: '任务', icon: 'ri-timer-flash-line', tone: 'bg-secondary-200 text-secondary-900' },
};

/**
 * Restore a recycle-bin record back into its source table.
 */
export async function restoreRecycleItem(row: RecycleRow): Promise<{ ok: boolean; message: string }> {
  const table = restoreTable[row.module];
  if (!table) return { ok: false, message: '该模块暂不支持一键还原' };
  if (!row.snapshot || Object.keys(row.snapshot).length === 0) {
    return { ok: false, message: '缺少快照数据,无法还原' };
  }
  try {
    // 取出随快照保存的关联(用户↔角色、角色↔权限),它们不是表字段,需先剔除
    const snapshot: Record<string, unknown> = { ...row.snapshot };
    const roles = Array.isArray(snapshot._roles) ? (snapshot._roles as string[]) : [];
    const permissions = Array.isArray(snapshot._permissions)
      ? (snapshot._permissions as string[])
      : [];
    delete snapshot._roles;
    delete snapshot._permissions;

    const { error } = await supabase.from(table).insert(snapshot);
    if (error) throw error;

    // 还原用户时一并恢复其角色关联,避免还原成没有任何角色的空壳账号
    if (row.module === 'user' && roles.length > 0) {
      await supabase
        .from('user_roles')
        .upsert(
          roles.map((rid) => ({ user_id: row.item_id, role_id: rid })),
          { onConflict: 'user_id,role_id' },
        );
    }
    // 还原角色时一并恢复其权限关联
    if (row.module === 'role' && permissions.length > 0) {
      await supabase
        .from('role_permissions')
        .upsert(
          permissions.map((pid) => ({ role_id: row.item_id, permission_id: pid })),
          { onConflict: 'role_id,permission_id' },
        );
    }

    await supabase.from('recycle_bin').delete().eq('id', row.id);
    return { ok: true, message: '已还原' };
  } catch (err) {
    console.error('restoreRecycleItem failed', err);
    return { ok: false, message: '还原失败,可能存在重复记录或权限不足' };
  }
}

export async function purgeRecycleItem(id: string): Promise<boolean> {
  const { error } = await supabase.from('recycle_bin').delete().eq('id', id);
  return !error;
}

/**
 * Restore many recycle-bin records at once.
 * Returns the count of successfully restored rows.
 */
export async function restoreRecycleItems(
  rows: RecycleRow[],
): Promise<{ restored: number; failed: number }> {
  let restored = 0;
  let failed = 0;
  for (const row of rows) {
    const res = await restoreRecycleItem(row);
    if (res.ok) restored += 1;
    else failed += 1;
  }
  return { restored, failed };
}

/** Permanently delete many recycle-bin records at once. */
export async function purgeRecycleItems(ids: string[]): Promise<boolean> {
  if (ids.length === 0) return true;
  const { error } = await supabase.from('recycle_bin').delete().in('id', ids);
  return !error;
}

export async function emptyRecycleBin(): Promise<boolean> {
  const { error } = await supabase.from('recycle_bin').delete().neq('id', '00000000-0000-0000-0000-000000000000');
  return !error;
}