import { useEffect, useMemo, useState } from 'react';
import { supabase } from '@/lib/supabase';
import { formatTime, type DeploymentRow } from '@/pages/settings/system/types';

const statusMeta: Record<string, { label: string; dot: string; tone: string }> = {
  running: { label: '运行中', dot: 'bg-primary-500', tone: 'bg-primary-100 text-primary-800' },
  degraded: { label: '异常', dot: 'bg-accent-500', tone: 'bg-accent-100 text-accent-900' },
  stopped: { label: '已停止', dot: 'bg-foreground-400', tone: 'bg-secondary-100 text-secondary-900' },
};

function UsageBar({ label, value }: { label: string; value: string | null }) {
  const pct = Number((value ?? '0').replace('%', '')) || 0;
  const tone = pct >= 80 ? 'bg-secondary-600' : pct >= 60 ? 'bg-accent-500' : 'bg-primary-500';
  return (
    <div>
      <div className="flex items-center justify-between text-[10px] text-foreground-500 mb-1">
        <span>{label}</span>
        <span className="font-label">{value ?? '—'}</span>
      </div>
      <div className="h-1.5 rounded-full bg-background-200 overflow-hidden">
        <div className={`h-full rounded-full ${tone}`} style={{ width: `${Math.min(100, pct)}%` }} />
      </div>
    </div>
  );
}

export default function DeployCard() {
  const [rows, setRows] = useState<DeploymentRow[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let active = true;
    (async () => {
      try {
        const { data, error } = await supabase
          .from('deployments')
          .select('*')
          .order('env', { ascending: true })
          .order('service', { ascending: true });
        if (error) throw error;
        if (active) setRows((data as DeploymentRow[]) ?? []);
      } catch (err) {
        console.error(err);
      } finally {
        if (active) setLoading(false);
      }
    })();
    return () => {
      active = false;
    };
  }, []);

  const stats = useMemo(() => {
    const running = rows.filter((r) => r.status === 'running').length;
    const degraded = rows.filter((r) => r.status !== 'running').length;
    const pods = rows.reduce((s, r) => s + (r.ready_replicas ?? 0), 0);
    const totalPods = rows.reduce((s, r) => s + (r.replicas ?? 0), 0);
    return { total: rows.length, running, degraded, pods, totalPods };
  }, [rows]);

  return (
    <div className="rounded-lg bg-background-50 border border-background-200">
      <div className="flex items-center gap-2.5 px-4 md:px-5 py-3.5 border-b border-background-200">
        <span className="w-9 h-9 rounded-md bg-accent-100 text-accent-800 flex items-center justify-center">
          <i className="ri-stack-line text-lg"></i>
        </span>
        <div className="flex-1">
          <h3 className="text-sm font-semibold text-foreground-950">容器化 / 部署状态</h3>
          <p className="text-xs text-foreground-500">Kubernetes 工作负载实时概览</p>
        </div>
        <span className="shrink-0 text-[10px] px-2 py-0.5 rounded-full bg-secondary-100 text-secondary-900 whitespace-nowrap">
          演示数据
        </span>
      </div>

      <div className="grid grid-cols-3 divide-x divide-background-200 border-b border-background-200">
        <div className="px-4 py-3">
          <p className="text-[11px] text-foreground-500">服务</p>
          <p className="mt-0.5 text-lg font-semibold text-foreground-950 font-label">{stats.total}</p>
        </div>
        <div className="px-4 py-3">
          <p className="text-[11px] text-foreground-500">副本就绪</p>
          <p className="mt-0.5 text-lg font-semibold text-foreground-950 font-label">
            {stats.pods}
            <span className="text-xs font-normal text-foreground-500">/{stats.totalPods}</span>
          </p>
        </div>
        <div className="px-4 py-3">
          <p className="text-[11px] text-foreground-500">异常</p>
          <p className={`mt-0.5 text-lg font-semibold font-label ${stats.degraded > 0 ? 'text-accent-700' : 'text-foreground-950'}`}>
            {stats.degraded}
          </p>
        </div>
      </div>

      {loading ? (
        <div className="p-4 md:p-5 space-y-2.5">
          {[0, 1, 2, 3].map((n) => (
            <div key={n} className="h-16 rounded-md bg-background-100 animate-pulse-soft" />
          ))}
        </div>
      ) : (
        <ul className="divide-y divide-background-200 max-h-[360px] overflow-y-auto">
          {rows.map((r) => {
            const meta = statusMeta[r.status ?? 'running'] ?? statusMeta.running;
            return (
              <li key={r.id} className="px-4 md:px-5 py-3">
                <div className="flex items-center gap-2.5">
                  <span className={`w-2 h-2 rounded-full shrink-0 ${meta.dot} ${r.status === 'running' ? 'animate-pulse-soft' : ''}`} />
                  <span className="text-sm font-medium text-foreground-950 truncate">{r.service}</span>
                  <span className="text-[10px] font-label px-1.5 py-0.5 rounded-full bg-background-100 text-foreground-600 uppercase">
                    {r.env}
                  </span>
                  <span className={`ml-auto text-[10px] px-2 py-0.5 rounded-full ${meta.tone}`}>{meta.label}</span>
                </div>
                <div className="mt-1.5 flex flex-wrap items-center gap-x-3 gap-y-1 text-[11px] text-foreground-500">
                  <span className="inline-flex items-center gap-1 font-label">
                    {r.image}:{r.version_tag}
                  </span>
                  <span className="inline-flex items-center gap-1">
                    <i className="ri-stack-line"></i>
                    {r.ready_replicas}/{r.replicas}
                  </span>
                  <span className="inline-flex items-center gap-1">
                    <i className="ri-map-pin-2-line"></i>
                    {r.region}
                  </span>
                  {r.restarts && r.restarts > 0 ? (
                    <span className="inline-flex items-center gap-1 text-accent-700">
                      <i className="ri-restart-line"></i>
                      重启 {r.restarts}
                    </span>
                  ) : null}
                </div>
                <div className="mt-2.5 grid grid-cols-2 gap-3">
                  <UsageBar label="CPU" value={r.cpu_usage} />
                  <UsageBar label="内存" value={r.memory_usage} />
                </div>
              </li>
            );
          })}
        </ul>
      )}
    </div>
  );
}