import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from 'react';
import { supabase } from '@/lib/supabase';

export interface TenantRow {
  id: string;
  name: string;
  code: string | null;
  plan: string | null;
  status: string | null;
  seats: number | null;
  seat_used: number | null;
  contact_email: string | null;
  expires_at: string | null;
  storage_quota_gb: number | null;
  api_quota: number | null;
  api_used: number | null;
  owner: string | null;
  created_at: string | null;
}

interface TenantContextValue {
  tenants: TenantRow[];
  loading: boolean;
  currentTenantId: string;
  currentTenant: TenantRow | null;
  scoped: boolean;
  refreshTenants: () => Promise<void>;
  setCurrentTenantId: (id: string) => void;
}

const STORAGE_KEY = 'readdy.currentTenantId';
const ALL = 'all';

const TenantContext = createContext<TenantContextValue | undefined>(undefined);

export function TenantProvider({ children }: { children: ReactNode }) {
  const [tenants, setTenants] = useState<TenantRow[]>([]);
  const [loading, setLoading] = useState(false);
  const [currentTenantId, setCurrentId] = useState<string>(() => {
    if (typeof window === 'undefined') return ALL;
    return window.localStorage.getItem(STORAGE_KEY) ?? ALL;
  });

  const refreshTenants = useCallback(async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('tenants')
        .select('*')
        .order('created_at', { ascending: true });
      if (error) throw error;
      setTenants((data as TenantRow[]) ?? []);
    } catch (err) {
      console.error('Failed to load tenants', err);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    refreshTenants();
  }, [refreshTenants]);

  const setCurrentTenantId = useCallback((id: string) => {
    setCurrentId(id);
    if (typeof window !== 'undefined') {
      window.localStorage.setItem(STORAGE_KEY, id);
    }
  }, []);

  const currentTenant = useMemo(
    () => (currentTenantId === ALL ? null : tenants.find((t) => t.id === currentTenantId) ?? null),
    [tenants, currentTenantId],
  );

  const value = useMemo<TenantContextValue>(
    () => ({
      tenants,
      loading,
      currentTenantId,
      currentTenant,
      scoped: currentTenantId !== ALL,
      refreshTenants,
      setCurrentTenantId,
    }),
    [tenants, loading, currentTenantId, currentTenant, refreshTenants, setCurrentTenantId],
  );

  return <TenantContext.Provider value={value}>{children}</TenantContext.Provider>;
}

export function useTenant() {
  const ctx = useContext(TenantContext);
  if (!ctx) {
    throw new Error('useTenant must be used within a TenantProvider');
  }
  return ctx;
}