import { useCallback, useEffect, useState } from 'react';
import { supabase } from '@/lib/supabase';
import { useAuth } from '@/contexts/AuthContext';
import { memberLevelMeta, type MemberRow } from '@/pages/member/types';

export default function MemberProfilePage() {
  const { user } = useAuth();
  const [member, setMember] = useState<MemberRow | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const [saving, setSaving] = useState(false);

  const [nickname, setNickname] = useState('');
  const [phone, setPhone] = useState('');
  const [bio, setBio] = useState('');

  const load = useCallback(async () => {
    if (!user) return;
    setLoading(true);
    setError('');
    try {
      const { data, error: err } = await supabase
        .from('members')
        .select('*')
        .eq('id', user.id)
        .maybeSingle();
      if (err) throw err;
      const row = (data as MemberRow) ?? null;
      setMember(row);
      setNickname(row?.nickname ?? '');
      setPhone(row?.phone ?? '');
      setBio(row?.bio ?? '');
    } catch (err) {
      console.error(err);
      setError('加载资料失败,请重试');
    } finally {
      setLoading(false);
    }
  }, [user]);

  useEffect(() => {
    load();
  }, [load]);

  useEffect(() => {
    if (!notice) return;
    const timer = setTimeout(() => setNotice(''), 2600);
    return () => clearTimeout(timer);
  }, [notice]);

  const save = async () => {
    if (!user) return;
    if (!nickname.trim()) {
      setError('昵称不能为空');
      return;
    }
    setSaving(true);
    setError('');
    try {
      const { error: err } = await supabase
        .from('members')
        .update({ nickname: nickname.trim(), phone: phone.trim() || null, bio: bio.trim() || null })
        .eq('id', user.id);
      if (err) throw err;
      setNotice('资料已保存');
      await load();
    } catch (err) {
      console.error(err);
      setError('保存失败,请重试');
    } finally {
      setSaving(false);
    }
  };

  const meta = memberLevelMeta(member?.level ?? null);

  return (
    <div className="space-y-5">
      <div>
        <h1 className="text-lg font-semibold text-foreground-950">我的资料</h1>
        <p className="text-sm text-foreground-500 mt-0.5">维护会员昵称、联系方式与个人简介</p>
      </div>

      {notice ? (
        <div className="flex items-center gap-2 px-3 py-2.5 rounded-md bg-primary-50 text-primary-800 text-sm animate-fade-up">
          <i className="ri-checkbox-circle-line"></i>
          {notice}
        </div>
      ) : null}
      {error ? (
        <div className="flex items-center justify-between gap-3 px-3 py-2.5 rounded-md bg-accent-100 text-accent-900 text-sm">
          {error}
          <button type="button" onClick={load} className="text-xs underline cursor-pointer whitespace-nowrap">
            重试
          </button>
        </div>
      ) : null}

      <div className="grid grid-cols-1 lg:grid-cols-[300px_1fr] gap-4 items-start">
        <div className="rounded-lg bg-background-50 border border-background-200 p-5 text-center">
          <span className={`mx-auto w-20 h-20 rounded-full flex items-center justify-center text-3xl ${meta.tone}`}>
            <i className={meta.icon}></i>
          </span>
          <p className="mt-3 text-base font-semibold text-foreground-950">{member?.nickname || '会员'}</p>
          <p className="text-xs text-foreground-500 mt-0.5">{member?.email}</p>
          <span className={`mt-3 inline-flex items-center gap-1.5 text-[11px] px-2.5 py-1 rounded-full ${meta.tone}`}>
            <i className={meta.icon}></i>
            {meta.label}
          </span>
          <div className="mt-4 grid grid-cols-2 gap-3 text-left">
            <div className="rounded-md bg-background-100 border border-background-200 px-3 py-2.5">
              <p className="text-[11px] text-foreground-500">积分</p>
              <p className="mt-0.5 text-sm font-semibold text-foreground-950 font-label">
                {loading ? '—' : (member?.points ?? 0).toLocaleString()}
              </p>
            </div>
            <div className="rounded-md bg-background-100 border border-background-200 px-3 py-2.5">
              <p className="text-[11px] text-foreground-500">状态</p>
              <p className="mt-0.5 text-sm font-semibold text-foreground-950">
                {member?.status === 'disabled' ? '已停用' : '正常'}
              </p>
            </div>
          </div>
        </div>

        <div className="rounded-lg bg-background-50 border border-background-200 p-5 space-y-4">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3.5">
            <div>
              <label className="block text-xs font-medium text-foreground-700 mb-1.5">昵称</label>
              <input
                type="text"
                value={nickname}
                onChange={(e) => setNickname(e.target.value)}
                placeholder="请输入昵称"
                className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-accent-400"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-foreground-700 mb-1.5">手机号</label>
              <input
                type="text"
                value={phone}
                onChange={(e) => setPhone(e.target.value)}
                placeholder="例如:138-0000-0000"
                className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-accent-400"
              />
            </div>
          </div>

          <div>
            <label className="block text-xs font-medium text-foreground-700 mb-1.5">邮箱(不可修改)</label>
            <input
              type="email"
              value={member?.email ?? ''}
              readOnly
              className="w-full h-10 px-3 rounded-md bg-background-100 border border-background-200 text-sm text-foreground-500 cursor-not-allowed"
            />
          </div>

          <div>
            <label className="block text-xs font-medium text-foreground-700 mb-1.5">个人简介</label>
            <textarea
              value={bio}
              onChange={(e) => setBio(e.target.value)}
              rows={4}
              maxLength={500}
              placeholder="介绍一下自己吧"
              className="w-full px-3 py-2 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-accent-400 resize-none"
            />
            <p className="mt-1 text-[11px] text-foreground-400 text-right">{bio.length}/500</p>
          </div>

          <div className="flex justify-end">
            <button
              type="button"
              onClick={save}
              disabled={saving || loading}
              className="h-10 px-5 rounded-md bg-accent-500 text-background-50 text-sm hover:bg-accent-600 disabled:opacity-60 cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5"
            >
              <i className="ri-save-3-line"></i>
              {saving ? '保存中…' : '保存资料'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}