import { useEffect, useRef } from 'react';
import { cssVar, withAlpha } from '@/lib/themeColor';

export interface ChartSeries {
  name: string;
  color: string;
  data: number[];
}

interface LineChartProps {
  series: ChartSeries[];
  height?: number;
  minValue?: number;
  yFormatter?: (value: number) => string;
}

export default function LineChart({
  series,
  height = 150,
  minValue,
  yFormatter,
}: LineChartProps) {
  const wrapRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const wrap = wrapRef.current;
    const canvas = canvasRef.current;
    if (!wrap || !canvas) return () => undefined;

    let frame = 0;

    const draw = () => {
      const ctx = canvas.getContext('2d');
      if (!ctx) return;
      const dpr = window.devicePixelRatio || 1;
      const width = Math.max(1, wrap.clientWidth);
      const h = height;
      canvas.width = Math.floor(width * dpr);
      canvas.height = Math.floor(h * dpr);
      canvas.style.width = `${width}px`;
      canvas.style.height = `${h}px`;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, width, h);

      const all = series.flatMap((s) => s.data);
      if (all.length === 0) return;

      const maxVal = Math.max(...all);
      const minRaw = minValue != null ? minValue : Math.min(...all);
      const pad = (maxVal - minRaw) * 0.18 || maxVal * 0.1 || 1;
      const top = maxVal + pad;
      const bottom = minValue != null ? minValue : Math.max(0, minRaw - pad);
      const range = top - bottom || 1;

      const padLeft = 6;
      const padRight = 46;
      const padTop = 12;
      const padBottom = 10;
      const plotW = Math.max(1, width - padLeft - padRight);
      const plotH = Math.max(1, h - padTop - padBottom);

      const gridColor = withAlpha(cssVar('--foreground-400', '#9ca3af'), 0.28);
      const labelColor = cssVar('--foreground-400', '#9ca3af');

      ctx.font = '10px "JetBrains Mono", monospace';
      ctx.textBaseline = 'middle';
      ctx.textAlign = 'left';

      const rows = 4;
      for (let r = 0; r <= rows; r += 1) {
        const y = padTop + (plotH * r) / rows;
        ctx.strokeStyle = gridColor;
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(padLeft, y);
        ctx.lineTo(padLeft + plotW, y);
        ctx.stroke();

        const val = top - (range * r) / rows;
        ctx.fillStyle = labelColor;
        const text = yFormatter
          ? yFormatter(val)
          : String(Number.isInteger(val) ? Math.round(val) : Number(val.toFixed(1)));
        ctx.fillText(text, padLeft + plotW + 6, y);
      }

      const n = Math.max(...series.map((s) => s.data.length), 1);
      const xAt = (i: number) => padLeft + (n <= 1 ? 0 : (plotW * i) / (n - 1));
      const yAt = (v: number) => padTop + plotH - ((v - bottom) / range) * plotH;

      series.forEach((s) => {
        if (s.data.length === 0) return;

        // area fill
        ctx.beginPath();
        s.data.forEach((v, i) => {
          const x = xAt(i);
          const y = yAt(v);
          if (i === 0) ctx.moveTo(x, y);
          else ctx.lineTo(x, y);
        });
        const lastX = xAt(s.data.length - 1);
        ctx.lineTo(lastX, padTop + plotH);
        ctx.lineTo(xAt(0), padTop + plotH);
        ctx.closePath();
        const grad = ctx.createLinearGradient(0, padTop, 0, padTop + plotH);
        grad.addColorStop(0, withAlpha(s.color, 0.22));
        grad.addColorStop(1, withAlpha(s.color, 0));
        ctx.fillStyle = grad;
        ctx.fill();

        // line
        ctx.beginPath();
        s.data.forEach((v, i) => {
          const x = xAt(i);
          const y = yAt(v);
          if (i === 0) ctx.moveTo(x, y);
          else ctx.lineTo(x, y);
        });
        ctx.strokeStyle = s.color;
        ctx.lineWidth = 2;
        ctx.lineJoin = 'round';
        ctx.lineCap = 'round';
        ctx.stroke();

        // latest point
        const latest = s.data[s.data.length - 1];
        const lx = xAt(s.data.length - 1);
        const ly = yAt(latest);
        ctx.beginPath();
        ctx.arc(lx, ly, 3.2, 0, Math.PI * 2);
        ctx.fillStyle = s.color;
        ctx.fill();
        ctx.beginPath();
        ctx.arc(lx, ly, 6.5, 0, Math.PI * 2);
        ctx.fillStyle = withAlpha(s.color, 0.22);
        ctx.fill();
      });
    };

    const schedule = () => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(draw);
    };

    schedule();
    const observer = new ResizeObserver(schedule);
    observer.observe(wrap);
    return () => {
      observer.disconnect();
      cancelAnimationFrame(frame);
    };
  }, [series, height, minValue, yFormatter]);

  return (
    <div ref={wrapRef} className="w-full">
      <canvas ref={canvasRef} className="block" />
    </div>
  );
}