import { useEffect, useRef } from 'react';
import { supabase } from '@/lib/supabase';

/**
 * 控制台后台心跳:
 * 只要后台界面处于打开状态,每隔一段时间就向后端发起一次「到点检查」,
 * 由数据库调度器判断哪些定时任务已到期并自动执行(含补跑错过的任务)。
 *
 * 说明:该托管后端不支持 pg_cron / pg_net,无法做到无人值守的 24×7 后台触发,
 * 因此采用「数据库到点执行器 + 控制台心跳」的组合来摆脱纯手动执行。
 */
export function useSchedulerHeartbeat(intervalMs = 60000) {
  const busyRef = useRef(false);

  useEffect(() => {
    let cancelled = false;
    let timer: ReturnType<typeof setInterval> | null = null;

    const tick = async () => {
      if (busyRef.current || cancelled) return;
      busyRef.current = true;
      try {
        await supabase.functions.invoke('run-scheduled-task', { body: { mode: 'due' } });
      } catch (err) {
        // 心跳失败不打扰用户,静默记录
        console.error('[scheduler-heartbeat]', err);
      } finally {
        busyRef.current = false;
      }
    };

    // 打开控制台先补跑一次,之后按间隔轮询
    void tick();
    timer = setInterval(tick, intervalMs);

    return () => {
      cancelled = true;
      if (timer) clearInterval(timer);
    };
  }, [intervalMs]);
}