import { useCallback, useEffect, useMemo, useRef, useState, type ReactNode } from 'react';
import { supabase } from '@/lib/supabase';
import { useAuth } from '@/contexts/AuthContext';
import Modal from '@/components/base/Modal';
import { DATA_SCOPE_OPTIONS, dataScopeLabel } from '@/hooks/useDataScope';
import { moveToRecycleBin } from '@/lib/recycleBin';
import { recordAuditLog } from '@/lib/auditLog';
import {
  recordRolePermissionChange,
  fetchRolePermissionChanges,
  type RolePermissionChange,
  type PermRef,
} from '@/lib/rolePermissionChanges';

interface RoleRow {
  id: string;
  name: string;
  code: string | null;
  description: string | null;
  data_scope: string | null;
  created_at: string | null;
}

interface PermRow {
  id: string;
  name: string;
  code: string | null;
  type: string;
  parent_id: string | null;
  sort_order: number | null;
}

interface RolePermRow {
  role_id: string;
  permission_id: string;
}

interface PermNode extends PermRow {
  children: PermNode[];
}

const typeMeta: Record<string, { label: string; tone: string }> = {
  menu: { label: '菜单', tone: 'bg-primary-100 text-primary-800' },
  button: { label: '按钮', tone: 'bg-accent-100 text-accent-900' },
  api: { label: '接口', tone: 'bg-secondary-200 text-secondary-900' },
};

/** 支持半选态的复选框:原生 indeterminate 只能通过 ref 设置 */
function TreeCheckbox({
  checked,
  indeterminate,
  onChange,
  disabled,
}: {
  checked: boolean;
  indeterminate: boolean;
  onChange: () => void;
  disabled?: boolean;
}) {
  const ref = useRef<HTMLInputElement>(null);
  useEffect(() => {
    if (ref.current) ref.current.indeterminate = indeterminate;
  }, [indeterminate]);
  return (
    <input
      ref={ref}
      type="checkbox"
      checked={checked}
      onChange={onChange}
      disabled={disabled}
      className="w-4 h-4 accent-primary-500 cursor-pointer shrink-0 disabled:cursor-not-allowed"
    />
  );
}

export default function RolesPage() {
  const { hasPermission } = useAuth();
  const canCreate = hasPermission('role:create');
  const canUpdate = hasPermission('role:update');
  const canAssign = hasPermission('role:assign_perm');
  const canDelete = hasPermission('role:delete');

  const [roles, setRoles] = useState<RoleRow[]>([]);
  const [permissions, setPermissions] = useState<PermRow[]>([]);
  const [rolePerms, setRolePerms] = useState<RolePermRow[]>([]);
  const [userCounts, setUserCounts] = useState<Record<string, number>>({});
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');

  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [checked, setChecked] = useState<Set<string>>(new Set());
  const [savingPerms, setSavingPerms] = useState(false);

  // 权限变更历史(授予前后对比)
  const [permHistoryOpen, setPermHistoryOpen] = useState(false);
  const [permHistory, setPermHistory] = useState<RolePermissionChange[]>([]);
  const [permHistoryLoading, setPermHistoryLoading] = useState(false);

  const [editOpen, setEditOpen] = useState(false);
  const [editingRole, setEditingRole] = useState<RoleRow | null>(null);
  const [form, setForm] = useState({ name: '', code: '', description: '', data_scope: 'all' });
  const [formError, setFormError] = useState('');
  const [savingRole, setSavingRole] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState<RoleRow | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const [roleRes, permRes, rpRes, urRes] = await Promise.all([
        supabase.from('roles').select('*').order('created_at', { ascending: true }),
        supabase.from('permissions').select('*').order('sort_order', { ascending: true }),
        supabase.from('role_permissions').select('role_id, permission_id'),
        supabase.from('user_roles').select('role_id'),
      ]);
      if (roleRes.error) throw roleRes.error;
      const roleList = (roleRes.data as RoleRow[]) ?? [];
      setRoles(roleList);
      setPermissions((permRes.data as PermRow[]) ?? []);
      setRolePerms((rpRes.data as RolePermRow[]) ?? []);

      const counts: Record<string, number> = {};
      ((urRes.data as { role_id: string }[]) ?? []).forEach((row) => {
        counts[row.role_id] = (counts[row.role_id] ?? 0) + 1;
      });
      setUserCounts(counts);

      setSelectedId((prev) => prev ?? roleList[0]?.id ?? null);
    } catch (err) {
      console.error(err);
      setError('加载角色数据失败,请重试');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  useEffect(() => {
    if (!notice) return;
    const timer = setTimeout(() => setNotice(''), 2600);
    return () => clearTimeout(timer);
  }, [notice]);

  useEffect(() => {
    if (!selectedId) {
      setChecked(new Set());
      return;
    }
    const ids = rolePerms.filter((rp) => rp.role_id === selectedId).map((rp) => rp.permission_id);
    setChecked(new Set(ids));
  }, [selectedId, rolePerms]);

  const permCountByRole = useMemo(() => {
    const map: Record<string, number> = {};
    rolePerms.forEach((rp) => {
      map[rp.role_id] = (map[rp.role_id] ?? 0) + 1;
    });
    return map;
  }, [rolePerms]);

  // 构建多层权限树 + 父级索引,支持任意层级深度的渲染与勾选联动
  const { tree, parentMap, descendantIds } = useMemo(() => {
    const byParent: Record<string, PermRow[]> = {};
    const parentMap: Record<string, string | null> = {};
    permissions.forEach((p) => {
      parentMap[p.id] = p.parent_id;
      const key = p.parent_id ?? 'root';
      (byParent[key] ||= []).push(p);
    });
    const build = (key: string): PermNode[] =>
      (byParent[key] ?? [])
        .slice()
        .sort((a, b) => (a.sort_order ?? 0) - (b.sort_order ?? 0))
        .map((p) => ({ ...p, children: build(p.id) }));
    const tree = build('root');

    // 后序构建每个节点的全部后代 id
    const descendantIds: Record<string, string[]> = {};
    const buildDesc = (nodes: PermNode[]) => {
      nodes.forEach((n) => {
        buildDesc(n.children);
        descendantIds[n.id] = n.children.flatMap((c) => [c.id, ...(descendantIds[c.id] ?? [])]);
      });
    };
    buildDesc(tree);

    return { tree, parentMap, descendantIds };
  }, [permissions]);

  const collectIds = useCallback((node: PermNode): string[] => [node.id, ...(descendantIds[node.id] ?? [])], [descendantIds]);

  const groupState = useCallback(
    (node: PermNode) => {
      const ids = collectIds(node);
      const count = ids.filter((id) => checked.has(id)).length;
      return { all: ids.length > 0 && count === ids.length, partial: count > 0 && count < ids.length };
    },
    [checked, collectIds],
  );

  const toggleGroup = useCallback(
    (node: PermNode) => {
      const ids = collectIds(node);
      const allChecked = ids.every((id) => checked.has(id));
      setChecked((prev) => {
        const next = new Set(prev);
        if (allChecked) ids.forEach((id) => next.delete(id));
        else ids.forEach((id) => next.add(id));
        return next;
      });
    },
    [checked, collectIds],
  );

  // 勾选叶子:选中时自动带上所有父级菜单;取消时若父级已无任何被选子项则一并取消
  const toggleLeaf = useCallback(
    (node: PermNode) => {
      setChecked((prev) => {
        const next = new Set(prev);
        if (next.has(node.id)) {
          next.delete(node.id);
          let parent = parentMap[node.id] ?? null;
          while (parent) {
            const hasCheckedChild = (descendantIds[parent] ?? []).some((id) => next.has(id));
            if (!hasCheckedChild) next.delete(parent);
            parent = parentMap[parent] ?? null;
          }
        } else {
          next.add(node.id);
          let parent = parentMap[node.id] ?? null;
          while (parent) {
            next.add(parent);
            parent = parentMap[parent] ?? null;
          }
        }
        return next;
      });
    },
    [parentMap, descendantIds],
  );

  // 超级管理员为内置角色,始终拥有全部权限,权限树锁定不可编辑
  const selectedIsSuperAdmin = roles.find((r) => r.id === selectedId)?.code === 'super_admin';

  const renderNode = (node: PermNode, depth: number): ReactNode => {
    const st = groupState(node);
    return (
      <div key={node.id}>
        <label
          className="flex items-center gap-2.5 py-1.5 cursor-pointer hover:bg-background-100/60 rounded-md"
          style={{ paddingLeft: depth * 22 + 4, paddingRight: 4 }}
        >
          <TreeCheckbox
            checked={st.all}
            indeterminate={st.partial}
            onChange={() => (node.children.length > 0 ? toggleGroup(node) : toggleLeaf(node))}
            disabled={!canAssign || selectedIsSuperAdmin}
          />
          <span className="text-sm text-foreground-800">{node.name}</span>
          <span className={`text-[10px] px-1.5 py-0.5 rounded-full ${typeMeta[node.type]?.tone ?? typeMeta.menu.tone}`}>
            {typeMeta[node.type]?.label ?? node.type}
          </span>
          {node.code ? <span className="text-[11px] text-foreground-500 font-label">{node.code}</span> : null}
        </label>
        {node.children.length > 0 ? <div>{node.children.map((child) => renderNode(child, depth + 1))}</div> : null}
      </div>
    );
  };

  // 按差异增量保存:只新增勾上的、只删除取消的,避免「先清空再写入」时中途失败导致权限全丢
  const savePermissions = async () => {
    if (!selectedId) return;
    setSavingPerms(true);
    try {
      const current = rolePerms
        .filter((rp) => rp.role_id === selectedId)
        .map((rp) => rp.permission_id);
      const next = Array.from(checked);
      const toAdd = next.filter((id) => !current.includes(id));
      const toRemove = current.filter((id) => !next.includes(id));
      if (toRemove.length > 0) {
        const { error: delErr } = await supabase
          .from('role_permissions')
          .delete()
          .eq('role_id', selectedId)
          .in('permission_id', toRemove);
        if (delErr) throw delErr;
      }
      if (toAdd.length > 0) {
        const { error: insErr } = await supabase
          .from('role_permissions')
          .insert(toAdd.map((pid) => ({ role_id: selectedId, permission_id: pid })));
        if (insErr) throw insErr;
      }
      // 记录「变更前后对比」:具体新增/移除了哪些权限点,便于回查每次授权改了什么
      if (toAdd.length > 0 || toRemove.length > 0) {
        const permById = new Map(permissions.map((p) => [p.id, p]));
        const toRef = (id: string): PermRef => ({
          name: permById.get(id)?.name ?? id,
          code: permById.get(id)?.code ?? null,
        });
        await recordRolePermissionChange({
          roleId: selectedId,
          roleName: selectedRole?.name ?? '未知角色',
          beforeCount: current.length,
          afterCount: next.length,
          added: toAdd.map(toRef),
          removed: toRemove.map(toRef),
        });
      }
      setNotice('权限配置已保存');
      await recordAuditLog({
        action: '修改角色权限',
        module: '角色管理',
        detail: `修改「${selectedRole?.name ?? '角色'}」的权限,新增 ${toAdd.length} 项 / 移除 ${toRemove.length} 项,当前共 ${next.length} 项`,
      });
      await load();
      if (permHistoryOpen) await openPermHistory();
    } catch (err) {
      console.error(err);
      setError((err as { message?: string })?.message || '保存权限失败,可能权限不足');
    } finally {
      setSavingPerms(false);
    }
  };

  // 打开/刷新当前角色的权限变更历史
  const openPermHistory = async () => {
    if (!selectedId) return;
    setPermHistoryOpen(true);
    setPermHistoryLoading(true);
    try {
      setPermHistory(await fetchRolePermissionChanges(selectedId, 30));
    } catch (err) {
      console.error(err);
      setPermHistory([]);
    } finally {
      setPermHistoryLoading(false);
    }
  };

  const openCreateRole = () => {
    setEditingRole(null);
    setForm({ name: '', code: '', description: '', data_scope: 'all' });
    setFormError('');
    setEditOpen(true);
  };

  const openEditRole = (role: RoleRow) => {
    setEditingRole(role);
    setForm({
      name: role.name,
      code: role.code ?? '',
      description: role.description ?? '',
      data_scope: role.data_scope ?? 'all',
    });
    setFormError('');
    setEditOpen(true);
  };

  const isBuiltinSuperAdmin = editingRole?.code === 'super_admin';

  const submitRole = async () => {
    if (!form.name.trim()) {
      setFormError('请输入角色名称');
      return;
    }
    // 内置超管角色标识不可修改,否则会破坏超管的权限旁路
    const codeValue = isBuiltinSuperAdmin ? 'super_admin' : form.code.trim() || null;
    if (codeValue) {
      const dup = roles.some((r) => r.code === codeValue && r.id !== editingRole?.id);
      if (dup) {
        setFormError('该角色标识已被占用,请换一个');
        return;
      }
    }
    setSavingRole(true);
    try {
      const payload = {
        name: form.name,
        code: codeValue,
        description: form.description,
        data_scope: form.data_scope,
      };
      if (editingRole) {
        const { error: err } = await supabase.from('roles').update(payload).eq('id', editingRole.id);
        if (err) throw err;
        setNotice('角色已更新');
        await recordAuditLog({
          action: '修改角色',
          module: '角色管理',
          detail: `修改角色「${payload.name}」`,
        });
      } else {
        const { error: err } = await supabase.from('roles').insert(payload);
        if (err) throw err;
        setNotice('角色创建成功');
        await recordAuditLog({
          action: '新增角色',
          module: '角色管理',
          detail: `新增角色「${payload.name}」`,
        });
      }
      setEditOpen(false);
      setEditingRole(null);
      await load();
    } catch (err) {
      console.error(err);
      setFormError('保存失败,请检查权限后重试');
    } finally {
      setSavingRole(false);
    }
  };

  const confirmDeleteRole = async () => {
    if (!deleteTarget) return;
    // 超级管理员是系统内置角色,删除会导致整个权限体系失去根基
    if (deleteTarget.code === 'super_admin') {
      setError('超级管理员为系统内置角色,不可删除');
      setDeleteTarget(null);
      return;
    }
    try {
      // 记录该角色现有的权限关联,删除后可在回收站还原
      const rolePermIds = rolePerms
        .filter((rp) => rp.role_id === deleteTarget.id)
        .map((rp) => rp.permission_id);
      // 表之间没有外键约束,必须手动清理用户关联与权限关联,否则会留下孤儿记录
      const { error: urErr } = await supabase
        .from('user_roles')
        .delete()
        .eq('role_id', deleteTarget.id);
      if (urErr) throw urErr;
      const { error: rpErr } = await supabase
        .from('role_permissions')
        .delete()
        .eq('role_id', deleteTarget.id);
      if (rpErr) throw rpErr;
      const { error: err } = await supabase.from('roles').delete().eq('id', deleteTarget.id);
      if (err) throw err;
      // 删除成功后再写入回收站
      await moveToRecycleBin({
        module: 'role',
        itemId: deleteTarget.id,
        itemName: deleteTarget.name,
        snapshot: {
          id: deleteTarget.id,
          name: deleteTarget.name,
          code: deleteTarget.code,
          description: deleteTarget.description,
          data_scope: deleteTarget.data_scope ?? 'all',
          _permissions: rolePermIds,
        },
      });
      setNotice('角色已删除');
      await recordAuditLog({
        action: '删除角色',
        module: '角色管理',
        level: 'warn',
        detail: `删除角色「${deleteTarget.name}」,同时移除 ${rolePermIds.length} 项权限关联`,
      });
      if (selectedId === deleteTarget.id) setSelectedId(null);
      setDeleteTarget(null);
      await load();
    } catch (err) {
      console.error(err);
      setError((err as { message?: string })?.message || '删除角色失败,请稍后重试');
      setDeleteTarget(null);
    }
  };

  const selectedRole = roles.find((r) => r.id === selectedId) ?? null;
  const deleteMemberCount = deleteTarget ? (userCounts[deleteTarget.id] ?? 0) : 0;

  return (
    <div className="space-y-4">
      <div className="flex flex-col md:flex-row md:items-center gap-3">
        <div>
          <h2 className="text-lg font-semibold text-foreground-950">角色管理</h2>
          <p className="text-sm text-foreground-500 mt-0.5">定义角色并为其分配细粒度的权限资源</p>
        </div>
        <button
          type="button"
          onClick={openCreateRole}
          disabled={!canCreate}
          className="md:ml-auto h-9 px-3.5 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 disabled:opacity-50 cursor-pointer whitespace-nowrap flex items-center gap-1.5 dark:text-foreground-950"
        >
          <i className="ri-add-line"></i>
          新增角色
        </button>
      </div>

      {notice ? (
        <div className="flex items-center gap-2 px-3 py-2.5 rounded-md bg-primary-50 text-primary-800 text-sm animate-fade-up">
          <i className="ri-checkbox-circle-line"></i>
          {notice}
        </div>
      ) : null}
      {error ? (
        <div className="flex items-center justify-between gap-3 px-3 py-2.5 rounded-md bg-accent-100 text-accent-900 text-sm">
          {error}
          <button type="button" onClick={load} className="text-xs underline cursor-pointer whitespace-nowrap">
            重试
          </button>
        </div>
      ) : null}

      <div className="grid grid-cols-1 lg:grid-cols-[320px_1fr] gap-4">
        {/* Role list */}
        <div className="space-y-2.5">
          {loading
            ? [0, 1, 2].map((n) => (
                <div key={n} className="h-20 rounded-lg bg-background-50 border border-background-200 animate-pulse-soft" />
              ))
            : roles.map((role) => {
                const active = role.id === selectedId;
                return (
                  <button
                    key={role.id}
                    type="button"
                    onClick={() => setSelectedId(role.id)}
                    className={`w-full text-left rounded-lg border p-3.5 cursor-pointer transition-colors ${
                      active
                        ? 'bg-background-50 border-primary-400'
                        : 'bg-background-50 border-background-200 hover:border-background-300'
                    }`}
                  >
                    <div className="flex items-center justify-between gap-2">
                      <span className="text-sm font-medium text-foreground-950 truncate">{role.name}</span>
                      {active ? <i className="ri-checkbox-circle-fill text-primary-500"></i> : null}
                    </div>
                    <p className="mt-1 text-xs text-foreground-500 line-clamp-2">{role.description || '暂无描述'}</p>
                    <div className="mt-2.5 flex items-center gap-3 text-[11px] text-foreground-500 flex-wrap">
                      <span className="flex items-center gap-1">
                        <i className="ri-key-2-line"></i>
                        {permCountByRole[role.id] ?? 0} 权限
                      </span>
                      <span className="flex items-center gap-1">
                        <i className="ri-user-line"></i>
                        {userCounts[role.id] ?? 0} 用户
                      </span>
                      <span className="font-label px-1.5 py-0.5 rounded-full bg-accent-100 text-accent-900">
                        {dataScopeLabel[role.data_scope ?? 'all'] ?? '全部数据'}
                      </span>
                      {role.code ? (
                        <span className="font-label px-1.5 py-0.5 rounded-full bg-secondary-100 text-secondary-900">
                          {role.code}
                        </span>
                      ) : null}
                    </div>
                  </button>
                );
              })}
        </div>

        {/* Permission panel */}
        <div className="rounded-lg bg-background-50 border border-background-200">
          {!selectedRole ? (
            <div className="flex flex-col items-center justify-center py-24 text-foreground-500">
              <i className="ri-shield-keyhole-line text-3xl mb-2"></i>
              <p className="text-sm">请选择左侧角色以配置权限</p>
            </div>
          ) : (
            <>
              <div className="flex flex-col sm:flex-row sm:items-center gap-3 px-4 md:px-5 py-4 border-b border-background-200">
                <div className="min-w-0">
                  <h3 className="text-sm font-semibold text-foreground-950 truncate">
                    为「{selectedRole.name}」配置权限
                  </h3>
                  {selectedIsSuperAdmin ? (
                    <p className="text-xs text-primary-700 mt-0.5 flex items-center gap-1">
                      <i className="ri-shield-star-line"></i>
                      内置角色,自动拥有全部 {permissions.length} 项权限,无需单独配置
                    </p>
                  ) : (
                    <p className="text-xs text-foreground-500 mt-0.5">
                      已选 {checked.size} / {permissions.length} 项
                    </p>
                  )}
                </div>
                <div className="sm:ml-auto flex items-center gap-2">
                  <button
                    type="button"
                    onClick={openPermHistory}
                    disabled={selectedIsSuperAdmin}
                    title={selectedIsSuperAdmin ? '内置角色拥有全部权限,无需记录' : '查看该角色的权限变更历史'}
                    className="h-8 px-3 rounded-md bg-background-100 border border-background-300 text-xs text-foreground-800 hover:bg-background-200 disabled:opacity-40 disabled:cursor-not-allowed cursor-pointer whitespace-nowrap"
                  >
                    <i className="ri-history-line mr-1"></i>
                    变更记录
                  </button>
                  <button
                    type="button"
                    onClick={() => openEditRole(selectedRole)}
                    disabled={!canUpdate}
                    className="h-8 px-3 rounded-md bg-background-100 border border-background-300 text-xs text-foreground-800 hover:bg-background-200 disabled:opacity-40 cursor-pointer whitespace-nowrap"
                  >
                    <i className="ri-edit-line mr-1"></i>
                    编辑角色
                  </button>
                  <button
                    type="button"
                    onClick={() => setDeleteTarget(selectedRole)}
                    disabled={!canDelete || selectedRole.code === 'super_admin'}
                    title={selectedRole.code === 'super_admin' ? '内置角色不可删除' : undefined}
                    className="h-8 px-3 rounded-md bg-background-100 border border-background-300 text-xs text-foreground-800 hover:bg-secondary-200 disabled:opacity-40 disabled:cursor-not-allowed cursor-pointer whitespace-nowrap"
                  >
                    <i className="ri-delete-bin-line mr-1"></i>
                    删除
                  </button>
                  <button
                    type="button"
                    onClick={savePermissions}
                    disabled={!canAssign || savingPerms || selectedIsSuperAdmin}
                    className="h-8 px-3.5 rounded-md bg-primary-500 text-background-50 text-xs hover:bg-primary-600 disabled:opacity-50 cursor-pointer whitespace-nowrap dark:text-foreground-950"
                  >
                    {savingPerms ? '保存中…' : '保存权限'}
                  </button>
                </div>
              </div>

              <div className="p-4 md:p-5 space-y-3 max-h-[560px] overflow-y-auto">
                {tree.map((menu) => {
                  const st = groupState(menu);
                  return (
                    <div key={menu.id} className="rounded-md border border-background-200">
                      <label className="flex items-center gap-3 px-3.5 py-2.5 cursor-pointer">
                        <TreeCheckbox
                          checked={st.all}
                          indeterminate={st.partial}
                          onChange={() => toggleGroup(menu)}
                          disabled={!canAssign || selectedIsSuperAdmin}
                        />
                        <i className="ri-folders-line text-foreground-500 w-4 h-4 flex items-center justify-center"></i>
                        <span className="text-sm font-medium text-foreground-900">{menu.name}</span>
                        <span className={`ml-auto text-[10px] px-1.5 py-0.5 rounded-full ${typeMeta.menu.tone}`}>
                          菜单
                        </span>
                      </label>
                      {menu.children.length > 0 ? (
                        <div className="px-3.5 pb-2.5 border-t border-background-200 pt-1.5">
                          {menu.children.map((child) => renderNode(child, 0))}
                        </div>
                      ) : null}
                    </div>
                  );
                })}
              </div>
            </>
          )}
        </div>
      </div>

      {/* Role create/edit modal */}
      <Modal
        open={editOpen}
        title={editingRole ? '编辑角色' : '新增角色'}
        onClose={() => setEditOpen(false)}
        footer={
          <>
            <button
              type="button"
              onClick={() => setEditOpen(false)}
              className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
            >
              取消
            </button>
            <button
              type="button"
              onClick={submitRole}
              disabled={savingRole}
              className="h-9 px-4 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 disabled:opacity-60 cursor-pointer whitespace-nowrap dark:text-foreground-950"
            >
              {savingRole ? '保存中…' : '保存'}
            </button>
          </>
        }
      >
        <div className="space-y-3.5">
          <div>
            <label className="block text-xs font-medium text-foreground-700 mb-1.5">角色名称</label>
            <input
              type="text"
              value={form.name}
              onChange={(e) => setForm((p) => ({ ...p, name: e.target.value }))}
              placeholder="例如:内容运营"
              className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400"
            />
          </div>
          <div>
            <label className="block text-xs font-medium text-foreground-700 mb-1.5">角色标识(可选)</label>
            <input
              type="text"
              value={form.code}
              onChange={(e) => setForm((p) => ({ ...p, code: e.target.value }))}
              disabled={Boolean(isBuiltinSuperAdmin)}
              placeholder="例如:content_operator"
              className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400 font-label disabled:bg-background-100 disabled:text-foreground-500 disabled:cursor-not-allowed"
            />
            {isBuiltinSuperAdmin ? (
              <p className="mt-1.5 text-[11px] text-foreground-500">
                超级管理员为系统内置角色,标识已锁定,不可修改。
              </p>
            ) : null}
          </div>
          <div>
            <label className="block text-xs font-medium text-foreground-700 mb-1.5">描述</label>
            <textarea
              value={form.description}
              onChange={(e) => setForm((p) => ({ ...p, description: e.target.value }))}
              rows={3}
              maxLength={500}
              placeholder="简要描述该角色的职责范围"
              className="w-full px-3 py-2 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400 resize-none"
            />
          </div>
          <div>
            <label className="block text-xs font-medium text-foreground-700 mb-1.5">数据权限范围</label>
            <select
              value={form.data_scope}
              onChange={(e) => setForm((p) => ({ ...p, data_scope: e.target.value }))}
              className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400 cursor-pointer"
            >
              {DATA_SCOPE_OPTIONS.map((o) => (
                <option key={o.value} value={o.value}>
                  {o.label}
                </option>
              ))}
            </select>
            <p className="mt-1.5 text-[11px] text-foreground-500">
              {DATA_SCOPE_OPTIONS.find((o) => o.value === form.data_scope)?.desc}
            </p>
          </div>
          {formError ? (
            <div className="flex items-start gap-2 px-3 py-2.5 rounded-md bg-accent-100 text-accent-900 text-xs">
              <i className="ri-error-warning-line mt-0.5"></i>
              <span>{formError}</span>
            </div>
          ) : null}
        </div>
      </Modal>

      <Modal
        open={Boolean(deleteTarget)}
        title="删除角色"
        onClose={() => setDeleteTarget(null)}
        footer={
          <>
            <button
              type="button"
              onClick={() => setDeleteTarget(null)}
              className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
            >
              取消
            </button>
            <button
              type="button"
              onClick={confirmDeleteRole}
              className="h-9 px-4 rounded-md bg-secondary-700 text-background-50 text-sm hover:bg-secondary-800 cursor-pointer whitespace-nowrap"
            >
              确认删除
            </button>
          </>
        }
      >
        <p className="text-sm text-foreground-700">
          确定删除角色
          <span className="font-medium text-foreground-950"> {deleteTarget?.name} </span>
          吗?对应的权限关联也将一并移除。
        </p>
        {deleteMemberCount > 0 ? (
          <div className="mt-3 flex items-start gap-2 px-3 py-2.5 rounded-md bg-accent-100 text-accent-900 text-xs">
            <i className="ri-error-warning-line mt-0.5"></i>
            <span>
              该角色当前关联 <strong>{deleteMemberCount}</strong> 个用户,删除后这些用户将失去该角色及其带来的权限。
            </span>
          </div>
        ) : null}
      </Modal>

      <Modal
        open={permHistoryOpen}
        title="权限变更记录"
        subtitle={selectedRole ? `角色:${selectedRole.name} · 最近 30 次授权调整` : ''}
        width="max-w-2xl"
        onClose={() => setPermHistoryOpen(false)}
        footer={
          <button
            type="button"
            onClick={() => setPermHistoryOpen(false)}
            className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
          >
            关闭
          </button>
        }
      >
        {permHistoryLoading ? (
          <div className="space-y-2.5">
            {[0, 1, 2].map((n) => (
              <div key={n} className="h-20 rounded-md bg-background-100 animate-pulse-soft" />
            ))}
          </div>
        ) : permHistory.length === 0 ? (
          <div className="py-14 text-center text-foreground-500">
            <i className="ri-history-line text-2xl block mb-2"></i>
            该角色暂无权限变更记录
          </div>
        ) : (
          <ul className="space-y-3">
            {permHistory.map((change) => (
              <li key={change.id} className="rounded-md border border-background-200 bg-background-50 px-3.5 py-3">
                <div className="flex flex-wrap items-center gap-2">
                  <span className="inline-flex items-center gap-1.5 text-xs font-label">
                    <span className="text-foreground-500">{change.before_count} 项</span>
                    <i className="ri-arrow-right-line text-foreground-400"></i>
                    <span className="px-1.5 py-0.5 rounded-full bg-primary-100 text-primary-800 font-semibold">
                      {change.after_count} 项
                    </span>
                  </span>
                  <span className="text-[11px] text-foreground-600">操作人:{change.operator_name || '未知'}</span>
                  <span className="ml-auto text-[10px] text-foreground-500 font-label whitespace-nowrap">
                    {change.created_at ? new Date(change.created_at).toLocaleString() : ''}
                  </span>
                </div>
                <div className="mt-2.5 space-y-1.5">
                  {change.added.length > 0 ? (
                    <div className="flex flex-wrap items-center gap-1.5">
                      <span className="text-[11px] text-foreground-500 shrink-0">新增</span>
                      {change.added.map((p) => (
                        <span
                          key={`add-${change.id}-${p.code ?? p.name}`}
                          className="inline-flex items-center gap-1 text-[11px] px-2 py-0.5 rounded-full bg-primary-100 text-primary-800"
                        >
                          <i className="ri-add-line"></i>
                          {p.name}
                        </span>
                      ))}
                    </div>
                  ) : null}
                  {change.removed.length > 0 ? (
                    <div className="flex flex-wrap items-center gap-1.5">
                      <span className="text-[11px] text-foreground-500 shrink-0">移除</span>
                      {change.removed.map((p) => (
                        <span
                          key={`rm-${change.id}-${p.code ?? p.name}`}
                          className="inline-flex items-center gap-1 text-[11px] px-2 py-0.5 rounded-full bg-accent-100 text-accent-900 line-through"
                        >
                          <i className="ri-subtract-line"></i>
                          {p.name}
                        </span>
                      ))}
                    </div>
                  ) : null}
                  {change.added.length === 0 && change.removed.length === 0 ? (
                    <p className="text-[11px] text-foreground-500">本次保存未改变权限项</p>
                  ) : null}
                </div>
              </li>
            ))}
          </ul>
        )}
      </Modal>
    </div>
  );
}