import { useState } from 'react';
import { NavLink, Outlet, useNavigate } from 'react-router-dom';
import { supabase } from '@/lib/supabase';
import { recordLogoutLog } from '@/lib/loginLog';

const links = [
  { to: '/member', label: '会员概览', icon: 'ri-dashboard-line', end: true },
  { to: '/member/profile', label: '我的资料', icon: 'ri-user-settings-line', end: false },
];

export default function MemberLayout() {
  const navigate = useNavigate();
  const [menuOpen, setMenuOpen] = useState(false);

  const signOut = async () => {
    await recordLogoutLog();
    await supabase.auth.signOut();
    navigate('/member/login', { replace: true });
  };

  return (
    <div className="min-h-screen flex flex-col bg-background-100">
      <header className="sticky top-0 z-30 bg-background-50 border-b border-background-200">
        <div className="flex items-center gap-4 h-16 px-4 md:px-6">
          <NavLink to="/member" className="flex items-center gap-2.5 shrink-0">
            <div className="w-9 h-9 rounded-lg bg-accent-500 flex items-center justify-center">
              <i className="ri-vip-crown-line text-lg text-background-50"></i>
            </div>
            <div className="leading-tight hidden sm:block">
              <p className="text-sm font-semibold text-foreground-950">HuaanMembers</p>
              <p className="text-[11px] text-foreground-500">会员中心</p>
            </div>
          </NavLink>

          <nav className="hidden md:flex items-center gap-1 ml-4">
            {links.map((l) => (
              <NavLink
                key={l.to}
                to={l.to}
                end={l.end}
                className={({ isActive }) =>
                  `inline-flex items-center gap-1.5 h-9 px-3.5 rounded-md text-sm cursor-pointer transition-colors ${
                    isActive
                      ? 'bg-accent-100 text-accent-900 font-medium'
                      : 'text-foreground-700 hover:bg-background-100'
                  }`
                }
              >
                <i className={l.icon}></i>
                {l.label}
              </NavLink>
            ))}
          </nav>

          <div className="ml-auto flex items-center gap-2">
            <NavLink
              to="/auth"
              className="hidden sm:inline-flex items-center gap-1.5 h-9 px-3.5 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
            >
              <i className="ri-shield-user-line"></i>
              管理后台
            </NavLink>
            <button
              type="button"
              onClick={signOut}
              className="inline-flex items-center gap-1.5 h-9 px-3.5 rounded-md bg-accent-500 text-background-50 text-sm hover:bg-accent-600 cursor-pointer whitespace-nowrap"
            >
              <i className="ri-logout-box-r-line"></i>
              退出
            </button>
            <button
              type="button"
              onClick={() => setMenuOpen((v) => !v)}
              className="md:hidden w-9 h-9 flex items-center justify-center rounded-md bg-background-100 border border-background-300 text-foreground-800 cursor-pointer"
              aria-label="菜单"
            >
              <i className={menuOpen ? 'ri-close-line' : 'ri-menu-line'}></i>
            </button>
          </div>
        </div>

        {menuOpen ? (
          <nav className="md:hidden border-t border-background-200 px-3 py-2 space-y-1">
            {links.map((l) => (
              <NavLink
                key={l.to}
                to={l.to}
                end={l.end}
                onClick={() => setMenuOpen(false)}
                className={({ isActive }) =>
                  `flex items-center gap-2 h-10 px-3 rounded-md text-sm cursor-pointer ${
                    isActive ? 'bg-accent-100 text-accent-900 font-medium' : 'text-foreground-700 hover:bg-background-100'
                  }`
                }
              >
                <i className={l.icon}></i>
                {l.label}
              </NavLink>
            ))}
          </nav>
        ) : null}
      </header>

      <main className="flex-1 px-4 md:px-6 py-6">
        <div className="mx-auto w-full max-w-[1100px] animate-fade-up">
          <Outlet />
        </div>
      </main>

      <footer className="bg-secondary-100 border-t border-secondary-200">
        <div className="mx-auto max-w-[1100px] px-4 md:px-6 py-4 flex flex-col sm:flex-row items-center gap-2 text-xs text-secondary-900">
          <span className="inline-flex items-center gap-1.5">
            <i className="ri-vip-crown-line"></i>
            HuaanMembers 会员中心
          </span>
          <span className="sm:ml-auto">会员数据由 Readdy Backend 安全存储</span>
        </div>
      </footer>
    </div>
  );
}