import i18n from '@/i18n';
import { supabase } from '@/lib/supabase';

interface LangStringRow {
  lang: string | null;
  namespace: string | null;
  str_key: string | null;
  value: string | null;
}

/**
 * 把「多语言包管理」里维护的词条加载进前端 i18n。
 *
 * 数据库 language_strings 按 lang / namespace / str_key 存储,
 * 这里在应用启动时把它合并为 i18n 的 resource bundle(覆盖同名的静态词条)。
 * 之后任何通过 t('key', { ns: 'namespace' }) 读取的文案都会使用这里的值。
 * 采用尽力而为策略:失败只记录日志,不阻塞应用启动。
 */
export async function loadRemoteStrings(): Promise<boolean> {
  try {
    const { data, error } = await supabase
      .from('language_strings')
      .select('lang, namespace, str_key, value');
    if (error) throw error;

    const byLang: Record<string, Record<string, Record<string, string>>> = {};
    (data as LangStringRow[] | null)?.forEach((row) => {
      const lang = row.lang;
      const ns = row.namespace || 'translation';
      const key = row.str_key;
      if (!lang || !key) return;
      if (!byLang[lang]) byLang[lang] = {};
      if (!byLang[lang][ns]) byLang[lang][ns] = {};
      byLang[lang][ns][key] = row.value ?? '';
    });

    Object.entries(byLang).forEach(([lang, nsMap]) => {
      Object.entries(nsMap).forEach(([ns, bundle]) => {
        i18n.addResourceBundle(lang, ns, bundle, true, true);
      });
    });
    return true;
  } catch (err) {
    console.error('loadRemoteStrings failed', err);
    return false;
  }
}