import { useCallback, useEffect, useMemo, useState, type ReactNode } from 'react';
import { supabase } from '@/lib/supabase';
import { cssVar } from '@/lib/themeColor';
import { METRIC_META, useLiveMetrics, type MetricKey } from '@/hooks/useLiveMetrics';
import LineChart from '@/pages/dashboard/components/LineChart';
import MetricCard from '@/pages/dashboard/components/MetricCard';
import HealthPanel from '@/pages/dashboard/components/HealthPanel';

interface AlertRow {
  id: string;
  action: string | null;
  module: string | null;
  level: string | null;
  detail: string | null;
  created_at: string;
}

const intervalOptions = [
  { value: 2000, label: '2 秒' },
  { value: 3000, label: '3 秒' },
  { value: 5000, label: '5 秒' },
  { value: 10000, label: '10 秒' },
];

function timeAgo(iso: string) {
  const diff = Date.now() - new Date(iso).getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return '刚刚';
  if (mins < 60) return `${mins} 分钟前`;
  const hours = Math.floor(mins / 60);
  if (hours < 24) return `${hours} 小时前`;
  return `${Math.floor(hours / 24)} 天前`;
}

function ChartCard({
  title,
  subtitle,
  legend,
  children,
}: {
  title: string;
  subtitle?: string;
  legend?: { label: string; color: string }[];
  children: ReactNode;
}) {
  return (
    <section className="rounded-lg bg-background-50 border border-background-200 p-4 md:p-5">
      <div className="flex items-start justify-between gap-3 mb-1">
        <div>
          <h3 className="text-sm font-semibold text-foreground-950">{title}</h3>
          {subtitle ? <p className="text-xs text-foreground-500 mt-0.5">{subtitle}</p> : null}
        </div>
        {legend ? (
          <div className="flex flex-wrap items-center gap-3">
            {legend.map((l) => (
              <span key={l.label} className="inline-flex items-center gap-1.5 text-[11px] text-foreground-600">
                <span className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: l.color }} />
                {l.label}
              </span>
            ))}
          </div>
        ) : null}
      </div>
      <div className="mt-3">{children}</div>
    </section>
  );
}

export default function DashboardPage() {
  const { series, loading, error, reload, paused, setPaused, intervalMs, setIntervalMs } =
    useLiveMetrics();
  const [alerts, setAlerts] = useState<AlertRow[]>([]);

  const colors = useMemo(
    () => ({
      primary: cssVar('--primary-500', '#0d9488'),
      accent: cssVar('--accent-500', '#d97706'),
      secondary: cssVar('--secondary-600', '#7c6f5f'),
      foreground: cssVar('--foreground-400', '#9ca3af'),
    }),
    [],
  );

  const loadAlerts = useCallback(async () => {
    try {
      const { data } = await supabase
        .from('audit_logs')
        .select('id, action, module, level, detail, created_at')
        .in('level', ['warn', 'error'])
        .order('created_at', { ascending: false })
        .limit(6);
      setAlerts((data as AlertRow[]) ?? []);
    } catch (err) {
      console.error(err);
    }
  }, []);

  useEffect(() => {
    loadAlerts();
  }, [loadAlerts]);

  const last = useCallback((k: MetricKey) => {
    const arr = series[k];
    return arr.length ? arr[arr.length - 1].v : 0;
  }, [series]);

  const delta = useCallback(
    (k: MetricKey) => {
      const arr = series[k];
      if (arr.length < 2) return 0;
      const prev = arr[arr.length - 2].v;
      if (!prev) return 0;
      return ((arr[arr.length - 1].v - prev) / prev) * 100;
    },
    [series],
  );

  const qps = last('qps');
  const latency = last('avg_latency');
  const errorRate = last('error_rate');
  const cpu = last('cpu_usage');
  const memory = last('memory_usage');
  const online = last('online_users');

  const fmt = (v: number, decimals: number) => v.toFixed(decimals);
  const ready = !loading && series.qps.length > 0;

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center gap-3">
        <div>
          <div className="flex items-center gap-2">
            <h2 className="text-lg font-semibold text-foreground-950">实时监控仪表盘</h2>
            <span className="text-[10px] px-2 py-0.5 rounded-full bg-secondary-100 text-secondary-900 whitespace-nowrap">
              演示数据
            </span>
          </div>
          <p className="text-sm text-foreground-500 mt-0.5">
            系统关键指标实时采集,每 {intervalMs / 1000} 秒刷新一次(演示数据,前端模拟波动)
          </p>
        </div>
        <div className="md:ml-auto flex flex-wrap items-center gap-2">
          <span className="inline-flex items-center gap-2 h-9 px-3 rounded-md bg-background-50 border border-background-200 text-xs text-foreground-700">
            <span
              className={`w-2 h-2 rounded-full ${paused ? 'bg-foreground-400' : 'bg-primary-500 animate-pulse-soft'}`}
            />
            {paused ? '已暂停' : '实时采集中'}
          </span>
          <select
            value={intervalMs}
            onChange={(e) => setIntervalMs(Number(e.target.value))}
            className="h-9 px-3 rounded-md bg-background-50 border border-background-200 text-sm text-foreground-800 focus:outline-none cursor-pointer"
          >
            {intervalOptions.map((opt) => (
              <option key={opt.value} value={opt.value}>
                每 {opt.label}
              </option>
            ))}
          </select>
          <button
            type="button"
            onClick={() => setPaused(!paused)}
            className="h-9 px-3.5 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-800 hover:bg-background-100 cursor-pointer whitespace-nowrap flex items-center gap-1.5"
          >
            <i className={paused ? 'ri-play-line' : 'ri-pause-line'}></i>
            {paused ? '继续' : '暂停'}
          </button>
          <button
            type="button"
            onClick={reload}
            className="h-9 px-3.5 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 cursor-pointer whitespace-nowrap flex items-center gap-1.5 dark:text-foreground-950"
          >
            <i className="ri-refresh-line"></i>
            刷新
          </button>
        </div>
      </div>

      {error ? (
        <div className="flex items-center justify-between gap-3 rounded-lg bg-accent-100 border border-accent-200 px-4 py-3">
          <span className="text-sm text-accent-900">{error}</span>
          <button
            type="button"
            onClick={reload}
            className="h-8 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-800 hover:bg-background-100 cursor-pointer whitespace-nowrap"
          >
            重试
          </button>
        </div>
      ) : null}

      {/* KPI cards */}
      <section className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-3 md:gap-4">
        <MetricCard
          label={METRIC_META.qps.label}
          value={ready ? fmt(qps, 1) : '—'}
          unit={METRIC_META.qps.unit}
          change={delta('qps')}
          icon="ri-flashlight-line"
          tone="bg-primary-100 text-primary-700"
          color={colors.primary}
          data={series.qps.map((p) => p.v)}
        />
        <MetricCard
          label={METRIC_META.avg_latency.label}
          value={ready ? fmt(latency, 0) : '—'}
          unit={METRIC_META.avg_latency.unit}
          change={delta('avg_latency')}
          icon="ri-timer-flash-line"
          tone="bg-accent-100 text-accent-800"
          color={colors.accent}
          data={series.avg_latency.map((p) => p.v)}
          lowerIsBetter
        />
        <MetricCard
          label={METRIC_META.error_rate.label}
          value={ready ? fmt(errorRate, 2) : '—'}
          unit={METRIC_META.error_rate.unit}
          change={delta('error_rate')}
          icon="ri-error-warning-line"
          tone="bg-secondary-200 text-secondary-900"
          color={colors.secondary}
          data={series.error_rate.map((p) => p.v)}
          lowerIsBetter
          minValue={0}
        />
        <MetricCard
          label={METRIC_META.online_users.label}
          value={ready ? fmt(online, 0) : '—'}
          unit={METRIC_META.online_users.unit}
          change={delta('online_users')}
          icon="ri-group-line"
          tone="bg-primary-100 text-primary-700"
          color={colors.primary}
          data={series.online_users.map((p) => p.v)}
        />
      </section>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-4">
        <div className="xl:col-span-2 space-y-4">
          <ChartCard
            title="请求吞吐量 (QPS)"
            subtitle="API 网关每秒处理请求数 · 近 45 个采样点"
          >
            <LineChart
              series={[{ name: 'QPS', color: colors.primary, data: series.qps.map((p) => p.v) }]}
              height={190}
            />
          </ChartCard>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <ChartCard title="响应延迟" subtitle="平均 P95 耗时 (ms)">
              <LineChart
                series={[{ name: '延迟', color: colors.accent, data: series.avg_latency.map((p) => p.v) }]}
                height={150}
              />
            </ChartCard>
            <ChartCard title="错误率" subtitle="5xx 占比 (%)">
              <LineChart
                series={[{ name: '错误率', color: colors.secondary, data: series.error_rate.map((p) => p.v) }]}
                height={150}
                minValue={0}
              />
            </ChartCard>
          </div>

          <ChartCard
            title="资源占用"
            subtitle="集群节点平均使用率 (%)"
            legend={[
              { label: 'CPU', color: colors.primary },
              { label: '内存', color: colors.accent },
            ]}
          >
            <LineChart
              series={[
                { name: 'CPU', color: colors.primary, data: series.cpu_usage.map((p) => p.v) },
                { name: '内存', color: colors.accent, data: series.memory_usage.map((p) => p.v) },
              ]}
              height={160}
            />
          </ChartCard>
        </div>

        <div className="space-y-4">
          <HealthPanel
            latency={latency}
            errorRate={errorRate}
            cpu={cpu}
            memory={memory}
            onlineUsers={online}
          />

          <section className="rounded-lg bg-background-50 border border-background-200 p-4 md:p-5">
            <div className="flex items-center justify-between mb-3">
              <h3 className="text-sm font-semibold text-foreground-950">最近告警</h3>
              <span className="text-[11px] px-2 py-0.5 rounded-full bg-secondary-100 text-secondary-900">
                {alerts.length} 条
              </span>
            </div>
            {alerts.length === 0 ? (
              <p className="text-sm text-foreground-500 py-8 text-center">暂无告警,系统运行平稳</p>
            ) : (
              <ul className="space-y-2.5">
                {alerts.map((a) => (
                  <li key={a.id} className="flex items-start gap-2.5">
                    <span
                      className={`mt-0.5 w-6 h-6 rounded-md flex items-center justify-center shrink-0 ${
                        a.level === 'error'
                          ? 'bg-secondary-200 text-secondary-900'
                          : 'bg-accent-100 text-accent-800'
                      }`}
                    >
                      <i className={`${a.level === 'error' ? 'ri-close-circle-line' : 'ri-alert-line'} text-sm`}></i>
                    </span>
                    <div className="min-w-0 flex-1">
                      <p className="text-sm text-foreground-900 truncate">{a.action}</p>
                      <p className="text-[11px] text-foreground-500 truncate">{a.detail}</p>
                      <div className="mt-0.5 flex items-center gap-2 text-[10px] text-foreground-400">
                        <span className="font-label">{a.module}</span>
                        <span>{a.created_at ? timeAgo(a.created_at) : ''}</span>
                      </div>
                    </div>
                  </li>
                ))}
              </ul>
            )}
          </section>
        </div>
      </div>
    </div>
  );
}