import { useEffect, useMemo, useState } from 'react';
import Modal from '@/components/base/Modal';
import type { MarketPlugin } from '@/pages/plugins/marketCatalog';

interface MarketDetailModalProps {
  open: boolean;
  plugin: MarketPlugin | null;
  installedMap: Record<string, { enabled: boolean; name: string }>;
  canManage: boolean;
  onClose: () => void;
  onInstall: (plugin: MarketPlugin) => Promise<void>;
}

const tabs = [
  { key: 'overview', label: '概览', icon: 'ri-information-line' },
  { key: 'deps', label: '依赖关系', icon: 'ri-git-branch-line' },
  { key: 'changelog', label: '更新日志', icon: 'ri-history-line' },
];

function formatDate(iso: string) {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return iso;
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

function Stars({ rating }: { rating: number }) {
  return (
    <span className="inline-flex items-center gap-0.5" title={`${rating} 分`}>
      {[1, 2, 3, 4, 5].map((n) => (
        <i
          key={n}
          className={`text-[12px] ${
            rating >= n - 0.25
              ? 'ri-star-fill text-accent-500'
              : rating >= n - 0.75
                ? 'ri-star-half-fill text-accent-500'
                : 'ri-star-line text-foreground-300'
          }`}
        ></i>
      ))}
    </span>
  );
}

export default function MarketDetailModal({
  open,
  plugin,
  installedMap,
  canManage,
  onClose,
  onInstall,
}: MarketDetailModalProps) {
  const [tab, setTab] = useState('overview');
  const [installing, setInstalling] = useState(false);

  useEffect(() => {
    setTab('overview');
  }, [plugin]);

  const deps = useMemo(() => plugin?.dependencies ?? [], [plugin]);
  const changelog = useMemo(() => plugin?.changelog ?? [], [plugin]);

  const runInstall = async () => {
    if (!plugin) return;
    setInstalling(true);
    try {
      await onInstall(plugin);
    } finally {
      setInstalling(false);
    }
  };

  const installed = plugin ? Boolean(installedMap[plugin.code]) : false;

  return (
    <Modal
      open={open}
      title={plugin?.name ?? '插件详情'}
      subtitle={plugin ? `${plugin.code} · 最新 v${plugin.latest_version ?? plugin.version}` : ''}
      onClose={onClose}
      width="max-w-2xl"
      footer={
        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={onClose}
            className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
          >
            关闭
          </button>
          <button
            type="button"
            onClick={runInstall}
            disabled={!canManage || installed || installing}
            className="h-9 px-4 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 disabled:opacity-50 cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5 dark:text-foreground-950"
          >
            <i className={installing ? 'ri-loader-4-line animate-spin' : installed ? 'ri-check-line' : 'ri-install-line'}></i>
            {installed ? '已安装' : installing ? '安装中' : '立即安装'}
          </button>
        </div>
      }
    >
      {!plugin ? null : (
        <div className="space-y-4">
          <div className="flex items-start gap-3">
            <span className="w-12 h-12 rounded-lg flex items-center justify-center bg-primary-100 text-primary-700 shrink-0">
              <i className="ri-plug-2-line text-2xl"></i>
            </span>
            <div className="min-w-0 flex-1">
              <div className="flex flex-wrap items-center gap-2">
                <span className="text-[11px] px-2 py-0.5 rounded-full bg-secondary-200 text-secondary-900">{plugin.category}</span>
                <span className="text-[11px] px-2 py-0.5 rounded-full bg-background-200 text-foreground-700 font-label">v{plugin.version}</span>
              </div>
              <div className="mt-1.5 flex items-center gap-2">
                <Stars rating={plugin.rating} />
                <span className="text-sm font-semibold text-foreground-950 font-label">{plugin.rating.toFixed(1)}</span>
                <span className="text-[11px] text-foreground-400">{plugin.reviewCount} 条评价</span>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-3 gap-3">
            {[
              { label: '下载量', value: plugin.downloads.toLocaleString(), icon: 'ri-download-2-line' },
              { label: '开发者', value: plugin.author, icon: 'ri-user-3-line' },
              { label: '依赖项', value: `${deps.length} 个`, icon: 'ri-git-branch-line' },
            ].map((item) => (
              <div key={item.label} className="rounded-md bg-background-100 border border-background-200 px-3 py-2.5">
                <div className="flex items-center gap-1.5 text-[11px] text-foreground-500">
                  <i className={item.icon}></i>
                  {item.label}
                </div>
                <p className="mt-1 text-sm text-foreground-900 truncate">{item.value}</p>
              </div>
            ))}
          </div>

          <div className="flex items-center gap-1 p-1 rounded-full bg-background-100 border border-background-200 w-fit">
            {tabs.map((t) => (
              <button
                key={t.key}
                type="button"
                onClick={() => setTab(t.key)}
                className={`px-3 py-1.5 rounded-full text-xs cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5 transition-colors ${
                  tab === t.key
                    ? 'bg-background-50 text-foreground-950 font-medium'
                    : 'text-foreground-600 hover:text-foreground-900'
                }`}
              >
                <i className={t.icon}></i>
                {t.label}
              </button>
            ))}
          </div>

          {tab === 'overview' ? (
            <div className="space-y-3">
              <p className="text-sm text-foreground-700 leading-relaxed">{plugin.description}</p>
              <div className="flex items-center gap-2 text-xs text-foreground-600">
                <i className="ri-link"></i>
                <span className="font-label truncate">{plugin.homepage}</span>
              </div>
              {plugin.latest_version ? (
                <div className="flex items-center gap-2 rounded-md bg-accent-100/70 border border-accent-200 px-3 py-2 text-xs text-accent-900">
                  <i className="ri-arrow-up-circle-line"></i>
                  已发布新版本 v{plugin.latest_version},安装后可直接热更新
                </div>
              ) : null}
            </div>
          ) : null}

          {tab === 'deps' ? (
            <div>
              {deps.length === 0 ? (
                <p className="text-xs text-foreground-500">该插件无外部依赖,可独立运行</p>
              ) : (
                <ul className="space-y-2">
                  {deps.map((d) => {
                    const target = installedMap[d.code];
                    const satisfied = Boolean(target && target.enabled);
                    return (
                      <li
                        key={d.code}
                        className="flex items-center gap-3 rounded-md bg-background-100 border border-background-200 px-3 py-2.5"
                      >
                        <span
                          className={`w-7 h-7 rounded-md flex items-center justify-center shrink-0 ${
                            satisfied ? 'bg-primary-100 text-primary-700' : 'bg-accent-100 text-accent-900'
                          }`}
                        >
                          <i className={satisfied ? 'ri-check-line' : 'ri-error-warning-line'}></i>
                        </span>
                        <div className="min-w-0 flex-1">
                          <p className="text-xs text-foreground-900 truncate">
                            {d.name}
                            {d.required ? (
                              <span className="text-accent-700 ml-1">必需</span>
                            ) : (
                              <span className="text-foreground-400 ml-1">可选</span>
                            )}
                          </p>
                          <p className="text-[10px] font-label text-foreground-500">
                            {d.code} {d.version}
                          </p>
                        </div>
                        <span
                          className={`text-[10px] px-2 py-0.5 rounded-full whitespace-nowrap ${
                            satisfied
                              ? 'bg-primary-100 text-primary-800'
                              : target
                                ? 'bg-secondary-200 text-secondary-900'
                                : 'bg-accent-100 text-accent-900'
                          }`}
                        >
                          {satisfied ? '已启用' : target ? '未启用' : '未安装'}
                        </span>
                      </li>
                    );
                  })}
                </ul>
              )}
            </div>
          ) : null}

          {tab === 'changelog' ? (
            <div>
              {changelog.length === 0 ? (
                <p className="text-xs text-foreground-500">暂无更新记录</p>
              ) : (
                <ol className="relative pl-5">
                  <span className="absolute left-[5px] top-1.5 bottom-1.5 w-px bg-background-300" />
                  {changelog.map((c, i) => (
                    <li key={c.version} className="relative mb-4 last:mb-0">
                      <span
                        className={`absolute -left-5 top-1 w-2.5 h-2.5 rounded-full ${
                          i === 0 ? 'bg-accent-500' : 'bg-background-400'
                        }`}
                      />
                      <div className="flex items-center gap-2">
                        <span className="text-sm font-medium text-foreground-950 font-label">v{c.version}</span>
                        <span className="text-[11px] text-foreground-500 font-label">{formatDate(c.date)}</span>
                        {i === 0 ? (
                          <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-accent-100 text-accent-900">最新</span>
                        ) : null}
                      </div>
                      <ul className="mt-1.5 space-y-1">
                        {c.notes.map((n) => (
                          <li key={n} className="flex items-start gap-1.5 text-xs text-foreground-700">
                            <i className="ri-subtract-line mt-1 text-foreground-400"></i>
                            {n}
                          </li>
                        ))}
                      </ul>
                    </li>
                  ))}
                </ol>
              )}
            </div>
          ) : null}
        </div>
      )}
    </Modal>
  );
}