import { useMemo, useState, type ComponentType } from 'react';
import { useSearchParams } from 'react-router-dom';
import DocSidebar from '@/pages/docs/components/DocSidebar';
import { docSections, findDocSection } from '@/pages/docs/types';
import IntroSection from '@/pages/docs/sections/IntroSection';
import QuickstartSection from '@/pages/docs/sections/QuickstartSection';
import StructureSection from '@/pages/docs/sections/StructureSection';
import PermissionSection from '@/pages/docs/sections/PermissionSection';
import ApiSection from '@/pages/docs/sections/ApiSection';
import SdkSection from '@/pages/docs/sections/SdkSection';
import PluginSection from '@/pages/docs/sections/PluginSection';
import FaqSection from '@/pages/docs/sections/FaqSection';

const renderMap: Record<string, ComponentType> = {
  intro: IntroSection,
  quickstart: QuickstartSection,
  structure: StructureSection,
  permission: PermissionSection,
  api: ApiSection,
  sdk: SdkSection,
  plugin: PluginSection,
  faq: FaqSection,
};

export default function DocsPage() {
  const [params, setParams] = useSearchParams();
  const activeId = params.get('section') && findDocSection(params.get('section') as string)
    ? (params.get('section') as string)
    : 'intro';
  const [keyword, setKeyword] = useState('');

  const active = findDocSection(activeId);
  const index = docSections.findIndex((s) => s.id === activeId);
  const prev = index > 0 ? docSections[index - 1] : null;
  const next = index < docSections.length - 1 ? docSections[index + 1] : null;

  const SectionBody = renderMap[activeId] ?? IntroSection;

  const matches = useMemo(() => {
    const kw = keyword.trim().toLowerCase();
    if (!kw) return [];
    return docSections.filter(
      (s) => s.label.toLowerCase().includes(kw) || s.summary.toLowerCase().includes(kw),
    );
  }, [keyword]);

  const go = (id: string) => {
    setParams({ section: id }, { replace: false });
    setKeyword('');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return (
    <div className="space-y-4">
      <section className="rounded-lg bg-background-50 border border-background-200 p-5 md:p-6">
        <div className="flex flex-col md:flex-row md:items-center gap-4">
          <div className="flex-1">
            <div className="flex items-center gap-2 text-xs text-foreground-500">
              <i className="ri-book-2-line"></i>
              <span>开发者文档</span>
              <i className="ri-arrow-right-s-line"></i>
              <span className="text-foreground-800">{active?.label}</span>
            </div>
            <h2 className="mt-2 text-xl md:text-2xl font-semibold text-foreground-950 font-heading">
              快速上手 HuaanAdmin
            </h2>
            <p className="mt-1.5 text-sm text-foreground-600 max-w-2xl">
              框架介绍、接入指南、权限体系与扩展开发的完整说明,按左侧章节循序渐进阅读。
            </p>
          </div>
          <div className="relative w-full md:w-72">
            <div className="flex items-center gap-2 h-10 px-3 rounded-md bg-background-100 border border-background-200">
              <i className="ri-search-line text-foreground-400"></i>
              <input
                type="text"
                value={keyword}
                onChange={(e) => setKeyword(e.target.value)}
                placeholder="搜索文档章节…"
                className="flex-1 bg-transparent text-sm text-foreground-900 placeholder:text-foreground-400 focus:outline-none"
              />
              {keyword ? (
                <button
                  type="button"
                  onClick={() => setKeyword('')}
                  className="w-5 h-5 flex items-center justify-center text-foreground-400 hover:text-foreground-700 cursor-pointer"
                  aria-label="清空"
                >
                  <i className="ri-close-line text-sm"></i>
                </button>
              ) : null}
            </div>
            {keyword ? (
              <div className="absolute z-30 mt-1.5 w-full rounded-lg bg-background-50 border border-background-200 py-1.5 animate-fade-up max-h-72 overflow-y-auto">
                {matches.length === 0 ? (
                  <p className="px-3 py-2 text-sm text-foreground-500">没有匹配的章节</p>
                ) : (
                  matches.map((s) => (
                    <button
                      key={s.id}
                      type="button"
                      onClick={() => go(s.id)}
                      className="w-full flex items-start gap-2.5 px-3 py-2 text-left hover:bg-background-100 cursor-pointer"
                    >
                      <i className={`${s.icon} text-foreground-400 mt-0.5`}></i>
                      <span className="min-w-0">
                        <span className="block text-sm text-foreground-900">{s.label}</span>
                        <span className="block text-[11px] text-foreground-500 truncate">{s.summary}</span>
                      </span>
                    </button>
                  ))
                )}
              </div>
            ) : null}
          </div>
        </div>
      </section>

      <div className="grid grid-cols-1 lg:grid-cols-[264px_1fr] gap-4 items-start">
        <DocSidebar activeId={activeId} onSelect={go} />

        <article className="min-w-0 rounded-lg bg-background-50 border border-background-200 p-5 md:p-7">
          <SectionBody />

          <div className="mt-8 pt-5 border-t border-background-200 flex flex-col sm:flex-row gap-3">
            {prev ? (
              <button
                type="button"
                onClick={() => go(prev.id)}
                className="group flex-1 flex items-center gap-3 rounded-md border border-background-200 px-4 py-3 hover:border-primary-300 hover:bg-primary-50/40 cursor-pointer transition-colors text-left"
              >
                <i className="ri-arrow-left-line text-foreground-400 group-hover:text-primary-600"></i>
                <span className="min-w-0">
                  <span className="block text-[11px] text-foreground-400">上一篇</span>
                  <span className="block text-sm text-foreground-900 truncate">{prev.label}</span>
                </span>
              </button>
            ) : (
              <div className="hidden sm:block flex-1" />
            )}
            {next ? (
              <button
                type="button"
                onClick={() => go(next.id)}
                className="group flex-1 flex items-center justify-end gap-3 rounded-md border border-background-200 px-4 py-3 hover:border-primary-300 hover:bg-primary-50/40 cursor-pointer transition-colors text-right"
              >
                <span className="min-w-0">
                  <span className="block text-[11px] text-foreground-400">下一篇</span>
                  <span className="block text-sm text-foreground-900 truncate">{next.label}</span>
                </span>
                <i className="ri-arrow-right-line text-foreground-400 group-hover:text-primary-600"></i>
              </button>
            ) : null}
          </div>
        </article>
      </div>
    </div>
  );
}