import { useEffect, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { supabase } from '@/lib/supabase';

interface NotifyRow {
  id: string;
  title: string;
  content: string | null;
  category: string | null;
  level: string | null;
  is_read: boolean | null;
  created_at: string | null;
}

const levelStyle: Record<string, string> = {
  warn: 'bg-accent-100 text-accent-900',
  error: 'bg-secondary-200 text-secondary-900',
  info: 'bg-primary-100 text-primary-800',
};

function timeAgo(iso: string | null) {
  if (!iso) return '';
  const diff = Date.now() - new Date(iso).getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return '刚刚';
  if (mins < 60) return `${mins} 分钟前`;
  const hours = Math.floor(mins / 60);
  if (hours < 24) return `${hours} 小时前`;
  return `${Math.floor(hours / 24)} 天前`;
}

export default function NotificationMenu() {
  const navigate = useNavigate();
  const [open, setOpen] = useState(false);
  const [rows, setRows] = useState<NotifyRow[]>([]);
  const [unread, setUnread] = useState(0);
  const [loading, setLoading] = useState(false);
  const wrapRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const onClick = (e: MouseEvent) => {
      if (wrapRef.current && !wrapRef.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener('mousedown', onClick);
    return () => document.removeEventListener('mousedown', onClick);
  }, []);

  const load = async () => {
    setLoading(true);
    try {
      const [listRes, countRes] = await Promise.all([
        supabase
          .from('notifications')
          .select('id, title, content, category, level, is_read, created_at')
          .order('created_at', { ascending: false })
          .limit(6),
        supabase.from('notifications').select('id', { count: 'exact', head: true }).eq('is_read', false),
      ]);
      if (listRes.error) throw listRes.error;
      setRows((listRes.data as NotifyRow[]) ?? []);
      setUnread(countRes.count ?? 0);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
  }, []);

  const handleToggle = () => {
    const next = !open;
    setOpen(next);
    if (next) load();
  };

  return (
    <div className="relative" ref={wrapRef}>
      <button
        type="button"
        onClick={handleToggle}
        className="relative w-9 h-9 flex items-center justify-center rounded-md text-foreground-600 hover:bg-background-100 cursor-pointer"
        aria-label="通知"
      >
        <i className="ri-notification-3-line text-lg"></i>
        {unread > 0 ? (
          <span className="absolute top-1.5 right-1.5 min-w-[15px] h-[15px] px-1 rounded-full bg-accent-500 text-background-50 text-[9px] font-label flex items-center justify-center">
            {unread > 9 ? '9+' : unread}
          </span>
        ) : null}
      </button>

      {open ? (
        <div className="absolute right-0 mt-2 w-80 rounded-lg bg-background-50 border border-background-200 py-1.5 animate-fade-up z-30">
          <div className="flex items-center justify-between px-3 py-1.5">
            <span className="text-sm font-medium text-foreground-950">通知中心</span>
            <span className="text-[11px] text-foreground-400">
              {unread > 0 ? `${unread} 条未读` : '全部已读'}
            </span>
          </div>
          <div className="my-1 border-t border-background-200" />
          {loading ? (
            <div className="px-3 py-3 space-y-2">
              {[0, 1, 2].map((n) => (
                <div key={n} className="h-9 rounded-md bg-background-100 animate-pulse-soft" />
              ))}
            </div>
          ) : rows.length === 0 ? (
            <p className="px-3 py-6 text-center text-sm text-foreground-500">暂无通知</p>
          ) : (
            <div className="max-h-72 overflow-y-auto">
              {rows.map((row) => (
                <button
                  key={row.id}
                  type="button"
                  onClick={() => {
                    setOpen(false);
                    navigate('/settings/notifications');
                  }}
                  className="w-full flex items-start gap-2.5 px-3 py-2.5 text-left hover:bg-background-100 cursor-pointer"
                >
                  <span
                    className={`mt-0.5 w-1.5 h-1.5 rounded-full shrink-0 ${
                      row.is_read ? 'bg-background-300' : 'bg-accent-500'
                    }`}
                  />
                  <span className="min-w-0 flex-1">
                    <span className="block text-sm text-foreground-900 truncate">{row.title}</span>
                    <span className="mt-1 flex items-center gap-2 text-[11px] text-foreground-500">
                      <span className={`px-1.5 py-0.5 rounded-full ${levelStyle[row.level || 'info'] || levelStyle.info}`}>
                        {row.category || '系统'}
                      </span>
                      <span>{timeAgo(row.created_at)}</span>
                    </span>
                  </span>
                </button>
              ))}
            </div>
          )}
          <div className="my-1 border-t border-background-200" />
          <button
            type="button"
            onClick={() => {
              setOpen(false);
              navigate('/settings/notifications');
            }}
            className="w-full px-3 py-2 text-sm text-primary-700 hover:bg-background-100 cursor-pointer text-center whitespace-nowrap"
          >
            查看全部通知
          </button>
        </div>
      ) : null}
    </div>
  );
}