import { useEffect, useState } from 'react';

interface RoleBadge {
  id: string;
  name: string;
  code: string | null;
}

interface ProfileCardProps {
  fullName: string;
  email: string;
  tenantName: string;
  createdAt: string;
  roles: RoleBadge[];
  saving: boolean;
  message: string;
  onSave: (name: string) => void;
}

function formatDate(iso: string) {
  if (!iso) return '—';
  const d = new Date(iso);
  const p = (n: number) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
}

export default function ProfileCard({
  fullName,
  email,
  tenantName,
  createdAt,
  roles,
  saving,
  message,
  onSave,
}: ProfileCardProps) {
  const [name, setName] = useState(fullName);

  useEffect(() => {
    setName(fullName);
  }, [fullName]);

  const initial = (fullName || email || 'U').slice(0, 1).toUpperCase();
  const dirty = name.trim() !== fullName.trim();

  return (
    <section className="rounded-lg bg-background-50 border border-background-200 p-4 md:p-5">
      <h3 className="text-sm font-semibold text-foreground-950">基本资料</h3>
      <p className="text-xs text-foreground-500 mt-0.5">更新你的昵称与账号信息</p>

      <div className="mt-4 flex items-center gap-4">
        <span className="w-14 h-14 rounded-full bg-primary-100 text-primary-700 flex items-center justify-center text-xl font-semibold shrink-0">
          {initial}
        </span>
        <div className="min-w-0">
          <p className="text-sm font-medium text-foreground-950 truncate">{fullName || '未设置昵称'}</p>
          <p className="text-xs text-foreground-500 truncate">{email}</p>
          <div className="mt-1.5 flex flex-wrap gap-1.5">
            {roles.length === 0 ? (
              <span className="text-[11px] text-foreground-400">未分配角色</span>
            ) : (
              roles.map((r) => (
                <span key={r.id} className="text-[11px] px-2 py-0.5 rounded-full bg-secondary-100 text-secondary-900">
                  {r.name}
                </span>
              ))
            )}
          </div>
        </div>
      </div>

      <div className="mt-5 space-y-3.5">
        <div>
          <label className="block text-xs font-medium text-foreground-700 mb-1.5">昵称</label>
          <input
            type="text"
            value={name}
            maxLength={40}
            onChange={(e) => setName(e.target.value)}
            placeholder="请输入昵称"
            className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400"
          />
        </div>
        <div>
          <label className="block text-xs font-medium text-foreground-700 mb-1.5">登录邮箱</label>
          <input
            type="email"
            value={email}
            readOnly
            className="w-full h-10 px-3 rounded-md bg-background-100 border border-background-200 text-sm text-foreground-500 cursor-not-allowed"
          />
        </div>

        <div className="grid grid-cols-2 gap-3">
          <div className="rounded-md bg-background-100 px-3 py-2.5">
            <p className="text-[11px] text-foreground-500">所属租户</p>
            <p className="text-sm text-foreground-900 mt-0.5 truncate">{tenantName || '默认租户'}</p>
          </div>
          <div className="rounded-md bg-background-100 px-3 py-2.5">
            <p className="text-[11px] text-foreground-500">注册时间</p>
            <p className="text-sm text-foreground-900 mt-0.5 font-label">{formatDate(createdAt)}</p>
          </div>
        </div>
      </div>

      <div className="mt-4 flex items-center gap-3">
        <button
          type="button"
          onClick={() => onSave(name.trim())}
          disabled={saving || !dirty}
          className="h-9 px-4 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 disabled:opacity-50 cursor-pointer whitespace-nowrap dark:text-foreground-950"
        >
          {saving ? '保存中…' : '保存修改'}
        </button>
        {message ? <span className="text-xs text-foreground-600">{message}</span> : null}
      </div>
    </section>
  );
}