interface LoginRow {
  id: string;
  status: string | null;
  ip: string | null;
  location: string | null;
  device: string | null;
  message: string | null;
  created_at: string;
}

const statusMeta: Record<string, { label: string; badge: string; dot: string }> = {
  success: { label: '成功', badge: 'bg-primary-100 text-primary-800', dot: 'bg-primary-500' },
  failed: { label: '失败', badge: 'bg-secondary-200 text-secondary-900', dot: 'bg-secondary-600' },
  logout: { label: '登出', badge: 'bg-background-200 text-foreground-700', dot: 'bg-foreground-400' },
};

function formatDateTime(iso: string) {
  const d = new Date(iso);
  const p = (n: number) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}`;
}

export default function RecentLogins({ logins, loading }: { logins: LoginRow[]; loading: boolean }) {
  return (
    <section className="rounded-lg bg-background-50 border border-background-200 p-4 md:p-5">
      <h3 className="text-sm font-semibold text-foreground-950">最近登录记录</h3>
      <p className="text-xs text-foreground-500 mt-0.5">检测账号是否有异常登录行为</p>

      {loading ? (
        <div className="mt-4 space-y-2.5">
          {[0, 1, 2].map((n) => (
            <div key={n} className="h-12 rounded-md bg-background-100 animate-pulse-soft" />
          ))}
        </div>
      ) : logins.length === 0 ? (
        <p className="mt-6 text-sm text-foreground-500 text-center py-6">暂无登录记录</p>
      ) : (
        <ul className="mt-3 divide-y divide-background-200">
          {logins.map((log) => {
            const meta = statusMeta[log.status ?? 'success'] ?? statusMeta.success;
            return (
              <li key={log.id} className="flex items-center gap-3 py-2.5">
                <span className={`w-2 h-2 rounded-full shrink-0 ${meta.dot}`} />
                <div className="min-w-0 flex-1">
                  <div className="flex items-center gap-2">
                    <span className="text-sm text-foreground-900 truncate">{log.device ?? '未知设备'}</span>
                    <span className={`text-[10px] px-1.5 py-0.5 rounded-full ${meta.badge}`}>{meta.label}</span>
                  </div>
                  <p className="text-[11px] text-foreground-500 font-label truncate">
                    {log.ip ?? '—'} · {log.location ?? '未知'} · {log.message ?? ''}
                  </p>
                </div>
                <span className="text-[11px] text-foreground-400 font-label whitespace-nowrap">
                  {formatDateTime(log.created_at)}
                </span>
              </li>
            );
          })}
        </ul>
      )}
    </section>
  );
}