import { useCallback, useEffect, useMemo, useState } from 'react';
import { supabase } from '@/lib/supabase';
import { useAuth } from '@/contexts/AuthContext';
import Modal from '@/components/base/Modal';

interface PermRow {
  id: string;
  name: string;
  code: string | null;
  type: string;
  parent_id: string | null;
  route: string | null;
  icon: string | null;
  sort_order: number | null;
}

const typeMeta: Record<string, { label: string; tone: string; icon: string }> = {
  menu: { label: '菜单', tone: 'bg-primary-100 text-primary-800', icon: 'ri-layout-top-line' },
  button: { label: '按钮', tone: 'bg-accent-100 text-accent-900', icon: 'ri-cursor-line' },
  api: { label: '接口', tone: 'bg-secondary-200 text-secondary-900', icon: 'ri-code-s-slash-line' },
};

const emptyForm = {
  name: '',
  code: '',
  type: 'menu',
  parent_id: '',
  route: '',
  sort_order: '0',
};

export default function PermissionsPage() {
  const { hasPermission } = useAuth();
  const canCreate = hasPermission('perm:create');
  const canUpdate = hasPermission('perm:update');
  const canDelete = hasPermission('perm:delete');

  const [permissions, setPermissions] = useState<PermRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');

  const [typeFilter, setTypeFilter] = useState('all');
  const [keyword, setKeyword] = useState('');

  const [editOpen, setEditOpen] = useState(false);
  const [editing, setEditing] = useState<PermRow | null>(null);
  const [form, setForm] = useState(emptyForm);
  const [formError, setFormError] = useState('');
  const [saving, setSaving] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState<PermRow | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const { data, error: err } = await supabase
        .from('permissions')
        .select('*')
        .order('sort_order', { ascending: true });
      if (err) throw err;
      setPermissions((data as PermRow[]) ?? []);
    } catch (err) {
      console.error(err);
      setError('加载权限资源失败,请重试');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  useEffect(() => {
    if (!notice) return;
    const timer = setTimeout(() => setNotice(''), 2600);
    return () => clearTimeout(timer);
  }, [notice]);

  const stats = useMemo(() => {
    const menu = permissions.filter((p) => p.type === 'menu').length;
    const button = permissions.filter((p) => p.type === 'button').length;
    const api = permissions.filter((p) => p.type === 'api').length;
    return { menu, button, api };
  }, [permissions]);

  const topMenus = useMemo(
    () => permissions.filter((p) => !p.parent_id).sort((a, b) => (a.sort_order ?? 0) - (b.sort_order ?? 0)),
    [permissions],
  );

  const matches = useCallback(
    (p: PermRow) => {
      const kw = keyword.trim().toLowerCase();
      const matchKw =
        !kw || p.name.toLowerCase().includes(kw) || (p.code ?? '').toLowerCase().includes(kw);
      const matchType = typeFilter === 'all' || p.type === typeFilter;
      return matchKw && matchType;
    },
    [keyword, typeFilter],
  );

  const grouped = useMemo(() => {
    return topMenus
      .map((menu) => {
        const children = permissions
          .filter((p) => p.parent_id === menu.id)
          .sort((a, b) => (a.sort_order ?? 0) - (b.sort_order ?? 0))
          .filter(matches);
        return { menu, children, menuMatches: matches(menu) };
      })
      .filter((g) => g.menuMatches || g.children.length > 0);
  }, [topMenus, permissions, matches]);

  const parentOptions = useMemo(() => topMenus, [topMenus]);

  const openCreate = () => {
    setEditing(null);
    setForm(emptyForm);
    setFormError('');
    setEditOpen(true);
  };

  const openEdit = (p: PermRow) => {
    setEditing(p);
    setForm({
      name: p.name,
      code: p.code ?? '',
      type: p.type,
      parent_id: p.parent_id ?? '',
      route: p.route ?? '',
      sort_order: String(p.sort_order ?? 0),
    });
    setFormError('');
    setEditOpen(true);
  };

  const submit = async () => {
    if (!form.name.trim()) {
      setFormError('请输入资源名称');
      return;
    }
    setSaving(true);
    try {
      const payload = {
        name: form.name,
        code: form.code || null,
        type: form.type,
        parent_id: form.type === 'menu' && !form.parent_id ? null : form.parent_id || null,
        route: form.type === 'menu' ? form.route || null : null,
        sort_order: Number(form.sort_order) || 0,
      };
      if (editing) {
        const { error: err } = await supabase.from('permissions').update(payload).eq('id', editing.id);
        if (err) throw err;
        setNotice('权限资源已更新');
      } else {
        const { error: err } = await supabase.from('permissions').insert(payload);
        if (err) throw err;
        setNotice('权限资源创建成功');
      }
      setEditOpen(false);
      setEditing(null);
      await load();
    } catch (err) {
      console.error(err);
      setFormError('保存失败,请检查权限后重试');
    } finally {
      setSaving(false);
    }
  };

  const confirmDelete = async () => {
    if (!deleteTarget) return;
    // 删除菜单时连同其子级资源一起删,避免子资源失去父级变成孤儿
    const childIds = permissions.filter((p) => p.parent_id === deleteTarget.id).map((p) => p.id);
    const allIds = [deleteTarget.id, ...childIds];
    try {
      // 表之间没有外键约束,需手动清理角色对该权限的引用
      const { error: rpErr } = await supabase
        .from('role_permissions')
        .delete()
        .in('permission_id', allIds);
      if (rpErr) throw rpErr;
      const { error: err } = await supabase.from('permissions').delete().in('id', allIds);
      if (err) throw err;
      setNotice(childIds.length > 0 ? `权限资源及其 ${childIds.length} 个子项已删除` : '权限资源已删除');
      setDeleteTarget(null);
      await load();
    } catch (err) {
      console.error(err);
      setError('删除失败,请检查权限后重试');
      setDeleteTarget(null);
    }
  };

  return (
    <div className="space-y-4">
      <div className="flex flex-col md:flex-row md:items-center gap-3">
        <div>
          <h2 className="text-lg font-semibold text-foreground-950">权限资源</h2>
          <p className="text-sm text-foreground-500 mt-0.5">
            统一维护菜单、按钮与接口三类权限资源点,供角色自由组合
          </p>
        </div>
        <button
          type="button"
          onClick={openCreate}
          disabled={!canCreate}
          className="md:ml-auto h-9 px-3.5 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 disabled:opacity-50 cursor-pointer whitespace-nowrap flex items-center gap-1.5 dark:text-foreground-950"
        >
          <i className="ri-add-line"></i>
          新增资源
        </button>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
        {[
          { key: 'menu', label: '菜单权限', value: stats.menu, tone: 'bg-primary-100 text-primary-700', icon: typeMeta.menu.icon },
          { key: 'button', label: '按钮权限', value: stats.button, tone: 'bg-accent-100 text-accent-800', icon: typeMeta.button.icon },
          { key: 'api', label: '接口权限', value: stats.api, tone: 'bg-secondary-100 text-secondary-900', icon: typeMeta.api.icon },
        ].map((card) => (
          <div key={card.key} className="rounded-lg bg-background-50 border border-background-200 p-4 flex items-center gap-3">
            <span className={`w-10 h-10 rounded-md flex items-center justify-center ${card.tone}`}>
              <i className={`${card.icon} text-lg`}></i>
            </span>
            <div>
              <p className="text-xl font-semibold text-foreground-950 font-heading">{card.value}</p>
              <p className="text-xs text-foreground-500">{card.label}</p>
            </div>
          </div>
        ))}
      </div>

      {notice ? (
        <div className="flex items-center gap-2 px-3 py-2.5 rounded-md bg-primary-50 text-primary-800 text-sm animate-fade-up">
          <i className="ri-checkbox-circle-line"></i>
          {notice}
        </div>
      ) : null}
      {error ? (
        <div className="flex items-center justify-between gap-3 px-3 py-2.5 rounded-md bg-accent-100 text-accent-900 text-sm">
          {error}
          <button type="button" onClick={load} className="text-xs underline cursor-pointer whitespace-nowrap">
            重试
          </button>
        </div>
      ) : null}

      <div className="rounded-lg bg-background-50 border border-background-200">
        <div className="flex flex-col sm:flex-row sm:items-center gap-3 px-4 md:px-5 py-3.5 border-b border-background-200">
          <div className="inline-flex p-1 rounded-full bg-background-200/70">
            {[
              { key: 'all', label: '全部' },
              { key: 'menu', label: '菜单' },
              { key: 'button', label: '按钮' },
              { key: 'api', label: '接口' },
            ].map((tab) => (
              <button
                key={tab.key}
                type="button"
                onClick={() => setTypeFilter(tab.key)}
                className={`px-3 py-1.5 text-xs rounded-full cursor-pointer whitespace-nowrap ${
                  typeFilter === tab.key ? 'bg-background-50 text-foreground-950 font-medium' : 'text-foreground-600'
                }`}
              >
                {tab.label}
              </button>
            ))}
          </div>
          <div className="sm:ml-auto flex items-center gap-2 h-9 px-3 rounded-md bg-background-100 border border-background-200 w-full sm:w-60">
            <i className="ri-search-line text-foreground-400 text-sm"></i>
            <input
              type="text"
              value={keyword}
              onChange={(e) => setKeyword(e.target.value)}
              placeholder="搜索名称或标识"
              className="flex-1 bg-transparent text-sm text-foreground-900 placeholder:text-foreground-400 focus:outline-none"
            />
          </div>
        </div>

        <div className="p-4 md:p-5 space-y-3">
          {loading ? (
            [0, 1, 2].map((n) => (
              <div key={n} className="h-24 rounded-md bg-background-100 animate-pulse-soft" />
            ))
          ) : grouped.length === 0 ? (
            <div className="py-16 text-center text-foreground-500">
              <i className="ri-knife-blood-line text-2xl block mb-2"></i>
              <p className="text-sm">没有匹配的权限资源</p>
            </div>
          ) : (
            grouped.map(({ menu, children }) => (
              <div key={menu.id} className="rounded-md border border-background-200 overflow-hidden">
                <div className="flex items-center gap-3 px-3.5 py-2.5 bg-background-100">
                  <span className={`w-7 h-7 rounded-md flex items-center justify-center ${typeMeta.menu.tone}`}>
                    <i className={`${menu.icon || typeMeta.menu.icon} text-sm`}></i>
                  </span>
                  <div className="min-w-0 flex-1">
                    <div className="flex items-center gap-2">
                      <span className="text-sm font-medium text-foreground-900">{menu.name}</span>
                      <span className={`text-[10px] px-1.5 py-0.5 rounded-full ${typeMeta.menu.tone}`}>菜单</span>
                    </div>
                    {menu.code ? (
                      <span className="text-[11px] text-foreground-500 font-label">{menu.code}</span>
                    ) : null}
                  </div>
                  <button
                    type="button"
                    onClick={() => openEdit(menu)}
                    disabled={!canUpdate}
                    className="w-7 h-7 flex items-center justify-center rounded-md text-foreground-500 hover:bg-background-200 disabled:opacity-40 cursor-pointer"
                    title="编辑"
                  >
                    <i className="ri-pencil-line text-sm"></i>
                  </button>
                  <button
                    type="button"
                    onClick={() => setDeleteTarget(menu)}
                    disabled={!canDelete}
                    className="w-7 h-7 flex items-center justify-center rounded-md text-foreground-500 hover:bg-secondary-200 disabled:opacity-40 cursor-pointer"
                    title="删除"
                  >
                    <i className="ri-delete-bin-line text-sm"></i>
                  </button>
                </div>
                {children.length > 0 ? (
                  <ul className="divide-y divide-background-200">
                    {children.map((child) => (
                      <li key={child.id} className="flex items-center gap-3 px-3.5 py-2.5 hover:bg-background-100/60">
                        <span className="w-1.5 h-1.5 rounded-full bg-background-400 ml-2" />
                        <span className="text-sm text-foreground-800">{child.name}</span>
                        <span className={`text-[10px] px-1.5 py-0.5 rounded-full ${typeMeta[child.type]?.tone ?? typeMeta.menu.tone}`}>
                          {typeMeta[child.type]?.label ?? child.type}
                        </span>
                        {child.code ? (
                          <span className="text-[11px] text-foreground-500 font-label">{child.code}</span>
                        ) : null}
                        <div className="ml-auto flex items-center gap-1">
                          <button
                            type="button"
                            onClick={() => openEdit(child)}
                            disabled={!canUpdate}
                            className="w-7 h-7 flex items-center justify-center rounded-md text-foreground-500 hover:bg-background-200 disabled:opacity-40 cursor-pointer"
                            title="编辑"
                          >
                            <i className="ri-pencil-line text-sm"></i>
                          </button>
                          <button
                            type="button"
                            onClick={() => setDeleteTarget(child)}
                            disabled={!canDelete}
                            className="w-7 h-7 flex items-center justify-center rounded-md text-foreground-500 hover:bg-secondary-200 disabled:opacity-40 cursor-pointer"
                            title="删除"
                          >
                            <i className="ri-delete-bin-line text-sm"></i>
                          </button>
                        </div>
                      </li>
                    ))}
                  </ul>
                ) : null}
              </div>
            ))
          )}
        </div>
      </div>

      {/* Form modal */}
      <Modal
        open={editOpen}
        title={editing ? '编辑权限资源' : '新增权限资源'}
        onClose={() => setEditOpen(false)}
        footer={
          <>
            <button
              type="button"
              onClick={() => setEditOpen(false)}
              className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
            >
              取消
            </button>
            <button
              type="button"
              onClick={submit}
              disabled={saving}
              className="h-9 px-4 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 disabled:opacity-60 cursor-pointer whitespace-nowrap dark:text-foreground-950"
            >
              {saving ? '保存中…' : '保存'}
            </button>
          </>
        }
      >
        <div className="space-y-3.5">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3.5">
            <div>
              <label className="block text-xs font-medium text-foreground-700 mb-1.5">资源名称</label>
              <input
                type="text"
                value={form.name}
                onChange={(e) => setForm((p) => ({ ...p, name: e.target.value }))}
                placeholder="例如:导出报表"
                className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-foreground-700 mb-1.5">资源标识</label>
              <input
                type="text"
                value={form.code}
                onChange={(e) => setForm((p) => ({ ...p, code: e.target.value }))}
                placeholder="例如:report:export"
                className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400 font-label"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-foreground-700 mb-1.5">资源类型</label>
              <select
                value={form.type}
                onChange={(e) => setForm((p) => ({ ...p, type: e.target.value }))}
                className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400 cursor-pointer"
              >
                <option value="menu">菜单</option>
                <option value="button">按钮</option>
                <option value="api">接口</option>
              </select>
            </div>
            <div>
              <label className="block text-xs font-medium text-foreground-700 mb-1.5">上级菜单</label>
              <select
                value={form.parent_id}
                onChange={(e) => setForm((p) => ({ ...p, parent_id: e.target.value }))}
                className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400 cursor-pointer"
              >
                <option value="">无(作为顶级菜单)</option>
                {parentOptions.map((opt) => (
                  <option key={opt.id} value={opt.id}>
                    {opt.name}
                  </option>
                ))}
              </select>
            </div>
            {form.type === 'menu' ? (
              <div>
                <label className="block text-xs font-medium text-foreground-700 mb-1.5">路由路径</label>
                <input
                  type="text"
                  value={form.route}
                  onChange={(e) => setForm((p) => ({ ...p, route: e.target.value }))}
                  placeholder="例如:/reports"
                  className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400 font-label"
                />
              </div>
            ) : null}
            <div>
              <label className="block text-xs font-medium text-foreground-700 mb-1.5">排序</label>
              <input
                type="number"
                value={form.sort_order}
                onChange={(e) => setForm((p) => ({ ...p, sort_order: e.target.value }))}
                className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400 font-label"
              />
            </div>
          </div>
          {formError ? (
            <div className="flex items-start gap-2 px-3 py-2.5 rounded-md bg-accent-100 text-accent-900 text-xs">
              <i className="ri-error-warning-line mt-0.5"></i>
              <span>{formError}</span>
            </div>
          ) : null}
        </div>
      </Modal>

      <Modal
        open={Boolean(deleteTarget)}
        title="删除权限资源"
        onClose={() => setDeleteTarget(null)}
        footer={
          <>
            <button
              type="button"
              onClick={() => setDeleteTarget(null)}
              className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
            >
              取消
            </button>
            <button
              type="button"
              onClick={confirmDelete}
              className="h-9 px-4 rounded-md bg-secondary-700 text-background-50 text-sm hover:bg-secondary-800 cursor-pointer whitespace-nowrap"
            >
              确认删除
            </button>
          </>
        }
      >
        <p className="text-sm text-foreground-700">
          确定删除资源
          <span className="font-medium text-foreground-950"> {deleteTarget?.name} </span>
          吗?它可能同时被多个角色引用。
        </p>
      </Modal>
    </div>
  );
}