import { useCallback, useEffect, useMemo, useState } from 'react';
import { supabase } from '@/lib/supabase';
import { useAuth } from '@/contexts/AuthContext';
import Modal from '@/components/base/Modal';
import { moveToRecycleBin } from '@/lib/recycleBin';
import { nextCronRun, formatNextRun, absoluteNextRun } from '@/lib/cronNextRun';
import TaskLogDashboard from '@/pages/system/tasks/components/TaskLogDashboard';

interface TaskRow {
  id: string;
  name: string;
  code: string | null;
  cron: string | null;
  description: string | null;
  handler: string | null;
  enabled: boolean | null;
  last_run_at: string | null;
  run_count: number | null;
  success_count: number | null;
  fail_count: number | null;
  created_at: string | null;
}

interface TaskRunRow {
  id: string;
  task_id: string | null;
  task_name: string | null;
  status: string | null;
  trigger: string | null;
  started_at: string | null;
  duration_ms: number | null;
  output: string | null;
}

interface FormState {
  name: string;
  code: string;
  cron: string;
  handler: string;
  description: string;
  enabled: boolean;
}

const emptyForm: FormState = {
  name: '',
  code: '',
  cron: '0 * * * *',
  handler: '',
  description: '',
  enabled: true,
};

function timeAgo(iso: string | null) {
  if (!iso) return '从未执行';
  const diff = Date.now() - new Date(iso).getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return '刚刚';
  if (mins < 60) return `${mins} 分钟前`;
  const hours = Math.floor(mins / 60);
  if (hours < 24) return `${hours} 小时前`;
  return `${Math.floor(hours / 24)} 天前`;
}

const presets = [
  { label: '每分钟', cron: '* * * * *' },
  { label: '每 5 分钟', cron: '*/5 * * * *' },
  { label: '每小时', cron: '0 * * * *' },
  { label: '每天 2 点', cron: '0 2 * * *' },
  { label: '每周一 9 点', cron: '0 9 * * 1' },
];

/** 尚未接入真实执行通道的处理器,界面上如实标注,避免被当成「能跑却一直没跑」 */
const handlerChannelNote: Record<string, string> = {
  fn_retry_email: '系统暂无邮件发送通道',
  fn_backup: '系统暂无对象存储备份通道',
};

export default function TasksPage() {
  const { hasPermission } = useAuth();
  // 按钮级权限:严格按勾选的权限点判断,不再使用「能看到菜单就能操作」的兜底
  const canManage = hasPermission('task:update');
  const canDelete = hasPermission('task:delete');

  const [tasks, setTasks] = useState<TaskRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const [runningId, setRunningId] = useState<string | null>(null);
  const [view, setView] = useState<'list' | 'board'>('list');
  const [refreshKey, setRefreshKey] = useState(0);
  const [checking, setChecking] = useState(false);

  const [formOpen, setFormOpen] = useState(false);
  const [editing, setEditing] = useState<TaskRow | null>(null);
  const [form, setForm] = useState<FormState>(emptyForm);
  const [formError, setFormError] = useState('');
  const [saving, setSaving] = useState(false);

  const [historyTask, setHistoryTask] = useState<TaskRow | null>(null);
  const [history, setHistory] = useState<TaskRunRow[]>([]);
  const [historyLoading, setHistoryLoading] = useState(false);

  const [deleteTarget, setDeleteTarget] = useState<TaskRow | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const { data, error: err } = await supabase
        .from('scheduled_tasks')
        .select('*')
        .order('created_at', { ascending: true });
      if (err) throw err;
      setTasks((data as TaskRow[]) ?? []);
    } catch (err) {
      console.error(err);
      setError('加载定时任务失败,请重试');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  useEffect(() => {
    if (!notice) return;
    const timer = setTimeout(() => setNotice(''), 2600);
    return () => clearTimeout(timer);
  }, [notice]);

  const stats = useMemo(
    () => ({
      total: tasks.length,
      enabled: tasks.filter((t) => t.enabled).length,
      runs: tasks.reduce((s, t) => s + (t.run_count ?? 0), 0),
      fails: tasks.reduce((s, t) => s + (t.fail_count ?? 0), 0),
    }),
    [tasks],
  );

  const openCreate = () => {
    setEditing(null);
    setForm(emptyForm);
    setFormError('');
    setFormOpen(true);
  };

  const openEdit = (task: TaskRow) => {
    setEditing(task);
    setForm({
      name: task.name,
      code: task.code ?? '',
      cron: task.cron ?? '0 * * * *',
      handler: task.handler ?? '',
      description: task.description ?? '',
      enabled: task.enabled ?? true,
    });
    setFormError('');
    setFormOpen(true);
  };

  const submit = async () => {
    if (!form.name.trim()) {
      setFormError('请输入任务名称');
      return;
    }
    if (!form.cron.trim()) {
      setFormError('请输入 Cron 表达式');
      return;
    }
    setSaving(true);
    try {
      const payload = {
        name: form.name.trim(),
        code: form.code.trim() || null,
        cron: form.cron.trim(),
        handler: form.handler.trim() || null,
        description: form.description.trim(),
        enabled: form.enabled,
        updated_at: new Date().toISOString(),
      };
      if (editing) {
        const { error: err } = await supabase.from('scheduled_tasks').update(payload).eq('id', editing.id);
        if (err) throw err;
        setNotice('任务已更新');
      } else {
        const { error: err } = await supabase.from('scheduled_tasks').insert(payload);
        if (err) throw err;
        setNotice('任务创建成功');
      }
      setFormOpen(false);
      setEditing(null);
      await load();
    } catch (err) {
      console.error(err);
      setFormError('保存失败,请检查权限后重试');
    } finally {
      setSaving(false);
    }
  };

  const toggle = async (task: TaskRow) => {
    const { error: err } = await supabase
      .from('scheduled_tasks')
      .update({ enabled: !task.enabled, updated_at: new Date().toISOString() })
      .eq('id', task.id);
    if (err) {
      setError('状态更新失败');
      return;
    }
    setNotice(task.enabled ? `已停用「${task.name}」` : `已启用「${task.name}」`);
    await load();
  };

  const runNow = async (task: TaskRow) => {
    setRunningId(task.id);
    try {
      // 调用后端函数真实执行:命中已注册处理器则执行真实副作用,未注册则如实记为「未执行」
      const { data, error: invokeErr } = await supabase.functions.invoke('run-scheduled-task', {
        body: { taskId: task.id },
      });
      if (invokeErr) throw invokeErr;
      const result = (data ?? {}) as {
        status?: string;
        durationMs?: number;
        output?: string;
        error?: string;
      };
      if (result.error) {
        setError(`执行失败:${result.error}`);
        return;
      }
      const msg = result.output ?? '';
      if (result.status === 'success') {
        setNotice(`「${task.name}」执行成功 (${result.durationMs ?? 0}ms)｜${msg}`);
      } else if (result.status === 'skipped') {
        setNotice(`「${task.name}」未执行:${msg}`);
      } else {
        setNotice(`「${task.name}」执行失败:${msg}`);
      }
      if (historyTask?.id === task.id) await openHistory(task);
      await load();
      setRefreshKey((k) => k + 1);
    } catch (err) {
      console.error(err);
      setError('执行失败,请重试');
    } finally {
      setRunningId(null);
    }
  };

  // 手动触发一次「到点检查」:由后端调度器自动执行所有已到期的任务(含补跑)
  const checkDue = async () => {
    setChecking(true);
    try {
      const { data, error: invokeErr } = await supabase.functions.invoke('run-scheduled-task', {
        body: { mode: 'due' },
      });
      if (invokeErr) throw invokeErr;
      const res = (data ?? {}) as { count?: number; tasks?: string[] };
      const n = res.count ?? 0;
      if (n > 0) {
        setNotice(
          `到点检查完成:自动执行了 ${n} 个到期任务${res.tasks?.length ? `(${res.tasks.join('、')})` : ''}`,
        );
      } else {
        setNotice('到点检查完成:当前没有到期的任务');
      }
      await load();
      setRefreshKey((k) => k + 1);
    } catch (err) {
      console.error(err);
      setError('到点检查失败,请重试');
    } finally {
      setChecking(false);
    }
  };

  const openHistory = async (task: TaskRow) => {
    setHistoryTask(task);
    setHistoryLoading(true);
    try {
      const { data, error: err } = await supabase
        .from('task_runs')
        .select('*')
        .eq('task_id', task.id)
        .order('started_at', { ascending: false })
        .limit(30);
      if (err) throw err;
      setHistory((data as TaskRunRow[]) ?? []);
    } catch (err) {
      console.error(err);
      setHistory([]);
    } finally {
      setHistoryLoading(false);
    }
  };

  const confirmDelete = async () => {
    if (!deleteTarget) return;
    try {
      const { error: err } = await supabase.from('scheduled_tasks').delete().eq('id', deleteTarget.id);
      if (err) throw err;
      await moveToRecycleBin({
        module: 'task',
        itemId: deleteTarget.id,
        itemName: deleteTarget.name,
        snapshot: {
          id: deleteTarget.id,
          name: deleteTarget.name,
          code: deleteTarget.code,
          cron: deleteTarget.cron,
          description: deleteTarget.description,
          handler: deleteTarget.handler,
          enabled: deleteTarget.enabled ?? true,
          last_run_at: deleteTarget.last_run_at,
          run_count: deleteTarget.run_count ?? 0,
          success_count: deleteTarget.success_count ?? 0,
          fail_count: deleteTarget.fail_count ?? 0,
        },
      });
      setNotice('任务已删除,可在回收站还原');
      setDeleteTarget(null);
      await load();
    } catch (err) {
      console.error(err);
      setError('删除失败,可能权限不足');
      setDeleteTarget(null);
    }
  };

  const statCards = [
    { label: '任务总数', value: stats.total, icon: 'ri-timer-flash-line', tone: 'bg-primary-100 text-primary-700' },
    { label: '运行中', value: stats.enabled, icon: 'ri-play-circle-line', tone: 'bg-accent-100 text-accent-800' },
    { label: '累计执行', value: stats.runs.toLocaleString(), icon: 'ri-refresh-line', tone: 'bg-secondary-200 text-secondary-900' },
    { label: '失败次数', value: stats.fails, icon: 'ri-error-warning-line', tone: 'bg-primary-100 text-primary-700' },
  ];

  return (
    <div className="space-y-4">
      <div className="flex flex-col md:flex-row md:items-center gap-3">
        <div>
          <h2 className="text-lg font-semibold text-foreground-950">定时任务</h2>
          <p className="text-sm text-foreground-500 mt-0.5">
            配置 Cron 计划任务、启停调度、手动执行并查看执行历史
          </p>
        </div>
        <div className="md:ml-auto flex flex-wrap items-center gap-2">
          <div className="flex items-center gap-1 p-1 rounded-full bg-background-100 border border-background-200">
            <button
              type="button"
              onClick={() => setView('list')}
              className={`h-7 px-3 rounded-full text-xs cursor-pointer whitespace-nowrap transition-colors ${
                view === 'list' ? 'bg-primary-500 text-background-50 dark:text-foreground-950' : 'text-foreground-600 hover:bg-background-200'
              }`}
            >
              任务列表
            </button>
            <button
              type="button"
              onClick={() => setView('board')}
              className={`h-7 px-3 rounded-full text-xs cursor-pointer whitespace-nowrap transition-colors ${
                view === 'board' ? 'bg-primary-500 text-background-50 dark:text-foreground-950' : 'text-foreground-600 hover:bg-background-200'
              }`}
            >
              执行看板
            </button>
          </div>
          <button
            type="button"
            onClick={checkDue}
            disabled={checking}
            className="h-9 px-3.5 rounded-md bg-background-50 border border-background-200 text-sm text-foreground-700 hover:bg-background-100 disabled:opacity-50 cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5"
          >
            <i className={checking ? 'ri-loader-4-line animate-spin' : 'ri-refresh-line'}></i>
            {checking ? '检查中…' : '到点检查'}
          </button>
          <button
            type="button"
            onClick={openCreate}
            disabled={!canManage}
            className="h-9 px-3.5 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 disabled:opacity-50 cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5 dark:text-foreground-950"
          >
            <i className="ri-add-line"></i>
            新建任务
          </button>
        </div>
      </div>

      {notice ? (
        <div className="flex items-center gap-2 px-3 py-2.5 rounded-md bg-primary-50 text-primary-800 text-sm animate-fade-up">
          <i className="ri-checkbox-circle-line"></i>
          {notice}
        </div>
      ) : null}
      {error ? (
        <div className="flex items-center justify-between gap-3 px-3 py-2.5 rounded-md bg-accent-100 text-accent-900 text-sm">
          {error}
          <button type="button" onClick={load} className="text-xs underline cursor-pointer whitespace-nowrap">
            重试
          </button>
        </div>
      ) : null}

      <div className="flex flex-wrap items-center gap-x-3 gap-y-1.5 px-3 py-2.5 rounded-md bg-background-100 border border-background-200 text-xs text-foreground-600">
        <span className="inline-flex items-center gap-1.5 font-medium text-foreground-800 whitespace-nowrap">
          <span className="w-1.5 h-1.5 rounded-full bg-primary-500 animate-pulse-soft" />
          后台调度已启用
        </span>
        <span className="leading-relaxed">
          只要后台界面处于打开状态,系统每隔约 1 分钟自动检查一次,到点的任务会自动执行并补跑错过的任务,无需手动点击。也可点右上角「到点检查」立即触发一次。
        </span>
      </div>

      {view === 'board' ? (
        <TaskLogDashboard key={refreshKey} tasks={tasks} />
      ) : (
        <>
      <section className="grid grid-cols-2 xl:grid-cols-4 gap-3 md:gap-4">
        {statCards.map((s) => (
          <div key={s.label} className="rounded-lg bg-background-50 border border-background-200 p-4">
            <div className="flex items-center gap-2">
              <span className={`w-8 h-8 rounded-md flex items-center justify-center ${s.tone}`}>
                <i className={`${s.icon} text-sm`}></i>
              </span>
              <span className="text-xs text-foreground-500">{s.label}</span>
            </div>
            <p className="mt-2.5 text-2xl font-semibold text-foreground-950 font-label">{s.value}</p>
          </div>
        ))}
      </section>

      {loading ? (
        <div className="space-y-3">
          {[0, 1, 2].map((n) => (
            <div key={n} className="h-28 rounded-lg bg-background-50 border border-background-200 animate-pulse-soft" />
          ))}
        </div>
      ) : tasks.length === 0 ? (
        <div className="rounded-lg bg-background-50 border border-background-200 py-16 text-center text-foreground-500">
          <i className="ri-timer-flash-line text-3xl block mb-2"></i>
          还没有定时任务
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
          {tasks.map((task) => {
            const total = task.run_count ?? 0;
            const fail = task.fail_count ?? 0;
            const successRate = total > 0 ? Math.round(((total - fail) / total) * 100) : 100;
            const enabled = Boolean(task.enabled);
            const nextRun = enabled && task.cron ? nextCronRun(task.cron) : null;
            return (
              <article key={task.id} className="rounded-lg bg-background-50 border border-background-200 p-4 md:p-5">
                <div className="flex items-start gap-3">
                  <span
                    className={`w-10 h-10 rounded-lg flex items-center justify-center shrink-0 ${
                      enabled ? 'bg-primary-100 text-primary-700' : 'bg-background-200 text-foreground-500'
                    }`}
                  >
                    <i className="ri-timer-flash-line text-lg"></i>
                  </span>
                  <div className="min-w-0 flex-1">
                    <div className="flex items-center gap-2 flex-wrap">
                      <h3 className="text-sm font-semibold text-foreground-950 truncate">{task.name}</h3>
                      <span
                        className={`text-[10px] px-1.5 py-0.5 rounded-full ${
                          enabled ? 'bg-primary-100 text-primary-800' : 'bg-background-200 text-foreground-600'
                        }`}
                      >
                        {enabled ? '运行中' : '已暂停'}
                      </span>
                    </div>
                    <div className="mt-1 flex flex-wrap items-center gap-2 text-[11px] text-foreground-500">
                      {task.code ? <span className="font-label">{task.code}</span> : null}
                      <span className="font-label px-1.5 py-0.5 rounded bg-secondary-100 text-secondary-900">
                        {task.cron}
                      </span>
                      <span className="inline-flex items-center gap-1">
                        <i className="ri-flashlight-line"></i>
                        {task.handler ?? '未指定处理器'}
                      </span>
                      {task.handler && handlerChannelNote[task.handler] ? (
                        <span className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded bg-accent-100 text-accent-900">
                          <i className="ri-alert-line"></i>
                          {handlerChannelNote[task.handler]}
                        </span>
                      ) : null}
                    </div>
                  </div>
                  <button
                    type="button"
                    onClick={() => toggle(task)}
                    disabled={!canManage}
                    className={`shrink-0 inline-flex items-center gap-1.5 h-7 pl-1.5 pr-2.5 rounded-full text-[11px] cursor-pointer whitespace-nowrap disabled:opacity-50 ${
                      enabled ? 'bg-primary-100 text-primary-800' : 'bg-background-200 text-foreground-600'
                    }`}
                  >
                    <span className="relative w-7 h-3.5 rounded-full">
                      <span className={`absolute inset-0 rounded-full ${enabled ? 'bg-primary-500' : 'bg-background-400'}`} />
                      <span
                        className={`absolute top-0.5 w-2.5 h-2.5 rounded-full bg-background-50 transition-all ${
                          enabled ? 'left-3.5' : 'left-0.5'
                        }`}
                      />
                    </span>
                    {enabled ? '启用' : '停用'}
                  </button>
                </div>

                <p className="mt-3 text-xs text-foreground-600 leading-relaxed line-clamp-2 min-h-[32px]">
                  {task.description || '暂无描述'}
                </p>

                <div className="mt-2.5 flex flex-wrap items-center gap-x-2 gap-y-1 text-[11px]">
                  {enabled ? (
                    task.cron && nextRun ? (
                      <>
                        <span className="inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full bg-accent-100 text-accent-900">
                          <i className="ri-time-line"></i>
                          下次执行 {formatNextRun(nextRun)}
                        </span>
                        <span className="font-label text-foreground-500">{absoluteNextRun(nextRun)}</span>
                      </>
                    ) : (
                      <span className="inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full bg-background-200 text-foreground-600">
                        <i className="ri-time-line"></i>
                        Cron 表达式无法解析,暂无下次执行时间
                      </span>
                    )
                  ) : (
                    <span className="inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full bg-background-200 text-foreground-600">
                      <i className="ri-pause-circle-line"></i>
                      已暂停,不参与自动调度
                    </span>
                  )}
                </div>

                <div className="mt-3 grid grid-cols-3 gap-2">
                  <div className="rounded-md bg-background-100 border border-background-200 px-2.5 py-2">
                    <p className="text-[10px] text-foreground-500">执行次数</p>
                    <p className="text-sm font-semibold text-foreground-950 font-label">{total.toLocaleString()}</p>
                  </div>
                  <div className="rounded-md bg-background-100 border border-background-200 px-2.5 py-2">
                    <p className="text-[10px] text-foreground-500">成功率</p>
                    <p className="text-sm font-semibold text-foreground-950 font-label">{successRate}%</p>
                  </div>
                  <div className="rounded-md bg-background-100 border border-background-200 px-2.5 py-2">
                    <p className="text-[10px] text-foreground-500">最近执行</p>
                    <p className="text-sm font-semibold text-foreground-950 truncate">{timeAgo(task.last_run_at)}</p>
                  </div>
                </div>

                <div className="mt-4 pt-3.5 border-t border-background-200 flex flex-wrap items-center gap-1.5">
                  <button
                    type="button"
                    onClick={() => runNow(task)}
                    disabled={!canManage || runningId === task.id}
                    className="h-8 px-2.5 rounded-md bg-primary-500 text-background-50 text-xs hover:bg-primary-600 disabled:opacity-50 cursor-pointer whitespace-nowrap inline-flex items-center gap-1 dark:text-foreground-950"
                  >
                    <i className={runningId === task.id ? 'ri-loader-4-line animate-spin' : 'ri-play-line'}></i>
                    {runningId === task.id ? '执行中…' : '运行一次'}
                  </button>
                  <button
                    type="button"
                    onClick={() => openHistory(task)}
                    className="h-8 px-2.5 rounded-md bg-background-100 border border-background-300 text-xs text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap inline-flex items-center gap-1"
                  >
                    <i className="ri-history-line"></i>
                    执行历史
                  </button>
                  <button
                    type="button"
                    onClick={() => openEdit(task)}
                    disabled={!canManage}
                    className="h-8 px-2.5 rounded-md bg-background-100 border border-background-300 text-xs text-foreground-800 hover:bg-background-200 disabled:opacity-40 cursor-pointer whitespace-nowrap inline-flex items-center gap-1"
                  >
                    <i className="ri-pencil-line"></i>
                    编辑
                  </button>
                  <button
                    type="button"
                    onClick={() => setDeleteTarget(task)}
                    disabled={!canDelete}
                    title="删除"
                    className="ml-auto w-8 h-8 flex items-center justify-center rounded-md text-foreground-500 hover:bg-secondary-200 hover:text-secondary-900 disabled:opacity-40 cursor-pointer"
                  >
                    <i className="ri-delete-bin-line"></i>
                  </button>
                </div>
              </article>
            );
          })}
        </div>
      )}
        </>
      )}

      <Modal
        open={formOpen}
        title={editing ? '编辑任务' : '新建任务'}
        subtitle="设置调度表达式、处理器与启用状态"
        onClose={() => setFormOpen(false)}
        footer={
          <>
            <button
              type="button"
              onClick={() => setFormOpen(false)}
              className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
            >
              取消
            </button>
            <button
              type="button"
              onClick={submit}
              disabled={saving}
              className="h-9 px-4 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 disabled:opacity-60 cursor-pointer whitespace-nowrap dark:text-foreground-950"
            >
              {saving ? '保存中…' : '保存'}
            </button>
          </>
        }
      >
        <div className="space-y-3.5">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3.5">
            <div>
              <label className="block text-xs font-medium text-foreground-700 mb-1.5">任务名称</label>
              <input
                type="text"
                value={form.name}
                onChange={(e) => setForm((p) => ({ ...p, name: e.target.value }))}
                placeholder="例如:日志归档"
                className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-foreground-700 mb-1.5">任务标识(可选)</label>
              <input
                type="text"
                value={form.code}
                onChange={(e) => setForm((p) => ({ ...p, code: e.target.value }))}
                placeholder="例如:log_archive"
                className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400 font-label"
              />
            </div>
          </div>

          <div>
            <label className="block text-xs font-medium text-foreground-700 mb-1.5">Cron 表达式</label>
            <input
              type="text"
              value={form.cron}
              onChange={(e) => setForm((p) => ({ ...p, cron: e.target.value }))}
              placeholder="分 时 日 月 周,例如 0 2 * * *"
              className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400 font-label"
            />
            <div className="mt-2 flex flex-wrap gap-1.5">
              {presets.map((p) => (
                <button
                  key={p.cron}
                  type="button"
                  onClick={() => setForm((prev) => ({ ...prev, cron: p.cron }))}
                  className={`h-7 px-2.5 rounded-full text-[11px] border cursor-pointer whitespace-nowrap ${
                    form.cron === p.cron
                      ? 'bg-primary-500 text-background-50 border-primary-500 dark:text-foreground-950'
                      : 'bg-background-50 text-foreground-700 border-background-300 hover:bg-background-100'
                  }`}
                >
                  {p.label}
                </button>
              ))}
            </div>
          </div>

          <div>
            <label className="block text-xs font-medium text-foreground-700 mb-1.5">处理器函数</label>
            <input
              type="text"
              value={form.handler}
              onChange={(e) => setForm((p) => ({ ...p, handler: e.target.value }))}
              placeholder="例如:fn_archive_logs"
              className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400 font-label"
            />
          </div>

          <div>
            <label className="block text-xs font-medium text-foreground-700 mb-1.5">描述</label>
            <textarea
              value={form.description}
              onChange={(e) => setForm((p) => ({ ...p, description: e.target.value }))}
              rows={3}
              maxLength={500}
              placeholder="简要描述该任务的作用"
              className="w-full px-3 py-2 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400 resize-none"
            />
          </div>

          <label className="flex items-center gap-2.5 cursor-pointer">
            <input
              type="checkbox"
              checked={form.enabled}
              onChange={(e) => setForm((p) => ({ ...p, enabled: e.target.checked }))}
              className="w-4 h-4 accent-primary-500 cursor-pointer"
            />
            <span className="text-sm text-foreground-800">创建后立即启用调度</span>
          </label>

          {formError ? (
            <div className="flex items-start gap-2 px-3 py-2.5 rounded-md bg-accent-100 text-accent-900 text-xs">
              <i className="ri-error-warning-line mt-0.5"></i>
              <span>{formError}</span>
            </div>
          ) : null}
        </div>
      </Modal>

      <Modal
        open={Boolean(historyTask)}
        title="执行历史"
        subtitle={historyTask ? `任务:${historyTask.name} · 最近 30 条` : ''}
        width="max-w-2xl"
        onClose={() => setHistoryTask(null)}
        footer={
          <button
            type="button"
            onClick={() => setHistoryTask(null)}
            className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
          >
            关闭
          </button>
        }
      >
        {historyLoading ? (
          <div className="space-y-2">
            {[0, 1, 2].map((n) => (
              <div key={n} className="h-14 rounded-md bg-background-100 animate-pulse-soft" />
            ))}
          </div>
        ) : history.length === 0 ? (
          <div className="py-12 text-center text-foreground-500">
            <i className="ri-history-line text-2xl block mb-2"></i>
            暂无执行记录
          </div>
        ) : (
          <ul className="space-y-2.5">
            {history.map((run) => {
              const ok = run.status === 'success';
              const skipped = run.status === 'skipped';
              const tone = ok
                ? { cls: 'bg-primary-100 text-primary-800', icon: 'ri-checkbox-circle-line', label: '成功' }
                : skipped
                  ? { cls: 'bg-secondary-100 text-secondary-900', icon: 'ri-indeterminate-circle-line', label: '未执行' }
                  : { cls: 'bg-accent-100 text-accent-900', icon: 'ri-error-warning-line', label: '失败' };
              return (
                <li key={run.id} className="rounded-md border border-background-200 bg-background-50 px-3.5 py-3">
                  <div className="flex items-center gap-2 flex-wrap">
                    <span
                      className={`inline-flex items-center gap-1 text-[11px] px-2 py-0.5 rounded-full ${tone.cls}`}
                    >
                      <i className={tone.icon}></i>
                      {tone.label}
                    </span>
                    <span className="text-[11px] px-1.5 py-0.5 rounded bg-secondary-100 text-secondary-900">
                      {run.trigger === 'manual' ? '手动触发' : '定时调度'}
                    </span>
                    <span className="text-[11px] text-foreground-500 font-label">
                      {run.started_at ? new Date(run.started_at).toLocaleString() : '—'}
                    </span>
                    <span className="text-[11px] text-foreground-500 font-label ml-auto">
                      {run.duration_ms ?? 0} ms
                    </span>
                  </div>
                  <p className="mt-1.5 text-xs text-foreground-700">{run.output || '无输出'}</p>
                </li>
              );
            })}
          </ul>
        )}
      </Modal>

      <Modal
        open={Boolean(deleteTarget)}
        title="删除任务"
        onClose={() => setDeleteTarget(null)}
        footer={
          <>
            <button
              type="button"
              onClick={() => setDeleteTarget(null)}
              className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
            >
              取消
            </button>
            <button
              type="button"
              onClick={confirmDelete}
              className="h-9 px-4 rounded-md bg-secondary-700 text-background-50 text-sm hover:bg-secondary-800 cursor-pointer whitespace-nowrap"
            >
              确认删除
            </button>
          </>
        }
      >
        <p className="text-sm text-foreground-700">
          确定删除任务
          <span className="font-medium text-foreground-950"> {deleteTarget?.name} </span>
          吗?删除后可在回收站还原。
        </p>
      </Modal>
    </div>
  );
}