import { useEffect, useMemo, useState } from 'react';
import Modal from '@/components/base/Modal';
import type { PluginRow } from '@/pages/plugins/types';

interface PluginDetailModalProps {
  open: boolean;
  plugin: PluginRow | null;
  installedMap: Record<string, PluginRow>;
  onClose: () => void;
}

const tabs = [
  { key: 'overview', label: '概览', icon: 'ri-information-line' },
  { key: 'config', label: '依赖与配置', icon: 'ri-settings-4-line' },
  { key: 'changelog', label: '更新日志', icon: 'ri-history-line' },
];

function formatDate(iso: string | null) {
  if (!iso) return '—';
  const d = new Date(iso);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

export default function PluginDetailModal({
  open,
  plugin,
  installedMap,
  onClose,
}: PluginDetailModalProps) {
  const [tab, setTab] = useState('overview');
  const [config, setConfig] = useState<Record<string, string | number | boolean>>({});

  useEffect(() => {
    if (!plugin) return;
    setTab('overview');
    const initial: Record<string, string | number | boolean> = {};
    (plugin.config_schema ?? []).forEach((f) => {
      if (f.default !== undefined) initial[f.key] = f.default;
    });
    setConfig(initial);
  }, [plugin]);

  const deps = useMemo(() => plugin?.dependencies ?? [], [plugin]);
  const changelog = useMemo(() => plugin?.changelog ?? [], [plugin]);
  const schema = useMemo(() => plugin?.config_schema ?? [], [plugin]);

  return (
    <Modal
      open={open}
      title={plugin?.name ?? '插件详情'}
      subtitle={plugin ? `${plugin.code} · 当前 v${plugin.version}` : ''}
      onClose={onClose}
      width="max-w-2xl"
      footer={
        <button
          type="button"
          onClick={onClose}
          className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
        >
          关闭
        </button>
      }
    >
      {!plugin ? null : (
        <div className="space-y-4">
          <div className="flex flex-wrap items-center gap-2">
            <div className="flex items-center gap-1 p-1 rounded-full bg-background-100 border border-background-200">
              {tabs.map((t) => (
                <button
                  key={t.key}
                  type="button"
                  onClick={() => setTab(t.key)}
                  className={`px-3 py-1.5 rounded-full text-xs cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5 transition-colors ${
                    tab === t.key
                      ? 'bg-background-50 text-foreground-950 font-medium'
                      : 'text-foreground-600 hover:text-foreground-900'
                  }`}
                >
                  <i className={t.icon}></i>
                  {t.label}
                </button>
              ))}
            </div>
            {plugin.has_update ? (
              <span className="inline-flex items-center gap-1 text-[11px] px-2 py-0.5 rounded-full bg-accent-100 text-accent-900">
                <i className="ri-arrow-up-circle-line"></i>
                v{plugin.latest_version} 可更新
              </span>
            ) : null}
          </div>

          {tab === 'overview' ? (
            <div className="space-y-4">
              <p className="text-sm text-foreground-700 leading-relaxed">
                {plugin.description || '暂无描述'}
              </p>
              <div className="grid grid-cols-2 gap-3">
                {[
                  { label: '版本', value: `v${plugin.version}`, icon: 'ri-price-tag-3-line' },
                  { label: '分类', value: plugin.category ?? '—', icon: 'ri-apps-2-line' },
                  { label: '开发者', value: plugin.author ?? '—', icon: 'ri-user-3-line' },
                  { label: '安装量', value: (plugin.downloads ?? 0).toLocaleString(), icon: 'ri-download-2-line' },
                  { label: '安装时间', value: formatDate(plugin.installed_at), icon: 'ri-calendar-line' },
                  { label: '状态', value: plugin.enabled ? '已启用' : '已停用', icon: 'ri-toggle-line' },
                ].map((item) => (
                  <div key={item.label} className="rounded-md bg-background-100 border border-background-200 px-3 py-2.5">
                    <div className="flex items-center gap-1.5 text-[11px] text-foreground-500">
                      <i className={item.icon}></i>
                      {item.label}
                    </div>
                    <p className="mt-1 text-sm text-foreground-900 truncate">{item.value}</p>
                  </div>
                ))}
              </div>
              {plugin.homepage ? (
                <div className="flex items-center gap-2 text-xs text-foreground-600">
                  <i className="ri-link"></i>
                  <span className="font-label truncate">{plugin.homepage}</span>
                </div>
              ) : null}
            </div>
          ) : null}

          {tab === 'config' ? (
            <div className="space-y-5">
              <div>
                <h4 className="text-xs font-medium text-foreground-700 mb-2">依赖关系</h4>
                {deps.length === 0 ? (
                  <p className="text-xs text-foreground-500">该插件无外部依赖</p>
                ) : (
                  <ul className="space-y-2">
                    {deps.map((d) => {
                      const target = installedMap[d.code];
                      const satisfied = Boolean(target && target.enabled);
                      return (
                        <li
                          key={d.code}
                          className="flex items-center gap-3 rounded-md bg-background-100 border border-background-200 px-3 py-2.5"
                        >
                          <span
                            className={`w-7 h-7 rounded-md flex items-center justify-center shrink-0 ${
                              satisfied ? 'bg-primary-100 text-primary-700' : 'bg-accent-100 text-accent-900'
                            }`}
                          >
                            <i className={satisfied ? 'ri-check-line' : 'ri-error-warning-line'}></i>
                          </span>
                          <div className="min-w-0 flex-1">
                            <p className="text-xs text-foreground-900 truncate">
                              {d.name}
                              {d.required ? <span className="text-accent-700 ml-1">必需</span> : <span className="text-foreground-400 ml-1">可选</span>}
                            </p>
                            <p className="text-[10px] font-label text-foreground-500">
                              {d.code} {d.version}
                            </p>
                          </div>
                          <span
                            className={`text-[10px] px-2 py-0.5 rounded-full whitespace-nowrap ${
                              satisfied
                                ? 'bg-primary-100 text-primary-800'
                                : target
                                  ? 'bg-secondary-200 text-secondary-900'
                                  : 'bg-accent-100 text-accent-900'
                            }`}
                          >
                            {satisfied ? '已启用' : target ? '未启用' : '未安装'}
                          </span>
                        </li>
                      );
                    })}
                  </ul>
                )}
              </div>

              <div>
                <h4 className="text-xs font-medium text-foreground-700 mb-2">配置项</h4>
                {schema.length === 0 ? (
                  <p className="text-xs text-foreground-500">该插件无配置项</p>
                ) : (
                  <div className="space-y-3">
                    {schema.map((f) => (
                      <div key={f.key}>
                        <label className="block text-[11px] font-medium text-foreground-700 mb-1">
                          {f.label}
                          <span className="ml-1.5 font-label text-[10px] text-foreground-400">{f.key}</span>
                        </label>
                        {f.type === 'boolean' ? (
                          <button
                            type="button"
                            onClick={() => setConfig((p) => ({ ...p, [f.key]: !p[f.key] }))}
                            className={`h-8 px-3 rounded-md text-xs cursor-pointer whitespace-nowrap ${
                              config[f.key] ? 'bg-primary-100 text-primary-800' : 'bg-background-200 text-foreground-600'
                            }`}
                          >
                            {config[f.key] ? '已开启' : '已关闭'}
                          </button>
                        ) : f.type === 'select' && f.options ? (
                          <select
                            value={String(config[f.key] ?? '')}
                            onChange={(e) => setConfig((p) => ({ ...p, [f.key]: e.target.value }))}
                            className="w-full h-9 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none cursor-pointer"
                          >
                            {f.options.map((o) => (
                              <option key={o} value={o}>
                                {o}
                              </option>
                            ))}
                          </select>
                        ) : (
                          <input
                            type={f.type === 'number' ? 'number' : 'text'}
                            value={String(config[f.key] ?? '')}
                            onChange={(e) =>
                              setConfig((p) => ({
                                ...p,
                                [f.key]: f.type === 'number' ? Number(e.target.value) : e.target.value,
                              }))
                            }
                            className="w-full h-9 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400"
                          />
                        )}
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </div>
          ) : null}

          {tab === 'changelog' ? (
            <div>
              {changelog.length === 0 ? (
                <p className="text-xs text-foreground-500">暂无更新记录</p>
              ) : (
                <ol className="relative pl-5">
                  <span className="absolute left-[5px] top-1.5 bottom-1.5 w-px bg-background-300" />
                  {changelog.map((c, i) => (
                    <li key={c.version} className="relative mb-4 last:mb-0">
                      <span
                        className={`absolute -left-5 top-1 w-2.5 h-2.5 rounded-full ${
                          i === 0 ? 'bg-accent-500' : 'bg-background-400'
                        }`}
                      />
                      <div className="flex items-center gap-2">
                        <span className="text-sm font-medium text-foreground-950 font-label">v{c.version}</span>
                        <span className="text-[11px] text-foreground-500 font-label">{c.date}</span>
                        {i === 0 ? (
                          <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-accent-100 text-accent-900">最新</span>
                        ) : null}
                      </div>
                      <ul className="mt-1.5 space-y-1">
                        {c.notes.map((n) => (
                          <li key={n} className="flex items-start gap-1.5 text-xs text-foreground-700">
                            <i className="ri-subtract-line mt-1 text-foreground-400"></i>
                            {n}
                          </li>
                        ))}
                      </ul>
                    </li>
                  ))}
                </ol>
              )}
            </div>
          ) : null}
        </div>
      )}
    </Modal>
  );
}