import { useCallback, useEffect, useMemo, useState } from 'react';
import { supabase } from '@/lib/supabase';
import LineChart from '@/pages/dashboard/components/LineChart';
import { cssVar } from '@/lib/themeColor';
import { fetchNumberSetting, saveSettingValue, fetchThresholdHistory, logThresholdChange, type ThresholdHistoryRow } from '@/lib/appConfig';

const ALERT_CONFIG_KEY = 'task_alert_fail_rate';

type SortMode = 'duration' | 'failRate';

interface TaskLite {
  id: string;
  name: string;
}

interface RunRow {
  id: string;
  task_id: string | null;
  task_name: string | null;
  status: string | null;
  trigger: string | null;
  started_at: string | null;
  duration_ms: number | null;
  output: string | null;
}

interface TaskLogDashboardProps {
  tasks: TaskLite[];
}

const rangeOptions = [
  { label: '近 7 天', value: 7 },
  { label: '近 14 天', value: 14 },
  { label: '近 30 天', value: 30 },
];

function dayKey(d: Date) {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

function timeAgo(iso: string | null) {
  if (!iso) return '从未执行';
  const diff = Date.now() - new Date(iso).getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return '刚刚';
  if (mins < 60) return `${mins} 分钟前`;
  const hours = Math.floor(mins / 60);
  if (hours < 24) return `${hours} 小时前`;
  return `${Math.floor(hours / 24)} 天前`;
}

export default function TaskLogDashboard({ tasks }: TaskLogDashboardProps) {
  const [range, setRange] = useState(14);
  const [taskFilter, setTaskFilter] = useState('all');
  const [threshold, setThreshold] = useState(20);
  const [sortBy, setSortBy] = useState<SortMode>('duration');
  const [runs, setRuns] = useState<RunRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [history, setHistory] = useState<ThresholdHistoryRow[]>([]);
  const [historyOpen, setHistoryOpen] = useState(false);

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const from = new Date();
      from.setHours(0, 0, 0, 0);
      from.setDate(from.getDate() - (range - 1));
      const { data, error: err } = await supabase
        .from('task_runs')
        .select('*')
        .gte('started_at', from.toISOString())
        .order('started_at', { ascending: true })
        .limit(2000);
      if (err) throw err;
      setRuns((data as RunRow[]) ?? []);
    } catch (err) {
      console.error(err);
      setError('加载执行日志失败,请重试');
    } finally {
      setLoading(false);
    }
  }, [range]);

  useEffect(() => {
    load();
  }, [load]);

  // load the persisted alert threshold + its change history
  useEffect(() => {
    (async () => {
      try {
        const value = await fetchNumberSetting(ALERT_CONFIG_KEY, 20);
        if (value > 0) setThreshold(value);
      } catch (err) {
        console.error(err);
      }
      try {
        setHistory(await fetchThresholdHistory(20));
      } catch (err) {
        console.error(err);
      }
    })();
  }, []);

  const reloadHistory = useCallback(async () => {
    try {
      setHistory(await fetchThresholdHistory(20));
    } catch (err) {
      console.error(err);
    }
  }, []);

  const changeThreshold = async (value: number) => {
    const previous = threshold;
    setThreshold(value);
    try {
      await saveSettingValue(ALERT_CONFIG_KEY, String(value));
      if (value !== previous) await logThresholdChange(value, previous);
      await reloadHistory();
    } catch (err) {
      console.error(err);
    }
  };

  const thresholdOptions = useMemo(() => {
    const base = [10, 20, 30, 50];
    if (!base.includes(threshold)) base.push(threshold);
    return Array.from(new Set(base)).sort((a, b) => a - b);
  }, [threshold]);

  const scoped = useMemo(
    () => (taskFilter === 'all' ? runs : runs.filter((r) => r.task_id === taskFilter)),
    [runs, taskFilter],
  );

  // daily buckets for the trend chart
  const { days, successSeries, failSeries, labels } = useMemo(() => {
    const buckets: { key: string; label: string; success: number; failed: number }[] = [];
    for (let i = range - 1; i >= 0; i -= 1) {
      const d = new Date();
      d.setHours(0, 0, 0, 0);
      d.setDate(d.getDate() - i);
      buckets.push({
        key: dayKey(d),
        label: `${d.getMonth() + 1}/${d.getDate()}`,
        success: 0,
        failed: 0,
      });
    }
    const map = new Map(buckets.map((b) => [b.key, b]));
    scoped.forEach((r) => {
      if (!r.started_at) return;
      const k = dayKey(new Date(r.started_at));
      const bucket = map.get(k);
      if (!bucket) return;
      if (r.status === 'success') bucket.success += 1;
      else if (r.status === 'failed') bucket.failed += 1;
    });
    return {
      days: buckets,
      labels: buckets.map((b) => b.label),
      successSeries: buckets.map((b) => b.success),
      failSeries: buckets.map((b) => b.failed),
    };
  }, [scoped, range]);

  const summary = useMemo(() => {
    const total = scoped.length;
    const success = scoped.filter((r) => r.status === 'success').length;
    const failed = scoped.filter((r) => r.status === 'failed').length;
    const durations = scoped.map((r) => r.duration_ms ?? 0).filter((d) => d > 0);
    const avg = durations.length ? Math.round(durations.reduce((s, d) => s + d, 0) / durations.length) : 0;
    const decided = success + failed;
    const rate = decided ? Math.round((success / decided) * 100) : 100;
    return { total, success, failed, avg, rate };
  }, [scoped]);

  // per-task aggregation
  const perTask = useMemo(() => {
    const map = new Map<
      string,
      { id: string; name: string; total: number; success: number; fail: number; durSum: number; durN: number; last: string | null }
    >();
    tasks.forEach((t) => {
      map.set(t.id, { id: t.id, name: t.name, total: 0, success: 0, fail: 0, durSum: 0, durN: 0, last: null });
    });
    runs.forEach((r) => {
      const id = r.task_id ?? '';
      if (!id) return;
      const item =
        map.get(id) ??
        { id, name: r.task_name ?? '未知任务', total: 0, success: 0, fail: 0, durSum: 0, durN: 0, last: null };
      item.total += 1;
      if (r.status === 'success') item.success += 1;
      else if (r.status === 'failed') item.fail += 1;
      if (r.duration_ms) {
        item.durSum += r.duration_ms;
        item.durN += 1;
      }
      if (r.started_at && (!item.last || r.started_at > item.last)) item.last = r.started_at;
      map.set(id, item);
    });
    return Array.from(map.values())
      .filter((t) => t.total > 0)
      .sort((a, b) => b.total - a.total);
  }, [runs, tasks]);

  const withRates = useMemo(
    () =>
      perTask.map((t) => ({
        ...t,
        avg: t.durN ? Math.round(t.durSum / t.durN) : 0,
        rate: t.success + t.fail ? Math.round((t.success / (t.success + t.fail)) * 100) : 100,
        failRate: t.success + t.fail ? Math.round((t.fail / (t.success + t.fail)) * 100) : 0,
      })),
    [perTask],
  );

  const alertTasks = useMemo(
    () => withRates.filter((t) => t.failRate >= threshold),
    [withRates, threshold],
  );

  const sortedTasks = useMemo(() => {
    const arr = [...withRates];
    if (sortBy === 'failRate') arr.sort((a, b) => b.failRate - a.failRate || b.avg - a.avg);
    else arr.sort((a, b) => b.avg - a.avg || b.failRate - a.failRate);
    return arr;
  }, [withRates, sortBy]);

  const topTasks = useMemo(() => {
    if (sortBy === 'failRate') {
      return [...withRates]
        .filter((t) => t.total > 0)
        .sort((a, b) => b.failRate - a.failRate || b.avg - a.avg)
        .slice(0, 5);
    }
    return [...withRates].filter((t) => t.avg > 0).sort((a, b) => b.avg - a.avg).slice(0, 5);
  }, [withRates, sortBy]);

  const maxBar = useMemo(
    () => topTasks.reduce((m, t) => Math.max(m, sortBy === 'failRate' ? t.failRate : t.avg), 0) || 1,
    [topTasks, sortBy],
  );

  const recentFailed = useMemo(
    () =>
      runs
        .filter((r) => r.status === 'failed')
        .slice(-6)
        .reverse(),
    [runs],
  );

  const exportAlertCsv = () => {
    if (alertTasks.length === 0) return;
    const csvCell = (v: unknown) => {
      const s = String(v ?? '');
      return /[",\n\r]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
    };
    const header = ['任务名称', '执行次数', '成功', '失败', '成功率(%)', '失败率(%)', '平均耗时(ms)', '最近执行'];
    const lines = alertTasks.map((t) =>
      [t.name, t.total, t.success, t.fail, t.rate, t.failRate, t.avg, t.last ?? ''].map(csvCell).join(','),
    );
    const csv = `\uFEFF${[header.join(','), ...lines].join('\r\n')}`;
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `task-alerts-${Date.now()}.csv`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const series = useMemo(
    () => [
      { name: '成功', color: cssVar('--primary-500', '#0d9488'), data: successSeries },
      { name: '失败', color: cssVar('--accent-500', '#ea580c'), data: failSeries },
    ],
    [successSeries, failSeries],
  );

  return (
    <div className="space-y-4">
      <div className="flex flex-col md:flex-row md:items-center gap-3">
        <div className="flex items-center gap-2">
          <span className="w-8 h-8 rounded-md flex items-center justify-center bg-primary-100 text-primary-700">
            <i className="ri-line-chart-line text-sm"></i>
          </span>
          <div>
            <h3 className="text-sm font-semibold text-foreground-950">执行日志看板</h3>
            <p className="text-[11px] text-foreground-500">按任务聚合成功 / 失败趋势,数据取自真实执行记录</p>
          </div>
        </div>
        <div className="md:ml-auto flex flex-wrap items-center gap-2">
          <div className="flex items-center gap-1 p-1 rounded-full bg-background-100 border border-background-200">
            <span className="px-2 text-[11px] text-foreground-500 whitespace-nowrap">排序</span>
            <button
              type="button"
              onClick={() => setSortBy('duration')}
              className={`h-7 px-3 rounded-full text-[11px] cursor-pointer whitespace-nowrap transition-colors ${
                sortBy === 'duration'
                  ? 'bg-primary-500 text-background-50 dark:text-foreground-950'
                  : 'text-foreground-600 hover:bg-background-200'
              }`}
            >
              按耗时
            </button>
            <button
              type="button"
              onClick={() => setSortBy('failRate')}
              className={`h-7 px-3 rounded-full text-[11px] cursor-pointer whitespace-nowrap transition-colors ${
                sortBy === 'failRate'
                  ? 'bg-primary-500 text-background-50 dark:text-foreground-950'
                  : 'text-foreground-600 hover:bg-background-200'
              }`}
            >
              按失败率
            </button>
          </div>
          <label
            className="flex items-center gap-1.5 text-[11px] text-foreground-600 whitespace-nowrap"
            title="阈值已同步到系统配置中心,可在配置中心修改"
          >
            <i className="ri-alert-line text-accent-700"></i>
            失败率阈值
            <select
              value={threshold}
              onChange={(e) => changeThreshold(Number(e.target.value))}
              className="h-9 px-2 rounded-md bg-background-50 border border-background-200 text-sm text-foreground-800 focus:outline-none cursor-pointer"
            >
              {thresholdOptions.map((v) => (
                <option key={v} value={v}>
                  {v}%
                </option>
              ))}
            </select>
          </label>
          <div className="relative">
            <button
              type="button"
              onClick={() => setHistoryOpen((v) => !v)}
              title="查看阈值变更历史"
              className="h-9 px-2.5 rounded-md bg-background-50 border border-background-200 text-sm text-foreground-700 hover:bg-background-100 cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5"
            >
              <i className="ri-history-line"></i>
              阈值变更
              <span className="font-label text-[11px] text-foreground-500">{history.length}</span>
            </button>
            {historyOpen ? (
              <>
                <button
                  type="button"
                  aria-label="关闭"
                  onClick={() => setHistoryOpen(false)}
                  className="fixed inset-0 z-40 cursor-default"
                />
                <div className="absolute right-0 mt-1 w-[320px] z-50 rounded-lg border border-background-200 bg-background-50">
                  <div className="flex items-center gap-2 px-3 py-2.5 border-b border-background-200">
                    <i className="ri-history-line text-sm text-secondary-800"></i>
                    <span className="text-xs font-semibold text-foreground-950">阈值变更历史</span>
                    <button
                      type="button"
                      onClick={reloadHistory}
                      title="刷新"
                      className="ml-auto w-7 h-7 flex items-center justify-center rounded-md text-foreground-500 hover:bg-background-100 cursor-pointer"
                    >
                      <i className="ri-refresh-line text-sm"></i>
                    </button>
                  </div>
                  <div className="max-h-[280px] overflow-y-auto">
                    {history.length === 0 ? (
                      <p className="py-8 text-center text-xs text-foreground-500">暂无变更记录</p>
                    ) : (
                      <ul className="divide-y divide-background-200">
                        {history.map((h) => (
                          <li key={h.id} className="px-3 py-2.5">
                            <div className="flex items-center gap-2">
                              <span className="inline-flex items-center gap-1.5 text-[11px] font-label">
                                {h.previous_threshold != null ? (
                                  <>
                                    <span className="text-foreground-500">{h.previous_threshold}%</span>
                                    <i className="ri-arrow-right-line text-foreground-400"></i>
                                  </>
                                ) : null}
                                <span className="px-1.5 py-0.5 rounded-full bg-primary-100 text-primary-800 font-semibold">
                                  {h.threshold}%
                                </span>
                              </span>
                              <span className="ml-auto text-[10px] text-foreground-500 font-label whitespace-nowrap">
                                {h.created_at ? new Date(h.created_at).toLocaleString() : ''}
                              </span>
                            </div>
                            <p className="mt-1 text-[11px] text-foreground-600">操作人:{h.changed_by_name || '未知'}</p>
                            <div className="mt-1.5 flex items-center gap-2">
                              <span className="text-[10px] text-foreground-500">
                                {h.threshold === threshold ? '当前阈值' : '历史版本'}
                              </span>
                              <button
                                type="button"
                                onClick={() => changeThreshold(h.threshold)}
                                disabled={h.threshold === threshold}
                                title={
                                  h.threshold === threshold
                                    ? '当前告警阈值已是该值'
                                    : `把告警阈值回滚到 ${h.threshold}%`
                                }
                                className="ml-auto inline-flex items-center gap-1 h-6 px-2 rounded-full border border-background-300 text-[10px] text-foreground-700 hover:bg-background-100 hover:border-primary-300 hover:text-primary-800 disabled:opacity-40 disabled:cursor-not-allowed cursor-pointer whitespace-nowrap"
                              >
                                <i className="ri-restart-line"></i>
                                回滚到此值
                              </button>
                            </div>
                          </li>
                        ))}
                      </ul>
                    )}
                  </div>
                </div>
              </>
            ) : null}
          </div>
          <button
            type="button"
            onClick={exportAlertCsv}
            disabled={alertTasks.length === 0}
            title={alertTasks.length === 0 ? '当前没有超过阈值的告警任务' : '导出全部告警任务为 CSV'}
            className="h-9 px-3 rounded-md bg-background-50 border border-background-200 text-sm text-foreground-700 hover:bg-background-100 disabled:opacity-50 cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5"
          >
            <i className="ri-file-excel-2-line"></i>
            导出告警 CSV
            {alertTasks.length > 0 ? (
              <span className="font-label text-[11px] text-accent-700">{alertTasks.length}</span>
            ) : null}
          </button>
          <select
            value={taskFilter}
            onChange={(e) => setTaskFilter(e.target.value)}
            className="h-9 px-3 rounded-md bg-background-50 border border-background-200 text-sm text-foreground-800 focus:outline-none cursor-pointer"
          >
            <option value="all">全部任务</option>
            {tasks.map((t) => (
              <option key={t.id} value={t.id}>
                {t.name}
              </option>
            ))}
          </select>
          <div className="flex items-center gap-1 p-1 rounded-full bg-background-100 border border-background-200">
            {rangeOptions.map((o) => (
              <button
                key={o.value}
                type="button"
                onClick={() => setRange(o.value)}
                className={`h-7 px-3 rounded-full text-[11px] cursor-pointer whitespace-nowrap transition-colors ${
                  range === o.value
                    ? 'bg-primary-500 text-background-50 dark:text-foreground-950'
                    : 'text-foreground-600 hover:bg-background-200'
                }`}
              >
                {o.label}
              </button>
            ))}
          </div>
        </div>
      </div>

      {error ? (
        <div className="flex items-center justify-between gap-3 rounded-lg bg-accent-100 border border-accent-200 px-4 py-3">
          <span className="text-sm text-accent-900">{error}</span>
          <button
            type="button"
            onClick={load}
            className="h-8 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-800 hover:bg-background-100 cursor-pointer whitespace-nowrap"
          >
            重试
          </button>
        </div>
      ) : null}

      <section className="grid grid-cols-2 xl:grid-cols-4 gap-3 md:gap-4">
        {[
          { label: '执行总数', value: summary.total.toLocaleString(), icon: 'ri-refresh-line', tone: 'bg-primary-100 text-primary-700' },
          { label: '成功率', value: `${summary.rate}%`, icon: 'ri-checkbox-circle-line', tone: 'bg-primary-100 text-primary-700' },
          { label: '失败次数', value: summary.failed, icon: 'ri-error-warning-line', tone: 'bg-accent-100 text-accent-800' },
          { label: '平均耗时', value: `${summary.avg} ms`, icon: 'ri-timer-line', tone: 'bg-secondary-200 text-secondary-900' },
        ].map((s) => (
          <div key={s.label} className="rounded-lg bg-background-50 border border-background-200 p-4">
            <div className="flex items-center gap-2">
              <span className={`w-8 h-8 rounded-md flex items-center justify-center ${s.tone}`}>
                <i className={`${s.icon} text-sm`}></i>
              </span>
              <span className="text-xs text-foreground-500">{s.label}</span>
            </div>
            <p className="mt-2.5 text-2xl font-semibold text-foreground-950 font-label">{s.value}</p>
          </div>
        ))}
      </section>

      <div className="rounded-lg bg-background-50 border border-background-200 p-4 md:p-5">
        <div className="flex flex-wrap items-center gap-3 mb-2">
          <h4 className="text-sm font-semibold text-foreground-950">成功 / 失败趋势</h4>
          <div className="flex items-center gap-3">
            <span className="inline-flex items-center gap-1.5 text-[11px] text-foreground-600">
              <span className="w-2.5 h-2.5 rounded-full bg-primary-500" />
              成功
            </span>
            <span className="inline-flex items-center gap-1.5 text-[11px] text-foreground-600">
              <span className="w-2.5 h-2.5 rounded-full bg-accent-500" />
              失败
            </span>
          </div>
          <span className="ml-auto text-[11px] text-foreground-500">共 {days.length} 天</span>
        </div>
        {loading ? (
          <div className="h-[190px] rounded-md bg-background-100 animate-pulse-soft" />
        ) : summary.total === 0 ? (
          <div className="h-[190px] flex items-center justify-center text-foreground-500 text-sm">
            <div className="text-center">
              <i className="ri-line-chart-line text-2xl block mb-2"></i>
              该时间范围内暂无执行记录
            </div>
          </div>
        ) : (
          <LineChart series={series} height={190} minValue={0} />
        )}
        {!loading && summary.total > 0 ? (
          <div className="mt-2 flex flex-wrap gap-x-3 gap-y-1 text-[10px] text-foreground-400 font-label">
            {labels.map((l) => (
              <span key={l}>{l}</span>
            ))}
          </div>
        ) : null}
      </div>

      <div className="rounded-lg bg-background-50 border border-background-200 overflow-hidden">
        <div className="flex items-center gap-2 px-4 py-3 border-b border-background-200">
          <i className="ri-speed-up-line text-sm text-secondary-800"></i>
          <h4 className="text-sm font-semibold text-foreground-950">
            Top 任务 · {sortBy === 'failRate' ? '按失败率' : '按平均耗时'}
          </h4>
          <span className="text-[11px] text-foreground-500 ml-auto">
            {sortBy === 'failRate' ? '失败率最高' : '耗时最高'}的前 {topTasks.length} 个任务
          </span>
        </div>
        {loading ? (
          <div className="p-4 space-y-2.5">
            {[0, 1, 2].map((n) => (
              <div key={n} className="h-12 rounded-md bg-background-100 animate-pulse-soft" />
            ))}
          </div>
        ) : topTasks.length === 0 ? (
          <p className="py-12 text-center text-sm text-foreground-500">
            暂无可统计的{sortBy === 'failRate' ? '失败率' : '耗时'}数据
          </p>
        ) : (
          <ul className="divide-y divide-background-200">
            {topTasks.map((t, i) => {
              const alerted = t.failRate >= threshold;
              return (
                <li key={t.id} className="px-4 py-3">
                  <div className="flex items-center gap-3">
                    <span
                      className={`w-6 h-6 rounded-md flex items-center justify-center text-[11px] font-semibold shrink-0 ${
                        i === 0
                          ? 'bg-primary-500 text-background-50 dark:text-foreground-950'
                          : 'bg-background-100 text-foreground-700'
                      }`}
                    >
                      {i + 1}
                    </span>
                    <div className="min-w-0 flex-1">
                      <div className="flex items-center gap-2">
                        <span className="text-sm font-medium text-foreground-950 truncate">{t.name}</span>
                        {alerted ? (
                          <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-accent-100 text-accent-900 inline-flex items-center gap-1">
                            <i className="ri-alert-line"></i>
                            失败率 {t.failRate}%
                          </span>
                        ) : null}
                        <span className="ml-auto text-xs font-label text-foreground-800 whitespace-nowrap">
                          {sortBy === 'failRate' ? `${t.failRate}%` : `${t.avg} ms`}
                        </span>
                      </div>
                      <div className="mt-1.5 h-2 rounded-full bg-background-200 overflow-hidden">
                        <div
                          className={`h-full rounded-full ${alerted ? 'bg-accent-500' : 'bg-secondary-500'}`}
                          style={{
                            width: `${Math.max(
                              6,
                              Math.round(
                                ((sortBy === 'failRate' ? t.failRate : t.avg) / maxBar) * 100,
                              ),
                            )}%`,
                          }}
                        />
                      </div>
                      <div className="mt-1 flex flex-wrap gap-x-4 text-[10px] text-foreground-500 font-label">
                        <span>执行 {t.total}</span>
                        <span>成功 {t.success}</span>
                        <span>失败 {t.fail}</span>
                      </div>
                    </div>
                  </div>
                </li>
              );
            })}
          </ul>
        )}
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-[1.5fr_1fr] gap-4">
        <div className="rounded-lg bg-background-50 border border-background-200 overflow-hidden">
          <div className="flex items-center gap-2 px-4 py-3 border-b border-background-200">
            <i className="ri-list-check-2 text-sm text-primary-700"></i>
            <h4 className="text-sm font-semibold text-foreground-950">按任务聚合</h4>
            {alertTasks.length > 0 ? (
              <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-accent-100 text-accent-900 inline-flex items-center gap-1">
                <i className="ri-alert-line"></i>
                {alertTasks.length} 个告警
              </span>
            ) : null}
            <span className="text-[11px] text-foreground-500 ml-auto">
              按{sortBy === 'failRate' ? '失败率' : '耗时'}排序 · 共 {perTask.length} 个有记录的任务
            </span>
          </div>
          {loading ? (
            <div className="p-4 space-y-2">
              {[0, 1, 2].map((n) => (
                <div key={n} className="h-12 rounded-md bg-background-100 animate-pulse-soft" />
              ))}
            </div>
          ) : perTask.length === 0 ? (
            <p className="py-12 text-center text-sm text-foreground-500">暂无聚合数据</p>
          ) : (
            <ul className="divide-y divide-background-200">
              {sortedTasks.map((t) => {
                const alerted = t.failRate >= threshold;
                return (
                  <li key={t.id} className={`px-4 py-3 ${alerted ? 'bg-accent-100/40' : ''}`}>
                    <div className="flex items-center gap-2 flex-wrap">
                      {alerted ? (
                        <span
                          className="w-5 h-5 rounded-md flex items-center justify-center bg-accent-100 text-accent-800 shrink-0"
                          title={`失败率 ${t.failRate}% 已超过阈值 ${threshold}%`}
                        >
                          <i className="ri-alert-line text-xs"></i>
                        </span>
                      ) : null}
                      <span className="text-sm font-medium text-foreground-950 truncate">{t.name}</span>
                      {alerted ? (
                        <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-accent-500 text-background-50 dark:text-foreground-950">
                          失败率 {t.failRate}%
                        </span>
                      ) : null}
                      <span className="text-[11px] text-foreground-500 ml-auto whitespace-nowrap">
                        最近 {timeAgo(t.last)}
                      </span>
                    </div>
                    <div className="mt-2 flex items-center gap-3">
                      <div className="flex-1 h-2 rounded-full bg-background-200 overflow-hidden">
                        <div
                          className={`h-full rounded-full ${alerted ? 'bg-accent-500' : 'bg-primary-500'}`}
                          style={{ width: `${t.rate}%` }}
                        />
                      </div>
                      <span className="text-xs font-label text-foreground-800 w-12 text-right">{t.rate}%</span>
                    </div>
                    <div className="mt-1.5 flex flex-wrap gap-x-4 gap-y-1 text-[11px] text-foreground-500 font-label">
                      <span>执行 {t.total}</span>
                      <span className="text-primary-700">成功 {t.success}</span>
                      <span className="text-accent-800">失败 {t.fail}</span>
                      <span>均耗时 {t.avg} ms</span>
                    </div>
                  </li>
                );
              })}
            </ul>
          )}
        </div>

        <div className="rounded-lg bg-background-50 border border-background-200 overflow-hidden">
          <div className="flex items-center gap-2 px-4 py-3 border-b border-background-200">
            <i className="ri-error-warning-line text-sm text-accent-700"></i>
            <h4 className="text-sm font-semibold text-foreground-950">近期失败记录</h4>
          </div>
          {loading ? (
            <div className="p-4 space-y-2">
              {[0, 1, 2].map((n) => (
                <div key={n} className="h-12 rounded-md bg-background-100 animate-pulse-soft" />
              ))}
            </div>
          ) : recentFailed.length === 0 ? (
            <p className="py-12 text-center text-sm text-foreground-500">
              <i className="ri-shield-check-line text-2xl block mb-2 text-primary-500"></i>
              该范围内没有失败记录
            </p>
          ) : (
            <ul className="divide-y divide-background-200">
              {recentFailed.map((r) => (
                <li key={r.id} className="px-4 py-3">
                  <div className="flex items-center gap-2">
                    <span className="w-6 h-6 rounded-md flex items-center justify-center bg-accent-100 text-accent-800 shrink-0">
                      <i className="ri-close-line text-xs"></i>
                    </span>
                    <span className="text-xs font-medium text-foreground-950 truncate">{r.task_name}</span>
                    <span className="ml-auto text-[10px] text-foreground-500 font-label whitespace-nowrap">
                      {r.started_at ? new Date(r.started_at).toLocaleString() : '—'}
                    </span>
                  </div>
                  <p className="mt-1.5 text-[11px] text-foreground-600 leading-relaxed pl-8">
                    {r.output || '无输出'}
                  </p>
                </li>
              ))}
            </ul>
          )}
        </div>
      </div>
    </div>
  );
}