import { supabase } from '@/lib/supabase';

export type LoginLogStatus = 'success' | 'failed' | 'logout';

interface RecordLoginLogParams {
  email: string | null;
  userName?: string | null;
  userId?: string | null;
  status: LoginLogStatus;
  message?: string | null;
}

interface ClientInfo {
  device: string;
  browser: string;
}

function versionFrom(ua: string, pattern: RegExp): string {
  const match = ua.match(pattern);
  return match?.[1] ? ` ${match[1]}` : '';
}

/** 从浏览器 UA 粗略识别设备与浏览器,用于登录日志展示。 */
function detectClient(): ClientInfo {
  if (typeof navigator === 'undefined') {
    return { device: '未知设备', browser: '未知浏览器' };
  }
  const ua = navigator.userAgent;

  let device = '桌面设备';
  if (/iPhone/.test(ua)) device = 'iPhone';
  else if (/iPad/.test(ua)) device = 'iPad';
  else if (/Android/.test(ua)) device = 'Android' + versionFrom(ua, /Android\s([\d.]+)/);
  else if (/Macintosh|Mac OS X/.test(ua)) device = 'macOS' + versionFrom(ua, /Mac OS X\s([\d_]+)/).replace(/_/g, '.');
  else if (/Windows NT 10/.test(ua)) device = 'Windows 10/11';
  else if (/Windows NT 6\.3/.test(ua)) device = 'Windows 8.1';
  else if (/Windows/.test(ua)) device = 'Windows';
  else if (/Linux/.test(ua)) device = 'Linux';

  let browser = '未知浏览器';
  if (/Edg\//.test(ua)) browser = 'Edge' + versionFrom(ua, /Edg\/([\d.]+)/);
  else if (/OPR\//.test(ua) || /Opera/.test(ua)) browser = 'Opera' + versionFrom(ua, /OPR\/([\d.]+)/);
  else if (/Chrome\//.test(ua)) browser = 'Chrome' + versionFrom(ua, /Chrome\/([\d.]+)/);
  else if (/Firefox\//.test(ua)) browser = 'Firefox' + versionFrom(ua, /Firefox\/([\d.]+)/);
  else if (/Safari\//.test(ua)) browser = 'Safari' + versionFrom(ua, /Version\/([\d.]+)/);

  return { device, browser };
}

/**
 * 把一次登录行为写入登录日志。失败静默处理,绝不阻塞登录流程。
 * 成功登录时会自动补全当前用户信息,失败登录则只记录被尝试的邮箱。
 */
export async function recordLoginLog({
  email,
  userName = null,
  userId = null,
  status,
  message = null,
}: RecordLoginLogParams): Promise<void> {
  try {
    const { device, browser } = detectClient();
    let finalUserId = userId;
    let finalUserName = userName;

    if (status !== 'failed' && (!finalUserId || !finalUserName)) {
      const { data } = await supabase.auth.getUser();
      finalUserId = finalUserId ?? data.user?.id ?? null;
      finalUserName =
        finalUserName ??
        (data.user?.user_metadata?.full_name as string | undefined) ??
        data.user?.email ??
        null;
    }

    const { error } = await supabase.from('login_logs').insert({
      user_id: finalUserId,
      user_name: finalUserName,
      email,
      status,
      device,
      browser,
      message,
    });
    if (error) throw error;
  } catch (err) {
    console.error('recordLoginLog failed', err);
  }
}

/**
 * 记录一次退出登录。必须在 signOut() 之前调用,否则拿不到当前用户信息。
 * 失败静默处理,绝不阻塞退出流程。
 */
export async function recordLogoutLog(): Promise<void> {
  try {
    const { data } = await supabase.auth.getUser();
    const current = data.user;
    if (!current) return;
    const { device, browser } = detectClient();
    const { error } = await supabase.from('login_logs').insert({
      user_id: current.id,
      user_name:
        (current.user_metadata?.full_name as string | undefined) ?? current.email ?? null,
      email: current.email ?? null,
      status: 'logout',
      device,
      browser,
      message: '退出登录',
    });
    if (error) throw error;
  } catch (err) {
    console.error('recordLogoutLog failed', err);
  }
}

/** 成功登录时建议使用的说明文案。 */
export function successMessage(deviceHint?: string): string {
  return deviceHint ? `${deviceHint} 登录成功` : '登录成功';
}