import { useCallback, useEffect, useState } from 'react';

export interface QuickScheme {
  id: string;
  name: string;
  items: string[];
  updatedAt: string;
}

interface StoredState {
  version: number;
  activeId: string;
  defaultId: string | null;
  schemes: QuickScheme[];
  ownerId: string;
}

const LEGACY_KEY = 'readdy.quickAccess';

function storageKey(userId: string) {
  return `readdy.quickAccess.schemes.${userId || 'guest'}`;
}

function newId() {
  return `s-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`;
}

function makeScheme(name: string, items: string[]): QuickScheme {
  return { id: newId(), name, items, updatedAt: new Date().toISOString() };
}

function readLegacy(defaults: string[]): string[] {
  if (typeof window === 'undefined') return defaults;
  const raw = window.localStorage.getItem(LEGACY_KEY);
  if (raw === null) return defaults;
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed.filter((k) => typeof k === 'string') : defaults;
  } catch (err) {
    console.error(err);
    return defaults;
  }
}

function loadState(userId: string, defaults: string[]): StoredState {
  const fallbackItems = readLegacy(defaults);
  const fallback: StoredState = {
    version: 3,
    activeId: 'default',
    defaultId: null,
    schemes: [{ id: 'default', name: '我的方案', items: fallbackItems, updatedAt: new Date().toISOString() }],
    ownerId: userId,
  };
  if (typeof window === 'undefined') return fallback;
  const raw = window.localStorage.getItem(storageKey(userId));
  if (!raw) return fallback;
  try {
    const parsed = JSON.parse(raw) as Partial<StoredState>;
    if (parsed && Array.isArray(parsed.schemes) && parsed.schemes.length > 0) {
      const schemes = parsed.schemes
        .filter((s): s is QuickScheme => Boolean(s) && typeof s.id === 'string' && Array.isArray(s.items))
        .map((s) => ({
          id: s.id,
          name: typeof s.name === 'string' && s.name.trim() ? s.name : '未命名方案',
          items: s.items.filter((k): k is string => typeof k === 'string'),
          updatedAt: s.updatedAt ?? new Date().toISOString(),
        }));
      if (schemes.length === 0) return fallback;
      const defaultId =
        typeof parsed.defaultId === 'string' && schemes.some((s) => s.id === parsed.defaultId)
          ? parsed.defaultId
          : null;
      // 设有默认方案时,打开/登录后一律套用默认方案;否则沿用上次选中的方案
      const activeId =
        defaultId ??
        (schemes.some((s) => s.id === parsed.activeId) ? (parsed.activeId as string) : schemes[0].id);
      return { version: 3, activeId, defaultId, schemes, ownerId: userId };
    }
  } catch (err) {
    console.error(err);
  }
  return fallback;
}

/**
 * 快捷入口的多套布局方案:每个账号可各自维护、命名并快速切换,
 * 数据按 user id 命名空间存本地,换账号不会串味。
 */
export function useQuickAccessSchemes(userId: string, defaults: string[]) {
  const [state, setState] = useState<StoredState>(() => loadState(userId, defaults));

  useEffect(() => {
    setState(loadState(userId, defaults));
    // 仅在账号切换时重新载入
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [userId]);

  useEffect(() => {
    if (typeof window === 'undefined') return;
    // 只持久化属于当前账号的状态,避免切换账号时把上一个账号的方案写进新账号
    if (state.ownerId !== userId) return;
    window.localStorage.setItem(storageKey(userId), JSON.stringify(state));
  }, [state, userId]);

  const active = state.schemes.find((s) => s.id === state.activeId) ?? state.schemes[0];

  const setItems = useCallback((items: string[]) => {
    setState((prev) => ({
      ...prev,
      schemes: prev.schemes.map((s) =>
        s.id === prev.activeId ? { ...s, items, updatedAt: new Date().toISOString() } : s,
      ),
    }));
  }, []);

  const selectScheme = useCallback((id: string) => {
    setState((prev) => (prev.schemes.some((s) => s.id === id) ? { ...prev, activeId: id } : prev));
  }, []);

  const createScheme = useCallback((name: string, items: string[]) => {
    const scheme = makeScheme(name.trim() || `方案 ${Date.now().toString().slice(-4)}`, items);
    setState((prev) => ({ ...prev, activeId: scheme.id, schemes: [...prev.schemes, scheme] }));
    return scheme.id;
  }, []);

  const renameScheme = useCallback((id: string, name: string) => {
    const trimmed = name.trim();
    if (!trimmed) return;
    setState((prev) => ({
      ...prev,
      schemes: prev.schemes.map((s) => (s.id === id ? { ...s, name: trimmed, updatedAt: new Date().toISOString() } : s)),
    }));
  }, []);

  const duplicateScheme = useCallback((id: string) => {
    setState((prev) => {
      const src = prev.schemes.find((s) => s.id === id);
      if (!src) return prev;
      const copy = makeScheme(`${src.name} 副本`, [...src.items]);
      return { ...prev, activeId: copy.id, schemes: [...prev.schemes, copy] };
    });
  }, []);

  const setDefaultScheme = useCallback((id: string) => {
    setState((prev) => {
      if (!prev.schemes.some((s) => s.id === id)) return prev;
      // 再次点击已设为默认的方案 => 取消默认;设为默认时同时切换过去使用
      const nextDefault = prev.defaultId === id ? null : id;
      return { ...prev, defaultId: nextDefault, activeId: nextDefault ?? prev.activeId };
    });
  }, []);

  const deleteScheme = useCallback((id: string) => {
    setState((prev) => {
      if (prev.schemes.length <= 1) return prev;
      const schemes = prev.schemes.filter((s) => s.id !== id);
      const activeId = prev.activeId === id ? schemes[0].id : prev.activeId;
      const defaultId = prev.defaultId === id ? null : prev.defaultId;
      return { ...prev, activeId, defaultId, schemes };
    });
  }, []);

  /**
   * 把某套方案的入口顺序应用到其他方案:
   * 其他方案按来源方案的排列顺序重排,来源里没有的入口保持原有相对顺序落在末尾,
   * 不会改变各方案自己的入口集合。
   */
  const copySchemeOrder = useCallback((sourceId: string) => {
    setState((prev) => {
      const src = prev.schemes.find((s) => s.id === sourceId);
      if (!src) return prev;
      const orderIndex = new Map(src.items.map((k, i) => [k, i] as const));
      const schemes = prev.schemes.map((s) => {
        if (s.id === sourceId) return s;
        const sorted = [...s.items].sort((a, b) => {
          const ai = orderIndex.has(a) ? (orderIndex.get(a) as number) : Number.MAX_SAFE_INTEGER;
          const bi = orderIndex.has(b) ? (orderIndex.get(b) as number) : Number.MAX_SAFE_INTEGER;
          return ai - bi;
        });
        return { ...s, items: sorted, updatedAt: new Date().toISOString() };
      });
      return { ...prev, schemes };
    });
  }, []);

  return {
    schemes: state.schemes,
    activeId: state.activeId,
    defaultId: state.defaultId,
    active,
    setItems,
    selectScheme,
    createScheme,
    renameScheme,
    duplicateScheme,
    setDefaultScheme,
    deleteScheme,
    copySchemeOrder,
  };
}