import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { onboardingSteps as steps } from '@/config/onboardingSteps';

const STORAGE_KEY = 'readdy.admin.onboarding.v1';

/** 全局事件名:任何地方 dispatch 该事件都能重新唤起上手引导 */
export const ONBOARDING_OPEN_EVENT = 'readdy:onboarding:open';

/** 命令式唤起「5 分钟快速上手」引导(供首页入口按钮等调用) */
export function openOnboardingGuide() {
  window.dispatchEvent(new Event(ONBOARDING_OPEN_EVENT));
}

export default function OnboardingGuide() {
  const [open, setOpen] = useState(false);
  const [index, setIndex] = useState(0);

  useEffect(() => {
    try {
      if (window.localStorage.getItem(STORAGE_KEY) !== 'done') setOpen(true);
    } catch (err) {
      console.error(err);
    }
    const reopen = () => {
      setIndex(0);
      setOpen(true);
    };
    window.addEventListener(ONBOARDING_OPEN_EVENT, reopen);
    return () => window.removeEventListener(ONBOARDING_OPEN_EVENT, reopen);
  }, []);

  const finish = () => {
    try {
      window.localStorage.setItem(STORAGE_KEY, 'done');
    } catch (err) {
      console.error(err);
    }
    setOpen(false);
  };

  if (!open) return null;

  const step = steps[index];
  const isLast = index === steps.length - 1;
  const progress = Math.round(((index + 1) / steps.length) * 100);

  return (
    <div className="fixed inset-0 z-[80] flex items-center justify-center p-4 bg-foreground-950/45">
      <div className="w-full max-w-lg rounded-lg bg-background-50 border border-background-200 overflow-hidden animate-fade-up">
        {/* header */}
        <div className="bg-primary-50 border-b border-background-200 px-5 py-4">
          <div className="flex items-center justify-between gap-3">
            <div className="flex items-center gap-2 min-w-0">
              <span className="w-8 h-8 rounded-md bg-primary-500 text-background-50 flex items-center justify-center shrink-0 dark:text-foreground-950">
                <i className="ri-rocket-2-line"></i>
              </span>
              <div className="min-w-0">
                <p className="text-sm font-semibold text-foreground-950">5 分钟快速上手</p>
                <p className="text-[11px] text-foreground-500">首次进入后台的引导流程 · 第 {index + 1}/{steps.length} 步</p>
              </div>
            </div>
            <button
              type="button"
              onClick={finish}
              title="跳过引导"
              className="text-[11px] text-foreground-500 hover:text-foreground-800 cursor-pointer whitespace-nowrap"
            >
              跳过
            </button>
          </div>
          <div className="mt-3 h-1 rounded-full bg-background-200 overflow-hidden">
            <div className="h-full rounded-full bg-primary-500 transition-all duration-300" style={{ width: `${progress}%` }} />
          </div>
        </div>

        {/* body */}
        <div className="px-5 py-5">
          <div className="flex items-start gap-3.5">
            <span className="w-12 h-12 rounded-lg bg-accent-100 text-accent-900 flex items-center justify-center shrink-0">
              <i className={`${step.icon} text-2xl`}></i>
            </span>
            <div className="min-w-0">
              <h4 className="text-base font-semibold text-foreground-950">{step.title}</h4>
              <p className="mt-1.5 text-sm text-foreground-600 leading-relaxed">{step.desc}</p>
            </div>
          </div>

          <ul className="mt-4 space-y-2">
            {step.tips.map((tip) => (
              <li key={tip} className="flex items-start gap-2 text-xs text-foreground-600">
                <i className="ri-checkbox-circle-line text-primary-600 mt-0.5 shrink-0"></i>
                <span>{tip}</span>
              </li>
            ))}
          </ul>

          {/* step dots */}
          <div className="mt-5 flex items-center gap-1.5">
            {steps.map((s, i) => (
              <button
                key={s.key}
                type="button"
                onClick={() => setIndex(i)}
                title={s.title}
                className={`h-1.5 rounded-full cursor-pointer transition-all ${
                  i === index ? 'w-6 bg-primary-500' : 'w-1.5 bg-background-300 hover:bg-background-400'
                }`}
              />
            ))}
          </div>
        </div>

        {/* footer */}
        <div className="flex flex-wrap items-center gap-2 px-5 py-4 border-t border-background-200">
          {step.action ? (
            <Link
              to={step.action.to}
              onClick={finish}
              className="inline-flex items-center gap-1.5 h-9 px-3.5 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
            >
              <i className="ri-arrow-right-up-line"></i>
              {step.action.label}
            </Link>
          ) : null}
          <div className="ml-auto flex items-center gap-2">
            {index > 0 ? (
              <button
                type="button"
                onClick={() => setIndex((i) => Math.max(0, i - 1))}
                className="h-9 px-3.5 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
              >
                上一步
              </button>
            ) : null}
            {isLast ? (
              <button
                type="button"
                onClick={finish}
                className="h-9 px-4 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 cursor-pointer whitespace-nowrap dark:text-foreground-950"
              >
                开始使用
              </button>
            ) : (
              <button
                type="button"
                onClick={() => setIndex((i) => Math.min(steps.length - 1, i + 1))}
                className="h-9 px-4 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 cursor-pointer whitespace-nowrap dark:text-foreground-950"
              >
                下一步
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}