import { useEffect, useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '@/contexts/AuthContext';
import { allNavItems, navGroups, type NavItem } from '@/config/nav';
import QuickAccessShareModal from '@/pages/home/components/QuickAccessShareModal';
import QuickSchemeMenu from '@/pages/home/components/QuickSchemeMenu';
import { useQuickAccessSchemes } from '@/pages/home/hooks/useQuickAccessSchemes';

const DEFAULT_KEYS = ['monitor', 'plugins', 'builder', 'apidocs'];

const itemIcon: Record<string, string> = {
  home: 'ri-dashboard-3-line',
  monitor: 'ri-pulse-line',
  users: 'ri-user-3-line',
  roles: 'ri-shield-user-line',
  permissions: 'ri-key-2-line',
  tenants: 'ri-building-2-line',
  logs: 'ri-file-list-3-line',
  plugins: 'ri-puzzle-2-line',
  builder: 'ri-layout-masonry-line',
  apidocs: 'ri-code-s-slash-line',
  settings: 'ri-settings-3-line',
  docs: 'ri-book-2-line',
};

const groupOfItem = (key: string) => navGroups.find((g) => g.items.some((i) => i.key === key));

export default function QuickAccess() {
  const { hasPermission, user } = useAuth();
  const {
    schemes,
    activeId,
    defaultId,
    active,
    setItems,
    selectScheme,
    createScheme,
    renameScheme,
    duplicateScheme,
    setDefaultScheme,
    deleteScheme,
    copySchemeOrder,
  } = useQuickAccessSchemes(user?.id ?? '', DEFAULT_KEYS);

  const [pickerOpen, setPickerOpen] = useState(false);
  const [managing, setManaging] = useState(false);
  const [shareOpen, setShareOpen] = useState(false);
  const [draggingKey, setDraggingKey] = useState<string | null>(null);
  const [overKey, setOverKey] = useState<string | null>(null);

  const keys = active?.items ?? [];
  const setKeys = setItems;

  useEffect(() => {
    if (!managing) {
      setDraggingKey(null);
      setOverKey(null);
    }
  }, [managing]);

  const accessibleItems = useMemo(
    () => allNavItems.filter((item) => hasPermission(item.permission)),
    [hasPermission],
  );

  const favorites = useMemo(
    () =>
      keys
        .map((key) => accessibleItems.find((item) => item.key === key))
        .filter((item): item is NavItem => Boolean(item)),
    [keys, accessibleItems],
  );

  const addable = useMemo(
    () => accessibleItems.filter((item) => !keys.includes(item.key)),
    [accessibleItems, keys],
  );

  const add = (key: string) => {
    setKeys(keys.includes(key) ? keys : [...keys, key]);
    setPickerOpen(false);
  };

  const remove = (key: string) => {
    setKeys(keys.filter((k) => k !== key));
  };

  const resetDefault = () => {
    setKeys(DEFAULT_KEYS.filter((k) => accessibleItems.some((i) => i.key === k)));
  };

  const importLayout = (name: string, imported: string[]) => {
    createScheme(name, imported);
    setPickerOpen(false);
  };

  const labelOf = (key: string) =>
    allNavItems.find((item) => item.key === key)?.label ?? key;

  const reorder = (fromKey: string, toKey: string) => {
    if (fromKey === toKey) return;
    const from = keys.indexOf(fromKey);
    const to = keys.indexOf(toKey);
    if (from === -1 || to === -1) return;
    const next = [...keys];
    const [moved] = next.splice(from, 1);
    next.splice(to, 0, moved);
    setKeys(next);
  };

  return (
    <section className="rounded-lg bg-background-50 border border-background-200 p-4 md:p-5">
      <div className="flex flex-wrap items-center gap-2 mb-3.5">
        <span className="w-8 h-8 rounded-md flex items-center justify-center bg-accent-100 text-accent-800">
          <i className="ri-star-line text-base"></i>
        </span>
        <div className="min-w-0">
          <h3 className="text-sm font-semibold text-foreground-950">我的快捷入口</h3>
          <p className="text-[11px] text-foreground-500">
            {managing ? '按住卡片拖动可调整顺序,拖到常用位置' : '多套布局方案,一键切换常用菜单'}
          </p>
        </div>
        <div className="ml-auto flex flex-wrap items-center gap-1.5">
          <QuickSchemeMenu
            schemes={schemes}
            activeId={activeId}
            defaultId={defaultId}
            activeName={active?.name ?? '我的方案'}
            currentCount={favorites.length}
            onSelect={selectScheme}
            onCreate={(name) => createScheme(name, keys)}
            onRename={renameScheme}
            onDuplicate={duplicateScheme}
            onSetDefault={setDefaultScheme}
            onCopyOrder={copySchemeOrder}
            onDelete={deleteScheme}
          />
          <div className="relative">
            <button
              type="button"
              onClick={() => setPickerOpen((v) => !v)}
              className="h-8 px-3 rounded-md bg-primary-500 text-background-50 text-xs hover:bg-primary-600 cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5 dark:text-foreground-950"
            >
              <i className="ri-add-line"></i>
              添加
            </button>
            {pickerOpen ? (
              <>
                <div className="fixed inset-0 z-20" onClick={() => setPickerOpen(false)} aria-hidden="true" />
                <div className="absolute right-0 z-30 mt-1.5 w-64 rounded-lg bg-background-50 border border-background-200 py-1.5 max-h-72 overflow-y-auto animate-fade-up">
                  {addable.length === 0 ? (
                    <p className="px-3 py-2 text-sm text-foreground-500">已收藏全部可用菜单</p>
                  ) : (
                    addable.map((item) => (
                      <button
                        key={item.key}
                        type="button"
                        onClick={() => add(item.key)}
                        className="w-full flex items-center gap-2.5 px-3 py-2 text-left hover:bg-background-100 cursor-pointer"
                      >
                        <i className={`${itemIcon[item.key] ?? 'ri-window-2-line'} text-foreground-400`}></i>
                        <span className="flex-1 min-w-0 text-sm text-foreground-900 truncate">{item.label}</span>
                        <span className="text-[10px] text-foreground-400">{groupOfItem(item.key)?.label}</span>
                      </button>
                    ))
                  )}
                </div>
              </>
            ) : null}
          </div>
          <button
            type="button"
            onClick={() => setShareOpen(true)}
            className="h-8 px-3 rounded-md bg-background-100 border border-background-300 text-xs text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5"
          >
            <i className="ri-share-forward-line"></i>
            分享布局
          </button>
          <button
            type="button"
            onClick={() => setManaging((v) => !v)}
            className={`h-8 px-3 rounded-md border text-xs cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5 ${
              managing
                ? 'bg-foreground-900 text-background-50 border-foreground-900'
                : 'bg-background-100 border-background-300 text-foreground-800 hover:bg-background-200'
            }`}
          >
            <i className={managing ? 'ri-check-line' : 'ri-settings-5-line'}></i>
            {managing ? '完成' : '管理'}
          </button>
        </div>
      </div>

      {favorites.length === 0 ? (
        <div className="rounded-lg border border-dashed border-background-300 py-10 text-center">
          <i className="ri-star-line text-2xl text-foreground-300 block mb-2"></i>
          <p className="text-sm text-foreground-600">该方案还没有收藏的菜单</p>
          <div className="mt-3 flex items-center justify-center gap-2">
            <button
              type="button"
              onClick={() => setPickerOpen(true)}
              className="h-8 px-3 rounded-md bg-primary-500 text-background-50 text-xs hover:bg-primary-600 cursor-pointer whitespace-nowrap dark:text-foreground-950"
            >
              去添加
            </button>
            <button
              type="button"
              onClick={resetDefault}
              className="h-8 px-3 rounded-md bg-background-100 border border-background-300 text-xs text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
            >
              恢复推荐
            </button>
          </div>
        </div>
      ) : (
        <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 xl:grid-cols-6 gap-2.5">
          {favorites.map((item) => {
            const isDragging = draggingKey === item.key;
            const isOver = overKey === item.key && draggingKey !== item.key;
            const inner = (
              <>
                <span className="w-8 h-8 rounded-md bg-background-100 text-foreground-700 flex items-center justify-center group-hover:bg-primary-100 group-hover:text-primary-700 transition-colors">
                  <i className={`${itemIcon[item.key] ?? 'ri-window-2-line'} text-base`}></i>
                </span>
                <span className="min-w-0">
                  <span className="block text-sm text-foreground-900 truncate">{item.label}</span>
                  <span className="block text-[11px] text-foreground-500 font-label truncate">
                    {groupOfItem(item.key)?.label}
                  </span>
                </span>
              </>
            );

            if (managing) {
              return (
                <div
                  key={item.key}
                  draggable
                  onDragStart={() => setDraggingKey(item.key)}
                  onDragEnd={() => {
                    setDraggingKey(null);
                    setOverKey(null);
                  }}
                  onDragOver={(e) => {
                    e.preventDefault();
                    setOverKey(item.key);
                  }}
                  onDragLeave={() => setOverKey((k) => (k === item.key ? null : k))}
                  onDrop={(e) => {
                    e.preventDefault();
                    if (draggingKey) reorder(draggingKey, item.key);
                    setDraggingKey(null);
                    setOverKey(null);
                  }}
                  className={`relative group flex flex-col gap-2.5 rounded-lg border bg-background-50 px-3.5 py-3 cursor-grab active:cursor-grabbing transition-all ${
                    isDragging
                      ? 'opacity-40 border-primary-300 border-dashed'
                      : isOver
                        ? 'border-primary-400 ring-2 ring-primary-200'
                        : 'border-background-200'
                  }`}
                >
                  <span className="absolute top-2 right-2 text-foreground-300">
                    <i className="ri-drag-move-2-line text-sm"></i>
                  </span>
                  {inner}
                  <button
                    type="button"
                    onClick={(e) => {
                      e.stopPropagation();
                      remove(item.key);
                    }}
                    aria-label={`移除 ${item.label}`}
                    className="absolute -top-1.5 -right-1.5 w-5 h-5 rounded-full bg-secondary-500 text-background-50 flex items-center justify-center cursor-pointer hover:bg-secondary-600"
                  >
                    <i className="ri-close-line text-xs"></i>
                  </button>
                </div>
              );
            }

            return (
              <Link
                key={item.key}
                to={item.path}
                className="group flex flex-col gap-2.5 rounded-lg border border-background-200 bg-background-50 px-3.5 py-3 hover:border-primary-300 hover:bg-primary-50/40 cursor-pointer transition-colors"
              >
                {inner}
              </Link>
            );
          })}
        </div>
      )}

      <QuickAccessShareModal
        open={shareOpen}
        schemes={schemes}
        activeId={activeId}
        validKeys={accessibleItems.map((i) => i.key)}
        labelOf={labelOf}
        onImport={importLayout}
        onClose={() => setShareOpen(false)}
      />
    </section>
  );
}