import { docGroups, docSections } from '@/pages/docs/types';

interface DocSidebarProps {
  activeId: string;
  onSelect: (id: string) => void;
}

export default function DocSidebar({ activeId, onSelect }: DocSidebarProps) {
  return (
    <nav className="rounded-lg bg-background-50 border border-background-200 p-3 lg:sticky lg:top-[88px]">
      {docGroups.map((group) => {
        const items = docSections.filter((s) => s.group === group.key);
        if (items.length === 0) return null;
        return (
          <div key={group.key} className="mb-4 last:mb-0">
            <p className="px-2.5 mb-1.5 text-[11px] font-medium text-foreground-400 tracking-wide">
              {group.label}
            </p>
            <ul className="space-y-0.5">
              {items.map((section) => {
                const active = section.id === activeId;
                return (
                  <li key={section.id}>
                    <button
                      type="button"
                      onClick={() => onSelect(section.id)}
                      className={`w-full flex items-center gap-2.5 px-2.5 py-2 rounded-md text-sm text-left transition-colors cursor-pointer ${
                        active
                          ? 'bg-primary-50 text-primary-700 font-medium'
                          : 'text-foreground-700 hover:bg-background-100'
                      }`}
                    >
                      <i className={`${section.icon} text-[15px] ${active ? 'text-primary-600' : 'text-foreground-400'}`}></i>
                      <span className="truncate">{section.label}</span>
                    </button>
                  </li>
                );
              })}
            </ul>
          </div>
        );
      })}
    </nav>
  );
}