import { useCallback, useEffect, useState } from 'react';
import { supabase } from '@/lib/supabase';

export type MetricKey =
  | 'qps'
  | 'avg_latency'
  | 'error_rate'
  | 'cpu_usage'
  | 'memory_usage'
  | 'online_users';

export const METRIC_KEYS: MetricKey[] = [
  'qps',
  'avg_latency',
  'error_rate',
  'cpu_usage',
  'memory_usage',
  'online_users',
];

interface MetricMeta {
  label: string;
  unit: string;
  min: number;
  max: number;
  drift: number;
  decimals: number;
}

export const METRIC_META: Record<MetricKey, MetricMeta> = {
  qps: { label: '实时 QPS', unit: '次/秒', min: 120, max: 340, drift: 26, decimals: 1 },
  avg_latency: { label: '平均响应延迟', unit: 'ms', min: 55, max: 180, drift: 11, decimals: 1 },
  error_rate: { label: '错误率', unit: '%', min: 0, max: 3.2, drift: 0.36, decimals: 2 },
  cpu_usage: { label: 'CPU 使用率', unit: '%', min: 22, max: 92, drift: 6, decimals: 1 },
  memory_usage: { label: '内存使用率', unit: '%', min: 45, max: 88, drift: 3.2, decimals: 1 },
  online_users: { label: '实时在线', unit: '人', min: 180, max: 520, drift: 32, decimals: 0 },
};

export interface MetricPoint {
  t: number;
  v: number;
}

export type MetricSeries = Record<MetricKey, MetricPoint[]>;

const WINDOW = 45;

function emptySeries(): MetricSeries {
  return {
    qps: [],
    avg_latency: [],
    error_rate: [],
    cpu_usage: [],
    memory_usage: [],
    online_users: [],
  };
}

function step(prev: MetricSeries): MetricSeries {
  const now = Date.now();
  const next: MetricSeries = { ...prev };
  METRIC_KEYS.forEach((key) => {
    const meta = METRIC_META[key];
    const arr = prev[key];
    const last = arr.length ? arr[arr.length - 1].v : (meta.min + meta.max) / 2;
    const center = (meta.min + meta.max) / 2;
    let v = last + (center - last) * 0.08 + (Math.random() - 0.5) * meta.drift;
    v = Math.max(meta.min, Math.min(meta.max, v));
    const rounded = Number(v.toFixed(meta.decimals));
    const nextArr = [...arr, { t: now, v: rounded }];
    if (nextArr.length > WINDOW) nextArr.shift();
    next[key] = nextArr;
  });
  return next;
}

export function useLiveMetrics() {
  const [series, setSeries] = useState<MetricSeries>(emptySeries);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [paused, setPaused] = useState(false);
  const [intervalMs, setIntervalMs] = useState(3000);

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const results = await Promise.all(
        METRIC_KEYS.map((key) =>
          supabase
            .from('metrics')
            .select('value, created_at')
            .eq('name', key)
            .order('created_at', { ascending: false })
            .limit(WINDOW),
        ),
      );
      const next = emptySeries();
      results.forEach((res, idx) => {
        if (res.error) throw res.error;
        const key = METRIC_KEYS[idx];
        const rows = (res.data ?? []) as { value: number | string | null; created_at: string | null }[];
        next[key] = rows
          .slice()
          .reverse()
          .map((row) => ({
            t: row.created_at ? new Date(row.created_at).getTime() : Date.now(),
            v: Number(row.value ?? 0),
          }));
      });
      setSeries(next);
    } catch (err) {
      console.error(err);
      setError('加载监控数据失败,请重试');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  useEffect(() => {
    if (paused || loading) return () => undefined;
    const timer = setInterval(() => {
      setSeries((prev) => step(prev));
    }, intervalMs);
    return () => clearInterval(timer);
  }, [paused, loading, intervalMs]);

  return { series, loading, error, reload: load, paused, setPaused, intervalMs, setIntervalMs };
}