import { useCallback, useEffect, useMemo, useState } from 'react';
import { supabase } from '@/lib/supabase';
import { useAuth } from '@/contexts/AuthContext';
import Modal from '@/components/base/Modal';
import {
  type RecycleRow,
  moduleMeta,
  restoreRecycleItem,
  restoreRecycleItems,
  purgeRecycleItem,
  purgeRecycleItems,
  emptyRecycleBin,
} from '@/lib/recycleBin';

function timeAgo(iso: string | null) {
  if (!iso) return '—';
  const diff = Date.now() - new Date(iso).getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return '刚刚';
  if (mins < 60) return `${mins} 分钟前`;
  const hours = Math.floor(mins / 60);
  if (hours < 24) return `${hours} 小时前`;
  return `${Math.floor(hours / 24)} 天前`;
}

const filters = [
  { key: 'all', label: '全部' },
  { key: 'user', label: '用户' },
  { key: 'role', label: '角色' },
  { key: 'department', label: '部门' },
  { key: 'tenant', label: '租户' },
  { key: 'plugin', label: '插件' },
];

export default function RecycleBinPage() {
  const { hasPermission } = useAuth();
  const canManage = hasPermission('recycle:manage');

  const [rows, setRows] = useState<RecycleRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const [filter, setFilter] = useState('all');
  const [keyword, setKeyword] = useState('');
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [busy, setBusy] = useState(false);
  const [purgeTarget, setPurgeTarget] = useState<RecycleRow | null>(null);
  const [batchPurgeOpen, setBatchPurgeOpen] = useState(false);
  const [confirmEmpty, setConfirmEmpty] = useState(false);

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const { data, error: err } = await supabase
        .from('recycle_bin')
        .select('*')
        .order('deleted_at', { ascending: false });
      if (err) throw err;
      setRows((data as RecycleRow[]) ?? []);
      setSelected(new Set());
    } catch (err) {
      console.error(err);
      setError('加载回收站失败,请重试');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  useEffect(() => {
    if (!notice) return;
    const timer = setTimeout(() => setNotice(''), 2600);
    return () => clearTimeout(timer);
  }, [notice]);

  const filtered = useMemo(() => {
    const kw = keyword.trim().toLowerCase();
    return rows.filter((r) => {
      const matchModule = filter === 'all' || r.module === filter;
      const matchKw = !kw || r.item_name.toLowerCase().includes(kw);
      return matchModule && matchKw;
    });
  }, [rows, filter, keyword]);

  const counts = useMemo(() => {
    const map: Record<string, number> = { all: rows.length };
    rows.forEach((r) => {
      map[r.module] = (map[r.module] ?? 0) + 1;
    });
    return map;
  }, [rows]);

  const allChecked = filtered.length > 0 && filtered.every((r) => selected.has(r.id));
  const selectedRows = useMemo(() => rows.filter((r) => selected.has(r.id)), [rows, selected]);

  const toggleOne = (id: string) => {
    setSelected((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const toggleAll = () => {
    setSelected((prev) => {
      if (filtered.every((r) => prev.has(r.id))) {
        const next = new Set(prev);
        filtered.forEach((r) => next.delete(r.id));
        return next;
      }
      return new Set([...prev, ...filtered.map((r) => r.id)]);
    });
  };

  const handleRestore = async (row: RecycleRow) => {
    const res = await restoreRecycleItem(row);
    if (res.ok) {
      setNotice(`「${row.item_name}」${res.message}`);
      await load();
    } else {
      setError(res.message);
    }
  };

  const handleBatchRestore = async () => {
    if (selectedRows.length === 0) return;
    setBusy(true);
    try {
      const { restored, failed } = await restoreRecycleItems(selectedRows);
      if (restored > 0) setNotice(`已批量还原 ${restored} 项${failed > 0 ? `,${failed} 项失败` : ''}`);
      if (failed > 0) setError(`${failed} 项还原失败,可能缺少快照或存在重复记录`);
      await load();
    } finally {
      setBusy(false);
    }
  };

  const confirmPurge = async () => {
    if (!purgeTarget) return;
    const ok = await purgeRecycleItem(purgeTarget.id);
    if (ok) {
      setNotice('已彻底删除');
      await load();
    } else {
      setError('删除失败,可能权限不足');
    }
    setPurgeTarget(null);
  };

  const confirmBatchPurge = async () => {
    setBusy(true);
    try {
      const ok = await purgeRecycleItems(Array.from(selected));
      if (ok) {
        setNotice(`已彻底删除 ${selected.size} 项`);
        await load();
      } else {
        setError('批量删除失败,可能权限不足');
      }
    } finally {
      setBusy(false);
      setBatchPurgeOpen(false);
    }
  };

  const handleEmpty = async () => {
    const ok = await emptyRecycleBin();
    if (ok) {
      setNotice('回收站已清空');
      await load();
    } else {
      setError('清空失败,可能权限不足');
    }
    setConfirmEmpty(false);
  };

  return (
    <div className="space-y-4">
      <div className="flex flex-col md:flex-row md:items-center gap-3">
        <div>
          <h2 className="text-lg font-semibold text-foreground-950">回收站</h2>
          <p className="text-sm text-foreground-500 mt-0.5">
            被删除的用户 / 角色 / 部门 / 租户 / 插件会暂存于此,支持单项或批量还原
          </p>
        </div>
        <div className="md:ml-auto flex flex-wrap items-center gap-2">
          <div className="flex items-center gap-2 h-9 px-3 rounded-md bg-background-50 border border-background-200 w-full sm:w-56">
            <i className="ri-search-line text-foreground-400 text-sm"></i>
            <input
              type="text"
              value={keyword}
              onChange={(e) => setKeyword(e.target.value)}
              placeholder="搜索名称"
              className="flex-1 bg-transparent text-sm text-foreground-900 placeholder:text-foreground-400 focus:outline-none"
            />
          </div>
          <button
            type="button"
            onClick={() => setConfirmEmpty(true)}
            disabled={!canManage || rows.length === 0}
            className="h-9 px-3.5 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-secondary-200 disabled:opacity-40 cursor-pointer whitespace-nowrap flex items-center gap-1.5"
          >
            <i className="ri-delete-bin-2-line"></i>
            清空回收站
          </button>
        </div>
      </div>

      {notice ? (
        <div className="flex items-center gap-2 px-3 py-2.5 rounded-md bg-primary-50 text-primary-800 text-sm animate-fade-up">
          <i className="ri-checkbox-circle-line"></i>
          {notice}
        </div>
      ) : null}
      {error ? (
        <div className="flex items-center justify-between gap-3 px-3 py-2.5 rounded-md bg-accent-100 text-accent-900 text-sm">
          {error}
          <button type="button" onClick={load} className="text-xs underline cursor-pointer whitespace-nowrap">
            重试
          </button>
        </div>
      ) : null}

      <div className="flex flex-wrap items-center gap-1.5">
        {filters.map((f) => (
          <button
            key={f.key}
            type="button"
            onClick={() => setFilter(f.key)}
            className={`h-8 px-3 rounded-full text-xs border cursor-pointer whitespace-nowrap transition-colors ${
              filter === f.key
                ? 'bg-primary-500 text-background-50 border-primary-500 dark:text-foreground-950'
                : 'bg-background-50 text-foreground-700 border-background-300 hover:bg-background-100'
            }`}
          >
            {f.label}
            {counts[f.key] !== undefined ? (
              <span className="ml-1.5 font-label opacity-80">{counts[f.key]}</span>
            ) : null}
          </button>
        ))}
      </div>

      {selected.size > 0 ? (
        <div className="flex flex-wrap items-center gap-3 px-4 py-2.5 rounded-md bg-secondary-100 border border-secondary-200 animate-fade-up">
          <span className="text-sm text-secondary-900">
            已选择 <span className="font-semibold font-label">{selected.size}</span> 项
          </span>
          <div className="ml-auto flex flex-wrap items-center gap-2">
            <button
              type="button"
              onClick={() => setSelected(new Set())}
              className="h-8 px-3 rounded-md bg-background-50 border border-background-300 text-xs text-foreground-800 hover:bg-background-100 cursor-pointer whitespace-nowrap"
            >
              取消选择
            </button>
            <button
              type="button"
              onClick={handleBatchRestore}
              disabled={!canManage || busy}
              className="h-8 px-3 rounded-md bg-primary-500 text-background-50 text-xs hover:bg-primary-600 disabled:opacity-50 cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5 dark:text-foreground-950"
            >
              <i className="ri-arrow-go-back-line"></i>
              {busy ? '处理中…' : '批量还原'}
            </button>
            <button
              type="button"
              onClick={() => setBatchPurgeOpen(true)}
              disabled={!canManage || busy}
              className="h-8 px-3 rounded-md bg-secondary-700 text-background-50 text-xs hover:bg-secondary-800 disabled:opacity-50 cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5"
            >
              <i className="ri-delete-bin-line"></i>
              批量彻底删除
            </button>
          </div>
        </div>
      ) : null}

      <div className="rounded-lg bg-background-50 border border-background-200 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full min-w-[720px] text-sm">
            <thead>
              <tr className="bg-background-100 text-left text-xs text-foreground-500">
                <th className="pl-4 pr-2 py-3 w-10">
                  <input
                    type="checkbox"
                    checked={allChecked}
                    onChange={toggleAll}
                    disabled={filtered.length === 0}
                    className="w-4 h-4 accent-primary-500 cursor-pointer"
                    aria-label="全选"
                  />
                </th>
                <th className="px-4 py-3 font-medium">名称</th>
                <th className="px-4 py-3 font-medium">类型</th>
                <th className="px-4 py-3 font-medium">删除人</th>
                <th className="px-4 py-3 font-medium">删除时间</th>
                <th className="px-4 py-3 font-medium text-right">操作</th>
              </tr>
            </thead>
            <tbody>
              {loading ? (
                [0, 1, 2].map((n) => (
                  <tr key={n} className="border-t border-background-200">
                    <td colSpan={6} className="px-4 py-3">
                      <div className="h-8 rounded-md bg-background-100 animate-pulse-soft" />
                    </td>
                  </tr>
                ))
              ) : filtered.length === 0 ? (
                <tr className="border-t border-background-200">
                  <td colSpan={6} className="px-4 py-14 text-center text-foreground-500">
                    <i className="ri-delete-bin-6-line text-2xl block mb-2"></i>
                    回收站是空的,没有可还原的记录
                  </td>
                </tr>
              ) : (
                filtered.map((row) => {
                  const meta = moduleMeta[row.module] ?? {
                    label: row.module,
                    icon: 'ri-file-line',
                    tone: 'bg-background-200 text-foreground-700',
                  };
                  const checked = selected.has(row.id);
                  return (
                    <tr
                      key={row.id}
                      className={`border-t border-background-200 ${checked ? 'bg-primary-50/60' : 'hover:bg-background-100/60'}`}
                    >
                      <td className="pl-4 pr-2 py-3">
                        <input
                          type="checkbox"
                          checked={checked}
                          onChange={() => toggleOne(row.id)}
                          className="w-4 h-4 accent-primary-500 cursor-pointer"
                          aria-label={`选择 ${row.item_name}`}
                        />
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex items-center gap-2.5">
                          <span className={`w-8 h-8 rounded-md flex items-center justify-center ${meta.tone}`}>
                            <i className={`${meta.icon} text-sm`}></i>
                          </span>
                          <div className="min-w-0">
                            <p className="text-foreground-950 truncate">{row.item_name}</p>
                            <p className="text-[11px] text-foreground-400 font-label truncate">{row.item_id}</p>
                          </div>
                        </div>
                      </td>
                      <td className="px-4 py-3">
                        <span className={`text-[11px] px-2 py-0.5 rounded-full ${meta.tone}`}>{meta.label}</span>
                      </td>
                      <td className="px-4 py-3 text-foreground-700">{row.deleted_by_name || '系统'}</td>
                      <td className="px-4 py-3 text-foreground-600 text-xs">{timeAgo(row.deleted_at)}</td>
                      <td className="px-4 py-3">
                        <div className="flex items-center justify-end gap-1">
                          <button
                            type="button"
                            onClick={() => handleRestore(row)}
                            disabled={!canManage}
                            title="还原"
                            className="h-8 px-2.5 rounded-md bg-background-100 border border-background-300 text-xs text-foreground-800 hover:bg-primary-50 hover:text-primary-700 disabled:opacity-40 cursor-pointer whitespace-nowrap flex items-center gap-1"
                          >
                            <i className="ri-arrow-go-back-line"></i>
                            还原
                          </button>
                          <button
                            type="button"
                            onClick={() => setPurgeTarget(row)}
                            disabled={!canManage}
                            title="彻底删除"
                            className="w-8 h-8 flex items-center justify-center rounded-md text-foreground-500 hover:bg-secondary-200 hover:text-secondary-900 disabled:opacity-40 cursor-pointer"
                          >
                            <i className="ri-delete-bin-line"></i>
                          </button>
                        </div>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>

      <Modal
        open={Boolean(purgeTarget)}
        title="彻底删除"
        onClose={() => setPurgeTarget(null)}
        footer={
          <>
            <button
              type="button"
              onClick={() => setPurgeTarget(null)}
              className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
            >
              取消
            </button>
            <button
              type="button"
              onClick={confirmPurge}
              className="h-9 px-4 rounded-md bg-secondary-700 text-background-50 text-sm hover:bg-secondary-800 cursor-pointer whitespace-nowrap"
            >
              确认删除
            </button>
          </>
        }
      >
        <p className="text-sm text-foreground-700">
          确定要彻底删除
          <span className="font-medium text-foreground-950"> {purgeTarget?.item_name} </span>
          吗?此操作不可恢复。
        </p>
      </Modal>

      <Modal
        open={batchPurgeOpen}
        title="批量彻底删除"
        onClose={() => setBatchPurgeOpen(false)}
        footer={
          <>
            <button
              type="button"
              onClick={() => setBatchPurgeOpen(false)}
              className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
            >
              取消
            </button>
            <button
              type="button"
              onClick={confirmBatchPurge}
              disabled={busy}
              className="h-9 px-4 rounded-md bg-secondary-700 text-background-50 text-sm hover:bg-secondary-800 disabled:opacity-60 cursor-pointer whitespace-nowrap"
            >
              确认删除
            </button>
          </>
        }
      >
        <p className="text-sm text-foreground-700">
          将彻底删除所选的 <span className="font-medium text-foreground-950">{selected.size}</span> 条记录,
          此操作不可恢复。
        </p>
      </Modal>

      <Modal
        open={confirmEmpty}
        title="清空回收站"
        onClose={() => setConfirmEmpty(false)}
        footer={
          <>
            <button
              type="button"
              onClick={() => setConfirmEmpty(false)}
              className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
            >
              取消
            </button>
            <button
              type="button"
              onClick={handleEmpty}
              className="h-9 px-4 rounded-md bg-secondary-700 text-background-50 text-sm hover:bg-secondary-800 cursor-pointer whitespace-nowrap"
            >
              确认清空
            </button>
          </>
        }
      >
        <p className="text-sm text-foreground-700">
          将彻底删除回收站内全部 {rows.length} 条记录,此操作不可恢复。
        </p>
      </Modal>
    </div>
  );
}