import { useCallback, useEffect, useMemo, useState } from 'react';
import { supabase } from '@/lib/supabase';
import { useAuth } from '@/contexts/AuthContext';
import { recordAuditLog } from '@/lib/auditLog';

interface SettingRow {
  id: number;
  category: string | null;
  config_key: string;
  label: string;
  value: string | null;
  value_type: string | null;
  options: string[] | null;
  description: string | null;
  editable: boolean;
  sort_order: number | null;
}

const typeIcon: Record<string, string> = {
  text: 'ri-text',
  number: 'ri-hashtag',
  switch: 'ri-toggle-line',
  select: 'ri-list-check-2',
};

export default function ConfigCenterPage() {
  const { hasPermission } = useAuth();
  const canEdit = hasPermission('setting:update');

  const [rows, setRows] = useState<SettingRow[]>([]);
  const [draft, setDraft] = useState<Record<number, string>>({});
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const [savingCat, setSavingCat] = useState<string | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const { data, error: err } = await supabase
        .from('system_settings')
        .select('*')
        .order('sort_order', { ascending: true });
      if (err) throw err;
      const list = (data as SettingRow[]) ?? [];
      setRows(list);
      const next: Record<number, string> = {};
      list.forEach((r) => {
        next[r.id] = r.value ?? '';
      });
      setDraft(next);
    } catch (err) {
      console.error(err);
      setError('加载系统配置失败,请重试');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  useEffect(() => {
    if (!notice) return;
    const timer = setTimeout(() => setNotice(''), 2600);
    return () => clearTimeout(timer);
  }, [notice]);

  const grouped = useMemo(() => {
    const map = new Map<string, SettingRow[]>();
    rows.forEach((r) => {
      const key = r.category || '其他';
      const arr = map.get(key) ?? [];
      arr.push(r);
      map.set(key, arr);
    });
    return Array.from(map.entries());
  }, [rows]);

  const isDirty = useCallback(
    (id: number) => (draft[id] ?? '') !== (rows.find((r) => r.id === id)?.value ?? ''),
    [draft, rows],
  );

  const dirtyCount = rows.filter((r) => r.editable && isDirty(r.id)).length;

  const saveCategory = async (category: string, items: SettingRow[]) => {
    setSavingCat(category);
    setError('');
    try {
      const changed = items.filter((r) => r.editable && isDirty(r.id));
      for (const r of changed) {
        const { error: err } = await supabase
          .from('system_settings')
          .update({ value: draft[r.id] ?? '', updated_at: new Date().toISOString() })
          .eq('id', r.id);
        if (err) throw err;
      }
      setNotice(changed.length ? `「${category}」已保存 ${changed.length} 项` : `「${category}」暂无改动`);
      if (changed.length > 0) {
        await recordAuditLog({
          action: '修改系统配置',
          module: '系统配置',
          detail: `「${category}」修改 ${changed.length} 项:${changed.map((r) => r.label).join('、')}`,
        });
      }
      await load();
    } catch (err) {
      console.error(err);
      setError('保存失败,请检查权限后重试');
    } finally {
      setSavingCat(null);
    }
  };

  const renderControl = (r: SettingRow) => {
    const disabled = !r.editable || !canEdit;
    const val = draft[r.id] ?? '';
    const base =
      'h-9 rounded-md border border-background-300 bg-background-50 text-sm text-foreground-900 focus:outline-none focus:border-primary-400 disabled:opacity-60 disabled:cursor-not-allowed';

    if (r.value_type === 'switch') {
      const on = val === 'on';
      return (
        <div className="flex items-center gap-2.5">
          <button
            type="button"
            disabled={disabled}
            onClick={() => setDraft((p) => ({ ...p, [r.id]: on ? 'off' : 'on' }))}
            className={`relative w-11 h-6 rounded-full transition-colors cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed ${
              on ? 'bg-primary-500' : 'bg-background-300'
            }`}
            aria-label={r.label}
          >
            <span
              className={`absolute top-0.5 left-0.5 w-5 h-5 rounded-full bg-background-50 transition-transform ${
                on ? 'translate-x-5' : ''
              }`}
            />
          </button>
          <span className="text-xs text-foreground-500">{on ? '开启' : '关闭'}</span>
        </div>
      );
    }

    if (r.value_type === 'select') {
      return (
        <select
          value={val}
          disabled={disabled}
          onChange={(e) => setDraft((p) => ({ ...p, [r.id]: e.target.value }))}
          className={`${base} px-3 min-w-[160px] cursor-pointer`}
        >
          {(r.options ?? []).map((opt) => (
            <option key={opt} value={opt}>
              {opt}
            </option>
          ))}
        </select>
      );
    }

    if (r.value_type === 'number') {
      return (
        <input
          type="number"
          value={val}
          disabled={disabled}
          onChange={(e) => setDraft((p) => ({ ...p, [r.id]: e.target.value }))}
          className={`${base} px-3 w-[160px]`}
        />
      );
    }

    return (
      <input
        type="text"
        value={val}
        disabled={disabled}
        onChange={(e) => setDraft((p) => ({ ...p, [r.id]: e.target.value }))}
        className={`${base} px-3 w-full max-w-[320px]`}
      />
    );
  };

  return (
    <div className="space-y-4">
      <div className="flex flex-col md:flex-row md:items-center gap-3">
        <div>
          <h2 className="text-lg font-semibold text-foreground-950">系统配置中心</h2>
          <p className="text-sm text-foreground-500 mt-0.5">
            集中管理数据库兼容、连接池、运行环境等运行参数,保存后即时生效
          </p>
        </div>
        <div className="md:ml-auto flex items-center gap-2">
          {dirtyCount > 0 ? (
            <span className="text-xs text-accent-700 bg-accent-100 px-2.5 py-1 rounded-full whitespace-nowrap">
              {dirtyCount} 项未保存
            </span>
          ) : (
            <span className="text-xs text-foreground-500 whitespace-nowrap">
              共 {rows.length} 项配置
            </span>
          )}
        </div>
      </div>

      {notice ? (
        <div className="flex items-center gap-2 px-3 py-2.5 rounded-md bg-primary-50 text-primary-800 text-sm animate-fade-up">
          <i className="ri-checkbox-circle-line"></i>
          {notice}
        </div>
      ) : null}
      {error ? (
        <div className="flex items-center justify-between gap-3 px-3 py-2.5 rounded-md bg-accent-100 text-accent-900 text-sm">
          {error}
          <button type="button" onClick={load} className="text-xs underline cursor-pointer whitespace-nowrap">
            重试
          </button>
        </div>
      ) : null}

      {loading ? (
        <div className="space-y-4">
          {[0, 1].map((n) => (
            <div key={n} className="h-48 rounded-lg bg-background-50 border border-background-200 animate-pulse-soft" />
          ))}
        </div>
      ) : (
        <div className="grid grid-cols-1 xl:grid-cols-2 gap-4 items-start">
          {grouped.map(([category, items]) => (
            <div key={category} className="rounded-lg bg-background-50 border border-background-200">
              <div className="flex items-center gap-2.5 px-4 md:px-5 py-3.5 border-b border-background-200">
                <span className="w-7 h-7 rounded-md bg-primary-100 text-primary-700 flex items-center justify-center">
                  <i className="ri-equalizer-2-line text-sm"></i>
                </span>
                <h3 className="text-sm font-semibold text-foreground-950">{category}</h3>
                <span className="ml-auto text-[11px] text-foreground-400">{items.length} 项</span>
              </div>
              <div className="divide-y divide-background-200">
                {items.map((r) => (
                  <div key={r.id} className="px-4 md:px-5 py-3.5 flex flex-col sm:flex-row sm:items-center gap-2.5">
                    <div className="min-w-0 sm:w-56 shrink-0">
                      <div className="flex items-center gap-1.5">
                        <i className={`${typeIcon[r.value_type ?? 'text'] ?? 'ri-text'} text-foreground-400 text-sm`}></i>
                        <span className="text-sm text-foreground-950">{r.label}</span>
                        {!r.editable ? (
                          <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-background-200 text-foreground-600">
                            只读
                          </span>
                        ) : null}
                      </div>
                      {r.description ? (
                        <p className="mt-1 text-[11px] text-foreground-500 leading-relaxed">{r.description}</p>
                      ) : null}
                    </div>
                    <div className="sm:ml-auto">{renderControl(r)}</div>
                  </div>
                ))}
              </div>
              <div className="flex items-center justify-between gap-3 px-4 md:px-5 py-3 border-t border-background-200">
                <span className="text-[11px] text-foreground-400 font-label">
                  {items.filter((r) => r.editable && isDirty(r.id)).length} 项待保存
                </span>
                <button
                  type="button"
                  onClick={() => saveCategory(category, items)}
                  disabled={!canEdit || savingCat === category}
                  className="h-8 px-3.5 rounded-md bg-primary-500 text-background-50 text-xs hover:bg-primary-600 disabled:opacity-50 cursor-pointer whitespace-nowrap dark:text-foreground-950"
                >
                  {savingCat === category ? '保存中…' : '保存本组'}
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {!canEdit ? (
        <p className="text-xs text-foreground-500">当前账号为只读权限,如需修改配置请联系超级管理员。</p>
      ) : null}
    </div>
  );
}