import { useCallback, useEffect, useMemo, useState } from 'react';
import { supabase } from '@/lib/supabase';
import { useAuth } from '@/contexts/AuthContext';
import ProfileCard from '@/pages/settings/account/components/ProfileCard';
import PasswordCard from '@/pages/settings/account/components/PasswordCard';
import PermissionCard from '@/pages/settings/account/components/PermissionCard';
import RecentLogins from '@/pages/settings/account/components/RecentLogins';

interface RoleRow {
  id: string;
  name: string;
  code: string | null;
  description: string | null;
}

interface PermRow {
  id: string;
  name: string;
  code: string | null;
  type: string;
}

interface LoginRow {
  id: string;
  status: string | null;
  ip: string | null;
  location: string | null;
  device: string | null;
  message: string | null;
  created_at: string;
}

export default function AccountPage() {
  const { user, profile, roleCodes, permissions: myCodes, loading: authLoading, refreshProfile } = useAuth();

  const [roles, setRoles] = useState<RoleRow[]>([]);
  const [allPerms, setAllPerms] = useState<PermRow[]>([]);
  const [tenantName, setTenantName] = useState('');
  const [logins, setLogins] = useState<LoginRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  const [savingName, setSavingName] = useState(false);
  const [nameMessage, setNameMessage] = useState('');

  const isSuper = roleCodes.includes('super_admin');

  const load = useCallback(async () => {
    if (!user) return;
    setLoading(true);
    setError('');
    try {
      const [urRes, permRes] = await Promise.all([
        supabase.from('user_roles').select('role_id').eq('user_id', user.id),
        supabase.from('permissions').select('id, name, code, type').order('sort_order', { ascending: true }),
      ]);
      if (urRes.error) throw urRes.error;
      if (permRes.error) throw permRes.error;

      const roleIds = ((urRes.data ?? []) as { role_id: string }[]).map((r) => r.role_id);
      if (roleIds.length > 0) {
        const { data: roleData } = await supabase
          .from('roles')
          .select('id, name, code, description')
          .in('id', roleIds);
        setRoles((roleData as RoleRow[]) ?? []);
      } else {
        setRoles([]);
      }

      setAllPerms((permRes.data as PermRow[]) ?? []);

      if (profile?.tenant_id) {
        const { data: tenant } = await supabase
          .from('tenants')
          .select('name')
          .eq('id', profile.tenant_id)
          .maybeSingle();
        setTenantName((tenant as { name?: string } | null)?.name ?? '');
      } else {
        setTenantName('');
      }

      if (profile?.email || user?.email) {
        const logEmail = user?.email ?? profile?.email;
        const { data: loginData } = await supabase
          .from('login_logs')
          .select('id, status, ip, location, device, message, created_at')
          .eq('email', logEmail)
          .order('created_at', { ascending: false })
          .limit(6);
        setLogins((loginData as LoginRow[]) ?? []);
      } else {
        setLogins([]);
      }
    } catch (err) {
      console.error(err);
      setError('加载账号信息失败,请重试');
    } finally {
      setLoading(false);
    }
  }, [user, profile]);

  useEffect(() => {
    if (!authLoading) load();
  }, [authLoading, load]);

  const grantedPerms = useMemo(() => {
    if (isSuper) return allPerms;
    const codeSet = new Set(myCodes);
    return allPerms.filter((p) => (p.code ? codeSet.has(p.code) : false));
  }, [allPerms, myCodes, isSuper]);

  const handleSaveName = async (newName: string) => {
    if (!user) return;
    if (!newName) {
      setNameMessage('昵称不能为空');
      return;
    }
    setSavingName(true);
    setNameMessage('');
    try {
      const { error: updErr } = await supabase
        .from('profiles')
        .update({ full_name: newName })
        .eq('id', user.id);
      if (updErr) throw updErr;
      await refreshProfile();
      setNameMessage('昵称已更新');
    } catch (err) {
      console.error(err);
      setNameMessage('保存失败,请稍后重试');
    } finally {
      setSavingName(false);
    }
  };

  const handleChangePassword = async (current: string, next: string) => {
    // 密码校验必须用登录邮箱(auth),而不是资料表里可能被修改过的邮箱
    const authEmail = user?.email ?? profile?.email;
    if (!authEmail) {
      return { ok: false, message: '账号信息缺失,无法修改密码' };
    }
    const { error: verifyErr } = await supabase.auth.signInWithPassword({
      email: authEmail,
      password: current,
    });
    if (verifyErr) {
      return { ok: false, message: '当前密码不正确' };
    }
    const { error: updErr } = await supabase.auth.updateUser({ password: next });
    if (updErr) {
      return { ok: false, message: updErr.message };
    }
    return { ok: true, message: '密码已更新,请使用新密码登录' };
  };

  return (
    <div className="space-y-4">
      <div>
        <h2 className="text-lg font-semibold text-foreground-950">个人账号设置</h2>
        <p className="text-sm text-foreground-500 mt-0.5">
          管理你的个人资料、登录密码,并查看当前账号的角色与权限明细
        </p>
      </div>

      {error ? (
        <div className="flex items-center justify-between gap-3 rounded-lg bg-accent-100 border border-accent-200 px-4 py-3">
          <span className="text-sm text-accent-900">{error}</span>
          <button
            type="button"
            onClick={load}
            className="h-8 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-800 hover:bg-background-100 cursor-pointer whitespace-nowrap"
          >
            重试
          </button>
        </div>
      ) : null}

      <div className="grid grid-cols-1 xl:grid-cols-2 gap-4">
        <div className="space-y-4">
          <ProfileCard
            fullName={profile?.full_name ?? ''}
            email={profile?.email ?? ''}
            tenantName={tenantName}
            createdAt={profile?.created_at ?? ''}
            roles={roles}
            saving={savingName}
            message={nameMessage}
            onSave={handleSaveName}
          />
          <PasswordCard onSubmit={handleChangePassword} />
        </div>

        <div className="space-y-4">
          <PermissionCard roles={roles} permissions={grantedPerms} isSuper={isSuper} loading={loading} />
          <RecentLogins logins={logins} loading={loading} />
        </div>
      </div>
    </div>
  );
}