import { useCallback, useEffect, useMemo, useState } from 'react';
import { useAuth } from '@/contexts/AuthContext';
import HighlightText from '@/pages/docs/components/HighlightText';
import SnippetCard from '@/pages/docs/components/SnippetCard';
import { Callout, DocHeading } from '@/pages/docs/components/DocPrimitives';
import { useSdkFavorites } from '@/pages/docs/hooks/useSdkFavorites';
import {
  defaultSdkStack,
  defaultSdkVersion,
  sdkCategories,
  sdkStacks,
  sdkVersions,
  snippetCodeFor,
  snippetFilenameFor,
  type SdkCategory,
  type SdkSnippet,
} from '@/pages/docs/sdkSnippets';

const RECENT_SEARCH_KEY = 'readdy.sdk.recentSearches';

function loadRecentSearches(): string[] {
  if (typeof window === 'undefined') return [];
  try {
    const raw = window.localStorage.getItem(RECENT_SEARCH_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed)
      ? parsed.filter((s): s is string => typeof s === 'string').slice(0, 6)
      : [];
  } catch (err) {
    console.error(err);
    return [];
  }
}

function persistRecentSearches(list: string[]) {
  if (typeof window === 'undefined') return;
  try {
    window.localStorage.setItem(RECENT_SEARCH_KEY, JSON.stringify(list));
  } catch (err) {
    console.error(err);
  }
}

function buildPageText(
  categories: SdkCategory[],
  version: string,
  versionLabel: string,
  stack: string,
  stackLabel: string,
) {
  const lines: string[] = [`# HuaanAdmin SDK 代码片段 · ${stackLabel} · ${versionLabel}`, ''];
  categories.forEach((cat) => {
    lines.push(`## ${cat.label}`);
    cat.snippets.forEach((s) => {
      lines.push(
        '',
        `### ${s.title} — ${snippetFilenameFor(s, stack)}`,
        `> ${s.desc}`,
        '```' + s.language,
        snippetCodeFor(s, version, stack),
        '```',
      );
    });
    lines.push('');
  });
  return lines.join('\n');
}

interface FlatResult {
  category: SdkCategory;
  snippet: SdkSnippet;
}

export default function SdkSection() {
  const [activeKey, setActiveKey] = useState(sdkCategories[0].key);
  const [keyword, setKeyword] = useState('');
  const [globalKeyword, setGlobalKeyword] = useState('');
  const [highlightId, setHighlightId] = useState<string | null>(null);
  const [version, setVersion] = useState(defaultSdkVersion);
  const [stack, setStack] = useState(defaultSdkStack);
  const [copiedPage, setCopiedPage] = useState(false);
  const [onlyFav, setOnlyFav] = useState(false);
  const [recent, setRecent] = useState<string[]>(loadRecentSearches);
  const { user } = useAuth();
  const { favIds, toggleFavorite, syncing: favSyncing, syncError: favError, reload: reloadFavorites } =
    useSdkFavorites(user?.id ?? '');

  const recordSearch = useCallback((term: string) => {
    const value = term.trim();
    if (!value) return;
    setRecent((prev) => {
      const next = [value, ...prev.filter((x) => x !== value)].slice(0, 6);
      persistRecentSearches(next);
      return next;
    });
  }, []);

  const active = sdkCategories.find((c) => c.key === activeKey) ?? sdkCategories[0];
  const activeVersion = sdkVersions.find((v) => v.key === version) ?? sdkVersions[0];
  const activeStack = sdkStacks.find((s) => s.key === stack) ?? sdkStacks[0];
  const favSet = useMemo(() => new Set(favIds), [favIds]);
  const activeFavCount = active.snippets.filter((s) => favSet.has(s.id)).length;

  const trimmedGlobal = globalKeyword.trim().toLowerCase();

  const snippets = useMemo(() => {
    const kw = keyword.trim().toLowerCase();
    const base = kw
      ? active.snippets.filter(
          (s) =>
            s.title.toLowerCase().includes(kw) ||
            s.desc.toLowerCase().includes(kw) ||
            snippetCodeFor(s, version, stack).toLowerCase().includes(kw),
        )
      : active.snippets;
    // 收藏的片段置顶显示
    return [...base].sort((a, b) => Number(favSet.has(b.id)) - Number(favSet.has(a.id)));
  }, [active, keyword, version, stack, favSet]);

  const globalResults = useMemo<FlatResult[]>(() => {
    if (!trimmedGlobal) return [];
    const results: FlatResult[] = [];
    sdkCategories.forEach((cat) => {
      cat.snippets.forEach((s) => {
        const haystack = `${s.title} ${s.desc} ${snippetFilenameFor(s, stack)} ${snippetCodeFor(s, version, stack)}`.toLowerCase();
        if (haystack.includes(trimmedGlobal)) {
          results.push({ category: cat, snippet: s });
        }
      });
    });
    return results;
  }, [trimmedGlobal, version, stack]);

  // 我的收藏:跨分类汇总所有已收藏片段,便于一键聚焦常用代码
  const favSnippets = useMemo<FlatResult[]>(() => {
    const results: FlatResult[] = [];
    sdkCategories.forEach((cat) => {
      cat.snippets.forEach((s) => {
        if (favSet.has(s.id)) results.push({ category: cat, snippet: s });
      });
    });
    return results;
  }, [favSet]);

  const total = sdkCategories.reduce((sum, c) => sum + c.snippets.length, 0);

  // 一键定位:切到目标分类后滚动并高亮对应片段
  useEffect(() => {
    if (!highlightId) return undefined;
    const el = document.getElementById(`sdk-snippet-${highlightId}`);
    if (!el) return undefined;
    el.scrollIntoView({ behavior: 'smooth', block: 'center' });
    const timer = window.setTimeout(() => setHighlightId(null), 2600);
    return () => window.clearTimeout(timer);
  }, [highlightId, activeKey]);

  const jumpTo = (categoryKey: string, snippetId: string) => {
    recordSearch(globalKeyword);
    setActiveKey(categoryKey);
    setKeyword('');
    setGlobalKeyword('');
    setHighlightId(snippetId);
  };

  const copyWholePage = async () => {
    try {
      await navigator.clipboard.writeText(
        buildPageText(sdkCategories, version, activeVersion.label, stack, activeStack.label),
      );
      setCopiedPage(true);
      window.setTimeout(() => setCopiedPage(false), 1800);
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div className="space-y-5">
      <DocHeading id="sdk-intro" sub="把日常最高频的读写与租户隔离逻辑沉淀成片段,复制即用,不用每次从零写。">
        SDK 代码片段
      </DocHeading>

      <Callout tone="tip" title="怎么用">
        顶部先选技术栈,再选框架版本,左侧切换分类,右侧点「复制」直接粘到你的模块里。常用的片段点右上角星标收藏,收藏后会置顶到分类最前面,并同步到你的账号,换台电脑打开仍保持置顶。点「只看已收藏」可一键聚焦全部分类收藏的常用片段。想找某段代码?用下方的全局搜索,输入关键字即可跨全部分类检索,点结果一键定位并高亮。也可一键「复制整页」把所有分类的片段连同说明一起拷走。
      </Callout>

      <div className="rounded-lg border border-background-200 bg-background-50 p-3.5 space-y-3.5">
        <div className="flex flex-col sm:flex-row sm:items-center gap-3">
          <div className="min-w-0">
            <div className="flex items-center gap-1.5 text-sm font-medium text-foreground-950">
              <i className="ri-code-box-line text-primary-600"></i>
              技术栈
            </div>
            <p className="mt-0.5 text-[11px] text-foreground-500">{activeStack.desc}</p>
          </div>
          <div className="sm:ml-auto flex flex-wrap items-center gap-2">
            <div className="flex items-center gap-1 bg-background-100 border border-background-200 rounded-full p-1">
              {sdkStacks.map((s) => (
                <button
                  key={s.key}
                  type="button"
                  onClick={() => setStack(s.key)}
                  className={`h-7 px-3 rounded-full text-xs whitespace-nowrap cursor-pointer transition-colors inline-flex items-center gap-1.5 ${
                    stack === s.key
                      ? 'bg-primary-500 text-background-50 font-medium dark:text-foreground-950'
                      : 'text-foreground-600 hover:text-foreground-900'
                  }`}
                >
                  {s.label}
                  <span
                    className={`text-[9px] px-1 py-0.5 rounded-full ${
                      stack === s.key
                        ? 'bg-background-50/25 text-background-50 dark:text-foreground-950'
                        : 'bg-background-200 text-foreground-600'
                    }`}
                  >
                    {s.tag}
                  </span>
                </button>
              ))}
            </div>
            <button
              type="button"
              onClick={copyWholePage}
              className="h-8 px-3 rounded-md bg-accent-500 text-background-50 text-xs hover:bg-accent-600 cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5 dark:text-foreground-950"
            >
              <i className={copiedPage ? 'ri-check-line' : 'ri-file-copy-2-line'}></i>
              {copiedPage ? '整页已复制' : '复制整页'}
            </button>
          </div>
        </div>

        <div className="flex flex-col sm:flex-row sm:items-center gap-3 pt-3.5 border-t border-background-200">
          <div className="min-w-0">
            <div className="flex items-center gap-1.5 text-sm font-medium text-foreground-950">
              <i className="ri-git-branch-line text-primary-600"></i>
              框架版本
            </div>
            <p className="mt-0.5 text-[11px] text-foreground-500">{activeVersion.desc}</p>
          </div>
          <div className="sm:ml-auto flex flex-wrap items-center gap-2">
            {stack !== defaultSdkStack ? (
              <span className="text-[11px] text-foreground-400 inline-flex items-center gap-1">
                <i className="ri-information-line"></i>
                版本差异仅适用于 React 写法
              </span>
            ) : null}
            <div className="flex items-center gap-1 bg-background-100 border border-background-200 rounded-full p-1">
              {sdkVersions.map((v) => (
                <button
                  key={v.key}
                  type="button"
                  onClick={() => setVersion(v.key)}
                  className={`h-7 px-3 rounded-full text-xs whitespace-nowrap cursor-pointer transition-colors inline-flex items-center gap-1.5 ${
                    version === v.key
                      ? 'bg-primary-500 text-background-50 font-medium dark:text-foreground-950'
                      : 'text-foreground-600 hover:text-foreground-900'
                  }`}
                >
                  {v.label}
                  <span
                    className={`text-[9px] px-1 py-0.5 rounded-full ${
                      version === v.key
                        ? 'bg-background-50/25 text-background-50 dark:text-foreground-950'
                        : 'bg-background-200 text-foreground-600'
                    }`}
                  >
                    {v.tag}
                  </span>
                </button>
              ))}
            </div>
          </div>
        </div>

        <div className="flex flex-col sm:flex-row sm:items-center gap-3 pt-3.5 border-t border-background-200">
          <div className="flex items-center gap-2 h-9 px-3 rounded-md bg-background-50 border border-background-200 w-full sm:w-80">
            <i className="ri-search-line text-foreground-400 text-sm"></i>
            <input
              type="text"
              value={globalKeyword}
              onChange={(e) => setGlobalKeyword(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') recordSearch(globalKeyword);
              }}
              placeholder="跨分类全局搜索片段…"
              className="flex-1 bg-transparent text-sm text-foreground-900 placeholder:text-foreground-400 focus:outline-none"
            />
            {globalKeyword ? (
              <button
                type="button"
                onClick={() => setGlobalKeyword('')}
                aria-label="清空搜索"
                className="w-5 h-5 rounded-full flex items-center justify-center text-foreground-400 hover:text-foreground-700 cursor-pointer"
              >
                <i className="ri-close-circle-line text-sm"></i>
              </button>
            ) : null}
          </div>
          <span className="text-[11px] text-foreground-500 inline-flex items-center gap-1">
            <i className="ri-flashlight-line text-accent-600"></i>
            {trimmedGlobal ? `在全部 ${total} 个片段中检索「${globalKeyword.trim()}」` : '输入关键字,跨全部分类定位代码'}
          </span>
        </div>

        {recent.length > 0 ? (
          <div className="flex flex-wrap items-center gap-1.5 pt-3 border-t border-background-200">
            <span className="text-[11px] text-foreground-500 inline-flex items-center gap-1">
              <i className="ri-history-line"></i>
              最近搜索
            </span>
            {recent.map((term) => (
              <button
                key={term}
                type="button"
                onClick={() => {
                  setGlobalKeyword(term);
                  recordSearch(term);
                }}
                className="px-2.5 py-1 rounded-full bg-background-100 border border-background-200 text-[11px] text-foreground-700 hover:border-primary-300 hover:text-primary-700 cursor-pointer whitespace-nowrap inline-flex items-center gap-1"
              >
                <i className="ri-search-line text-[10px] text-foreground-400"></i>
                {term}
              </button>
            ))}
            <button
              type="button"
              onClick={() => {
                setRecent([]);
                persistRecentSearches([]);
              }}
              className="ml-1 text-[11px] text-foreground-400 hover:text-foreground-700 cursor-pointer whitespace-nowrap"
            >
              清空
            </button>
          </div>
        ) : null}

        <div className="flex flex-wrap items-center gap-2 pt-3 border-t border-background-200">
          <button
            type="button"
            onClick={() => setOnlyFav((v) => !v)}
            disabled={favIds.length === 0}
            className={`h-7 px-3 rounded-full border text-xs cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5 transition-colors disabled:opacity-40 disabled:cursor-not-allowed ${
              onlyFav
                ? 'bg-accent-500 border-accent-500 text-background-50 dark:text-foreground-950'
                : 'bg-background-100 border-background-200 text-foreground-700 hover:border-accent-300'
            }`}
          >
            <i className={onlyFav ? 'ri-filter-3-fill' : 'ri-filter-3-line'}></i>
            只看已收藏
            <span
              className={`text-[10px] px-1.5 rounded-full ${
                onlyFav ? 'bg-background-50/25 text-background-50 dark:text-foreground-950' : 'bg-background-200 text-foreground-600'
              }`}
            >
              {favIds.length}
            </span>
          </button>
          <span className="text-[11px] text-foreground-500 inline-flex items-center gap-1">
            <i className="ri-star-line text-accent-600"></i>
            {onlyFav ? '已聚焦全部收藏片段' : '收藏的片段会在对应分类内置顶'}
          </span>
          {favError ? (
            <span className="inline-flex items-center gap-1.5 text-[11px] text-accent-900 sm:ml-auto">
              <i className="ri-error-warning-line"></i>
              {favError}
              <button type="button" onClick={reloadFavorites} className="underline cursor-pointer whitespace-nowrap">
                重试
              </button>
            </span>
          ) : (
            <span className="inline-flex items-center gap-1.5 text-[11px] text-foreground-400 sm:ml-auto">
              <i className={favSyncing ? 'ri-loader-4-line animate-spin' : 'ri-cloud-line'}></i>
              {user
                ? favSyncing
                  ? '正在同步收藏…'
                  : '收藏已按账号同步,换设备仍置顶'
                : '未登录:收藏仅保存在本机'}
            </span>
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-[200px_1fr] gap-4 items-start">
        <nav className="rounded-lg border border-background-200 bg-background-50 p-2 lg:sticky lg:top-24">
          <p className="px-2.5 py-1.5 text-[11px] font-medium text-foreground-400">
            共 {total} 个片段
          </p>
          <ul className="space-y-0.5">
            {sdkCategories.map((cat) => {
              const on = cat.key === activeKey && !trimmedGlobal && !onlyFav;
              return (
                <li key={cat.key}>
                  <button
                    type="button"
                    onClick={() => {
                      setActiveKey(cat.key);
                      setKeyword('');
                      setGlobalKeyword('');
                      setOnlyFav(false);
                    }}
                    className={`w-full flex items-center gap-2.5 px-2.5 py-2 rounded-md text-sm text-left transition-colors cursor-pointer ${
                      on
                        ? 'bg-primary-50 text-primary-700 font-medium'
                        : 'text-foreground-700 hover:bg-background-100'
                    }`}
                  >
                    <i className={`${cat.icon} text-[15px] ${on ? 'text-primary-600' : 'text-foreground-400'}`}></i>
                    <span className="flex-1 truncate">{cat.label}</span>
                    <span className="text-[11px] text-foreground-400">{cat.snippets.length}</span>
                  </button>
                </li>
              );
            })}
          </ul>
        </nav>

        <div className="min-w-0 space-y-4">
          {trimmedGlobal ? (
            <div className="space-y-3">
              <div className="flex items-center justify-between gap-3">
                <h4 className="text-sm font-semibold text-foreground-950">
                  搜索结果
                  <span className="ml-2 text-xs font-normal text-foreground-500">命中 {globalResults.length} 段代码</span>
                </h4>
                <button
                  type="button"
                  onClick={() => setGlobalKeyword('')}
                  className="text-xs text-foreground-500 hover:text-foreground-800 cursor-pointer whitespace-nowrap inline-flex items-center gap-1"
                >
                  <i className="ri-arrow-go-back-line"></i>
                  返回分类浏览
                </button>
              </div>
              {globalResults.length === 0 ? (
                <div className="rounded-lg border border-background-200 bg-background-50 py-12 text-center text-sm text-foreground-500">
                  <i className="ri-file-search-line text-2xl block mb-2"></i>
                  没有匹配的代码片段,换个关键字试试
                </div>
              ) : (
                <div className="space-y-2">
                  {globalResults.map(({ category, snippet }) => (
                    <button
                      key={`${category.key}-${snippet.id}`}
                      type="button"
                      onClick={() => jumpTo(category.key, snippet.id)}
                      className="group w-full flex items-start gap-3 rounded-lg border border-background-200 bg-background-50 p-3.5 text-left hover:border-primary-300 hover:bg-primary-50/40 cursor-pointer transition-colors"
                    >
                      <span className="w-8 h-8 rounded-md flex items-center justify-center bg-primary-100 text-primary-700 shrink-0">
                        <i className={`${category.icon} text-base`}></i>
                      </span>
                      <span className="min-w-0 flex-1">
                        <span className="flex flex-wrap items-center gap-2">
                          <HighlightText
                            text={snippet.title}
                            keyword={globalKeyword}
                            className="text-sm font-medium text-foreground-950"
                          />
                          <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-secondary-100 text-secondary-900">
                            {category.label}
                          </span>
                          <HighlightText
                            text={snippetFilenameFor(snippet, stack)}
                            keyword={globalKeyword}
                            className="text-[10px] font-label text-foreground-400"
                          />
                        </span>
                        <HighlightText
                          text={snippet.desc}
                          keyword={globalKeyword}
                          className="mt-0.5 block text-xs text-foreground-600 leading-relaxed line-clamp-2"
                        />
                      </span>
                      <span className="shrink-0 inline-flex items-center gap-1 text-[11px] text-primary-700 whitespace-nowrap self-center">
                        定位
                        <i className="ri-arrow-right-s-line group-hover:translate-x-0.5 transition-transform"></i>
                      </span>
                    </button>
                  ))}
                </div>
              )}
            </div>
          ) : onlyFav ? (
            <div className="space-y-3">
              <div className="flex items-center justify-between gap-3">
                <h4 className="text-sm font-semibold text-foreground-950">
                  我的收藏
                  <span className="ml-2 text-xs font-normal text-foreground-500">共 {favSnippets.length} 段代码</span>
                </h4>
                <button
                  type="button"
                  onClick={() => setOnlyFav(false)}
                  className="text-xs text-foreground-500 hover:text-foreground-800 cursor-pointer whitespace-nowrap inline-flex items-center gap-1"
                >
                  <i className="ri-arrow-go-back-line"></i>
                  返回分类浏览
                </button>
              </div>
              {favSnippets.length === 0 ? (
                <div className="rounded-lg border border-background-200 bg-background-50 py-12 text-center text-sm text-foreground-500">
                  <i className="ri-star-line text-2xl block mb-2"></i>
                  还没有收藏的片段,点代码卡片右上角的星标就能收藏
                </div>
              ) : (
                <div className="space-y-4">
                  {favSnippets.map(({ category, snippet }) => (
                    <SnippetCard
                      key={snippet.id}
                      snippet={snippet}
                      version={version}
                      stack={stack}
                      versionLabel={activeVersion.label}
                      stackLabel={activeStack.label}
                      favorited
                      highlighted={highlightId === snippet.id}
                      category={{ icon: category.icon, label: category.label }}
                      onToggleFavorite={toggleFavorite}
                    />
                  ))}
                </div>
              )}
            </div>
          ) : (
            <>
              <div className="flex flex-col sm:flex-row sm:items-center gap-3">
                <div>
                  <h4 className="text-sm font-semibold text-foreground-950 inline-flex items-center gap-2">
                    {active.label}
                    {activeFavCount > 0 ? (
                      <span className="text-[10px] font-normal px-1.5 py-0.5 rounded-full bg-accent-100 text-accent-900 inline-flex items-center gap-0.5">
                        <i className="ri-star-fill text-[9px]"></i>
                        已收藏 {activeFavCount} 段,置顶显示
                      </span>
                    ) : null}
                  </h4>
                  <p className="text-xs text-foreground-500 mt-0.5">{active.desc}</p>
                </div>
                <div className="sm:ml-auto flex items-center gap-2 h-9 px-3 rounded-md bg-background-50 border border-background-200 w-full sm:w-56">
                  <i className="ri-search-line text-foreground-400 text-sm"></i>
                  <input
                    type="text"
                    value={keyword}
                    onChange={(e) => setKeyword(e.target.value)}
                    placeholder="在当前分类内搜索…"
                    className="flex-1 bg-transparent text-sm text-foreground-900 placeholder:text-foreground-400 focus:outline-none"
                  />
                </div>
              </div>

              {snippets.length === 0 ? (
                <div className="rounded-lg border border-background-200 bg-background-50 py-12 text-center text-sm text-foreground-500">
                  <i className="ri-file-search-line text-2xl block mb-2"></i>
                  没有匹配的代码片段
                </div>
              ) : (
                <div className="space-y-4">
                  {snippets.map((s) => (
                    <SnippetCard
                      key={s.id}
                      snippet={s}
                      version={version}
                      stack={stack}
                      versionLabel={activeVersion.label}
                      stackLabel={activeStack.label}
                      favorited={favSet.has(s.id)}
                      highlighted={highlightId === s.id}
                      onToggleFavorite={toggleFavorite}
                    />
                  ))}
                </div>
              )}
            </>
          )}
        </div>
      </div>
    </div>
  );
}