import { supabase } from '@/lib/supabase';

export type AuditLevel = 'info' | 'warn' | 'error';

interface AuditLogParams {
  action: string;
  module: string;
  level?: AuditLevel;
  detail?: string | null;
}

let operatorCache: { id: string | null; name: string } | null = null;

/** 解析当前操作人(取资料里的姓名/邮箱,兜底为「系统」)。 */
async function resolveOperator(): Promise<{ id: string | null; name: string }> {
  if (operatorCache) return operatorCache;
  try {
    const { data } = await supabase.auth.getUser();
    const user = data.user;
    if (!user) {
      return { id: null, name: '系统' };
    }
    const { data: profile } = await supabase
      .from('profiles')
      .select('full_name, email')
      .eq('id', user.id)
      .maybeSingle();
    const name =
      (profile?.full_name as string | undefined) ||
      (profile?.email as string | undefined) ||
      (user.user_metadata?.full_name as string | undefined) ||
      user.email ||
      '系统';
    operatorCache = { id: user.id, name };
    return operatorCache;
  } catch {
    return { id: null, name: '系统' };
  }
}

/** 当前会话切换后调用,清掉操作人缓存。 */
export function clearAuditOperatorCache(): void {
  operatorCache = null;
}

/**
 * 记录一次关键操作到操作日志。失败静默处理,绝不阻塞业务动作。
 * 与数据库触发器(记录角色分配)互补,覆盖前端发起的新增/编辑/删除等操作。
 */
export async function recordAuditLog({
  action,
  module,
  level = 'info',
  detail = null,
}: AuditLogParams): Promise<void> {
  try {
    const operator = await resolveOperator();
    const { error } = await supabase.from('audit_logs').insert({
      user_id: operator.id,
      user_name: operator.name,
      action,
      module,
      level,
      detail,
    });
    if (error) throw error;
  } catch (err) {
    console.error('recordAuditLog failed', err);
  }
}