import { useCallback, useEffect, useMemo, useState } from 'react';
import Modal from '@/components/base/Modal';
import { supabase } from '@/lib/supabase';
import { useAuth } from '@/contexts/AuthContext';
import type { PluginRow, PluginTemplateRow } from '@/pages/plugins/types';

interface TemplateEditorModalProps {
  open: boolean;
  plugin: PluginRow | null;
  onClose: () => void;
}

const tokenHints = ['{{moduleName}}', '{{moduleCode}}', '{{fields}}', '{{title}}', '{{name}}', '{{handler}}'];

const emptyDraft = { name: '', description: '', content: '' };

export default function TemplateEditorModal({ open, plugin, onClose }: TemplateEditorModalProps) {
  const { hasPermission } = useAuth();
  const canEdit = hasPermission('plugin:update');

  const [templates, setTemplates] = useState<PluginTemplateRow[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [draft, setDraft] = useState(emptyDraft);
  const [isNew, setIsNew] = useState(false);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');

  const load = useCallback(async () => {
    if (!plugin) return;
    setLoading(true);
    setError('');
    try {
      const { data, error: err } = await supabase
        .from('plugin_templates')
        .select('*')
        .eq('plugin_id', plugin.id)
        .order('is_default', { ascending: false });
      if (err) throw err;
      const rows = (data as PluginTemplateRow[]) ?? [];
      setTemplates(rows);
      const first = rows[0] ?? null;
      setSelectedId(first?.id ?? null);
      setIsNew(false);
      setDraft(
        first
          ? { name: first.name, description: first.description ?? '', content: first.content ?? '' }
          : { ...emptyDraft, content: plugin.template ?? '' },
      );
    } catch (err) {
      console.error(err);
      setError('加载模板失败,请重试');
    } finally {
      setLoading(false);
    }
  }, [plugin]);

  useEffect(() => {
    if (open && plugin) load();
  }, [open, plugin, load]);

  useEffect(() => {
    if (!notice) return;
    const timer = setTimeout(() => setNotice(''), 2400);
    return () => clearTimeout(timer);
  }, [notice]);

  const selected = useMemo(
    () => templates.find((t) => t.id === selectedId) ?? null,
    [templates, selectedId],
  );

  const selectTemplate = (t: PluginTemplateRow) => {
    setSelectedId(t.id);
    setIsNew(false);
    setDraft({ name: t.name, description: t.description ?? '', content: t.content ?? '' });
  };

  const startNew = () => {
    setSelectedId(null);
    setIsNew(true);
    setDraft({ ...emptyDraft, content: plugin?.template ?? '' });
  };

  const save = async () => {
    if (!plugin) return;
    if (!draft.name.trim()) {
      setError('请填写模板名称');
      return;
    }
    setSaving(true);
    setError('');
    try {
      if (isNew || !selected) {
        const { data, error: err } = await supabase
          .from('plugin_templates')
          .insert({
            plugin_id: plugin.id,
            name: draft.name,
            description: draft.description,
            content: draft.content,
            is_default: false,
          })
          .select('*')
          .single();
        if (err) throw err;
        const created = data as PluginTemplateRow;
        setTemplates((prev) => [...prev, created]);
        setSelectedId(created.id);
        setIsNew(false);
        setNotice('模板已创建');
      } else {
        const { error: err } = await supabase
          .from('plugin_templates')
          .update({
            name: draft.name,
            description: draft.description,
            content: draft.content,
            updated_at: new Date().toISOString(),
          })
          .eq('id', selected.id);
        if (err) throw err;
        setTemplates((prev) =>
          prev.map((t) =>
            t.id === selected.id
              ? { ...t, name: draft.name, description: draft.description, content: draft.content }
              : t,
          ),
        );
        setNotice('模板已保存');
      }
    } catch (err) {
      console.error(err);
      setError('保存失败,请检查权限后重试');
    } finally {
      setSaving(false);
    }
  };

  const remove = async () => {
    if (!selected) return;
    try {
      const { error: err } = await supabase.from('plugin_templates').delete().eq('id', selected.id);
      if (err) throw err;
      const rest = templates.filter((t) => t.id !== selected.id);
      setTemplates(rest);
      const next = rest[0] ?? null;
      setSelectedId(next?.id ?? null);
      setIsNew(false);
      setDraft(
        next
          ? { name: next.name, description: next.description ?? '', content: next.content ?? '' }
          : { ...emptyDraft, content: plugin?.template ?? '' },
      );
      setNotice('模板已删除');
    } catch (err) {
      console.error(err);
      setError('删除失败,请检查权限');
    }
  };

  const insertToken = (token: string) => {
    setDraft((prev) => ({ ...prev, content: `${prev.content}${token}` }));
  };

  return (
    <Modal
      open={open}
      title="自定义模板编辑"
      subtitle={plugin ? `${plugin.name} · ${templates.length} 个模板` : ''}
      onClose={onClose}
      width="max-w-4xl"
      footer={
        <>
          <button
            type="button"
            onClick={onClose}
            className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
          >
            关闭
          </button>
          <button
            type="button"
            onClick={save}
            disabled={!canEdit || saving}
            className="h-9 px-4 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 disabled:opacity-50 cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5 dark:text-foreground-950"
          >
            <i className="ri-save-line"></i>
            {saving ? '保存中…' : '保存模板'}
          </button>
        </>
      }
    >
      {notice ? (
        <div className="mb-3 flex items-center gap-2 px-3 py-2 rounded-md bg-primary-50 text-primary-800 text-xs animate-fade-up">
          <i className="ri-checkbox-circle-line"></i>
          {notice}
        </div>
      ) : null}
      {error ? (
        <div className="mb-3 flex items-center gap-2 px-3 py-2 rounded-md bg-accent-100 text-accent-900 text-xs">
          <i className="ri-error-warning-line"></i>
          {error}
        </div>
      ) : null}

      <div className="grid grid-cols-1 lg:grid-cols-[230px_1fr] gap-4">
        <div className="space-y-2">
          <button
            type="button"
            onClick={startNew}
            disabled={!canEdit}
            className="w-full h-9 rounded-md bg-primary-500 text-background-50 text-xs hover:bg-primary-600 disabled:opacity-50 cursor-pointer whitespace-nowrap inline-flex items-center justify-center gap-1.5 dark:text-foreground-950"
          >
            <i className="ri-add-line"></i>
            新建模板
          </button>
          <div className="space-y-1.5 max-h-[360px] overflow-y-auto pr-0.5">
            {loading ? (
              [0, 1, 2].map((n) => (
                <div key={n} className="h-14 rounded-md bg-background-100 animate-pulse-soft" />
              ))
            ) : templates.length === 0 && !isNew ? (
              <p className="text-xs text-foreground-500 text-center py-6">该插件暂无模板</p>
            ) : (
              templates.map((t) => {
                const active = t.id === selectedId && !isNew;
                return (
                  <button
                    key={t.id}
                    type="button"
                    onClick={() => selectTemplate(t)}
                    className={`w-full text-left rounded-md border px-3 py-2.5 cursor-pointer transition-colors ${
                      active
                        ? 'bg-background-50 border-primary-400'
                        : 'bg-background-50 border-background-200 hover:border-background-300'
                    }`}
                  >
                    <div className="flex items-center gap-1.5">
                      <i className="ri-file-code-line text-foreground-500 text-xs"></i>
                      <span className="text-xs font-medium text-foreground-900 truncate">{t.name}</span>
                      {t.is_default ? (
                        <span className="ml-auto text-[9px] px-1.5 py-0.5 rounded-full bg-secondary-100 text-secondary-900">
                          默认
                        </span>
                      ) : null}
                    </div>
                    <p className="mt-0.5 text-[10px] text-foreground-500 line-clamp-1">
                      {t.description || '暂无描述'}
                    </p>
                  </button>
                );
              })
            )}
          </div>
        </div>

        <div className="space-y-3">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <div>
              <label className="block text-[11px] font-medium text-foreground-700 mb-1">模板名称</label>
              <input
                type="text"
                value={draft.name}
                onChange={(e) => setDraft((p) => ({ ...p, name: e.target.value }))}
                disabled={!canEdit}
                placeholder="例如:标准列表页"
                className="w-full h-9 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400 disabled:opacity-60"
              />
            </div>
            <div>
              <label className="block text-[11px] font-medium text-foreground-700 mb-1">描述</label>
              <input
                type="text"
                value={draft.description}
                onChange={(e) => setDraft((p) => ({ ...p, description: e.target.value }))}
                disabled={!canEdit}
                placeholder="一句话说明用途"
                className="w-full h-9 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400 disabled:opacity-60"
              />
            </div>
          </div>

          <div>
            <div className="flex items-center justify-between mb-1">
              <label className="text-[11px] font-medium text-foreground-700">模板内容</label>
              <div className="flex flex-wrap items-center gap-1">
                {tokenHints.map((tk) => (
                  <button
                    key={tk}
                    type="button"
                    onClick={() => insertToken(tk)}
                    disabled={!canEdit}
                    className="font-label text-[10px] px-1.5 py-0.5 rounded bg-background-100 border border-background-200 text-foreground-600 hover:bg-background-200 disabled:opacity-50 cursor-pointer whitespace-nowrap"
                  >
                    {tk}
                  </button>
                ))}
              </div>
            </div>
            <textarea
              value={draft.content}
              onChange={(e) => setDraft((p) => ({ ...p, content: e.target.value }))}
              disabled={!canEdit}
              rows={13}
              spellCheck={false}
              placeholder="在此编写模板,支持 {{变量}} 语法"
              className="w-full px-3.5 py-3 rounded-md bg-foreground-950 text-background-200 border border-background-300 font-label text-[12px] leading-relaxed focus:outline-none focus:border-primary-400 resize-none disabled:opacity-70"
            />
          </div>

          <div className="flex items-center gap-2">
            {selected && !isNew ? (
              <button
                type="button"
                onClick={remove}
                disabled={!canEdit}
                className="h-8 px-3 rounded-md bg-background-100 border border-background-300 text-xs text-foreground-800 hover:bg-secondary-200 disabled:opacity-50 cursor-pointer whitespace-nowrap inline-flex items-center gap-1"
              >
                <i className="ri-delete-bin-line"></i>
                删除该模板
              </button>
            ) : null}
            <button
              type="button"
              onClick={() => setDraft((p) => ({ ...p, content: plugin?.template ?? '' }))}
              disabled={!canEdit}
              className="ml-auto h-8 px-3 rounded-md bg-background-100 border border-background-300 text-xs text-foreground-800 hover:bg-background-200 disabled:opacity-50 cursor-pointer whitespace-nowrap inline-flex items-center gap-1"
            >
              <i className="ri-restart-line"></i>
              重置为默认内容
            </button>
          </div>
        </div>
      </div>
    </Modal>
  );
}