import { useCallback, useEffect, useMemo, useState } from 'react';
import ComponentPalette from '@/pages/builder/components/ComponentPalette';
import Canvas from '@/pages/builder/components/Canvas';
import PropertyPanel from '@/pages/builder/components/PropertyPanel';
import PreviewModal from '@/pages/builder/components/PreviewModal';
import { createBlock, findPaletteItem, palette, type BuilderBlock } from '@/pages/builder/types';

const STORAGE_KEY = 'readdy.builder.draft';

function presetLayout(): BuilderBlock[] {
  const pick = (type: string, props: Record<string, string>): BuilderBlock => {
    const item = findPaletteItem(type) ?? palette[0];
    return { ...createBlock(item), props: { ...item.defaultProps, ...props } };
  };
  return [
    pick('heading', { text: '华安后台开发框架', size: '3xl', align: 'center', color: 'default' }),
    pick('text', {
      text: '可视化搭建管理页面,拖拽即布局,配置即发布。',
      align: 'center',
      size: 'base',
    }),
    pick('button', { text: '立即体验', variant: 'primary', align: 'center' }),
    pick('divider', {}),
    pick('card', { title: '权限体系内核', desc: '菜单 / 按钮 / 接口三级权限,开箱即用。', accent: 'primary' }),
    pick('card', { title: '插件热更新', desc: '运行时无损升级插件,服务零中断。', accent: 'accent' }),
    pick('spacer', { height: '8' }),
    pick('stat', { label: '本月活跃租户', value: '128', unit: '个' }),
  ];
}

function loadDraft(): BuilderBlock[] {
  if (typeof window === 'undefined') return presetLayout();
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw) as BuilderBlock[];
      if (Array.isArray(parsed)) return parsed;
    }
  } catch (err) {
    console.error(err);
  }
  return presetLayout();
}

export default function BuilderPage() {
  const [blocks, setBlocks] = useState<BuilderBlock[]>(loadDraft);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [previewOpen, setPreviewOpen] = useState(false);
  const [saved, setSaved] = useState(false);

  useEffect(() => {
    try {
      window.localStorage.setItem(STORAGE_KEY, JSON.stringify(blocks));
    } catch (err) {
      console.error(err);
    }
  }, [blocks]);

  useEffect(() => {
    if (!saved) return;
    const timer = setTimeout(() => setSaved(false), 1800);
    return () => clearTimeout(timer);
  }, [saved]);

  const selectedBlock = useMemo(
    () => blocks.find((b) => b.id === selectedId) ?? null,
    [blocks, selectedId],
  );

  const addBlock = useCallback((type: string, index?: number) => {
    const item = findPaletteItem(type);
    if (!item) return;
    const block = createBlock(item);
    setBlocks((prev) => {
      const next = [...prev];
      if (typeof index === 'number' && index >= 0 && index <= next.length) {
        next.splice(index, 0, block);
      } else {
        next.push(block);
      }
      return next;
    });
    setSelectedId(block.id);
  }, []);

  const updateProps = (id: string, key: string, value: string) => {
    setBlocks((prev) =>
      prev.map((b) => (b.id === id ? { ...b, props: { ...b.props, [key]: value } } : b)),
    );
  };

  const moveBlock = (index: number, dir: -1 | 1) => {
    const target = index + dir;
    if (target < 0 || target >= blocks.length) return;
    const next = [...blocks];
    [next[index], next[target]] = [next[target], next[index]];
    setBlocks(next);
  };

  const removeBlock = (id: string) => {
    setBlocks((prev) => prev.filter((b) => b.id !== id));
    setSelectedId((prev) => (prev === id ? null : prev));
  };

  return (
    <div className="space-y-4">
      <div className="flex flex-col md:flex-row md:items-center gap-3">
        <div>
          <h2 className="text-lg font-semibold text-foreground-950">拖拽式页面布局设计器</h2>
          <p className="text-sm text-foreground-500 mt-0.5">
            从左侧拖入组件到画布,拖拽排序,右侧实时配置属性,一键预览并导出页面结构
          </p>
        </div>
        <div className="md:ml-auto flex flex-wrap items-center gap-2">
          {saved ? (
            <span className="inline-flex items-center gap-1.5 h-9 px-3 rounded-md bg-primary-50 text-primary-800 text-xs">
              <i className="ri-checkbox-circle-line"></i>
              草稿已自动保存
            </span>
          ) : null}
          <button
            type="button"
            onClick={() => {
              setBlocks(presetLayout());
              setSelectedId(null);
            }}
            className="h-9 px-3.5 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-800 hover:bg-background-100 cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5"
          >
            <i className="ri-magic-line"></i>
            载入示例布局
          </button>
          <button
            type="button"
            onClick={() => {
              setBlocks([]);
              setSelectedId(null);
            }}
            className="h-9 px-3.5 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-800 hover:bg-background-100 cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5"
          >
            <i className="ri-delete-bin-6-line"></i>
            清空画布
          </button>
          <button
            type="button"
            onClick={() => {
              setSaved(true);
              setPreviewOpen(true);
            }}
            className="h-9 px-3.5 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5 dark:text-foreground-950"
          >
            <i className="ri-eye-line"></i>
            预览与导出
          </button>
        </div>
      </div>

      <div className="flex flex-col lg:flex-row gap-4 items-stretch">
        <ComponentPalette onAdd={(item) => addBlock(item.type)} />
        <Canvas
          blocks={blocks}
          selectedId={selectedId}
          onSelect={setSelectedId}
          onChange={setBlocks}
          onDropFromPalette={addBlock}
        />
        <PropertyPanel
          block={selectedBlock}
          blocks={blocks}
          onUpdateProps={updateProps}
          onSelect={setSelectedId}
          onMove={moveBlock}
          onRemove={removeBlock}
        />
      </div>

      <PreviewModal open={previewOpen} blocks={blocks} onClose={() => setPreviewOpen(false)} />
    </div>
  );
}