import type { BuilderBlock } from '@/pages/builder/types';

interface BlockPreviewProps {
  block: BuilderBlock;
}

const alignText: Record<string, string> = {
  left: 'text-left',
  center: 'text-center',
  right: 'text-right',
};

const alignFlex: Record<string, string> = {
  left: 'justify-start',
  center: 'justify-center',
  right: 'justify-end',
};

const headingSize: Record<string, string> = {
  sm: 'text-sm',
  base: 'text-base',
  lg: 'text-lg',
  xl: 'text-xl',
  '2xl': 'text-2xl',
  '3xl': 'text-3xl',
};

const bodySize: Record<string, string> = {
  xs: 'text-xs',
  sm: 'text-sm',
  base: 'text-base',
};

const headingColor: Record<string, string> = {
  default: 'text-foreground-950',
  primary: 'text-primary-600',
  accent: 'text-accent-600',
  muted: 'text-foreground-500',
};

const buttonVariant: Record<string, string> = {
  primary: 'bg-primary-500 text-background-50 dark:text-foreground-950',
  accent: 'bg-accent-500 text-background-50 dark:text-foreground-950',
  secondary: 'bg-secondary-500 text-background-50 dark:text-foreground-950',
  outline: 'bg-background-50 border border-background-300 text-foreground-800',
};

const cardAccent: Record<string, string> = {
  primary: 'border-l-primary-500',
  accent: 'border-l-accent-500',
  secondary: 'border-l-secondary-500',
};

const radiusMap: Record<string, string> = {
  none: 'rounded-none',
  md: 'rounded-md',
  lg: 'rounded-lg',
  full: 'rounded-full',
};

export default function BlockPreview({ block }: BlockPreviewProps) {
  const p = block.props;

  switch (block.type) {
    case 'heading':
      return (
        <h3
          className={`${headingSize[p.size] ?? 'text-lg'} ${headingColor[p.color] ?? 'text-foreground-950'} ${
            alignText[p.align] ?? 'text-left'
          } font-semibold`}
        >
          {p.text || '标题'}
        </h3>
      );
    case 'text':
      return (
        <p
          className={`${bodySize[p.size] ?? 'text-sm'} ${alignText[p.align] ?? 'text-left'} text-foreground-600 leading-relaxed whitespace-pre-line`}
        >
          {p.text}
        </p>
      );
    case 'button':
      return (
        <div className={`flex ${alignFlex[p.align] ?? 'justify-start'}`}>
          <span
            className={`inline-flex items-center gap-1.5 h-9 px-4 rounded-md text-sm whitespace-nowrap ${
              buttonVariant[p.variant] ?? buttonVariant.primary
            }`}
          >
            <i className="ri-rocket-2-line"></i>
            {p.text || '按钮'}
          </span>
        </div>
      );
    case 'divider':
      return (
        <div
          className={`w-full border-t ${
            p.style === 'dashed' ? 'border-dashed border-background-300' : 'border-background-300'
          }`}
        />
      );
    case 'spacer':
      return <div style={{ height: `${Number(p.height) || 16}px` }} />;
    case 'card':
      return (
        <div
          className={`rounded-lg bg-background-50 border border-background-200 border-l-4 p-4 ${
            cardAccent[p.accent] ?? cardAccent.primary
          }`}
        >
          <h4 className="text-sm font-semibold text-foreground-950">{p.title}</h4>
          <p className="mt-1 text-xs text-foreground-600 leading-relaxed">{p.desc}</p>
        </div>
      );
    case 'image':
      return (
        <div
          className={`w-full overflow-hidden ${radiusMap[p.radius] ?? 'rounded-lg'} bg-background-200`}
          style={{ height: `${Number(p.height) || 180}px` }}
        >
          {p.url ? (
            <img
              src={p.url}
              alt="设计器配图"
              title="设计器配图 页面布局"
              className="w-full h-full object-top"
            />
          ) : (
            <div className="w-full h-full flex items-center justify-center text-foreground-400">
              <i className="ri-image-line text-2xl"></i>
            </div>
          )}
        </div>
      );
    case 'stat':
      return (
        <div className="rounded-lg bg-background-50 border border-background-200 p-4">
          <div className="flex items-center gap-1.5 text-[11px] text-foreground-500">
            <i className="ri-bar-chart-box-line"></i>
            {p.label}
          </div>
          <div className="mt-1.5 flex items-baseline gap-1">
            <span className="text-2xl font-semibold text-foreground-950 font-label">{p.value}</span>
            <span className="text-xs text-foreground-500">{p.unit}</span>
          </div>
        </div>
      );
    case 'input':
      return (
        <div className="w-full">
          <label className="block text-xs font-medium text-foreground-700 mb-1.5">{p.label}</label>
          <div className="h-10 px-3 rounded-md bg-background-50 border border-background-300 flex items-center text-sm text-foreground-400">
            {p.placeholder}
          </div>
        </div>
      );
    default:
      return <div className="text-xs text-foreground-400">未知组件:{block.type}</div>;
  }
}