import { useEffect, useMemo, useState } from 'react';
import { supabase } from '@/lib/supabase';
import { formatTestDuration, formatTime, type TestReportRow } from '@/pages/settings/system/types';

export default function TestReportCard() {
  const [rows, setRows] = useState<TestReportRow[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let active = true;
    (async () => {
      try {
        const { data, error } = await supabase
          .from('test_reports')
          .select('*')
          .order('id', { ascending: true });
        if (error) throw error;
        if (active) setRows((data as TestReportRow[]) ?? []);
      } catch (err) {
        console.error(err);
      } finally {
        if (active) setLoading(false);
      }
    })();
    return () => {
      active = false;
    };
  }, []);

  const stats = useMemo(() => {
    const total = rows.reduce((s, r) => s + (r.total ?? 0), 0);
    const passed = rows.reduce((s, r) => s + (r.passed ?? 0), 0);
    const failed = rows.reduce((s, r) => s + (r.failed ?? 0), 0);
    const skipped = rows.reduce((s, r) => s + (r.skipped ?? 0), 0);
    const passRate = total > 0 ? (passed / total) * 100 : 0;
    const coverage =
      rows.length > 0 ? rows.reduce((s, r) => s + (r.coverage ?? 0), 0) / rows.length : 0;
    return { total, passed, failed, skipped, passRate, coverage };
  }, [rows]);

  const summaryCards = [
    { label: '用例总数', value: stats.total, icon: 'ri-flask-line', tone: 'bg-primary-100 text-primary-700' },
    { label: '通过率', value: `${stats.passRate.toFixed(1)}%`, icon: 'ri-checkbox-circle-line', tone: 'bg-accent-100 text-accent-800' },
    { label: '平均覆盖率', value: `${stats.coverage.toFixed(1)}%`, icon: 'ri-line-chart-line', tone: 'bg-secondary-200 text-secondary-900' },
    { label: '失败 / 跳过', value: `${stats.failed} / ${stats.skipped}`, icon: 'ri-error-warning-line', tone: 'bg-secondary-100 text-secondary-900' },
  ];

  return (
    <div className="rounded-lg bg-background-50 border border-background-200">
      <div className="flex items-center gap-2.5 px-4 md:px-5 py-3.5 border-b border-background-200">
        <span className="w-9 h-9 rounded-md bg-primary-100 text-primary-700 flex items-center justify-center">
          <i className="ri-flask-line text-lg"></i>
        </span>
        <div>
          <h3 className="text-sm font-semibold text-foreground-950">单元测试报告</h3>
          <p className="text-xs text-foreground-500">最近一次测试运行的套件结果与覆盖率</p>
        </div>
        <span className="ml-auto shrink-0 text-[10px] px-2 py-0.5 rounded-full bg-secondary-100 text-secondary-900 whitespace-nowrap">
          演示数据
        </span>
      </div>

      <div className="grid grid-cols-2 xl:grid-cols-4 gap-3 p-4 md:p-5 border-b border-background-200">
        {summaryCards.map((c) => (
          <div key={c.label} className="rounded-md bg-background-100 border border-background-200 p-3">
            <div className="flex items-center gap-2">
              <span className={`w-7 h-7 rounded-md flex items-center justify-center ${c.tone}`}>
                <i className={`${c.icon} text-sm`}></i>
              </span>
              <span className="text-[11px] text-foreground-500">{c.label}</span>
            </div>
            <p className="mt-2 text-lg font-semibold text-foreground-950 font-label">{c.value}</p>
          </div>
        ))}
      </div>

      {loading ? (
        <div className="p-4 md:p-5 space-y-2.5">
          {[0, 1, 2, 3, 4].map((n) => (
            <div key={n} className="h-14 rounded-md bg-background-100 animate-pulse-soft" />
          ))}
        </div>
      ) : (
        <ul className="divide-y divide-background-200">
          {rows.map((r) => {
            const total = r.total ?? 0;
            const passPct = total > 0 ? ((r.passed ?? 0) / total) * 100 : 0;
            const failPct = total > 0 ? ((r.failed ?? 0) / total) * 100 : 0;
            const coverage = r.coverage ?? 0;
            const covTone = coverage >= 90 ? 'bg-primary-500' : coverage >= 80 ? 'bg-accent-500' : 'bg-secondary-600';
            return (
              <li key={r.id} className="px-4 md:px-5 py-3.5">
                <div className="flex flex-wrap items-center gap-2">
                  <span
                    className={`w-5 h-5 rounded-full flex items-center justify-center ${
                      r.status === 'passed' ? 'bg-primary-100 text-primary-700' : 'bg-secondary-700 text-background-50'
                    }`}
                  >
                    <i className={`${r.status === 'passed' ? 'ri-check-line' : 'ri-close-line'} text-[11px]`}></i>
                  </span>
                  <span className="text-sm font-medium text-foreground-950">{r.suite}</span>
                  <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-background-100 text-foreground-600">
                    {r.module}
                  </span>
                  <span className="ml-auto text-[11px] text-foreground-500 font-label">
                    {formatTestDuration(r.duration_ms)} · {formatTime(r.run_at)}
                  </span>
                </div>

                <div className="mt-2.5 grid grid-cols-1 md:grid-cols-2 gap-3">
                  <div>
                    <div className="flex items-center justify-between text-[11px] text-foreground-500 mb-1">
                      <span>通过 / 失败</span>
                      <span className="font-label">
                        {r.passed}/{total}
                        {r.failed && r.failed > 0 ? ` · 失败 ${r.failed}` : ''}
                      </span>
                    </div>
                    <div className="h-1.5 rounded-full bg-background-200 overflow-hidden flex">
                      <div className="h-full bg-primary-500" style={{ width: `${passPct}%` }} />
                      <div className="h-full bg-secondary-600" style={{ width: `${failPct}%` }} />
                    </div>
                  </div>
                  <div>
                    <div className="flex items-center justify-between text-[11px] text-foreground-500 mb-1">
                      <span>覆盖率</span>
                      <span className="font-label">{coverage.toFixed(1)}%</span>
                    </div>
                    <div className="h-1.5 rounded-full bg-background-200 overflow-hidden">
                      <div className={`h-full rounded-full ${covTone}`} style={{ width: `${coverage}%` }} />
                    </div>
                  </div>
                </div>
              </li>
            );
          })}
        </ul>
      )}
    </div>
  );
}