import { useEffect, useMemo, useState } from 'react';
import Modal from '@/components/base/Modal';
import type { RoleOption } from '@/pages/system/users/components/UserFormModal';

interface AssignRoleModalProps {
  open: boolean;
  userName: string;
  userEmail: string | null;
  roles: RoleOption[];
  currentRoleIds: string[];
  saving: boolean;
  onClose: () => void;
  onSubmit: (roleIds: string[]) => void;
}

export default function AssignRoleModal({
  open,
  userName,
  userEmail,
  roles,
  currentRoleIds,
  saving,
  onClose,
  onSubmit,
}: AssignRoleModalProps) {
  const [selected, setSelected] = useState<string[]>([]);
  const [keyword, setKeyword] = useState('');

  useEffect(() => {
    if (open) {
      setSelected(currentRoleIds);
      setKeyword('');
    }
  }, [open, currentRoleIds]);

  const filteredRoles = useMemo(() => {
    const kw = keyword.trim().toLowerCase();
    if (!kw) return roles;
    return roles.filter(
      (r) =>
        r.name.toLowerCase().includes(kw) || (r.code ?? '').toLowerCase().includes(kw),
    );
  }, [roles, keyword]);

  const toggle = (roleId: string) => {
    setSelected((prev) =>
      prev.includes(roleId) ? prev.filter((id) => id !== roleId) : [...prev, roleId],
    );
  };

  return (
    <Modal
      open={open}
      title="一键分配角色"
      subtitle={`为 ${userName} 快速配置访问权限`}
      onClose={onClose}
      footer={
        <>
          <span className="mr-auto text-xs text-foreground-500 self-center">
            已选 {selected.length} 个角色
          </span>
          <button
            type="button"
            onClick={onClose}
            className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
          >
            取消
          </button>
          <button
            type="button"
            onClick={() => onSubmit(selected)}
            disabled={saving}
            className="h-9 px-4 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 disabled:opacity-60 cursor-pointer whitespace-nowrap flex items-center gap-1.5 dark:text-foreground-950"
          >
            <i className={saving ? 'ri-loader-4-line animate-spin' : 'ri-shield-check-line'}></i>
            {saving ? '分配中…' : '确认分配'}
          </button>
        </>
      }
    >
      <div className="space-y-3.5">
        <div className="flex items-center gap-3 rounded-md bg-background-100 border border-background-200 px-3.5 py-3">
          <span className="w-9 h-9 rounded-full bg-primary-100 text-primary-700 flex items-center justify-center text-sm font-semibold shrink-0">
            {userName.slice(0, 1).toUpperCase()}
          </span>
          <span className="min-w-0">
            <span className="block text-sm text-foreground-950 truncate">{userName}</span>
            <span className="block text-xs text-foreground-500 truncate">{userEmail}</span>
          </span>
        </div>

        <div className="flex items-center gap-2 h-9 px-3 rounded-md bg-background-50 border border-background-200">
          <i className="ri-search-line text-foreground-400 text-sm"></i>
          <input
            type="text"
            value={keyword}
            onChange={(e) => setKeyword(e.target.value)}
            placeholder="搜索角色名称或标识"
            className="flex-1 bg-transparent text-sm text-foreground-900 placeholder:text-foreground-400 focus:outline-none"
          />
        </div>

        <div className="max-h-[320px] overflow-y-auto space-y-2">
          {filteredRoles.length === 0 ? (
            <p className="py-8 text-center text-sm text-foreground-500">没有匹配的角色</p>
          ) : (
            filteredRoles.map((role) => {
              const active = selected.includes(role.id);
              return (
                <button
                  key={role.id}
                  type="button"
                  onClick={() => toggle(role.id)}
                  className={`w-full flex items-center gap-3 rounded-md border px-3.5 py-3 text-left cursor-pointer transition-colors ${
                    active
                      ? 'bg-primary-50 border-primary-400'
                      : 'bg-background-50 border-background-200 hover:border-background-300'
                  }`}
                >
                  <span
                    className={`w-5 h-5 rounded-md flex items-center justify-center shrink-0 border ${
                      active
                        ? 'bg-primary-500 border-primary-500 text-background-50 dark:text-foreground-950'
                        : 'border-background-300'
                    }`}
                  >
                    {active ? <i className="ri-check-line text-xs"></i> : null}
                  </span>
                  <span className="min-w-0 flex-1">
                    <span className="block text-sm text-foreground-950 truncate">{role.name}</span>
                    {role.code ? (
                      <span className="block text-[11px] text-foreground-500 font-label truncate">
                        {role.code}
                      </span>
                    ) : null}
                  </span>
                  {active ? (
                    <span className="text-[11px] px-2 py-0.5 rounded-full bg-primary-100 text-primary-700 whitespace-nowrap">
                      已选
                    </span>
                  ) : null}
                </button>
              );
            })
          )}
        </div>

        <p className="flex items-start gap-1.5 text-[11px] text-foreground-500">
          <i className="ri-information-line mt-0.5"></i>
          保存后将替换该用户当前的所有角色分配。
        </p>
      </div>
    </Modal>
  );
}