import { useCallback, useEffect, useState } from 'react';

const KEY_PREFIX = 'readdy.plugin.recentViews';
const MAX_RECORDS = 8;

function storageKey(userId: string) {
  return `${KEY_PREFIX}.${userId || 'guest'}`;
}

function loadRecords(userId: string): string[] {
  if (typeof window === 'undefined') return [];
  try {
    const raw = window.localStorage.getItem(storageKey(userId));
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed)
      ? parsed.filter((c): c is string => typeof c === 'string').slice(0, MAX_RECORDS)
      : [];
  } catch (err) {
    console.error(err);
    return [];
  }
}

function persistRecords(userId: string, codes: string[]) {
  if (typeof window === 'undefined') return;
  try {
    window.localStorage.setItem(storageKey(userId), JSON.stringify(codes));
  } catch (err) {
    console.error(err);
  }
}

/**
 * 最近浏览过的插件:按账号命名空间记在本地,打开详情时记录,
 * 用于「我的」页签里把刚逛过的插件串起来。
 */
export function useRecentPlugins(userId: string) {
  const [codes, setCodes] = useState<string[]>(() => loadRecords(userId));

  useEffect(() => {
    setCodes(loadRecords(userId));
  }, [userId]);

  const record = useCallback(
    (code: string) => {
      if (!code) return;
      setCodes((prev) => {
        const next = [code, ...prev.filter((c) => c !== code)].slice(0, MAX_RECORDS);
        persistRecords(userId, next);
        return next;
      });
    },
    [userId],
  );

  const clear = useCallback(() => {
    setCodes([]);
    if (typeof window === 'undefined') return;
    try {
      window.localStorage.removeItem(storageKey(userId));
    } catch (err) {
      console.error(err);
    }
  }, [userId]);

  return { recent: codes, record, clear };
}