import { useState } from 'react';

interface PasswordCardProps {
  onSubmit: (current: string, next: string) => Promise<{ ok: boolean; message: string }>;
}

export default function PasswordCard({ onSubmit }: PasswordCardProps) {
  const [current, setCurrent] = useState('');
  const [next, setNext] = useState('');
  const [confirm, setConfirm] = useState('');
  const [show, setShow] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const strength = (() => {
    if (next.length === 0) return { level: 0, label: '', tone: '' };
    if (next.length < 6) return { level: 1, label: '过短', tone: 'bg-secondary-500' };
    if (next.length < 10) return { level: 2, label: '一般', tone: 'bg-accent-500' };
    return { level: 3, label: '较强', tone: 'bg-primary-500' };
  })();

  const handleSubmit = async () => {
    setError('');
    setSuccess('');
    if (!current || !next || !confirm) {
      setError('请填写全部密码字段');
      return;
    }
    if (next.length < 6) {
      setError('新密码至少需要 6 位');
      return;
    }
    if (next !== confirm) {
      setError('两次输入的新密码不一致');
      return;
    }
    if (next === current) {
      setError('新密码不能与当前密码相同');
      return;
    }
    setBusy(true);
    const result = await onSubmit(current, next);
    setBusy(false);
    if (result.ok) {
      setSuccess(result.message);
      setCurrent('');
      setNext('');
      setConfirm('');
    } else {
      setError(result.message);
    }
  };

  const inputType = show ? 'text' : 'password';

  return (
    <section className="rounded-lg bg-background-50 border border-background-200 p-4 md:p-5">
      <div className="flex items-center justify-between gap-3">
        <div>
          <h3 className="text-sm font-semibold text-foreground-950">修改密码</h3>
          <p className="text-xs text-foreground-500 mt-0.5">定期更换密码有助于账号安全</p>
        </div>
        <button
          type="button"
          onClick={() => setShow((v) => !v)}
          className="h-8 px-3 rounded-md bg-background-100 border border-background-300 text-xs text-foreground-700 hover:bg-background-200 cursor-pointer whitespace-nowrap flex items-center gap-1"
        >
          <i className={show ? 'ri-eye-off-line' : 'ri-eye-line'}></i>
          {show ? '隐藏' : '显示'}
        </button>
      </div>

      <div className="mt-4 space-y-3.5">
        <div>
          <label className="block text-xs font-medium text-foreground-700 mb-1.5">当前密码</label>
          <input
            type={inputType}
            value={current}
            onChange={(e) => setCurrent(e.target.value)}
            placeholder="请输入当前密码"
            autoComplete="current-password"
            className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400"
          />
        </div>
        <div>
          <label className="block text-xs font-medium text-foreground-700 mb-1.5">新密码</label>
          <input
            type={inputType}
            value={next}
            onChange={(e) => setNext(e.target.value)}
            placeholder="至少 6 位"
            autoComplete="new-password"
            className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400"
          />
          {next.length > 0 ? (
            <div className="mt-2 flex items-center gap-2">
              <div className="flex-1 h-1.5 rounded-full bg-background-200 overflow-hidden">
                <div className={`h-full rounded-full ${strength.tone}`} style={{ width: `${(strength.level / 3) * 100}%` }} />
              </div>
              <span className="text-[11px] text-foreground-500 w-8">{strength.label}</span>
            </div>
          ) : null}
        </div>
        <div>
          <label className="block text-xs font-medium text-foreground-700 mb-1.5">确认新密码</label>
          <input
            type={inputType}
            value={confirm}
            onChange={(e) => setConfirm(e.target.value)}
            placeholder="再次输入新密码"
            autoComplete="new-password"
            className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400"
          />
        </div>

        {error ? (
          <div className="flex items-start gap-2 px-3 py-2.5 rounded-md bg-accent-100 text-accent-900 text-xs">
            <i className="ri-error-warning-line mt-0.5"></i>
            <span>{error}</span>
          </div>
        ) : null}
        {success ? (
          <div className="flex items-start gap-2 px-3 py-2.5 rounded-md bg-primary-50 text-primary-800 text-xs">
            <i className="ri-checkbox-circle-line mt-0.5"></i>
            <span>{success}</span>
          </div>
        ) : null}

        <button
          type="button"
          onClick={handleSubmit}
          disabled={busy}
          className="h-9 px-4 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 disabled:opacity-60 cursor-pointer whitespace-nowrap dark:text-foreground-950"
        >
          {busy ? '提交中…' : '更新密码'}
        </button>
      </div>
    </section>
  );
}