import { useCallback, useEffect, useMemo, useState } from 'react';
import { supabase } from '@/lib/supabase';
import { useAuth } from '@/contexts/AuthContext';
import Modal from '@/components/base/Modal';

interface LangRow {
  id: string;
  lang: string;
  namespace: string;
  str_key: string;
  value: string | null;
  updated_at: string | null;
}

export default function I18nManagerPage() {
  const { hasPermission } = useAuth();
  const canManage = hasPermission('i18n:manage');

  const [rows, setRows] = useState<LangRow[]>([]);
  const [draft, setDraft] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const [savingId, setSavingId] = useState<string | null>(null);

  const [langFilter, setLangFilter] = useState('all');
  const [nsFilter, setNsFilter] = useState('all');
  const [keyword, setKeyword] = useState('');

  const [addOpen, setAddOpen] = useState(false);
  const [form, setForm] = useState({ lang: 'zh-CN', namespace: 'common', str_key: '', value: '' });
  const [formError, setFormError] = useState('');

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const { data, error: err } = await supabase
        .from('language_strings')
        .select('*')
        .order('lang', { ascending: true })
        .order('namespace', { ascending: true })
        .order('str_key', { ascending: true });
      if (err) throw err;
      const list = (data as LangRow[]) ?? [];
      setRows(list);
      const next: Record<string, string> = {};
      list.forEach((r) => {
        next[r.id] = r.value ?? '';
      });
      setDraft(next);
    } catch (err) {
      console.error(err);
      setError('加载语言包失败,请重试');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  useEffect(() => {
    if (!notice) return;
    const timer = setTimeout(() => setNotice(''), 2600);
    return () => clearTimeout(timer);
  }, [notice]);

  const langs = useMemo(() => Array.from(new Set(rows.map((r) => r.lang))).sort(), [rows]);
  const namespaces = useMemo(() => Array.from(new Set(rows.map((r) => r.namespace))).sort(), [rows]);

  const filtered = useMemo(() => {
    const kw = keyword.trim().toLowerCase();
    return rows.filter((r) => {
      const matchLang = langFilter === 'all' || r.lang === langFilter;
      const matchNs = nsFilter === 'all' || r.namespace === nsFilter;
      const matchKw = !kw || r.str_key.toLowerCase().includes(kw) || (r.value ?? '').toLowerCase().includes(kw);
      return matchLang && matchNs && matchKw;
    });
  }, [rows, langFilter, nsFilter, keyword]);

  const saveRow = async (row: LangRow) => {
    setSavingId(row.id);
    try {
      const { error: err } = await supabase
        .from('language_strings')
        .update({ value: draft[row.id] ?? '', updated_at: new Date().toISOString() })
        .eq('id', row.id);
      if (err) throw err;
      setNotice(`已保存 ${row.str_key}`);
      await load();
    } catch (err) {
      console.error(err);
      setError('保存失败,请检查权限后重试');
    } finally {
      setSavingId(null);
    }
  };

  const submitAdd = async () => {
    if (!form.lang.trim() || !form.namespace.trim() || !form.str_key.trim()) {
      setFormError('语言、命名空间与键名均不能为空');
      return;
    }
    try {
      const { error: err } = await supabase.from('language_strings').upsert(
        {
          lang: form.lang.trim(),
          namespace: form.namespace.trim(),
          str_key: form.str_key.trim(),
          value: form.value,
          updated_at: new Date().toISOString(),
        },
        { onConflict: 'lang,namespace,str_key' },
      );
      if (err) throw err;
      setNotice('已保存词条');
      setAddOpen(false);
      setForm({ lang: langs[0] ?? 'zh-CN', namespace: namespaces[0] ?? 'common', str_key: '', value: '' });
      setFormError('');
      await load();
    } catch (err) {
      console.error(err);
      setFormError('保存失败,请检查权限后重试');
    }
  };

  const deleteRow = async (row: LangRow) => {
    try {
      const { error: err } = await supabase.from('language_strings').delete().eq('id', row.id);
      if (err) throw err;
      setNotice(`已删除 ${row.str_key}`);
      await load();
    } catch (err) {
      console.error(err);
      setError('删除失败,可能权限不足');
    }
  };

  return (
    <div className="space-y-4">
      <div className="flex flex-col md:flex-row md:items-center gap-3">
        <div>
          <h2 className="text-lg font-semibold text-foreground-950">多语言包管理</h2>
          <p className="text-sm text-foreground-500 mt-0.5">
            在线维护各语言词条,按命名空间归类;保存后会在应用启动时加载进前端 i18n
          </p>
        </div>
        <div className="md:ml-auto flex flex-wrap items-center gap-2">
          <div className="flex items-center gap-2 h-9 px-3 rounded-md bg-background-50 border border-background-200 w-full sm:w-48">
            <i className="ri-search-line text-foreground-400 text-sm"></i>
            <input
              type="text"
              value={keyword}
              onChange={(e) => setKeyword(e.target.value)}
              placeholder="搜索键名或文案"
              className="flex-1 bg-transparent text-sm text-foreground-900 placeholder:text-foreground-400 focus:outline-none"
            />
          </div>
          <select
            value={langFilter}
            onChange={(e) => setLangFilter(e.target.value)}
            className="h-9 px-3 rounded-md bg-background-50 border border-background-200 text-sm text-foreground-800 focus:outline-none cursor-pointer"
          >
            <option value="all">全部语言</option>
            {langs.map((l) => (
              <option key={l} value={l}>
                {l}
              </option>
            ))}
          </select>
          <select
            value={nsFilter}
            onChange={(e) => setNsFilter(e.target.value)}
            className="h-9 px-3 rounded-md bg-background-50 border border-background-200 text-sm text-foreground-800 focus:outline-none cursor-pointer"
          >
            <option value="all">全部命名空间</option>
            {namespaces.map((n) => (
              <option key={n} value={n}>
                {n}
              </option>
            ))}
          </select>
          <button
            type="button"
            onClick={() => setAddOpen(true)}
            disabled={!canManage}
            className="h-9 px-3.5 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 disabled:opacity-50 cursor-pointer whitespace-nowrap flex items-center gap-1.5 dark:text-foreground-950"
          >
            <i className="ri-add-line"></i>
            新增词条
          </button>
        </div>
      </div>

      <div className="flex items-start gap-2 px-3 py-2.5 rounded-md bg-secondary-100 text-secondary-900 text-xs">
        <i className="ri-information-line mt-0.5"></i>
        <span>
          这里的词条会在应用启动时合并进前端 i18n,通过 <span className="font-label">t('键名', {'{'} ns: '命名空间' {'}'})</span> 读取的文案即以本页为准;
          当前界面仍有大量静态中文文案未走 i18n,因此并非所有文字都会随本页变化。保存后刷新页面即可看到生效的词条。
        </span>
      </div>

      {notice ? (
        <div className="flex items-center gap-2 px-3 py-2.5 rounded-md bg-primary-50 text-primary-800 text-sm animate-fade-up">
          <i className="ri-checkbox-circle-line"></i>
          {notice}
        </div>
      ) : null}
      {error ? (
        <div className="flex items-center justify-between gap-3 px-3 py-2.5 rounded-md bg-accent-100 text-accent-900 text-sm">
          {error}
          <button type="button" onClick={load} className="text-xs underline cursor-pointer whitespace-nowrap">
            重试
          </button>
        </div>
      ) : null}

      <div className="rounded-lg bg-background-50 border border-background-200 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full min-w-[760px] text-sm">
            <thead>
              <tr className="bg-background-100 text-left text-xs text-foreground-500">
                <th className="px-4 py-3 font-medium">语言</th>
                <th className="px-4 py-3 font-medium">命名空间</th>
                <th className="px-4 py-3 font-medium">键名</th>
                <th className="px-4 py-3 font-medium">文案</th>
                <th className="px-4 py-3 font-medium text-right">操作</th>
              </tr>
            </thead>
            <tbody>
              {loading ? (
                [0, 1, 2].map((n) => (
                  <tr key={n} className="border-t border-background-200">
                    <td colSpan={5} className="px-4 py-3">
                      <div className="h-8 rounded-md bg-background-100 animate-pulse-soft" />
                    </td>
                  </tr>
                ))
              ) : filtered.length === 0 ? (
                <tr className="border-t border-background-200">
                  <td colSpan={5} className="px-4 py-14 text-center text-foreground-500">
                    <i className="ri-translate-2 text-2xl block mb-2"></i>
                    没有匹配的词条
                  </td>
                </tr>
              ) : (
                filtered.map((row) => {
                  const dirty = (draft[row.id] ?? '') !== (row.value ?? '');
                  return (
                    <tr key={row.id} className="border-t border-background-200 hover:bg-background-100/60">
                      <td className="px-4 py-3">
                        <span className="text-[11px] px-2 py-0.5 rounded-full bg-primary-100 text-primary-800 font-label">
                          {row.lang}
                        </span>
                      </td>
                      <td className="px-4 py-3">
                        <span className="text-[11px] px-2 py-0.5 rounded-full bg-secondary-100 text-secondary-900 font-label">
                          {row.namespace}
                        </span>
                      </td>
                      <td className="px-4 py-3 font-label text-xs text-foreground-700">{row.str_key}</td>
                      <td className="px-4 py-3">
                        <input
                          type="text"
                          value={draft[row.id] ?? ''}
                          disabled={!canManage}
                          onChange={(e) => setDraft((p) => ({ ...p, [row.id]: e.target.value }))}
                          className="w-full h-9 px-2.5 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400"
                        />
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex items-center justify-end gap-1">
                          <button
                            type="button"
                            onClick={() => saveRow(row)}
                            disabled={!canManage || !dirty || savingId === row.id}
                            className="h-8 px-2.5 rounded-md bg-background-100 border border-background-300 text-xs text-foreground-800 hover:bg-primary-50 hover:text-primary-700 disabled:opacity-40 cursor-pointer whitespace-nowrap flex items-center gap-1"
                          >
                            <i className="ri-save-line"></i>
                            {savingId === row.id ? '保存中…' : '保存'}
                          </button>
                          <button
                            type="button"
                            onClick={() => deleteRow(row)}
                            disabled={!canManage}
                            title="删除"
                            className="w-8 h-8 flex items-center justify-center rounded-md text-foreground-500 hover:bg-secondary-200 hover:text-secondary-900 disabled:opacity-40 cursor-pointer"
                          >
                            <i className="ri-delete-bin-line"></i>
                          </button>
                        </div>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>

      <Modal
        open={addOpen}
        title="新增词条"
        subtitle="同一语言 + 命名空间 + 键名保存时会自动覆盖"
        onClose={() => setAddOpen(false)}
        footer={
          <>
            <button
              type="button"
              onClick={() => setAddOpen(false)}
              className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
            >
              取消
            </button>
            <button
              type="button"
              onClick={submitAdd}
              className="h-9 px-4 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 cursor-pointer whitespace-nowrap dark:text-foreground-950"
            >
              保存
            </button>
          </>
        }
      >
        <div className="space-y-3.5">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3.5">
            <div>
              <label className="block text-xs font-medium text-foreground-700 mb-1.5">语言代码</label>
              <input
                type="text"
                value={form.lang}
                onChange={(e) => setForm((p) => ({ ...p, lang: e.target.value }))}
                placeholder="例如:zh-CN / en"
                className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400 font-label"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-foreground-700 mb-1.5">命名空间</label>
              <input
                type="text"
                value={form.namespace}
                onChange={(e) => setForm((p) => ({ ...p, namespace: e.target.value }))}
                placeholder="例如:menu / common"
                className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400 font-label"
              />
            </div>
          </div>
          <div>
            <label className="block text-xs font-medium text-foreground-700 mb-1.5">键名</label>
            <input
              type="text"
              value={form.str_key}
              onChange={(e) => setForm((p) => ({ ...p, str_key: e.target.value }))}
              placeholder="例如:menu.users"
              className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400 font-label"
            />
          </div>
          <div>
            <label className="block text-xs font-medium text-foreground-700 mb-1.5">文案</label>
            <input
              type="text"
              value={form.value}
              onChange={(e) => setForm((p) => ({ ...p, value: e.target.value }))}
              placeholder="该键对应的显示文案"
              className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400"
            />
          </div>
          {formError ? (
            <div className="flex items-start gap-2 px-3 py-2.5 rounded-md bg-accent-100 text-accent-900 text-xs">
              <i className="ri-error-warning-line mt-0.5"></i>
              <span>{formError}</span>
            </div>
          ) : null}
        </div>
      </Modal>
    </div>
  );
}