import { useCallback, useEffect, useMemo, useState } from 'react';
import { runEndpoint, type TryResult } from '@/pages/api-docs/apiRunner';
import { methodStyle, type EndpointDef, type ParamDef } from '@/pages/api-docs/types';
import {
  deleteDebugCase,
  fetchDebugCases,
  normalizeTags,
  saveDebugCase,
  type DebugCase,
} from '@/pages/api-docs/debugCases';

interface TryItOutPanelProps {
  endpoint: EndpointDef;
}

function defaultQuery(p: ParamDef): string {
  if (p.name === 'page') return '1';
  if (p.name === 'page_size') return '20';
  return '';
}

function statusTone(status: number) {
  if (status >= 200 && status < 300) return 'bg-primary-100 text-primary-800';
  if (status >= 400 && status < 500) return 'bg-accent-100 text-accent-900';
  return 'bg-secondary-700 text-background-50';
}

function mergeParams(defs: ParamDef[], saved: Record<string, string> | null): Record<string, string> {
  const out: Record<string, string> = {};
  defs.forEach((p) => {
    const next = saved && saved[p.name] != null ? String(saved[p.name]) : defaultQuery(p);
    out[p.name] = next;
  });
  return out;
}

function formatTime(iso: string | null) {
  if (!iso) return '';
  const d = new Date(iso);
  return `${d.getMonth() + 1}/${d.getDate()} ${String(d.getHours()).padStart(2, '0')}:${String(
    d.getMinutes(),
  ).padStart(2, '0')}`;
}

export default function TryItOutPanel({ endpoint }: TryItOutPanelProps) {
  const pathParamsDefs = useMemo(() => endpoint.params.filter((p) => p.in === 'path'), [endpoint]);
  const queryParamsDefs = useMemo(() => endpoint.params.filter((p) => p.in === 'query'), [endpoint]);

  const [pathParams, setPathParams] = useState<Record<string, string>>({});
  const [queryParams, setQueryParams] = useState<Record<string, string>>({});
  const [bodyText, setBodyText] = useState('');
  const [sending, setSending] = useState(false);
  const [result, setResult] = useState<TryResult | null>(null);
  const [copied, setCopied] = useState(false);

  // debug cases
  const [cases, setCases] = useState<DebugCase[]>([]);
  const [casesLoading, setCasesLoading] = useState(false);
  const [caseName, setCaseName] = useState('');
  const [caseTagInput, setCaseTagInput] = useState('');
  const [savingCase, setSavingCase] = useState(false);
  const [caseNotice, setCaseNotice] = useState('');
  const [busyCaseId, setBusyCaseId] = useState<string | null>(null);

  useEffect(() => {
    setPathParams(mergeParams(pathParamsDefs, null));
    setQueryParams(mergeParams(queryParamsDefs, null));
    setBodyText(endpoint.requestBody ? JSON.stringify(endpoint.requestBody, null, 2) : '');
    setResult(null);
    setCaseName('');
    setCaseTagInput('');
    setCaseNotice('');
  }, [endpoint, pathParamsDefs, queryParamsDefs]);

  const loadCases = useCallback(async () => {
    setCasesLoading(true);
    try {
      const list = await fetchDebugCases(endpoint.code);
      setCases(list);
    } catch (err) {
      console.error(err);
      setCases([]);
    } finally {
      setCasesLoading(false);
    }
  }, [endpoint.code]);

  useEffect(() => {
    loadCases();
  }, [loadCases]);

  const runWith = async (
    pp: Record<string, string>,
    qp: Record<string, string>,
    body: string,
  ) => {
    setSending(true);
    try {
      const res = await runEndpoint(endpoint, { pathParams: pp, queryParams: qp, body });
      setResult(res);
    } finally {
      setSending(false);
    }
  };

  const send = () => runWith(pathParams, queryParams, bodyText);

  const saveCase = async () => {
    if (!caseName.trim()) {
      setCaseNotice('请先给这个用例起个名字');
      return;
    }
    setSavingCase(true);
    try {
      await saveDebugCase({
        name: caseName,
        endpointCode: endpoint.code,
        method: endpoint.method,
        path: endpoint.path,
        resource: endpoint.resource,
        action: endpoint.action,
        pathParams,
        queryParams,
        body: bodyText,
        tags: normalizeTags(caseTagInput),
      });
      setCaseName('');
      setCaseTagInput('');
      setCaseNotice('已保存为调试用例');
      await loadCases();
      setTimeout(() => setCaseNotice(''), 2400);
    } catch (err) {
      console.error(err);
      setCaseNotice('保存失败,请检查权限');
    } finally {
      setSavingCase(false);
    }
  };

  const applyCase = (c: DebugCase) => {
    setPathParams(mergeParams(pathParamsDefs, c.path_params));
    setQueryParams(mergeParams(queryParamsDefs, c.query_params));
    setBodyText(c.body ?? '');
    setResult(null);
    setCaseNotice(`已载入「${c.name}」`);
    setTimeout(() => setCaseNotice(''), 2000);
  };

  const replayCase = async (c: DebugCase) => {
    const pp = mergeParams(pathParamsDefs, c.path_params);
    const qp = mergeParams(queryParamsDefs, c.query_params);
    const body = c.body ?? '';
    setBusyCaseId(c.id);
    setPathParams(pp);
    setQueryParams(qp);
    setBodyText(body);
    try {
      await runWith(pp, qp, body);
      setCaseNotice(`已重放「${c.name}」`);
      setTimeout(() => setCaseNotice(''), 2000);
    } finally {
      setBusyCaseId(null);
    }
  };

  const removeCase = async (c: DebugCase) => {
    setBusyCaseId(c.id);
    try {
      await deleteDebugCase(c.id);
      await loadCases();
    } catch (err) {
      console.error(err);
    } finally {
      setBusyCaseId(null);
    }
  };

  const copyResponse = async () => {
    if (!result) return;
    try {
      await navigator.clipboard.writeText(JSON.stringify(result.data, null, 2));
      setCopied(true);
      setTimeout(() => setCopied(false), 1600);
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <section className="rounded-md border border-primary-200 bg-primary-50/50 p-4">
      <div className="flex items-center gap-2 mb-3">
        <span className="w-7 h-7 rounded-md flex items-center justify-center bg-primary-500 text-background-50 dark:text-foreground-950">
          <i className="ri-terminal-box-line text-sm"></i>
        </span>
        <div>
          <h4 className="text-sm font-semibold text-foreground-950">在线调试 · Try it out</h4>
          <p className="text-[11px] text-foreground-500">填写参数后直接向后端发起真实请求,可将常用请求存为调试用例并一键重放</p>
        </div>
      </div>

      <div className="space-y-3">
        {pathParamsDefs.length === 0 && queryParamsDefs.length === 0 ? (
          <p className="text-xs text-foreground-500">该接口无需请求参数,可直接发送。</p>
        ) : null}

        {pathParamsDefs.length > 0 ? (
          <div>
            <p className="text-[11px] font-medium text-foreground-600 mb-1.5">路径参数</p>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
              {pathParamsDefs.map((p) => (
                <label key={p.name} className="block">
                  <span className="text-[11px] text-foreground-600 font-label">
                    {p.name}
                    {p.required ? <span className="text-secondary-800 ml-0.5">*</span> : null}
                  </span>
                  <input
                    type="text"
                    value={pathParams[p.name] ?? ''}
                    onChange={(e) => setPathParams((prev) => ({ ...prev, [p.name]: e.target.value }))}
                    placeholder={p.description}
                    className="mt-1 w-full h-9 px-3 rounded-md bg-background-50 border border-background-300 text-xs text-foreground-900 focus:outline-none focus:border-primary-400 font-label"
                  />
                </label>
              ))}
            </div>
          </div>
        ) : null}

        {queryParamsDefs.length > 0 ? (
          <div>
            <p className="text-[11px] font-medium text-foreground-600 mb-1.5">查询参数</p>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
              {queryParamsDefs.map((p) => (
                <label key={p.name} className="block">
                  <span className="text-[11px] text-foreground-600 font-label">{p.name}</span>
                  <input
                    type="text"
                    value={queryParams[p.name] ?? ''}
                    onChange={(e) => setQueryParams((prev) => ({ ...prev, [p.name]: e.target.value }))}
                    placeholder={p.description}
                    className="mt-1 w-full h-9 px-3 rounded-md bg-background-50 border border-background-300 text-xs text-foreground-900 focus:outline-none focus:border-primary-400 font-label"
                  />
                </label>
              ))}
            </div>
          </div>
        ) : null}

        {endpoint.requestBody ? (
          <div>
            <p className="text-[11px] font-medium text-foreground-600 mb-1.5">请求体 (JSON)</p>
            <textarea
              value={bodyText}
              onChange={(e) => setBodyText(e.target.value)}
              rows={7}
              spellCheck={false}
              className="w-full px-3 py-2 rounded-md bg-background-50 border border-background-300 text-xs text-foreground-900 font-label focus:outline-none focus:border-primary-400 resize-y"
            />
          </div>
        ) : null}

        <div className="flex flex-wrap items-center gap-2">
          <button
            type="button"
            onClick={send}
            disabled={sending}
            className="h-9 px-4 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 disabled:opacity-60 cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5 dark:text-foreground-950"
          >
            <i className={sending ? 'ri-loader-4-line animate-spin' : 'ri-send-plane-line'}></i>
            {sending ? '请求中…' : '发送请求'}
          </button>
          <span className={`text-[11px] font-label px-2 py-0.5 rounded ${methodStyle[endpoint.method]}`}>
            {endpoint.method}
          </span>
          <span className="text-[11px] text-foreground-500 font-label truncate">{endpoint.path}</span>
        </div>

        {result ? (
          <div className="rounded-md border border-background-200 overflow-hidden bg-background-50">
            <div className="flex flex-wrap items-center gap-2 px-3 py-2 bg-background-100 border-b border-background-200">
              <span className={`text-[11px] font-label px-2 py-0.5 rounded ${statusTone(result.status)}`}>
                {result.status} {result.statusText}
              </span>
              <span className="text-[11px] text-foreground-500 inline-flex items-center gap-1">
                <i className="ri-timer-line"></i>
                {result.timeMs} ms
              </span>
              <button
                type="button"
                onClick={copyResponse}
                className="ml-auto inline-flex items-center gap-1 text-[11px] text-foreground-600 hover:text-foreground-900 cursor-pointer whitespace-nowrap"
              >
                <i className={copied ? 'ri-check-line' : 'ri-file-copy-line'}></i>
                {copied ? '已复制' : '复制响应'}
              </button>
            </div>
            {result.note ? (
              <p className="px-3 py-1.5 text-[11px] text-foreground-500 bg-background-100/60 border-b border-background-200">
                {result.note}
              </p>
            ) : null}
            <pre className="px-3 py-3 text-xs leading-relaxed font-label text-foreground-800 overflow-x-auto max-h-[360px]">
              {JSON.stringify(result.data, null, 2)}
            </pre>
          </div>
        ) : null}

        {/* ---------- debug cases ---------- */}
        <div className="rounded-md border border-background-200 bg-background-50">
          <div className="flex items-center gap-2 px-3 py-2 border-b border-background-200">
            <i className="ri-bookmark-3-line text-sm text-secondary-700"></i>
            <span className="text-xs font-semibold text-foreground-900">调试用例</span>
            <span className="text-[11px] text-foreground-500">共 {cases.length} 个</span>
            {caseNotice ? (
              <span className="ml-auto text-[11px] text-primary-700 inline-flex items-center gap-1">
                <i className="ri-checkbox-circle-line"></i>
                {caseNotice}
              </span>
            ) : null}
          </div>

          <div className="px-3 py-2.5 border-b border-background-200 space-y-2">
            <input
              type="text"
              value={caseName}
              onChange={(e) => setCaseName(e.target.value)}
              placeholder="给当前这组参数起个名字,例如「用户列表 · 默认分页」"
              className="w-full h-9 px-3 rounded-md bg-background-50 border border-background-300 text-xs text-foreground-900 focus:outline-none focus:border-primary-400"
            />
            <div className="flex flex-col sm:flex-row sm:items-center gap-2">
              <div className="flex items-center gap-2 h-9 px-3 rounded-md bg-background-50 border border-background-300 flex-1">
                <i className="ri-price-tag-3-line text-foreground-400 text-xs"></i>
                <input
                  type="text"
                  value={caseTagInput}
                  onChange={(e) => setCaseTagInput(e.target.value)}
                  placeholder="标签(可选),用逗号分隔,例如 smoke, regression"
                  className="flex-1 bg-transparent text-xs text-foreground-900 placeholder:text-foreground-400 focus:outline-none"
                />
              </div>
              <button
                type="button"
                onClick={saveCase}
                disabled={savingCase}
                className="h-9 px-3 rounded-md bg-secondary-500 text-background-50 text-xs hover:bg-secondary-600 disabled:opacity-60 cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5 dark:text-foreground-950"
              >
                <i className={savingCase ? 'ri-loader-4-line animate-spin' : 'ri-save-3-line'}></i>
                保存当前请求
              </button>
            </div>
          </div>

          {casesLoading ? (
            <div className="p-3 space-y-2">
              {[0, 1].map((n) => (
                <div key={n} className="h-10 rounded-md bg-background-100 animate-pulse-soft" />
              ))}
            </div>
          ) : cases.length === 0 ? (
            <p className="px-3 py-6 text-center text-xs text-foreground-500">
              还没有保存的用例,填写参数后点「保存当前请求」即可
            </p>
          ) : (
            <ul className="divide-y divide-background-200">
              {cases.map((c) => (
                <li key={c.id} className="flex items-center gap-2 px-3 py-2.5">
                  <span className={`text-[10px] font-label px-1.5 py-0.5 rounded shrink-0 ${methodStyle[c.method ?? 'GET']}`}>
                    {c.method}
                  </span>
                  <div className="min-w-0 flex-1">
                    <p className="text-xs text-foreground-950 truncate">{c.name}</p>
                    <p className="text-[10px] text-foreground-500 font-label truncate">
                      {formatTime(c.created_at)} · {c.path}
                    </p>
                    {c.tags && c.tags.length > 0 ? (
                      <div className="mt-1 flex flex-wrap gap-1">
                        {c.tags.map((t) => (
                          <span
                            key={t}
                            className="text-[10px] px-1.5 py-0.5 rounded-full bg-secondary-100 text-secondary-900"
                          >
                            #{t}
                          </span>
                        ))}
                      </div>
                    ) : null}
                  </div>
                  <button
                    type="button"
                    onClick={() => applyCase(c)}
                    className="h-7 px-2 rounded-md bg-background-100 border border-background-300 text-[11px] text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap inline-flex items-center gap-1"
                  >
                    <i className="ri-download-2-line"></i>
                    载入
                  </button>
                  <button
                    type="button"
                    onClick={() => replayCase(c)}
                    disabled={busyCaseId === c.id}
                    className="h-7 px-2 rounded-md bg-primary-500 text-background-50 text-[11px] hover:bg-primary-600 disabled:opacity-60 cursor-pointer whitespace-nowrap inline-flex items-center gap-1 dark:text-foreground-950"
                  >
                    <i className={busyCaseId === c.id ? 'ri-loader-4-line animate-spin' : 'ri-play-line'}></i>
                    重放
                  </button>
                  <button
                    type="button"
                    onClick={() => removeCase(c)}
                    disabled={busyCaseId === c.id}
                    title="删除"
                    className="w-7 h-7 flex items-center justify-center rounded-md text-foreground-500 hover:bg-secondary-200 hover:text-secondary-900 disabled:opacity-40 cursor-pointer shrink-0"
                  >
                    <i className="ri-delete-bin-line text-xs"></i>
                  </button>
                </li>
              ))}
            </ul>
          )}
        </div>
      </div>
    </section>
  );
}