interface HealthPanelProps {
  latency: number;
  errorRate: number;
  cpu: number;
  memory: number;
  onlineUsers: number;
}

interface ServiceState {
  name: string;
  desc: string;
  icon: string;
  status: 'healthy' | 'warning' | 'down';
}

const statusMeta: Record<ServiceState['status'], { label: string; dot: string; text: string; bg: string }> = {
  healthy: { label: '正常', dot: 'bg-primary-500', text: 'text-primary-700', bg: 'bg-primary-50' },
  warning: { label: '波动', dot: 'bg-accent-500', text: 'text-accent-800', bg: 'bg-accent-100' },
  down: { label: '异常', dot: 'bg-secondary-600', text: 'text-secondary-900', bg: 'bg-secondary-200' },
};

export default function HealthPanel({ latency, errorRate, cpu, memory, onlineUsers }: HealthPanelProps) {
  const grade = (bad: boolean, worse: boolean): ServiceState['status'] =>
    worse ? 'down' : bad ? 'warning' : 'healthy';

  const services: ServiceState[] = [
    {
      name: 'API 网关',
      desc: `P95 ${latency.toFixed(0)}ms · QPS 正常`,
      icon: 'ri-router-line',
      status: grade(latency > 150, latency > 220),
    },
    {
      name: '认证服务',
      desc: `会话 ${Math.round(onlineUsers)} 个 · 签发正常`,
      icon: 'ri-fingerprint-line',
      status: grade(errorRate > 1.6, errorRate > 2.6),
    },
    {
      name: '数据库集群',
      desc: `连接池 ${Math.min(99, Math.round(40 + cpu * 0.5))}% · 主从同步正常`,
      icon: 'ri-database-2-line',
      status: grade(cpu > 78, cpu > 90),
    },
    {
      name: '缓存服务 Redis',
      desc: `命中率 ${Math.max(60, Math.round(98 - memory * 0.28))}% · 内存平稳`,
      icon: 'ri-archive-2-line',
      status: grade(memory > 78, memory > 88),
    },
    {
      name: '任务调度',
      desc: '队列积压 0 · 定时任务正常',
      icon: 'ri-time-line',
      status: 'healthy',
    },
    {
      name: '对象存储',
      desc: '读写延迟 < 20ms · 容量充足',
      icon: 'ri-hard-drive-3-line',
      status: 'healthy',
    },
  ];

  const healthy = services.filter((s) => s.status === 'healthy').length;
  const score = Math.round((healthy / services.length) * 100);

  return (
    <section className="rounded-lg bg-background-50 border border-background-200 p-4 md:p-5">
      <div className="flex items-center justify-between mb-3">
        <div>
          <h3 className="text-sm font-semibold text-foreground-950">服务健康大盘</h3>
          <p className="text-xs text-foreground-500 mt-0.5">核心依赖实时探活</p>
        </div>
        <div className="text-right">
          <p className="text-xl font-semibold text-foreground-950 font-heading">{score}</p>
          <p className="text-[11px] text-foreground-500">健康分</p>
        </div>
      </div>

      <ul className="space-y-2">
        {services.map((svc) => {
          const meta = statusMeta[svc.status];
          return (
            <li
              key={svc.name}
              className="flex items-center gap-3 rounded-md border border-background-200 px-3 py-2.5"
            >
              <span className={`w-8 h-8 rounded-md flex items-center justify-center ${meta.bg} ${meta.text}`}>
                <i className={`${svc.icon} text-base`}></i>
              </span>
              <div className="min-w-0 flex-1">
                <p className="text-sm text-foreground-900 truncate">{svc.name}</p>
                <p className="text-[11px] text-foreground-500 font-label truncate">{svc.desc}</p>
              </div>
              <span className={`inline-flex items-center gap-1.5 text-[11px] ${meta.text}`}>
                <span className={`w-1.5 h-1.5 rounded-full ${meta.dot} animate-pulse-soft`} />
                {meta.label}
              </span>
            </li>
          );
        })}
      </ul>
    </section>
  );
}