import { useCallback, useEffect, useState } from 'react';
import { supabase } from '@/lib/supabase';

const LOCAL_KEY_PREFIX = 'readdy.sdk.favoriteSnippets';

function localKey(userId: string) {
  return `${LOCAL_KEY_PREFIX}.${userId || 'guest'}`;
}

function loadLocal(userId: string): string[] {
  if (typeof window === 'undefined') return [];
  try {
    const raw = window.localStorage.getItem(localKey(userId));
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed.filter((s): s is string => typeof s === 'string') : [];
  } catch (err) {
    console.error(err);
    return [];
  }
}

function persistLocal(userId: string, list: string[]) {
  if (typeof window === 'undefined') return;
  try {
    window.localStorage.setItem(localKey(userId), JSON.stringify(list));
  } catch (err) {
    console.error(err);
  }
}

interface FavoriteRow {
  snippet_id: string;
  favorited: boolean | null;
}

/**
 * SDK 片段收藏:登录后按账号存后端(sdk_snippet_favorites),换设备自动同步并保持置顶;
 * 未登录时退化为本地存储。
 */
export function useSdkFavorites(userId: string) {
  const [favIds, setFavIds] = useState<string[]>([]);
  const [syncing, setSyncing] = useState(false);
  const [syncError, setSyncError] = useState('');

  const load = useCallback(async () => {
    if (!userId) {
      setFavIds(loadLocal(''));
      return;
    }
    setSyncing(true);
    setSyncError('');
    try {
      const { data, error } = await supabase
        .from('sdk_snippet_favorites')
        .select('snippet_id, favorited')
        .eq('user_id', userId);
      if (error) throw error;
      const rows = (data as FavoriteRow[]) ?? [];
      setFavIds(rows.filter((r) => r.favorited).map((r) => r.snippet_id));
    } catch (err) {
      console.error(err);
      setSyncError('账号数据同步失败');
      setFavIds(loadLocal(userId));
    } finally {
      setSyncing(false);
    }
  }, [userId]);

  useEffect(() => {
    load();
  }, [load]);

  const toggleFavorite = useCallback(
    async (id: string) => {
      const next = !favIds.includes(id);
      setSyncError('');
      setFavIds((prev) => (next ? [id, ...prev.filter((x) => x !== id)] : prev.filter((x) => x !== id)));

      // 未登录:仅本地保存
      if (!userId) {
        const updated = next
          ? [id, ...loadLocal('').filter((x) => x !== id)]
          : loadLocal('').filter((x) => x !== id);
        persistLocal('', updated);
        return;
      }

      try {
        const now = new Date().toISOString();
        const { error } = await supabase.from('sdk_snippet_favorites').upsert(
          {
            user_id: userId,
            snippet_id: id,
            favorited: next,
            favorited_at: now,
            updated_at: now,
          },
          { onConflict: 'user_id,snippet_id' },
        );
        if (error) throw error;
      } catch (err) {
        console.error(err);
        // 回滚
        setFavIds((prev) => (next ? prev.filter((x) => x !== id) : [id, ...prev.filter((x) => x !== id)]));
        setSyncError('收藏同步失败,请重试');
      }
    },
    [favIds, userId],
  );

  return { favIds, setFavIds, toggleFavorite, syncing, syncError, reload: load };
}