import { useCallback, useEffect, useMemo, useState } from 'react';
import { supabase } from '@/lib/supabase';
import { useAuth } from '@/contexts/AuthContext';
import Modal from '@/components/base/Modal';
import { moveToRecycleBin } from '@/lib/recycleBin';
import { memberLevels, memberLevelKeys, memberLevelMeta, type MemberRow } from '@/pages/member/types';

const avatarTones = [
  'bg-primary-100 text-primary-700',
  'bg-accent-100 text-accent-800',
  'bg-secondary-200 text-secondary-900',
  'bg-primary-200 text-primary-800',
];

interface EditState {
  nickname: string;
  phone: string;
  level: string;
  status: string;
  points: number;
  bio: string;
}

function initials(name: string) {
  return name.slice(0, 1).toUpperCase();
}

function fmtDate(iso: string | null) {
  if (!iso) return '—';
  const d = new Date(iso);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

export default function MembersAdminPage() {
  const { hasPermission } = useAuth();
  // 按钮级权限:严格按勾选的权限点判断,不再使用「能看到菜单就能改/删」的兜底
  const canUpdate = hasPermission('member:update');
  const canDelete = hasPermission('member:delete');

  const [members, setMembers] = useState<MemberRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');

  const [keyword, setKeyword] = useState('');
  const [levelFilter, setLevelFilter] = useState('all');
  const [statusFilter, setStatusFilter] = useState('all');

  const [editTarget, setEditTarget] = useState<MemberRow | null>(null);
  const [editForm, setEditForm] = useState<EditState>({
    nickname: '',
    phone: '',
    level: 'standard',
    status: 'active',
    points: 0,
    bio: '',
  });
  const [saving, setSaving] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState<MemberRow | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const { data, error: err } = await supabase
        .from('members')
        .select('*')
        .order('joined_at', { ascending: false });
      if (err) throw err;
      setMembers((data as MemberRow[]) ?? []);
    } catch (err) {
      console.error(err);
      setError('加载会员列表失败,请重试');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  useEffect(() => {
    if (!notice) return;
    const timer = setTimeout(() => setNotice(''), 2600);
    return () => clearTimeout(timer);
  }, [notice]);

  const stats = useMemo(
    () => ({
      total: members.length,
      active: members.filter((m) => (m.status ?? 'active') === 'active').length,
      gold: members.filter((m) => m.level === 'gold' || m.level === 'platinum').length,
      points: members.reduce((s, m) => s + (m.points ?? 0), 0),
    }),
    [members],
  );

  const filtered = useMemo(
    () =>
      members.filter((m) => {
        const kw = keyword.trim().toLowerCase();
        const matchKw =
          !kw ||
          (m.nickname ?? '').toLowerCase().includes(kw) ||
          (m.email ?? '').toLowerCase().includes(kw) ||
          (m.phone ?? '').includes(kw);
        const matchLevel = levelFilter === 'all' || (m.level ?? 'standard') === levelFilter;
        const matchStatus = statusFilter === 'all' || (m.status ?? 'active') === statusFilter;
        return matchKw && matchLevel && matchStatus;
      }),
    [members, keyword, levelFilter, statusFilter],
  );

  const openEdit = (m: MemberRow) => {
    setEditTarget(m);
    setEditForm({
      nickname: m.nickname ?? '',
      phone: m.phone ?? '',
      level: m.level ?? 'standard',
      status: m.status ?? 'active',
      points: m.points ?? 0,
      bio: m.bio ?? '',
    });
  };

  const submitEdit = async () => {
    if (!editTarget) return;
    if (!editForm.nickname.trim()) {
      setError('昵称不能为空');
      return;
    }
    setSaving(true);
    setError('');
    try {
      const { error: err } = await supabase
        .from('members')
        .update({
          nickname: editForm.nickname.trim(),
          phone: editForm.phone.trim() || null,
          level: editForm.level,
          status: editForm.status,
          points: Number(editForm.points) || 0,
          bio: editForm.bio.trim() || null,
        })
        .eq('id', editTarget.id);
      if (err) throw err;
      setNotice('会员信息已更新');
      setEditTarget(null);
      await load();
    } catch (err) {
      console.error(err);
      setError('保存失败,请检查权限后重试');
    } finally {
      setSaving(false);
    }
  };

  const toggleStatus = async (m: MemberRow) => {
    const next = (m.status ?? 'active') === 'active' ? 'disabled' : 'active';
    const { error: err } = await supabase.from('members').update({ status: next }).eq('id', m.id);
    if (err) {
      setError('状态更新失败');
      return;
    }
    setNotice(next === 'active' ? '已启用该会员' : '已停用该会员');
    await load();
  };

  const confirmDelete = async () => {
    const target = deleteTarget;
    if (!target) return;

    // 先尝试连登录账号一起彻底删除;若调用方无权限或该会员没有登录账号,则退化为仅删会员档案
    let loginDeleted = false;
    let fnMessage = '';
    try {
      const { data, error: invokeErr } = await supabase.functions.invoke('delete-account', {
        body: { userId: target.id },
      });
      if (invokeErr) {
        fnMessage = '无权限彻底删除登录账号';
      } else {
        const result = (data ?? {}) as { deleted?: boolean; authDeleted?: boolean; error?: string };
        if (result.error) {
          fnMessage = result.error;
        } else if (result.deleted) {
          loginDeleted = true;
          if (!result.authDeleted) fnMessage = '该会员没有可删除的登录账号';
        }
      }
    } catch (err) {
      console.error(err);
      fnMessage = '调用彻底删除失败';
    }

    try {
      if (!loginDeleted) {
        const { error: err } = await supabase.from('members').delete().eq('id', target.id);
        if (err) throw err;
      }
      await moveToRecycleBin({
        module: 'member',
        itemId: target.id,
        itemName: target.nickname || target.email || '未命名会员',
        snapshot: {
          id: target.id,
          email: target.email,
          nickname: target.nickname,
          phone: target.phone,
          avatar_url: target.avatar_url,
          bio: target.bio,
          level: target.level ?? 'standard',
          status: target.status ?? 'active',
          points: target.points ?? 0,
          joined_at: target.joined_at,
        },
      });
      setNotice(
        loginDeleted
          ? '会员及其登录账号已彻底删除(档案可在回收站还原,登录账号不可恢复)'
          : `会员档案已删除,可在回收站还原;登录账号未删除${fnMessage ? `(${fnMessage})` : ''}`,
      );
      setDeleteTarget(null);
      await load();
    } catch (err) {
      console.error(err);
      setError('删除失败,可能权限不足');
      setDeleteTarget(null);
    }
  };

  const statCards = [
    { label: '会员总数', value: stats.total, icon: 'ri-group-line', tone: 'bg-primary-100 text-primary-700' },
    { label: '正常会员', value: stats.active, icon: 'ri-user-follow-line', tone: 'bg-accent-100 text-accent-800' },
    { label: '高价值会员', value: stats.gold, icon: 'ri-vip-crown-line', tone: 'bg-secondary-200 text-secondary-900' },
    { label: '积分总量', value: stats.points.toLocaleString(), icon: 'ri-copper-coin-line', tone: 'bg-primary-100 text-primary-700' },
  ];

  return (
    <div className="space-y-4">
      <div className="flex flex-col md:flex-row md:items-center gap-3">
        <div>
          <h2 className="text-lg font-semibold text-foreground-950">会员中心</h2>
          <p className="text-sm text-foreground-500 mt-0.5">
            管理前台会员账号、等级与积分(与后台管理账号相互独立)
          </p>
        </div>
        <div className="md:ml-auto flex flex-wrap items-center gap-2">
          <div className="flex items-center gap-2 h-9 px-3 rounded-md bg-background-50 border border-background-200 w-full sm:w-52">
            <i className="ri-search-line text-foreground-400 text-sm"></i>
            <input
              type="text"
              value={keyword}
              onChange={(e) => setKeyword(e.target.value)}
              placeholder="搜索昵称 / 邮箱 / 手机号"
              className="flex-1 bg-transparent text-sm text-foreground-900 placeholder:text-foreground-400 focus:outline-none"
            />
          </div>
          <select
            value={levelFilter}
            onChange={(e) => setLevelFilter(e.target.value)}
            className="h-9 px-3 rounded-md bg-background-50 border border-background-200 text-sm text-foreground-800 focus:outline-none cursor-pointer"
          >
            <option value="all">全部等级</option>
            {memberLevelKeys.map((k) => (
              <option key={k} value={k}>
                {memberLevels[k].label}
              </option>
            ))}
          </select>
          <select
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
            className="h-9 px-3 rounded-md bg-background-50 border border-background-200 text-sm text-foreground-800 focus:outline-none cursor-pointer"
          >
            <option value="all">全部状态</option>
            <option value="active">正常</option>
            <option value="disabled">已停用</option>
          </select>
        </div>
      </div>

      {notice ? (
        <div className="flex items-center gap-2 px-3 py-2.5 rounded-md bg-primary-50 text-primary-800 text-sm animate-fade-up">
          <i className="ri-checkbox-circle-line"></i>
          {notice}
        </div>
      ) : null}
      {error ? (
        <div className="flex items-center justify-between gap-3 px-3 py-2.5 rounded-md bg-accent-100 text-accent-900 text-sm">
          {error}
          <button type="button" onClick={load} className="text-xs underline cursor-pointer whitespace-nowrap">
            重试
          </button>
        </div>
      ) : null}

      <section className="grid grid-cols-2 xl:grid-cols-4 gap-3 md:gap-4">
        {statCards.map((s) => (
          <div key={s.label} className="rounded-lg bg-background-50 border border-background-200 p-4">
            <div className="flex items-center gap-2">
              <span className={`w-8 h-8 rounded-md flex items-center justify-center ${s.tone}`}>
                <i className={`${s.icon} text-sm`}></i>
              </span>
              <span className="text-xs text-foreground-500">{s.label}</span>
            </div>
            <p className="mt-2.5 text-2xl font-semibold text-foreground-950 font-label">{s.value}</p>
          </div>
        ))}
      </section>

      <div className="rounded-lg bg-background-50 border border-background-200 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full min-w-[820px] text-sm">
            <thead>
              <tr className="bg-background-100 text-left text-xs text-foreground-500">
                <th className="px-4 py-3 font-medium">会员</th>
                <th className="px-4 py-3 font-medium">等级</th>
                <th className="px-4 py-3 font-medium">积分</th>
                <th className="px-4 py-3 font-medium">加入时间</th>
                <th className="px-4 py-3 font-medium">状态</th>
                <th className="px-4 py-3 font-medium text-right">操作</th>
              </tr>
            </thead>
            <tbody>
              {loading ? (
                [0, 1, 2, 3].map((n) => (
                  <tr key={n} className="border-t border-background-200">
                    <td colSpan={6} className="px-4 py-3">
                      <div className="h-8 rounded-md bg-background-100 animate-pulse-soft" />
                    </td>
                  </tr>
                ))
              ) : filtered.length === 0 ? (
                <tr className="border-t border-background-200">
                  <td colSpan={6} className="px-4 py-14 text-center text-foreground-500">
                    <i className="ri-user-search-line text-2xl block mb-2"></i>
                    没有匹配的会员
                  </td>
                </tr>
              ) : (
                filtered.map((m, idx) => {
                  const meta = memberLevelMeta(m.level);
                  const status = m.status ?? 'active';
                  const name = m.nickname || m.email || '未命名';
                  return (
                    <tr key={m.id} className="border-t border-background-200 hover:bg-background-100/60">
                      <td className="px-4 py-3">
                        <div className="flex items-center gap-3">
                          <span
                            className={`w-9 h-9 rounded-full flex items-center justify-center text-sm font-semibold shrink-0 ${
                              avatarTones[idx % avatarTones.length]
                            }`}
                          >
                            {initials(name)}
                          </span>
                          <div className="min-w-0">
                            <p className="text-foreground-950 truncate">{name}</p>
                            <p className="text-xs text-foreground-500 truncate">{m.email}</p>
                          </div>
                        </div>
                      </td>
                      <td className="px-4 py-3">
                        <span className={`inline-flex items-center gap-1.5 text-[11px] px-2 py-1 rounded-full ${meta.tone}`}>
                          <i className={meta.icon}></i>
                          {meta.label}
                        </span>
                      </td>
                      <td className="px-4 py-3 text-foreground-800 font-label">{(m.points ?? 0).toLocaleString()}</td>
                      <td className="px-4 py-3 text-foreground-600 text-xs">{fmtDate(m.joined_at)}</td>
                      <td className="px-4 py-3">
                        <span
                          className={`inline-flex items-center gap-1.5 text-[11px] px-2 py-1 rounded-full ${
                            status === 'active'
                              ? 'bg-primary-100 text-primary-800'
                              : 'bg-background-200 text-foreground-600'
                          }`}
                        >
                          <span
                            className={`w-1.5 h-1.5 rounded-full ${
                              status === 'active' ? 'bg-primary-500' : 'bg-foreground-400'
                            }`}
                          />
                          {status === 'active' ? '正常' : '已停用'}
                        </span>
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex items-center justify-end gap-1">
                          <button
                            type="button"
                            onClick={() => openEdit(m)}
                            disabled={!canUpdate}
                            title="编辑"
                            className="w-8 h-8 flex items-center justify-center rounded-md text-foreground-500 hover:bg-background-200 hover:text-foreground-900 disabled:opacity-40 cursor-pointer"
                          >
                            <i className="ri-pencil-line"></i>
                          </button>
                          <button
                            type="button"
                            onClick={() => toggleStatus(m)}
                            disabled={!canUpdate}
                            title={status === 'active' ? '停用' : '启用'}
                            className="w-8 h-8 flex items-center justify-center rounded-md text-foreground-500 hover:bg-background-200 hover:text-foreground-900 disabled:opacity-40 cursor-pointer"
                          >
                            <i className={status === 'active' ? 'ri-forbid-2-line' : 'ri-play-circle-line'}></i>
                          </button>
                          <button
                            type="button"
                            onClick={() => setDeleteTarget(m)}
                            disabled={!canDelete}
                            title="删除"
                            className="w-8 h-8 flex items-center justify-center rounded-md text-foreground-500 hover:bg-secondary-200 hover:text-secondary-900 disabled:opacity-40 cursor-pointer"
                          >
                            <i className="ri-delete-bin-line"></i>
                          </button>
                        </div>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>

      <Modal
        open={Boolean(editTarget)}
        title="编辑会员"
        subtitle={editTarget?.email ?? ''}
        onClose={() => setEditTarget(null)}
        footer={
          <>
            <button
              type="button"
              onClick={() => setEditTarget(null)}
              className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
            >
              取消
            </button>
            <button
              type="button"
              onClick={submitEdit}
              disabled={saving}
              className="h-9 px-4 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 disabled:opacity-60 cursor-pointer whitespace-nowrap dark:text-foreground-950"
            >
              {saving ? '保存中…' : '保存'}
            </button>
          </>
        }
      >
        <div className="space-y-3.5">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3.5">
            <div>
              <label className="block text-xs font-medium text-foreground-700 mb-1.5">昵称</label>
              <input
                type="text"
                value={editForm.nickname}
                onChange={(e) => setEditForm((p) => ({ ...p, nickname: e.target.value }))}
                className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-foreground-700 mb-1.5">手机号</label>
              <input
                type="text"
                value={editForm.phone}
                onChange={(e) => setEditForm((p) => ({ ...p, phone: e.target.value }))}
                className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-foreground-700 mb-1.5">会员等级</label>
              <select
                value={editForm.level}
                onChange={(e) => setEditForm((p) => ({ ...p, level: e.target.value }))}
                className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400 cursor-pointer"
              >
                {memberLevelKeys.map((k) => (
                  <option key={k} value={k}>
                    {memberLevels[k].label}
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-xs font-medium text-foreground-700 mb-1.5">积分</label>
              <input
                type="number"
                value={editForm.points}
                onChange={(e) => setEditForm((p) => ({ ...p, points: Number(e.target.value) }))}
                className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-foreground-700 mb-1.5">状态</label>
              <select
                value={editForm.status}
                onChange={(e) => setEditForm((p) => ({ ...p, status: e.target.value }))}
                className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400 cursor-pointer"
              >
                <option value="active">正常</option>
                <option value="disabled">已停用</option>
              </select>
            </div>
          </div>
          <div>
            <label className="block text-xs font-medium text-foreground-700 mb-1.5">个人简介</label>
            <textarea
              value={editForm.bio}
              onChange={(e) => setEditForm((p) => ({ ...p, bio: e.target.value }))}
              rows={3}
              maxLength={500}
              className="w-full px-3 py-2 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400 resize-none"
            />
          </div>
        </div>
      </Modal>

      <Modal
        open={Boolean(deleteTarget)}
        title="删除会员"
        onClose={() => setDeleteTarget(null)}
        footer={
          <>
            <button
              type="button"
              onClick={() => setDeleteTarget(null)}
              className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
            >
              取消
            </button>
            <button
              type="button"
              onClick={confirmDelete}
              className="h-9 px-4 rounded-md bg-secondary-700 text-background-50 text-sm hover:bg-secondary-800 cursor-pointer whitespace-nowrap"
            >
              确认删除
            </button>
          </>
        }
      >
        <p className="text-sm text-foreground-700">
          确定删除会员
          <span className="font-medium text-foreground-950"> {deleteTarget?.nickname || deleteTarget?.email} </span>
          吗?将同时删除其会员档案与登录账号;档案可在回收站还原,登录账号删除后不可恢复。
        </p>
      </Modal>
    </div>
  );
}