import { useCallback, useEffect, useMemo, useState } from 'react';
import { supabase } from '@/lib/supabase';
import { useAuth } from '@/contexts/AuthContext';
import Modal from '@/components/base/Modal';

interface NotificationRow {
  id: string;
  title: string;
  content: string | null;
  category: string | null;
  level: string | null;
  is_read: boolean | null;
  created_at: string | null;
}

interface TemplateRow {
  id: string;
  code: string;
  name: string;
  subject: string | null;
  body: string | null;
  enabled: boolean | null;
  updated_at: string | null;
}

const levelMeta: Record<string, { label: string; tone: string }> = {
  info: { label: '提示', tone: 'bg-primary-100 text-primary-800' },
  warn: { label: '警告', tone: 'bg-accent-100 text-accent-900' },
  error: { label: '错误', tone: 'bg-secondary-200 text-secondary-900' },
};

const categoryLabel: Record<string, string> = {
  system: '系统',
  plugin: '插件',
  user: '用户',
  tenant: '租户',
  monitor: '监控',
};

function timeAgo(iso: string | null) {
  if (!iso) return '—';
  const diff = Date.now() - new Date(iso).getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return '刚刚';
  if (mins < 60) return `${mins} 分钟前`;
  const hours = Math.floor(mins / 60);
  if (hours < 24) return `${hours} 小时前`;
  return `${Math.floor(hours / 24)} 天前`;
}

type TabKey = 'inbox' | 'templates';

export default function NotificationCenterPage() {
  const { hasPermission } = useAuth();
  const canManage = hasPermission('notify:manage');

  const [tab, setTab] = useState<TabKey>('inbox');
  const [rows, setRows] = useState<NotificationRow[]>([]);
  const [templates, setTemplates] = useState<TemplateRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const [levelFilter, setLevelFilter] = useState('all');

  const [composeOpen, setComposeOpen] = useState(false);
  const [compose, setCompose] = useState({ title: '', content: '', category: 'system', level: 'info' });
  const [composeError, setComposeError] = useState('');

  const [editTpl, setEditTpl] = useState<TemplateRow | null>(null);
  const [tplForm, setTplForm] = useState({ subject: '', body: '', enabled: true });

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const [notifyRes, tplRes] = await Promise.all([
        supabase.from('notifications').select('*').order('created_at', { ascending: false }),
        supabase.from('email_templates').select('*').order('code', { ascending: true }),
      ]);
      if (notifyRes.error) throw notifyRes.error;
      setRows((notifyRes.data as NotificationRow[]) ?? []);
      setTemplates((tplRes.data as TemplateRow[]) ?? []);
    } catch (err) {
      console.error(err);
      setError('加载通知中心失败,请重试');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  useEffect(() => {
    if (!notice) return;
    const timer = setTimeout(() => setNotice(''), 2600);
    return () => clearTimeout(timer);
  }, [notice]);

  const unread = rows.filter((r) => !r.is_read).length;

  const filtered = useMemo(() => {
    if (levelFilter === 'all') return rows;
    return rows.filter((r) => r.level === levelFilter);
  }, [rows, levelFilter]);

  const toggleRead = async (row: NotificationRow) => {
    const { error: err } = await supabase
      .from('notifications')
      .update({ is_read: !row.is_read })
      .eq('id', row.id);
    if (err) {
      setError('操作失败,可能权限不足');
      return;
    }
    await load();
  };

  const markAllRead = async () => {
    const { error: err } = await supabase.from('notifications').update({ is_read: true }).eq('is_read', false);
    if (err) {
      setError('操作失败,可能权限不足');
      return;
    }
    setNotice('已全部标记为已读');
    await load();
  };

  const removeNotification = async (row: NotificationRow) => {
    const { error: err } = await supabase.from('notifications').delete().eq('id', row.id);
    if (err) {
      setError('删除失败,可能权限不足');
      return;
    }
    await load();
  };

  const submitCompose = async () => {
    if (!compose.title.trim()) {
      setComposeError('请输入通知标题');
      return;
    }
    try {
      const { error: err } = await supabase.from('notifications').insert({
        title: compose.title.trim(),
        content: compose.content,
        category: compose.category,
        level: compose.level,
        is_read: false,
      });
      if (err) throw err;
      setNotice('通知已发布');
      setComposeOpen(false);
      setCompose({ title: '', content: '', category: 'system', level: 'info' });
      setComposeError('');
      await load();
    } catch (err) {
      console.error(err);
      setComposeError('发布失败,请检查权限后重试');
    }
  };

  const openEditTpl = (tpl: TemplateRow) => {
    setEditTpl(tpl);
    setTplForm({ subject: tpl.subject ?? '', body: tpl.body ?? '', enabled: tpl.enabled ?? true });
  };

  const saveTpl = async () => {
    if (!editTpl) return;
    try {
      const { error: err } = await supabase
        .from('email_templates')
        .update({
          subject: tplForm.subject,
          body: tplForm.body,
          enabled: tplForm.enabled,
          updated_at: new Date().toISOString(),
        })
        .eq('id', editTpl.id);
      if (err) throw err;
      setNotice(`已保存模板 ${editTpl.code}`);
      setEditTpl(null);
      await load();
    } catch (err) {
      console.error(err);
      setError('保存失败,请检查权限后重试');
    }
  };

  const toggleTemplate = async (tpl: TemplateRow) => {
    const { error: err } = await supabase
      .from('email_templates')
      .update({ enabled: !tpl.enabled, updated_at: new Date().toISOString() })
      .eq('id', tpl.id);
    if (err) {
      setError('操作失败,可能权限不足');
      return;
    }
    await load();
  };

  return (
    <div className="space-y-4">
      <div className="flex flex-col md:flex-row md:items-center gap-3">
        <div>
          <h2 className="text-lg font-semibold text-foreground-950">通知中心</h2>
          <p className="text-sm text-foreground-500 mt-0.5">
            管理站内信与邮件模板,统一系统的消息触达
          </p>
        </div>
        <div className="md:ml-auto flex items-center gap-1.5 px-1 py-1 rounded-full bg-background-100 border border-background-200">
          <button
            type="button"
            onClick={() => setTab('inbox')}
            className={`h-8 px-3.5 rounded-full text-xs cursor-pointer whitespace-nowrap transition-colors flex items-center gap-1.5 ${
              tab === 'inbox' ? 'bg-primary-500 text-background-50 dark:text-foreground-950' : 'text-foreground-700 hover:bg-background-200'
            }`}
          >
            <i className="ri-notification-3-line"></i>
            站内信
            {unread > 0 ? (
              <span className={`text-[10px] px-1.5 rounded-full font-label ${tab === 'inbox' ? 'bg-background-50/30' : 'bg-accent-100 text-accent-900'}`}>
                {unread}
              </span>
            ) : null}
          </button>
          <button
            type="button"
            onClick={() => setTab('templates')}
            className={`h-8 px-3.5 rounded-full text-xs cursor-pointer whitespace-nowrap transition-colors flex items-center gap-1.5 ${
              tab === 'templates' ? 'bg-primary-500 text-background-50 dark:text-foreground-950' : 'text-foreground-700 hover:bg-background-200'
            }`}
          >
            <i className="ri-mail-settings-line"></i>
            邮件模板
          </button>
        </div>
      </div>

      {notice ? (
        <div className="flex items-center gap-2 px-3 py-2.5 rounded-md bg-primary-50 text-primary-800 text-sm animate-fade-up">
          <i className="ri-checkbox-circle-line"></i>
          {notice}
        </div>
      ) : null}
      {error ? (
        <div className="flex items-center justify-between gap-3 px-3 py-2.5 rounded-md bg-accent-100 text-accent-900 text-sm">
          {error}
          <button type="button" onClick={load} className="text-xs underline cursor-pointer whitespace-nowrap">
            重试
          </button>
        </div>
      ) : null}

      {tab === 'inbox' ? (
        <>
          <div className="flex flex-wrap items-center gap-2">
            {['all', 'info', 'warn', 'error'].map((lv) => (
              <button
                key={lv}
                type="button"
                onClick={() => setLevelFilter(lv)}
                className={`h-8 px-3 rounded-full text-xs border cursor-pointer whitespace-nowrap transition-colors ${
                  levelFilter === lv
                    ? 'bg-primary-500 text-background-50 border-primary-500 dark:text-foreground-950'
                    : 'bg-background-50 text-foreground-700 border-background-300 hover:bg-background-100'
                }`}
              >
                {lv === 'all' ? '全部' : levelMeta[lv].label}
              </button>
            ))}
            <div className="ml-auto flex items-center gap-2">
              <button
                type="button"
                onClick={markAllRead}
                disabled={!canManage || unread === 0}
                className="h-9 px-3 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 disabled:opacity-40 cursor-pointer whitespace-nowrap"
              >
                全部已读
              </button>
              <button
                type="button"
                onClick={() => setComposeOpen(true)}
                disabled={!canManage}
                className="h-9 px-3.5 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 disabled:opacity-50 cursor-pointer whitespace-nowrap flex items-center gap-1.5 dark:text-foreground-950"
              >
                <i className="ri-add-line"></i>
                发布通知
              </button>
            </div>
          </div>

          <div className="rounded-lg bg-background-50 border border-background-200 divide-y divide-background-200">
            {loading ? (
              [0, 1, 2].map((n) => (
                <div key={n} className="p-4">
                  <div className="h-10 rounded-md bg-background-100 animate-pulse-soft" />
                </div>
              ))
            ) : filtered.length === 0 ? (
              <div className="py-16 text-center text-foreground-500">
                <i className="ri-mail-open-line text-2xl block mb-2"></i>
                暂无通知
              </div>
            ) : (
              filtered.map((row) => {
                const lv = levelMeta[row.level ?? 'info'] ?? levelMeta.info;
                return (
                  <div
                    key={row.id}
                    className={`flex items-start gap-3 p-4 ${row.is_read ? '' : 'bg-background-100/50'}`}
                  >
                    <span className={`mt-0.5 w-8 h-8 rounded-md flex items-center justify-center shrink-0 ${lv.tone}`}>
                      <i
                        className={`text-sm ${
                          row.level === 'error'
                            ? 'ri-error-warning-line'
                            : row.level === 'warn'
                              ? 'ri-alert-line'
                              : 'ri-information-line'
                        }`}
                      ></i>
                    </span>
                    <div className="min-w-0 flex-1">
                      <div className="flex items-center gap-2">
                        <p className="text-sm font-medium text-foreground-950">
                          {row.title}
                          {!row.is_read ? <span className="ml-1.5 w-1.5 h-1.5 rounded-full bg-accent-500 inline-block align-middle" /> : null}
                        </p>
                      </div>
                      {row.content ? (
                        <p className="mt-1 text-[13px] text-foreground-600 leading-relaxed">{row.content}</p>
                      ) : null}
                      <div className="mt-2 flex items-center gap-2 text-[11px] text-foreground-500">
                        <span className={`px-1.5 py-0.5 rounded-full ${lv.tone}`}>
                          {categoryLabel[row.category ?? 'system'] ?? row.category}
                        </span>
                        <span>{timeAgo(row.created_at)}</span>
                      </div>
                    </div>
                    <div className="flex items-center gap-1 shrink-0">
                      <button
                        type="button"
                        onClick={() => toggleRead(row)}
                        title={row.is_read ? '标为未读' : '标为已读'}
                        className="w-8 h-8 flex items-center justify-center rounded-md text-foreground-500 hover:bg-background-200 hover:text-foreground-900 cursor-pointer"
                      >
                        <i className={row.is_read ? 'ri-mail-unread-line' : 'ri-mail-check-line'}></i>
                      </button>
                      <button
                        type="button"
                        onClick={() => removeNotification(row)}
                        disabled={!canManage}
                        title="删除"
                        className="w-8 h-8 flex items-center justify-center rounded-md text-foreground-500 hover:bg-secondary-200 hover:text-secondary-900 disabled:opacity-40 cursor-pointer"
                      >
                        <i className="ri-delete-bin-line"></i>
                      </button>
                    </div>
                  </div>
                );
              })
            )}
          </div>
        </>
      ) : (
        <div className="grid grid-cols-1 xl:grid-cols-2 gap-4 items-start">
          {loading ? (
            [0, 1].map((n) => (
              <div key={n} className="h-44 rounded-lg bg-background-50 border border-background-200 animate-pulse-soft" />
            ))
          ) : (
            templates.map((tpl) => (
              <div key={tpl.id} className="rounded-lg bg-background-50 border border-background-200">
                <div className="flex items-center gap-2.5 px-4 md:px-5 py-3.5 border-b border-background-200">
                  <span className="w-8 h-8 rounded-md bg-accent-100 text-accent-900 flex items-center justify-center">
                    <i className="ri-mail-line text-sm"></i>
                  </span>
                  <div className="min-w-0">
                    <p className="text-sm font-semibold text-foreground-950 truncate">{tpl.name}</p>
                    <p className="text-[11px] text-foreground-400 font-label truncate">{tpl.code}</p>
                  </div>
                  <span
                    className={`ml-auto text-[10px] px-2 py-0.5 rounded-full ${
                      tpl.enabled ? 'bg-primary-100 text-primary-800' : 'bg-background-200 text-foreground-600'
                    }`}
                  >
                    {tpl.enabled ? '启用中' : '已停用'}
                  </span>
                </div>
                <div className="px-4 md:px-5 py-3.5 space-y-2">
                  <div>
                    <p className="text-[11px] text-foreground-400">邮件主题</p>
                    <p className="text-sm text-foreground-900 mt-0.5">{tpl.subject || '—'}</p>
                  </div>
                  <div>
                    <p className="text-[11px] text-foreground-400">正文模板</p>
                    <p className="text-[13px] text-foreground-600 mt-0.5 leading-relaxed line-clamp-3">{tpl.body || '—'}</p>
                  </div>
                </div>
                <div className="flex items-center justify-between gap-2 px-4 md:px-5 py-3 border-t border-background-200">
                  <button
                    type="button"
                    onClick={() => toggleTemplate(tpl)}
                    disabled={!canManage}
                    className="h-8 px-3 rounded-md bg-background-100 border border-background-300 text-xs text-foreground-800 hover:bg-background-200 disabled:opacity-40 cursor-pointer whitespace-nowrap"
                  >
                    {tpl.enabled ? '停用' : '启用'}
                  </button>
                  <button
                    type="button"
                    onClick={() => openEditTpl(tpl)}
                    disabled={!canManage}
                    className="h-8 px-3.5 rounded-md bg-primary-500 text-background-50 text-xs hover:bg-primary-600 disabled:opacity-50 cursor-pointer whitespace-nowrap dark:text-foreground-950"
                  >
                    <i className="ri-edit-line mr-1"></i>
                    编辑
                  </button>
                </div>
              </div>
            ))
          )}
        </div>
      )}

      <Modal
        open={composeOpen}
        title="发布通知"
        onClose={() => setComposeOpen(false)}
        footer={
          <>
            <button
              type="button"
              onClick={() => setComposeOpen(false)}
              className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
            >
              取消
            </button>
            <button
              type="button"
              onClick={submitCompose}
              className="h-9 px-4 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 cursor-pointer whitespace-nowrap dark:text-foreground-950"
            >
              发布
            </button>
          </>
        }
      >
        <div className="space-y-3.5">
          <div>
            <label className="block text-xs font-medium text-foreground-700 mb-1.5">标题</label>
            <input
              type="text"
              value={compose.title}
              onChange={(e) => setCompose((p) => ({ ...p, title: e.target.value }))}
              placeholder="通知标题"
              className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400"
            />
          </div>
          <div>
            <label className="block text-xs font-medium text-foreground-700 mb-1.5">内容</label>
            <textarea
              value={compose.content}
              onChange={(e) => setCompose((p) => ({ ...p, content: e.target.value }))}
              rows={4}
              maxLength={500}
              placeholder="通知正文(最多 500 字)"
              className="w-full px-3 py-2 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400 resize-none"
            />
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3.5">
            <div>
              <label className="block text-xs font-medium text-foreground-700 mb-1.5">分类</label>
              <select
                value={compose.category}
                onChange={(e) => setCompose((p) => ({ ...p, category: e.target.value }))}
                className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400 cursor-pointer"
              >
                {Object.entries(categoryLabel).map(([k, v]) => (
                  <option key={k} value={k}>
                    {v}
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-xs font-medium text-foreground-700 mb-1.5">级别</label>
              <select
                value={compose.level}
                onChange={(e) => setCompose((p) => ({ ...p, level: e.target.value }))}
                className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400 cursor-pointer"
              >
                <option value="info">提示</option>
                <option value="warn">警告</option>
                <option value="error">错误</option>
              </select>
            </div>
          </div>
          {composeError ? (
            <div className="flex items-start gap-2 px-3 py-2.5 rounded-md bg-accent-100 text-accent-900 text-xs">
              <i className="ri-error-warning-line mt-0.5"></i>
              <span>{composeError}</span>
            </div>
          ) : null}
        </div>
      </Modal>

      <Modal
        open={Boolean(editTpl)}
        title="编辑邮件模板"
        subtitle={editTpl?.code}
        onClose={() => setEditTpl(null)}
        width="max-w-2xl"
        footer={
          <>
            <button
              type="button"
              onClick={() => setEditTpl(null)}
              className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
            >
              取消
            </button>
            <button
              type="button"
              onClick={saveTpl}
              className="h-9 px-4 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 cursor-pointer whitespace-nowrap dark:text-foreground-950"
            >
              保存
            </button>
          </>
        }
      >
        <div className="space-y-3.5">
          <div>
            <label className="block text-xs font-medium text-foreground-700 mb-1.5">邮件主题</label>
            <input
              type="text"
              value={tplForm.subject}
              onChange={(e) => setTplForm((p) => ({ ...p, subject: e.target.value }))}
              className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400"
            />
          </div>
          <div>
            <label className="block text-xs font-medium text-foreground-700 mb-1.5">正文模板</label>
            <textarea
              value={tplForm.body}
              onChange={(e) => setTplForm((p) => ({ ...p, body: e.target.value }))}
              rows={8}
              maxLength={500}
              className="w-full px-3 py-2 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400 resize-none font-mono"
            />
            <p className="mt-1.5 text-[11px] text-foreground-500">
              支持 {'{{name}}'}、{'{'}{'{orderNo}}'} 等变量占位符
            </p>
          </div>
          <label className="flex items-center gap-2 text-sm text-foreground-800 cursor-pointer">
            <input
              type="checkbox"
              checked={tplForm.enabled}
              onChange={(e) => setTplForm((p) => ({ ...p, enabled: e.target.checked }))}
              className="w-4 h-4 accent-primary-500 cursor-pointer"
            />
            启用该模板
          </label>
        </div>
      </Modal>
    </div>
  );
}