import { useState } from 'react';
import type { DragEvent } from 'react';
import BlockPreview from '@/pages/builder/components/BlockPreview';
import type { BuilderBlock } from '@/pages/builder/types';

interface CanvasProps {
  blocks: BuilderBlock[];
  selectedId: string | null;
  onSelect: (id: string | null) => void;
  onChange: (blocks: BuilderBlock[]) => void;
  onDropFromPalette: (type: string) => void;
}

export default function Canvas({
  blocks,
  selectedId,
  onSelect,
  onChange,
  onDropFromPalette,
}: CanvasProps) {
  const [dragIndex, setDragIndex] = useState<number | null>(null);
  const [overIndex, setOverIndex] = useState<number | null>(null);
  const [canvasHover, setCanvasHover] = useState(false);

  const handleDrop = (e: DragEvent) => {
    e.preventDefault();
    setCanvasHover(false);
    const raw = e.dataTransfer.getData('application/x-builder');
    if (!raw) return;
    try {
      const payload = JSON.parse(raw) as { source: string; type?: string; index?: number };
      if (payload.source === 'palette' && payload.type) {
        onDropFromPalette(payload.type);
        return;
      }
      if (payload.source === 'canvas' && typeof payload.index === 'number') {
        const from = payload.index;
        const to = blocks.length - 1;
        if (from === to) return;
        const next = [...blocks];
        const [moved] = next.splice(from, 1);
        next.splice(to, 0, moved);
        onChange(next);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setDragIndex(null);
      setOverIndex(null);
    }
  };

  const dropOnBlock = (e: DragEvent, targetIndex: number) => {
    e.preventDefault();
    e.stopPropagation();
    const raw = e.dataTransfer.getData('application/x-builder');
    setOverIndex(null);
    if (!raw) return;
    try {
      const payload = JSON.parse(raw) as { source: string; type?: string; index?: number };
      if (payload.source === 'canvas' && typeof payload.index === 'number') {
        const from = payload.index;
        if (from === targetIndex) return;
        const next = [...blocks];
        const [moved] = next.splice(from, 1);
        next.splice(targetIndex, 0, moved);
        onChange(next);
      } else if (payload.source === 'palette' && payload.type) {
        onDropFromPalette(payload.type, targetIndex);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setDragIndex(null);
    }
  };

  const move = (index: number, dir: -1 | 1) => {
    const target = index + dir;
    if (target < 0 || target >= blocks.length) return;
    const next = [...blocks];
    [next[index], next[target]] = [next[target], next[index]];
    onChange(next);
  };

  const remove = (id: string) => {
    onChange(blocks.filter((b) => b.id !== id));
    if (selectedId === id) onSelect(null);
  };

  const duplicate = (index: number) => {
    const src = blocks[index];
    const copy: BuilderBlock = {
      ...src,
      id: `b_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      props: { ...src.props },
    };
    const next = [...blocks];
    next.splice(index + 1, 0, copy);
    onChange(next);
    onSelect(copy.id);
  };

  return (
    <section
      className={`flex-1 min-w-0 rounded-lg border bg-background-100 transition-colors ${
        canvasHover ? 'border-primary-400 bg-primary-50/40' : 'border-background-200'
      }`}
      onDragOver={(e) => {
        e.preventDefault();
        setCanvasHover(true);
      }}
      onDragLeave={() => setCanvasHover(false)}
      onDrop={handleDrop}
    >
      <div className="flex items-center gap-2 px-4 py-3 border-b border-background-200 bg-background-50 rounded-t-lg">
        <i className="ri-layout-4-line text-foreground-500 text-sm"></i>
        <span className="text-sm font-medium text-foreground-900">页面画布</span>
        <span className="text-[11px] px-1.5 py-0.5 rounded-full bg-background-100 text-foreground-500 font-label">
          {blocks.length} 个组件
        </span>
        <span className="ml-auto text-[11px] text-foreground-400 hidden sm:block">1200px 桌面端预览</span>
      </div>

      <div className="p-4 md:p-6 min-h-[520px]">
        {blocks.length === 0 ? (
          <div
            className={`flex flex-col items-center justify-center h-[460px] rounded-lg border-2 border-dashed ${
              canvasHover ? 'border-primary-400 text-primary-600' : 'border-background-300 text-foreground-400'
            }`}
          >
            <i className="ri-drag-drop-line text-4xl mb-3"></i>
            <p className="text-sm">从左侧拖拽组件到这里</p>
            <p className="text-[11px] mt-1">或点击组件卡片快速添加</p>
          </div>
        ) : (
          <div className="mx-auto max-w-[720px] rounded-lg bg-background-50 border border-background-200 p-5 md:p-7 space-y-4">
            {blocks.map((block, index) => {
              const active = block.id === selectedId;
              return (
                <div
                  key={block.id}
                  draggable
                  onDragStart={(e) => {
                    e.dataTransfer.setData(
                      'application/x-builder',
                      JSON.stringify({ source: 'canvas', index }),
                    );
                    e.dataTransfer.effectAllowed = 'move';
                    setDragIndex(index);
                  }}
                  onDragEnd={() => setDragIndex(null)}
                  onDragOver={(e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    setOverIndex(index);
                  }}
                  onDrop={(e) => dropOnBlock(e, index)}
                  onClick={() => onSelect(block.id)}
                  className={`group relative rounded-md transition-colors cursor-pointer ${
                    dragIndex === index ? 'opacity-40' : ''
                  } ${active ? 'ring-2 ring-primary-500 ring-offset-2 ring-offset-background-50' : ''}`}
                >
                  <span
                    className={`absolute -top-2 -left-2 z-10 w-5 h-5 rounded-full bg-primary-500 text-background-50 text-[10px] flex items-center justify-center font-label opacity-0 group-hover:opacity-100 ${
                      active ? 'opacity-100' : ''
                    }`}
                  >
                    {index + 1}
                  </span>

                  <div className="rounded-md px-3 py-2 hover:bg-background-100/70">
                    <BlockPreview block={block} />
                  </div>

                  <div className="absolute top-1 right-1 flex items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
                    <button
                      type="button"
                      onClick={(e) => {
                        e.stopPropagation();
                        move(index, -1);
                      }}
                      className="w-6 h-6 rounded-md bg-background-50 border border-background-200 text-foreground-500 hover:text-foreground-900 flex items-center justify-center cursor-pointer"
                      aria-label="上移"
                    >
                      <i className="ri-arrow-up-s-line text-sm"></i>
                    </button>
                    <button
                      type="button"
                      onClick={(e) => {
                        e.stopPropagation();
                        move(index, 1);
                      }}
                      className="w-6 h-6 rounded-md bg-background-50 border border-background-200 text-foreground-500 hover:text-foreground-900 flex items-center justify-center cursor-pointer"
                      aria-label="下移"
                    >
                      <i className="ri-arrow-down-s-line text-sm"></i>
                    </button>
                    <button
                      type="button"
                      onClick={(e) => {
                        e.stopPropagation();
                        duplicate(index);
                      }}
                      className="w-6 h-6 rounded-md bg-background-50 border border-background-200 text-foreground-500 hover:text-foreground-900 flex items-center justify-center cursor-pointer"
                      aria-label="复制"
                    >
                      <i className="ri-file-copy-line text-xs"></i>
                    </button>
                    <button
                      type="button"
                      onClick={(e) => {
                        e.stopPropagation();
                        remove(block.id);
                      }}
                      className="w-6 h-6 rounded-md bg-background-50 border border-background-200 text-foreground-500 hover:text-secondary-800 flex items-center justify-center cursor-pointer"
                      aria-label="删除"
                    >
                      <i className="ri-delete-bin-line text-xs"></i>
                    </button>
                  </div>

                  {overIndex === index && dragIndex !== index ? (
                    <span className="absolute -top-2 left-0 right-0 h-0.5 rounded-full bg-primary-500" />
                  ) : null}
                </div>
              );
            })}
          </div>
        )}
      </div>
    </section>
  );
}