import { supabase } from '@/lib/supabase';

export interface DebugCase {
  id: string;
  name: string;
  endpoint_code: string;
  method: string | null;
  path: string | null;
  resource: string | null;
  action: string | null;
  path_params: Record<string, string> | null;
  query_params: Record<string, string> | null;
  body: string | null;
  tags: string[] | null;
  created_at: string | null;
}

export interface SaveDebugCaseInput {
  name: string;
  endpointCode: string;
  method: string;
  path: string;
  resource: string;
  action: string;
  pathParams: Record<string, string>;
  queryParams: Record<string, string>;
  body: string;
  tags?: string[];
}

/** Normalize a tag input (array or "a,b c" string) into a de-duplicated clean list. */
export function normalizeTags(input: unknown): string[] {
  if (Array.isArray(input)) {
    return Array.from(new Set(input.map((t) => String(t).trim()).filter(Boolean)));
  }
  if (typeof input === 'string') {
    return Array.from(new Set(input.split(/[,，、\s]+/).map((t) => t.trim()).filter(Boolean)));
  }
  return [];
}

export async function fetchDebugCases(endpointCode?: string): Promise<DebugCase[]> {
  let query = supabase
    .from('api_debug_cases')
    .select('*')
    .order('created_at', { ascending: false });
  if (endpointCode) query = query.eq('endpoint_code', endpointCode);
  const { data, error } = await query;
  if (error) throw error;
  return (data as DebugCase[]) ?? [];
}

export async function saveDebugCase(input: SaveDebugCaseInput): Promise<void> {
  const { data: authData } = await supabase.auth.getUser();
  const { error } = await supabase.from('api_debug_cases').insert({
    name: input.name.trim(),
    endpoint_code: input.endpointCode,
    method: input.method,
    path: input.path,
    resource: input.resource,
    action: input.action,
    path_params: input.pathParams,
    query_params: input.queryParams,
    body: input.body.trim() || null,
    tags: normalizeTags(input.tags),
    created_by: authData.user?.id ?? null,
  });
  if (error) throw error;
}

export async function deleteDebugCase(id: string): Promise<void> {
  const { error } = await supabase.from('api_debug_cases').delete().eq('id', id);
  if (error) throw error;
}

/** Bulk insert debug cases, e.g. after importing a shared JSON file. */
export async function importDebugCases(list: SaveDebugCaseInput[]): Promise<void> {
  if (list.length === 0) return;
  const { data: authData } = await supabase.auth.getUser();
  const rows = list.map((input) => ({
    name: input.name.trim(),
    endpoint_code: input.endpointCode,
    method: input.method,
    path: input.path,
    resource: input.resource,
    action: input.action,
    path_params: input.pathParams,
    query_params: input.queryParams,
    body: input.body.trim() || null,
    tags: normalizeTags(input.tags),
    created_by: authData.user?.id ?? null,
  }));
  const { error } = await supabase.from('api_debug_cases').insert(rows);
  if (error) throw error;
}