import { useState } from 'react';

interface CodeBlockProps {
  code: string;
  language?: string;
  filename?: string;
  className?: string;
}

export default function CodeBlock({ code, language = 'bash', filename, className = '' }: CodeBlockProps) {
  const [copied, setCopied] = useState(false);

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(code);
      setCopied(true);
      window.setTimeout(() => setCopied(false), 1600);
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div className={`rounded-lg overflow-hidden border border-foreground-800/40 bg-foreground-950 ${className}`}>
      <div className="flex items-center gap-2 px-3.5 py-2 bg-foreground-900/80 border-b border-foreground-800/50">
        <span className="flex items-center gap-1.5">
          <span className="w-2.5 h-2.5 rounded-full bg-accent-500/80" />
          <span className="w-2.5 h-2.5 rounded-full bg-primary-400/70" />
          <span className="w-2.5 h-2.5 rounded-full bg-secondary-400/70" />
        </span>
        <span className="ml-1 text-[11px] font-label text-background-300 truncate">
          {filename ?? language}
        </span>
        <button
          type="button"
          onClick={handleCopy}
          className="ml-auto inline-flex items-center gap-1 h-7 px-2 rounded-md text-[11px] text-background-200 hover:bg-foreground-800 hover:text-background-50 cursor-pointer whitespace-nowrap transition-colors"
        >
          <i className={copied ? 'ri-check-line text-primary-300' : 'ri-file-copy-line'}></i>
          {copied ? '已复制' : '复制'}
        </button>
      </div>
      <pre className="px-4 py-3.5 overflow-x-auto">
        <code className="font-label text-[12.5px] leading-relaxed text-background-100 whitespace-pre">
          {code}
        </code>
      </pre>
    </div>
  );
}