import { useCallback, useEffect, useMemo, useState } from 'react';
import { supabase } from '@/lib/supabase';
import { useAuth } from '@/contexts/AuthContext';
import type { SystemSettingRow } from '@/pages/settings/system/types';

const categoryIcon: Record<string, string> = {
  兼容性: 'ri-swap-box-line',
  连接池: 'ri-link-m',
  字符集与事务: 'ri-translate-2',
  运行环境: 'ri-server-line',
};

export default function DbCompatCard() {
  const { roleCodes } = useAuth();
  const canManage = roleCodes.includes('super_admin');

  const [settings, setSettings] = useState<SystemSettingRow[]>([]);
  const [draft, setDraft] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const [saving, setSaving] = useState(false);

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const { data, error: err } = await supabase
        .from('system_settings')
        .select('*')
        .order('sort_order', { ascending: true });
      if (err) throw err;
      const rows = (data as SystemSettingRow[]) ?? [];
      setSettings(rows);
      const nextDraft: Record<string, string> = {};
      rows.forEach((r) => {
        nextDraft[r.config_key] = r.value ?? '';
      });
      setDraft(nextDraft);
    } catch (err) {
      console.error(err);
      setError('加载数据库配置失败,请重试');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  useEffect(() => {
    if (!notice) return;
    const timer = setTimeout(() => setNotice(''), 2600);
    return () => clearTimeout(timer);
  }, [notice]);

  const categories = useMemo(() => {
    const order: string[] = [];
    settings.forEach((s) => {
      if (!order.includes(s.category)) order.push(s.category);
    });
    return order;
  }, [settings]);

  const dirty = useMemo(
    () => settings.filter((s) => (draft[s.config_key] ?? '') !== (s.value ?? '')),
    [settings, draft],
  );

  const save = async () => {
    if (dirty.length === 0) return;
    setSaving(true);
    setError('');
    try {
      await Promise.all(
        dirty.map((row) =>
          supabase
            .from('system_settings')
            .update({ value: draft[row.config_key], updated_at: new Date().toISOString() })
            .eq('id', row.id),
        ),
      );
      setSettings((prev) =>
        prev.map((r) =>
          draft[r.config_key] !== (r.value ?? '') ? { ...r, value: draft[r.config_key] } : r,
        ),
      );
      setNotice('数据库兼容配置已保存');
    } catch (err) {
      console.error(err);
      setError('保存失败,请检查权限后重试');
    } finally {
      setSaving(false);
    }
  };

  const reset = () => {
    const next: Record<string, string> = {};
    settings.forEach((r) => {
      next[r.config_key] = r.value ?? '';
    });
    setDraft(next);
  };

  const renderControl = (row: SystemSettingRow) => {
    const value = draft[row.config_key] ?? '';
    const onChange = (v: string) => setDraft((p) => ({ ...p, [row.config_key]: v }));
    const disabled = !canManage || !row.editable;

    if (row.value_type === 'switch') {
      const on = value === 'on';
      return (
        <button
          type="button"
          onClick={() => onChange(on ? 'off' : 'on')}
          disabled={disabled}
          className={`relative w-11 h-6 rounded-full transition-colors disabled:opacity-50 cursor-pointer ${
            on ? 'bg-primary-500' : 'bg-background-300'
          }`}
          aria-label={row.label}
        >
          <span
            className={`absolute top-0.5 w-5 h-5 rounded-full bg-background-50 transition-all ${
              on ? 'left-[22px]' : 'left-0.5'
            }`}
          />
        </button>
      );
    }

    if (row.value_type === 'select') {
      return (
        <select
          value={value}
          onChange={(e) => onChange(e.target.value)}
          disabled={disabled}
          className="h-9 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400 disabled:opacity-60 cursor-pointer font-label min-w-[140px]"
        >
          {(row.options ?? []).map((opt) => (
            <option key={opt} value={opt}>
              {opt}
            </option>
          ))}
        </select>
      );
    }

    return (
      <input
        type={row.value_type === 'number' ? 'number' : 'text'}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        disabled={disabled}
        className="w-40 h-9 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400 disabled:opacity-60 font-label"
      />
    );
  };

  return (
    <div className="rounded-lg bg-background-50 border border-background-200">
      <div className="flex items-center justify-between gap-3 px-4 md:px-5 py-3.5 border-b border-background-200">
        <div className="flex items-center gap-2.5">
          <span className="w-9 h-9 rounded-md bg-primary-100 text-primary-700 flex items-center justify-center">
            <i className="ri-database-2-line text-lg"></i>
          </span>
          <div>
            <h3 className="text-sm font-semibold text-foreground-950">数据库兼容配置</h3>
            <p className="text-xs text-foreground-500">方言、连接池、字符集与事务策略</p>
          </div>
        </div>
        {canManage ? (
          <span className="hidden sm:inline-flex items-center gap-1 text-[11px] px-2 py-0.5 rounded-full bg-primary-100 text-primary-800">
            <i className="ri-edit-line"></i>
            可编辑
          </span>
        ) : (
          <span className="hidden sm:inline-flex items-center gap-1 text-[11px] px-2 py-0.5 rounded-full bg-secondary-100 text-secondary-900">
            <i className="ri-eye-line"></i>
            只读
          </span>
        )}
      </div>

      {notice ? (
        <div className="mx-4 md:mx-5 mt-3.5 flex items-center gap-2 px-3 py-2 rounded-md bg-primary-50 text-primary-800 text-sm animate-fade-up">
          <i className="ri-checkbox-circle-line"></i>
          {notice}
        </div>
      ) : null}
      {error ? (
        <div className="mx-4 md:mx-5 mt-3.5 flex items-center justify-between gap-3 px-3 py-2 rounded-md bg-accent-100 text-accent-900 text-sm">
          {error}
          <button type="button" onClick={load} className="text-xs underline cursor-pointer whitespace-nowrap">
            重试
          </button>
        </div>
      ) : null}

      {loading ? (
        <div className="p-4 md:p-5 space-y-2.5">
          {[0, 1, 2, 3, 4].map((n) => (
            <div key={n} className="h-12 rounded-md bg-background-100 animate-pulse-soft" />
          ))}
        </div>
      ) : (
        <div className="p-4 md:p-5 space-y-5">
          {categories.map((cat) => (
            <div key={cat}>
              <div className="flex items-center gap-1.5 mb-2">
                <i className={`${categoryIcon[cat] ?? 'ri-settings-4-line'} text-[13px] text-foreground-400`}></i>
                <span className="text-[11px] font-medium text-foreground-400">{cat}</span>
              </div>
              <div className="rounded-md border border-background-200 divide-y divide-background-200">
                {settings
                  .filter((s) => s.category === cat)
                  .map((row) => (
                    <div key={row.id} className="flex flex-col sm:flex-row sm:items-center gap-2 px-3.5 py-3">
                      <div className="min-w-0 flex-1">
                        <p className="text-sm text-foreground-900">{row.label}</p>
                        <p className="text-[11px] text-foreground-500 mt-0.5">
                          {row.description}
                          <span className="ml-2 font-label text-foreground-400">{row.config_key}</span>
                        </p>
                      </div>
                      <div className="shrink-0">{renderControl(row)}</div>
                    </div>
                  ))}
              </div>
            </div>
          ))}
        </div>
      )}

      {canManage ? (
        <div className="flex items-center justify-end gap-2 px-4 md:px-5 py-3.5 border-t border-background-200">
          {dirty.length > 0 ? (
            <span className="mr-auto text-xs text-accent-700">
              {dirty.length} 项待保存
            </span>
          ) : null}
          <button
            type="button"
            onClick={reset}
            disabled={dirty.length === 0}
            className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 disabled:opacity-50 cursor-pointer whitespace-nowrap"
          >
            重置
          </button>
          <button
            type="button"
            onClick={save}
            disabled={dirty.length === 0 || saving}
            className="h-9 px-4 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 disabled:opacity-50 cursor-pointer whitespace-nowrap dark:text-foreground-950"
          >
            {saving ? '保存中…' : '保存配置'}
          </button>
        </div>
      ) : null}
    </div>
  );
}