import { useCallback, useEffect, useMemo, useState } from 'react';
import { Link, useParams } from 'react-router-dom';
import { supabase } from '@/lib/supabase';
import { useAuth } from '@/contexts/AuthContext';
import Modal from '@/components/base/Modal';
import type { GenColumn, GenOps } from '@/hooks/useGeneratedPages';

interface PageConfig {
  slug: string;
  title: string;
  table_name: string;
  icon: string | null;
  columns: GenColumn[];
  ops: GenOps;
  permission_code: string | null;
}

type Row = Record<string, unknown>;

function inputType(col: GenColumn) {
  if (col.type === 'number') return 'number';
  if (col.type === 'date') return 'datetime-local';
  return 'text';
}

/** 运行时动态管理页:根据注册表里的配置,对目标表做通用增删改查。 */
export default function DynamicCrudPage() {
  const { slug } = useParams<{ slug: string }>();
  const { hasPermission } = useAuth();

  const [config, setConfig] = useState<PageConfig | null>(null);
  const [configLoading, setConfigLoading] = useState(true);
  const [error, setError] = useState('');

  const [rows, setRows] = useState<Row[]>([]);
  const [loading, setLoading] = useState(true);
  const [keyword, setKeyword] = useState('');
  const [notice, setNotice] = useState('');

  const [formOpen, setFormOpen] = useState(false);
  const [editing, setEditing] = useState<Row | null>(null);
  const [form, setForm] = useState<Record<string, string>>({});
  const [saving, setSaving] = useState(false);
  const [formError, setFormError] = useState('');
  const [deleteTarget, setDeleteTarget] = useState<Row | null>(null);

  // 列排序与分页:数据量较大时更易用
  const [sortCol, setSortCol] = useState<string | null>(null);
  const [sortDir, setSortDir] = useState<'asc' | 'desc'>('asc');
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(10);

  // 加载页面配置
  const loadConfig = useCallback(async () => {
    if (!slug) return;
    setConfigLoading(true);
    setError('');
    try {
      const { data, error: err } = await supabase
        .from('generated_pages')
        .select('*')
        .eq('slug', slug)
        .maybeSingle();
      if (err) throw err;
      if (!data) {
        setConfig(null);
        setError('该动态页面不存在或已下线');
        return;
      }
      setConfig(data as PageConfig);
    } catch (e) {
      console.error(e);
      setError('加载页面配置失败');
    } finally {
      setConfigLoading(false);
    }
  }, [slug]);

  useEffect(() => {
    loadConfig();
  }, [loadConfig]);

  const tableName = config?.table_name ?? '';
  const columns = useMemo(() => config?.columns ?? [], [config]);
  const ops = useMemo<GenOps>(() => config?.ops ?? {}, [config]);
  const primary = useMemo(() => columns.find((c) => c.primary) ?? columns[0], [columns]);
  const displayCols = useMemo(() => columns.filter((c) => !c.primary), [columns]);
  const editableCols = useMemo(
    () => columns.filter((c) => !c.primary && c.name !== 'created_at'),
    [columns],
  );

  const canCreate = Boolean(config) && hasPermission(`${tableName}:create`);
  const canUpdate = Boolean(config) && hasPermission(`${tableName}:update`);
  const canDelete = Boolean(config) && hasPermission(`${tableName}:delete`);

  // 加载数据
  const load = useCallback(async () => {
    if (!tableName) return;
    setLoading(true);
    setError('');
    try {
      let q = supabase.from(tableName).select('*');
      q = q.order('created_at', { ascending: false });
      const { data, error: err } = await q;
      if (err) {
        // 目标表没有 created_at 时降级为无序查询
        const fallback = await supabase.from(tableName).select('*');
        if (fallback.error) throw fallback.error;
        setRows((fallback.data as Row[]) ?? []);
      } else {
        setRows((data as Row[]) ?? []);
      }
    } catch (e) {
      console.error(e);
      setError('数据加载失败,请重试');
    } finally {
      setLoading(false);
    }
  }, [tableName]);

  useEffect(() => {
    if (tableName) load();
  }, [tableName, load]);

  useEffect(() => {
    if (!notice) return;
    const timer = setTimeout(() => setNotice(''), 2600);
    return () => clearTimeout(timer);
  }, [notice]);

  const filtered = useMemo(() => {
    const kw = keyword.trim().toLowerCase();
    if (!kw) return rows;
    return rows.filter((r) =>
      displayCols.some((c) => String(r[c.name] ?? '').toLowerCase().includes(kw)),
    );
  }, [rows, keyword, displayCols]);

  // 按选中的列排序(数字列按数值比较,其余按字符串本地化比较)
  const sortedRows = useMemo(() => {
    if (!sortCol) return filtered;
    const arr = [...filtered];
    arr.sort((a, b) => {
      const va = a[sortCol];
      const vb = b[sortCol];
      const na = va === null || va === undefined || va === '' ? null : Number(va);
      const nb = vb === null || vb === undefined || vb === '' ? null : Number(vb);
      let cmp: number;
      if (na !== null && nb !== null && !Number.isNaN(na) && !Number.isNaN(nb)) {
        cmp = na - nb;
      } else {
        cmp = String(va ?? '').localeCompare(String(vb ?? ''), 'zh-Hans-CN');
      }
      return sortDir === 'asc' ? cmp : -cmp;
    });
    return arr;
  }, [filtered, sortCol, sortDir]);

  const totalPages = Math.max(1, Math.ceil(sortedRows.length / pageSize));
  const currentPage = Math.min(page, totalPages);
  const pagedRows = useMemo(
    () => sortedRows.slice((currentPage - 1) * pageSize, currentPage * pageSize),
    [sortedRows, currentPage, pageSize],
  );

  // 搜索或切换每页条数时回到第一页,避免落在空白页
  useEffect(() => {
    setPage(1);
  }, [keyword, pageSize, tableName]);

  const toggleSort = (name: string) => {
    if (sortCol === name) {
      setSortDir((d) => (d === 'asc' ? 'desc' : 'asc'));
    } else {
      setSortCol(name);
      setSortDir('asc');
    }
  };

  const openCreate = () => {
    setEditing(null);
    setForm({});
    setFormError('');
    setFormOpen(true);
  };

  const openEdit = (row: Row) => {
    setEditing(row);
    const next: Record<string, string> = {};
    editableCols.forEach((c) => {
      next[c.name] = String(row[c.name] ?? '');
    });
    setForm(next);
    setFormError('');
    setFormOpen(true);
  };

  const buildPayload = () => {
    const payload: Record<string, unknown> = {};
    editableCols.forEach((c) => {
      const raw = (form[c.name] ?? '').trim();
      if (c.type === 'number') payload[c.name] = raw === '' ? null : Number(raw);
      else if (c.type === 'boolean') payload[c.name] = raw === 'true';
      else payload[c.name] = raw === '' ? null : raw;
    });
    return payload;
  };

  const handleSubmit = async () => {
    if (!primary) return;
    setSaving(true);
    setFormError('');
    try {
      const payload = buildPayload();
      if (editing) {
        const { error: err } = await supabase
          .from(tableName)
          .update(payload)
          .eq(primary.name, editing[primary.name] as never);
        if (err) throw err;
        setNotice('已保存修改');
      } else {
        const { error: err } = await supabase.from(tableName).insert(payload);
        if (err) throw err;
        setNotice('新增成功');
      }
      setFormOpen(false);
      await load();
    } catch (e) {
      console.error(e);
      setFormError('保存失败,请检查权限后重试');
    } finally {
      setSaving(false);
    }
  };

  const confirmDelete = async () => {
    if (!deleteTarget || !primary) return;
    try {
      const { error: err } = await supabase
        .from(tableName)
        .delete()
        .eq(primary.name, deleteTarget[primary.name] as never);
      if (err) throw err;
      setNotice('已删除');
      setDeleteTarget(null);
      await load();
    } catch (e) {
      console.error(e);
      setError('删除失败,可能权限不足');
      setDeleteTarget(null);
    }
  };

  if (configLoading) {
    return (
      <div className="space-y-3">
        <div className="h-9 w-48 rounded-md bg-background-100 animate-pulse-soft" />
        <div className="h-64 rounded-lg bg-background-50 border border-background-200 animate-pulse-soft" />
      </div>
    );
  }

  if (!config) {
    return (
      <div className="rounded-lg bg-background-50 border border-background-200 py-20 text-center">
        <i className="ri-ghost-2-line text-3xl text-foreground-400 block mb-2"></i>
        <p className="text-sm text-foreground-600">{error || '页面不存在'}</p>
        <Link
          to="/generator"
          className="inline-flex items-center gap-1.5 mt-3 h-9 px-4 rounded-md bg-primary-500 text-background-50 text-sm cursor-pointer whitespace-nowrap dark:text-foreground-950"
        >
          <i className="ri-arrow-left-line"></i>
          返回代码生成器
        </Link>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex flex-col md:flex-row md:items-center gap-3">
        <div className="flex items-center gap-2.5">
          <span className="w-9 h-9 rounded-lg bg-primary-100 text-primary-700 flex items-center justify-center">
            <i className={`${config.icon || 'ri-layout-4-line'} text-lg`}></i>
          </span>
          <div>
            <h2 className="text-lg font-semibold text-foreground-950 flex items-center gap-2">
              {config.title}
              <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-secondary-100 text-secondary-900">
                运行时生成
              </span>
            </h2>
            <p className="text-xs text-foreground-500">
              数据表 <span className="font-label">{config.table_name}</span> · 路由 /generated/{config.slug}
            </p>
          </div>
        </div>
        <div className="md:ml-auto flex flex-wrap items-center gap-2">
          {ops.search ? (
            <div className="flex items-center gap-2 h-9 px-3 rounded-md bg-background-50 border border-background-200 w-full sm:w-56">
              <i className="ri-search-line text-foreground-400 text-sm"></i>
              <input
                type="text"
                value={keyword}
                onChange={(e) => setKeyword(e.target.value)}
                placeholder="搜索…"
                className="flex-1 bg-transparent text-sm text-foreground-900 placeholder:text-foreground-400 focus:outline-none"
              />
            </div>
          ) : null}
          {ops.create ? (
            <button
              type="button"
              onClick={openCreate}
              disabled={!canCreate}
              className="h-9 px-3.5 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 disabled:opacity-50 cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5 dark:text-foreground-950"
            >
              <i className="ri-add-line"></i>
              新增
            </button>
          ) : null}
        </div>
      </div>

      {notice ? (
        <div className="flex items-center gap-2 px-3 py-2.5 rounded-md bg-primary-50 text-primary-800 text-sm animate-fade-up">
          <i className="ri-checkbox-circle-line"></i>
          {notice}
        </div>
      ) : null}
      {error ? (
        <div className="flex items-center justify-between gap-3 px-3 py-2.5 rounded-md bg-accent-100 text-accent-900 text-sm">
          {error}
          <button type="button" onClick={load} className="text-xs underline cursor-pointer whitespace-nowrap">
            重试
          </button>
        </div>
      ) : null}

      <div className="rounded-lg bg-background-50 border border-background-200 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full min-w-[720px] text-sm">
            <thead>
              <tr className="bg-background-100 text-left text-xs text-foreground-500">
                {displayCols.map((c) => (
                  <th key={c.name} className="px-4 py-3 font-medium">
                    <button
                      type="button"
                      onClick={() => toggleSort(c.name)}
                      title={`按「${c.label}」排序`}
                      className={`inline-flex items-center gap-1 cursor-pointer whitespace-nowrap hover:text-foreground-900 ${
                        sortCol === c.name ? 'text-foreground-900 font-semibold' : ''
                      }`}
                    >
                      {c.label}
                      <i
                        className={`text-[13px] ${
                          sortCol === c.name
                            ? sortDir === 'asc'
                              ? 'ri-arrow-up-line text-primary-600'
                              : 'ri-arrow-down-line text-primary-600'
                            : 'ri-arrow-up-down-line text-foreground-400'
                        }`}
                      ></i>
                    </button>
                  </th>
                ))}
                {ops.update || ops.delete ? (
                  <th className="px-4 py-3 font-medium text-right">操作</th>
                ) : null}
              </tr>
            </thead>
            <tbody>
              {loading ? (
                [0, 1, 2, 3].map((n) => (
                  <tr key={n} className="border-t border-background-200">
                    <td colSpan={displayCols.length + 1} className="px-4 py-3">
                      <div className="h-8 rounded-md bg-background-100 animate-pulse-soft" />
                    </td>
                  </tr>
                ))
              ) : filtered.length === 0 ? (
                <tr className="border-t border-background-200">
                  <td
                    colSpan={displayCols.length + 1}
                    className="px-4 py-14 text-center text-foreground-500"
                  >
                    <i className="ri-inbox-line text-2xl block mb-2"></i>
                    暂无数据
                  </td>
                </tr>
              ) : (
                pagedRows.map((row) => (
                  <tr
                    key={String(row[primary?.name ?? 'id'])}
                    className="border-t border-background-200 hover:bg-background-100/60"
                  >
                    {displayCols.map((c) => (
                      <td key={c.name} className="px-4 py-3 text-foreground-800">
                        {String(row[c.name] ?? '—')}
                      </td>
                    ))}
                    {ops.update || ops.delete ? (
                      <td className="px-4 py-3">
                        <div className="flex items-center justify-end gap-1">
                          {ops.update ? (
                            <button
                              type="button"
                              onClick={() => openEdit(row)}
                              disabled={!canUpdate}
                              title="编辑"
                              className="w-8 h-8 flex items-center justify-center rounded-md text-foreground-500 hover:bg-background-200 hover:text-foreground-900 disabled:opacity-40 cursor-pointer"
                            >
                              <i className="ri-pencil-line"></i>
                            </button>
                          ) : null}
                          {ops.delete ? (
                            <button
                              type="button"
                              onClick={() => setDeleteTarget(row)}
                              disabled={!canDelete}
                              title="删除"
                              className="w-8 h-8 flex items-center justify-center rounded-md text-foreground-500 hover:bg-secondary-200 hover:text-secondary-900 disabled:opacity-40 cursor-pointer"
                            >
                              <i className="ri-delete-bin-line"></i>
                            </button>
                          ) : null}
                        </div>
                      </td>
                    ) : null}
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
        {!loading && sortedRows.length > 0 ? (
          <div className="flex flex-col sm:flex-row sm:items-center gap-3 px-4 py-3 border-t border-background-200">
            <span className="text-xs text-foreground-500">
              共 <span className="font-label font-semibold text-foreground-900">{sortedRows.length}</span> 条 · 第{' '}
              {currentPage} / {totalPages} 页
            </span>
            <div className="sm:ml-auto flex flex-wrap items-center gap-2">
              <select
                value={pageSize}
                onChange={(e) => setPageSize(Number(e.target.value))}
                className="h-8 px-2 rounded-md bg-background-50 border border-background-200 text-xs text-foreground-800 focus:outline-none cursor-pointer"
              >
                {[10, 20, 50, 100].map((n) => (
                  <option key={n} value={n}>
                    每页 {n} 条
                  </option>
                ))}
              </select>
              <button
                type="button"
                onClick={() => setPage((p) => Math.max(1, p - 1))}
                disabled={currentPage <= 1}
                className="h-8 px-3 rounded-md bg-background-100 border border-background-300 text-xs text-foreground-800 hover:bg-background-200 disabled:opacity-40 cursor-pointer whitespace-nowrap inline-flex items-center gap-1"
              >
                <i className="ri-arrow-left-s-line"></i>
                上一页
              </button>
              <button
                type="button"
                onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
                disabled={currentPage >= totalPages}
                className="h-8 px-3 rounded-md bg-background-100 border border-background-300 text-xs text-foreground-800 hover:bg-background-200 disabled:opacity-40 cursor-pointer whitespace-nowrap inline-flex items-center gap-1"
              >
                下一页
                <i className="ri-arrow-right-s-line"></i>
              </button>
            </div>
          </div>
        ) : null}
      </div>

      <Modal
        open={formOpen}
        title={editing ? `编辑${config.title}` : `新增${config.title}`}
        onClose={() => setFormOpen(false)}
        footer={
          <>
            <button
              type="button"
              onClick={() => setFormOpen(false)}
              className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
            >
              取消
            </button>
            <button
              type="button"
              onClick={handleSubmit}
              disabled={saving}
              className="h-9 px-4 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 disabled:opacity-60 cursor-pointer whitespace-nowrap dark:text-foreground-950"
            >
              {saving ? '保存中…' : '保存'}
            </button>
          </>
        }
      >
        <div className="space-y-3.5">
          {editableCols.map((c) => (
            <div key={c.name}>
              <label className="block text-xs font-medium text-foreground-700 mb-1.5">{c.label}</label>
              {c.type === 'boolean' ? (
                <label className="flex items-center gap-2.5 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={form[c.name] === 'true'}
                    onChange={(e) => setForm((p) => ({ ...p, [c.name]: String(e.target.checked) }))}
                    className="w-4 h-4 accent-primary-500 cursor-pointer"
                  />
                  <span className="text-sm text-foreground-800">{c.label}</span>
                </label>
              ) : c.type === 'select' && c.options?.length ? (
                <select
                  value={form[c.name] ?? ''}
                  onChange={(e) => setForm((p) => ({ ...p, [c.name]: e.target.value }))}
                  className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400 cursor-pointer"
                >
                  <option value="">请选择</option>
                  {c.options.map((o) => (
                    <option key={o} value={o}>
                      {o}
                    </option>
                  ))}
                </select>
              ) : (
                <input
                  type={inputType(c)}
                  value={form[c.name] ?? ''}
                  onChange={(e) => setForm((p) => ({ ...p, [c.name]: e.target.value }))}
                  className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400"
                />
              )}
            </div>
          ))}
          {formError ? (
            <div className="flex items-start gap-2 px-3 py-2.5 rounded-md bg-accent-100 text-accent-900 text-xs">
              <i className="ri-error-warning-line mt-0.5"></i>
              <span>{formError}</span>
            </div>
          ) : null}
        </div>
      </Modal>

      <Modal
        open={Boolean(deleteTarget)}
        title="删除确认"
        onClose={() => setDeleteTarget(null)}
        footer={
          <>
            <button
              type="button"
              onClick={() => setDeleteTarget(null)}
              className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
            >
              取消
            </button>
            <button
              type="button"
              onClick={confirmDelete}
              className="h-9 px-4 rounded-md bg-secondary-700 text-background-50 text-sm hover:bg-secondary-800 cursor-pointer whitespace-nowrap"
            >
              确认删除
            </button>
          </>
        }
      >
        <p className="text-sm text-foreground-700">确定删除这条记录吗?此操作不可恢复。</p>
      </Modal>
    </div>
  );
}