import { Component } from 'react';
import type { ErrorInfo, ReactNode } from 'react';

interface ErrorBoundaryProps {
  children: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
  error: Error | null;
}

/**
 * Global error boundary.
 * Catches render-time errors anywhere in the tree and shows a friendly,
 * recoverable fallback instead of a blank white screen.
 */
export default class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    // Hook for future error reporting (Sentry / logging backend).
    console.error('[ErrorBoundary] Uncaught error:', error, info.componentStack);
  }

  private handleRetry = () => {
    this.setState({ hasError: false, error: null });
  };

  private handleReload = () => {
    if (typeof window !== 'undefined') {
      window.location.reload();
    }
  };

  render() {
    const { hasError, error } = this.state;

    if (!hasError) {
      return this.props.children;
    }

    return (
      <div className="min-h-screen flex items-center justify-center bg-background-100 px-4 py-10">
        <div className="w-full max-w-lg rounded-lg bg-background-50 border border-background-200 p-6 md:p-8">
          <span className="w-12 h-12 rounded-md bg-secondary-100 text-secondary-900 flex items-center justify-center">
            <i className="ri-error-warning-line text-2xl"></i>
          </span>
          <h1 className="mt-4 text-lg font-semibold text-foreground-950 font-heading">页面出了点小问题</h1>
          <p className="mt-2 text-sm text-foreground-600 leading-relaxed">
            当前页面在渲染时遇到了异常,已为你拦截,其他数据不受影响。你可以直接重试,或刷新页面重新加载。
          </p>
          {error?.message ? (
            <p className="mt-3 px-3 py-2 rounded-md bg-background-100 text-[11px] text-foreground-500 font-label break-all">
              {error.message}
            </p>
          ) : null}
          <div className="mt-5 flex flex-wrap gap-2">
            <button
              type="button"
              onClick={this.handleRetry}
              className="inline-flex items-center gap-1.5 h-9 px-4 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 cursor-pointer whitespace-nowrap dark:text-foreground-950"
            >
              <i className="ri-refresh-line"></i>
              重试
            </button>
            <button
              type="button"
              onClick={this.handleReload}
              className="inline-flex items-center gap-1.5 h-9 px-4 rounded-md bg-background-100 border border-background-300 text-foreground-800 text-sm hover:bg-background-200 cursor-pointer whitespace-nowrap"
            >
              <i className="ri-restart-line"></i>
              刷新页面
            </button>
          </div>
        </div>
      </div>
    );
  }
}