import { useCallback, useEffect, useState } from 'react';
import { supabase } from '@/lib/supabase';

export interface GenColumn {
  name: string;
  label: string;
  type: string;
  primary?: boolean;
  options?: string[];
}

export interface GenOps {
  list?: boolean;
  search?: boolean;
  create?: boolean;
  update?: boolean;
  delete?: boolean;
  export?: boolean;
}

export interface GeneratedPage {
  id: string;
  slug: string;
  title: string;
  table_name: string;
  icon: string | null;
  columns: GenColumn[];
  ops: GenOps;
  permission_code: string | null;
  enabled: boolean;
  created_at: string | null;
}

/** 读取「运行时动态页面」注册表。onlyEnabled=true 时只取在线的页面(用于侧边导航)。 */
export function useGeneratedPages(onlyEnabled = true) {
  const [pages, setPages] = useState<GeneratedPage[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      let query = supabase.from('generated_pages').select('*');
      if (onlyEnabled) query = query.eq('enabled', true);
      const { data, error: err } = await query.order('created_at', { ascending: false });
      if (err) throw err;
      setPages((data as GeneratedPage[]) ?? []);
    } catch (e) {
      console.error(e);
      setError('加载生成的页面失败');
    } finally {
      setLoading(false);
    }
  }, [onlyEnabled]);

  useEffect(() => {
    load();
  }, [load]);

  return { pages, loading, error, reload: load };
}