/**
 * 轻量 Cron 解析:把标准的 5 段表达式(分 时 日 月 周)解析成允许值集合,
 * 并据此推算「下一次预计执行时间」。仅用于前端展示,真实的调度判定以后端为准。
 */

export interface ParsedCron {
  minutes: number[];
  hours: number[];
  dom: number[];
  months: number[];
  dow: number[];
  domRestricted: boolean;
  dowRestricted: boolean;
}

function parseField(field: string, min: number, max: number): number[] | null {
  const values = new Set<number>();
  for (const raw of field.split(',')) {
    const part = raw.trim();
    if (!part) return null;
    let step = 1;
    let range = part;
    const slash = part.indexOf('/');
    if (slash >= 0) {
      range = part.slice(0, slash).trim();
      step = Number(part.slice(slash + 1));
      if (!Number.isInteger(step) || step <= 0) return null;
    }
    let start: number;
    let end: number;
    if (range === '*') {
      start = min;
      end = max;
    } else if (range.includes('-')) {
      const [a, b] = range.split('-');
      start = Number(a);
      end = Number(b);
      if (!Number.isInteger(start) || !Number.isInteger(end)) return null;
    } else {
      start = Number(range);
      if (!Number.isInteger(start)) return null;
      // 单值带步长(如 5/10)按「从该值到最大值」处理,贴近常见实现
      end = slash >= 0 ? max : start;
    }
    if (start < min) start = min;
    if (end > max) end = max;
    if (start > end) return null;
    for (let v = start; v <= end; v += step) values.add(v);
  }
  return Array.from(values).sort((a, b) => a - b);
}

export function parseCron(cron: string): ParsedCron | null {
  const parts = cron.trim().split(/\s+/);
  if (parts.length !== 5) return null;
  const minutes = parseField(parts[0], 0, 59);
  const hours = parseField(parts[1], 0, 23);
  const dom = parseField(parts[2], 1, 31);
  const months = parseField(parts[3], 1, 12);
  const dow = parseField(parts[4], 0, 7);
  if (!minutes || !hours || !dom || !months || !dow) return null;
  if (!minutes.length || !hours.length || !months.length) return null;
  return {
    minutes,
    hours,
    dom,
    months,
    dow: Array.from(new Set(dow.map((d) => d % 7))).sort((a, b) => a - b),
    domRestricted: parts[2].trim() !== '*',
    dowRestricted: parts[4].trim() !== '*',
  };
}

/** 推算下一次执行时间,找不到(或表达式非法)时返回 null。 */
export function nextCronRun(cron: string, from: Date = new Date()): Date | null {
  const parsed = parseCron(cron);
  if (!parsed) return null;
  const { minutes, hours, dom, months, dow, domRestricted, dowRestricted } = parsed;
  const domSet = new Set(dom);
  const dowSet = new Set(dow);

  const cursor = new Date(from.getTime());
  cursor.setSeconds(0, 0);
  cursor.setMinutes(cursor.getMinutes() + 1);

  for (let day = 0; day < 732; day += 1) {
    const y = cursor.getFullYear();
    const mo = cursor.getMonth() + 1;
    const d = cursor.getDate();
    const wd = cursor.getDay();

    let dayOk: boolean;
    if (!domRestricted && !dowRestricted) dayOk = true;
    else if (domRestricted && !dowRestricted) dayOk = dowSet.has(wd);
    else if (!domRestricted && dowRestricted) dayOk = domSet.has(d);
    else dayOk = domSet.has(d) || dowSet.has(wd);

    if (months.includes(mo) && dayOk) {
      const startHour = day === 0 ? cursor.getHours() : 0;
      const startMinute = day === 0 ? cursor.getMinutes() : 0;
      for (const h of hours) {
        if (h < startHour) continue;
        for (const m of minutes) {
          if (h === startHour && m < startMinute) continue;
          return new Date(y, mo - 1, d, h, m, 0, 0);
        }
      }
    }
    cursor.setDate(cursor.getDate() + 1);
    cursor.setHours(0, 0, 0, 0);
  }
  return null;
}

/** 把下一次执行时间格式化成便于阅读的相对描述。 */
export function formatNextRun(next: Date | null): string {
  if (!next) return '—';
  const diff = next.getTime() - Date.now();
  const mins = Math.round(diff / 60000);
  if (mins <= 0) return '即将执行';
  if (mins < 60) return `约 ${mins} 分钟后`;
  const hours = Math.floor(mins / 60);
  if (hours < 24) return `约 ${hours} 小时后`;
  return `约 ${Math.round(hours / 24)} 天后`;
}

/** 具体到分的绝对时间文本,如「今天 14:30」「明天 02:00」「10-07 09:00」。 */
export function absoluteNextRun(next: Date | null): string {
  if (!next) return '—';
  const now = new Date();
  const hm = `${String(next.getHours()).padStart(2, '0')}:${String(next.getMinutes()).padStart(2, '0')}`;
  const sameDay = (a: Date, b: Date) =>
    a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();
  if (sameDay(next, now)) return `今天 ${hm}`;
  const tomorrow = new Date(now.getTime());
  tomorrow.setDate(now.getDate() + 1);
  if (sameDay(next, tomorrow)) return `明天 ${hm}`;
  return `${String(next.getMonth() + 1).padStart(2, '0')}-${String(next.getDate()).padStart(2, '0')} ${hm}`;
}