import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from 'react';
import type { Session, User } from '@supabase/supabase-js';
import { supabase } from '@/lib/supabase';

export interface Profile {
  id: string;
  email: string | null;
  full_name: string | null;
  avatar_url: string | null;
  status: string | null;
  tenant_id: string | null;
  created_at?: string;
}

interface AuthContextValue {
  session: Session | null;
  user: User | null;
  profile: Profile | null;
  roleCodes: string[];
  permissions: string[];
  loading: boolean;
  profileLoading: boolean;
  /** 体验(演示)账号:可浏览完整后台,但只读 */
  isDemo: boolean;
  /** 是否处于只读状态(演示账号即只读) */
  isReadOnly: boolean;
  /** 仅有访客权限、尚未被管理员分配权限的新账号 */
  isPendingApproval: boolean;
  hasPermission: (code: string) => boolean;
  hasRole: (code: string) => boolean;
  refreshProfile: () => Promise<void>;
  signOut: () => Promise<void>;
}

const AuthContext = createContext<AuthContextValue | undefined>(undefined);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [session, setSession] = useState<Session | null>(null);
  const [profile, setProfile] = useState<Profile | null>(null);
  const [roleCodes, setRoleCodes] = useState<string[]>([]);
  const [permissions, setPermissions] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [profileLoading, setProfileLoading] = useState(true);

  useEffect(() => {
    let mounted = true;
    supabase.auth
      .getSession()
      .then(({ data }) => {
        if (!mounted) return;
        setSession(data.session);
        setLoading(false);
      })
      .catch(() => {
        if (mounted) setLoading(false);
      });

    const { data: sub } = supabase.auth.onAuthStateChange((_event, nextSession) => {
      // Keep this synchronous: only update local auth state.
      setSession(nextSession);
    });

    return () => {
      mounted = false;
      sub.subscription.unsubscribe();
    };
  }, []);

  const loadProfile = useCallback(async (current: Session | null) => {
    if (!current?.user) {
      setProfile(null);
      setRoleCodes([]);
      setPermissions([]);
      setProfileLoading(false);
      return;
    }
    setProfileLoading(true);
    try {
      // Ensure a profile row + default role exist for this account.
      await supabase.rpc('bootstrap_new_user');

      const { data: prof } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', current.user.id)
        .maybeSingle();
      setProfile((prof as Profile) ?? null);

      const { data: ur } = await supabase
        .from('user_roles')
        .select('role_id')
        .eq('user_id', current.user.id);
      const roleIds = (ur ?? []).map((row) => row.role_id);

      if (roleIds.length > 0) {
        const { data: rolesData } = await supabase
          .from('roles')
          .select('code')
          .in('id', roleIds);
        setRoleCodes((rolesData ?? []).map((r) => r.code as string).filter(Boolean));
      } else {
        setRoleCodes([]);
      }

      const { data: perms } = await supabase.rpc('get_my_permissions');
      setPermissions(((perms ?? []) as { code: string }[]).map((p) => p.code).filter(Boolean));
    } catch (err) {
      console.error('Failed to load profile', err);
    } finally {
      setProfileLoading(false);
    }
  }, []);

  useEffect(() => {
    let active = true;
    loadProfile(session).then(() => {
      if (!active) return;
    });
    return () => {
      active = false;
    };
  }, [session, loadProfile]);

  const refreshProfile = useCallback(async () => {
    const { data } = await supabase.auth.getSession();
    await loadProfile(data.session);
  }, [loadProfile]);

  const signOut = useCallback(async () => {
    await supabase.auth.signOut();
    setProfile(null);
    setRoleCodes([]);
    setPermissions([]);
  }, []);

  const hasRole = useCallback((code: string) => roleCodes.includes(code), [roleCodes]);

  const hasPermission = useCallback(
    (code: string) => {
      if (!code) return true;
      if (roleCodes.includes('super_admin')) return true;
      return permissions.includes(code);
    },
    [permissions, roleCodes],
  );

  const isDemo = useMemo(
    () => session?.user?.user_metadata?.account_type === 'demo',
    [session],
  );

  const isReadOnly = isDemo;

  const isPendingApproval = useMemo(() => {
    if (isDemo) return false;
    if (roleCodes.includes('super_admin')) return false;
    // 除「工作台」外没有任何可用权限 → 视为等待管理员分配权限
    return permissions.filter((p) => p !== 'menu:home').length === 0;
  }, [isDemo, roleCodes, permissions]);

  const value = useMemo<AuthContextValue>(
    () => ({
      session,
      user: session?.user ?? null,
      profile,
      roleCodes,
      permissions,
      loading,
      profileLoading,
      isDemo,
      isReadOnly,
      isPendingApproval,
      hasPermission,
      hasRole,
      refreshProfile,
      signOut,
    }),
    [
      session,
      profile,
      roleCodes,
      permissions,
      loading,
      profileLoading,
      isDemo,
      isReadOnly,
      isPendingApproval,
      hasPermission,
      hasRole,
      refreshProfile,
      signOut,
    ],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return ctx;
}