import { useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import { supabase } from '@/lib/supabase';
import { generatorTables, type TableDef } from '@/pages/generator/generatorCatalog';
import { buildPermissionSpec, buildReact, buildSql, buildTypes, type GenOps } from '@/pages/generator/generateCode';
import { useGeneratedPages } from '@/hooks/useGeneratedPages';

type TabKey = 'react' | 'sql' | 'types';

const tabs: { key: TabKey; label: string; icon: string }[] = [
  { key: 'react', label: 'React 管理页', icon: 'ri-code-s-slash-line' },
  { key: 'sql', label: 'SQL DDL', icon: 'ri-database-2-line' },
  { key: 'types', label: '类型定义', icon: 'ri-braces-line' },
];

const opList: { key: keyof GenOps; label: string }[] = [
  { key: 'list', label: '列表查询' },
  { key: 'search', label: '关键字搜索' },
  { key: 'create', label: '新增' },
  { key: 'update', label: '编辑' },
  { key: 'delete', label: '删除' },
  { key: 'export', label: '导出' },
];

const defaultOps: GenOps = {
  list: true,
  search: true,
  create: true,
  update: true,
  delete: true,
  export: false,
};

function pascal(name: string) {
  return name
    .split(/[_\s-]+/)
    .map((s) => s.charAt(0).toUpperCase() + s.slice(1))
    .join('');
}

export default function GeneratorPage() {
  const [tableName, setTableName] = useState(generatorTables[0].name);
  const [selected, setSelected] = useState<Set<string>>(
    new Set(generatorTables[0].columns.map((c) => c.name)),
  );
  const [ops, setOps] = useState<GenOps>(defaultOps);
  const [tab, setTab] = useState<TabKey>('react');
  const [copied, setCopied] = useState(false);
  const [copiedRoute, setCopiedRoute] = useState(false);
  const [writing, setWriting] = useState(false);
  const [writeMsg, setWriteMsg] = useState('');
  const [writeError, setWriteError] = useState('');
  const [landing, setLanding] = useState(false);
  const [landMsg, setLandMsg] = useState('');
  const [landError, setLandError] = useState('');
  const [busySlug, setBusySlug] = useState('');

  const { pages: landedPages, reload: reloadLanded } = useGeneratedPages(false);

  const table: TableDef = generatorTables.find((t) => t.name === tableName) ?? generatorTables[0];
  const activeColumns = useMemo(
    () => table.columns.filter((c) => selected.has(c.name)),
    [table, selected],
  );
  const permissionSpecs = useMemo(() => buildPermissionSpec(table, ops), [table, ops]);

  const code = useMemo(() => {
    if (tab === 'sql') return buildSql(table, activeColumns, ops);
    if (tab === 'types') return buildTypes(table, activeColumns);
    return buildReact(table, activeColumns, ops);
  }, [tab, table, activeColumns, ops]);

  const componentName = `${pascal(table.name)}ManagePage`;
  const routeSnippet = useMemo(
    () =>
      [
        `import ${componentName} from '@/pages/${table.name}/page';`,
        '',
        '// 在 src/router/config.tsx 的 AdminLayout 子路由数组中加入一行:',
        `{ path: '${table.name}', element: <${componentName} /> },`,
      ].join('\n'),
    [componentName, table.name],
  );

  const pickTable = (t: TableDef) => {
    setTableName(t.name);
    setSelected(new Set(t.columns.map((c) => c.name)));
  };

  const toggleColumn = (name: string) => {
    setSelected((prev) => {
      const next = new Set(prev);
      if (next.has(name)) {
        if (next.size > 1) next.delete(name);
      } else {
        next.add(name);
      }
      return next;
    });
  };

  const toggleOp = (key: keyof GenOps) => {
    setOps((prev) => ({ ...prev, [key]: !prev[key] }));
  };

  const copyCode = async () => {
    try {
      await navigator.clipboard.writeText(code);
      setCopied(true);
      setTimeout(() => setCopied(false), 1800);
    } catch (err) {
      console.error(err);
    }
  };

  const copyRoute = async () => {
    try {
      await navigator.clipboard.writeText(routeSnippet);
      setCopiedRoute(true);
      setTimeout(() => setCopiedRoute(false), 1800);
    } catch (err) {
      console.error(err);
    }
  };

  const downloadCode = () => {
    const ext = tab === 'sql' ? 'sql' : 'tsx';
    const blob = new Blob([code], { type: 'text/plain;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${table.name}.manage.${ext}`;
    a.click();
    URL.revokeObjectURL(url);
  };

  // 幂等地把页面用到的权限点写进权限表(新权限会自动授予超管)
  const ensurePermissions = async () => {
    const specs = buildPermissionSpec(table, ops);
    const menuSpec = specs.find((s) => s.type === 'menu');
    let menuId: string | null = null;
    if (menuSpec) {
      const { data: existed, error: findErr } = await supabase
        .from('permissions')
        .select('id')
        .eq('code', menuSpec.code)
        .maybeSingle();
      if (findErr) throw findErr;
      if (existed?.id) {
        menuId = existed.id as string;
      } else {
        const { data: created, error: insErr } = await supabase
          .from('permissions')
          .insert({ name: menuSpec.name, code: menuSpec.code, type: 'menu' })
          .select('id')
          .single();
        if (insErr) throw insErr;
        menuId = created?.id as string;
      }
    }
    let created = 0;
    let skipped = 0;
    for (const spec of specs.filter((s) => s.type === 'button')) {
      const { data: existed, error: findErr } = await supabase
        .from('permissions')
        .select('id')
        .eq('code', spec.code)
        .maybeSingle();
      if (findErr) throw findErr;
      if (existed?.id) {
        skipped += 1;
        continue;
      }
      const { error: insErr } = await supabase
        .from('permissions')
        .insert({ name: spec.name, code: spec.code, type: 'button', parent_id: menuId });
      if (insErr) throw insErr;
      created += 1;
    }
    return { created, skipped };
  };

  const writePermissions = async () => {
    setWriting(true);
    setWriteMsg('');
    setWriteError('');
    try {
      const { created, skipped } = await ensurePermissions();
      setWriteMsg(`已写入 ${created} 个权限点,已存在 ${skipped} 个(新权限会自动授予超级管理员)。`);
    } catch (err) {
      console.error(err);
      setWriteError('写入失败,请确认当前为超级管理员且网络正常。');
    } finally {
      setWriting(false);
    }
  };

  // 一键落地:注册运行时页面(即时生效、自动路由)+ 登记权限点,无需复制源码
  const landPage = async () => {
    setLanding(true);
    setLandMsg('');
    setLandError('');
    try {
      const { created, skipped } = await ensurePermissions();
      const payload = {
        slug: table.name,
        title: `${table.label}管理`,
        table_name: table.name,
        icon: table.icon,
        columns: activeColumns,
        ops,
        permission_code: `menu:${table.name}`,
        enabled: true,
      };
      const { error: upErr } = await supabase
        .from('generated_pages')
        .upsert(payload, { onConflict: 'slug' });
      if (upErr) throw upErr;
      await reloadLanded();
      setLandMsg(
        `已落地:路由 /generated/${table.name} 即时可用｜权限点新增 ${created} 个、已存在 ${skipped} 个。`,
      );
    } catch (err) {
      console.error(err);
      setLandError('落地失败,请确认当前为超级管理员且网络正常。');
    } finally {
      setLanding(false);
    }
  };

  const unland = async (slug: string) => {
    setBusySlug(slug);
    try {
      const { error: err } = await supabase.from('generated_pages').delete().eq('slug', slug);
      if (err) throw err;
      await reloadLanded();
    } catch (err) {
      console.error(err);
      setLandError('下线失败,请稍后重试。');
    } finally {
      setBusySlug('');
    }
  };

  return (
    <div className="space-y-4">
      <div>
        <h2 className="text-lg font-semibold text-foreground-950">一键 CRUD 代码生成器</h2>
        <p className="text-sm text-foreground-500 mt-0.5">
          选一张表、勾选字段与操作,可一键落地为运行时页面(自动路由),也可生成源码、SQL 与类型定义
        </p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-[240px_1fr] gap-4 items-start">
        {/* Table picker */}
        <div className="rounded-lg bg-background-50 border border-background-200 p-2">
          <p className="px-2 py-1.5 text-[11px] font-medium tracking-wide text-foreground-400">选择数据表</p>
          <div className="space-y-1">
            {generatorTables.map((t) => (
              <button
                key={t.name}
                type="button"
                onClick={() => pickTable(t)}
                className={`w-full flex items-center gap-2.5 px-2.5 py-2 rounded-md text-sm cursor-pointer transition-colors ${
                  t.name === tableName
                    ? 'bg-primary-50 text-primary-700 font-medium'
                    : 'text-foreground-700 hover:bg-background-100'
                }`}
              >
                <i className={`${t.icon} text-sm`}></i>
                <span className="flex-1 text-left">{t.label}</span>
                <span className="text-[10px] font-label text-foreground-400">{t.name}</span>
              </button>
            ))}
          </div>
        </div>

        {/* Config + preview */}
        <div className="space-y-4">
          <div className="rounded-lg bg-background-50 border border-background-200 p-4 md:p-5">
            <div className="flex flex-wrap items-center gap-2">
              <h3 className="text-sm font-semibold text-foreground-950">
                {table.label}
                <span className="ml-2 font-label text-xs text-foreground-400">{table.name}</span>
              </h3>
              <span className="ml-auto text-[11px] text-foreground-500">
                已选 {activeColumns.length} / {table.columns.length} 字段
              </span>
            </div>

            <div className="mt-3.5">
              <p className="text-xs font-medium text-foreground-600 mb-2">字段</p>
              <div className="flex flex-wrap gap-2">
                {table.columns.map((c) => {
                  const on = selected.has(c.name);
                  return (
                    <button
                      key={c.name}
                      type="button"
                      onClick={() => toggleColumn(c.name)}
                      className={`inline-flex items-center gap-1.5 h-8 px-3 rounded-full text-xs border cursor-pointer whitespace-nowrap transition-colors ${
                        on
                          ? 'bg-secondary-100 text-secondary-900 border-secondary-200'
                          : 'bg-background-50 text-foreground-500 border-background-300 hover:bg-background-100'
                      }`}
                    >
                      {on ? <i className="ri-check-line"></i> : null}
                      {c.label}
                      {c.primary ? <i className="ri-key-2-line opacity-70"></i> : null}
                    </button>
                  );
                })}
              </div>
            </div>

            <div className="mt-4">
              <p className="text-xs font-medium text-foreground-600 mb-2">生成操作</p>
              <div className="flex flex-wrap gap-2">
                {opList.map((o) => {
                  const on = ops[o.key];
                  return (
                    <button
                      key={o.key}
                      type="button"
                      onClick={() => toggleOp(o.key)}
                      className={`inline-flex items-center gap-1.5 h-8 px-3 rounded-full text-xs border cursor-pointer whitespace-nowrap transition-colors ${
                        on
                          ? 'bg-primary-100 text-primary-800 border-primary-200'
                          : 'bg-background-50 text-foreground-500 border-background-300 hover:bg-background-100'
                      }`}
                    >
                      {on ? <i className="ri-checkbox-circle-line"></i> : <i className="ri-circle-line"></i>}
                      {o.label}
                    </button>
                  );
                })}
              </div>
            </div>
          </div>

          {/* 一键落地 + 路由注册 */}
          <div className="rounded-lg bg-background-50 border border-background-200 p-4 md:p-5">
            <div className="flex flex-wrap items-center gap-2">
              <h3 className="text-sm font-semibold text-foreground-950">落地到项目</h3>
              <span className="text-[11px] text-foreground-500">
                一键生成运行时页面并自动注册路由,无需复制源码;也可导出源码后手动注册
              </span>
            </div>
            <div className="mt-3.5 flex flex-wrap items-center gap-2">
              <button
                type="button"
                onClick={landPage}
                disabled={landing}
                className="h-9 px-3.5 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 disabled:opacity-60 cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5 dark:text-foreground-950"
              >
                <i className={landing ? 'ri-loader-4-line animate-spin' : 'ri-rocket-2-line'}></i>
                {landing ? '落地中…' : '一键落地'}
              </button>
              {landMsg ? (
                <span className="inline-flex items-center gap-1.5 text-xs text-primary-700">
                  <i className="ri-checkbox-circle-line"></i>
                  {landMsg}
                </span>
              ) : null}
              {landError ? (
                <span className="inline-flex items-center gap-1.5 text-xs text-accent-900">
                  <i className="ri-error-warning-line"></i>
                  {landError}
                </span>
              ) : null}
            </div>

            {landedPages.length > 0 ? (
              <ul className="mt-3.5 space-y-1.5">
                {landedPages.map((p) => (
                  <li
                    key={p.id}
                    className="flex flex-wrap items-center gap-2 rounded-md border border-background-200 bg-background-100/60 px-3 py-2"
                  >
                    <i className={`${p.icon || 'ri-layout-4-line'} text-foreground-500`}></i>
                    <span className="text-sm text-foreground-900">{p.title}</span>
                    <span className="text-[11px] font-label text-foreground-400">/generated/{p.slug}</span>
                    <div className="ml-auto flex items-center gap-1.5">
                      <Link
                        to={`/generated/${p.slug}`}
                        className="h-7 px-2.5 rounded-md bg-primary-500 text-background-50 text-[11px] inline-flex items-center gap-1 cursor-pointer whitespace-nowrap dark:text-foreground-950"
                      >
                        <i className="ri-external-link-line"></i>
                        打开
                      </Link>
                      <button
                        type="button"
                        onClick={() => unland(p.slug)}
                        disabled={busySlug === p.slug}
                        className="h-7 px-2.5 rounded-md bg-background-50 border border-background-300 text-[11px] text-foreground-700 hover:bg-background-200 disabled:opacity-50 cursor-pointer whitespace-nowrap"
                      >
                        {busySlug === p.slug ? '下线中…' : '下线'}
                      </button>
                    </div>
                  </li>
                ))}
              </ul>
            ) : (
              <p className="mt-3 text-xs text-foreground-500">还没有落地的运行时页面。</p>
            )}

            <div className="mt-4 pt-3.5 border-t border-background-200">
              <div className="flex flex-wrap items-center gap-2">
                <span className="text-xs font-medium text-foreground-600">路由注册代码(源码方式)</span>
                <span className="text-[11px] text-foreground-400">
                  把生成的 .tsx 放进项目后,用这段代码注册路由
                </span>
                <button
                  type="button"
                  onClick={copyRoute}
                  className="ml-auto h-7 px-2.5 rounded-md bg-background-100 border border-background-300 text-[11px] text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap inline-flex items-center gap-1"
                >
                  <i className={copiedRoute ? 'ri-check-line text-primary-600' : 'ri-file-copy-line'}></i>
                  {copiedRoute ? '已复制' : '复制'}
                </button>
              </div>
              <pre className="mt-2 p-3 rounded-md bg-background-100 border border-background-200 text-[12px] leading-relaxed text-foreground-800 overflow-auto font-mono whitespace-pre">
                {routeSnippet}
              </pre>
            </div>
          </div>

          <div className="rounded-lg bg-background-50 border border-background-200 p-4 md:p-5">
            <div className="flex flex-wrap items-center gap-2">
              <h3 className="text-sm font-semibold text-foreground-950">页面权限点</h3>
              <span className="text-[11px] text-foreground-500">
                生成的管理页会引用以下权限码,同步写入权限表即可避免「代码里有、数据库里却没有」的脱节
              </span>
            </div>
            <div className="mt-3 flex flex-wrap gap-1.5">
              {permissionSpecs.map((s) => (
                <span
                  key={s.code}
                  className={`inline-flex items-center gap-1.5 h-7 px-2.5 rounded-full text-[11px] border ${
                    s.type === 'menu'
                      ? 'bg-secondary-100 text-secondary-900 border-secondary-200'
                      : 'bg-background-50 text-foreground-600 border-background-300'
                  }`}
                >
                  <i className={s.type === 'menu' ? 'ri-menu-line' : 'ri-checkbox-blank-circle-line'}></i>
                  <span>{s.name}</span>
                  <code className="font-label text-foreground-400">{s.code}</code>
                </span>
              ))}
            </div>
            <div className="mt-3.5 flex flex-wrap items-center gap-2">
              <button
                type="button"
                onClick={writePermissions}
                disabled={writing}
                className="h-9 px-3.5 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 disabled:opacity-60 cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5 dark:text-foreground-950"
              >
                <i className={writing ? 'ri-loader-4-line animate-spin' : 'ri-shield-keyhole-line'}></i>
                {writing ? '写入中…' : '写入权限表'}
              </button>
              {writeMsg ? (
                <span className="inline-flex items-center gap-1.5 text-xs text-primary-700">
                  <i className="ri-checkbox-circle-line"></i>
                  {writeMsg}
                </span>
              ) : null}
              {writeError ? (
                <span className="inline-flex items-center gap-1.5 text-xs text-accent-900">
                  <i className="ri-error-warning-line"></i>
                  {writeError}
                </span>
              ) : null}
            </div>
          </div>

          <div className="rounded-lg bg-background-50 border border-background-200 overflow-hidden">
            <div className="flex items-center gap-1 px-2 py-2 border-b border-background-200">
              {tabs.map((t) => (
                <button
                  key={t.key}
                  type="button"
                  onClick={() => setTab(t.key)}
                  className={`flex items-center gap-1.5 h-8 px-3 rounded-md text-xs cursor-pointer whitespace-nowrap transition-colors ${
                    tab === t.key
                      ? 'bg-background-100 text-foreground-950 font-medium'
                      : 'text-foreground-500 hover:bg-background-100'
                  }`}
                >
                  <i className={`${t.icon} text-sm`}></i>
                  {t.label}
                </button>
              ))}
              <div className="ml-auto flex items-center gap-1.5 pr-1">
                <button
                  type="button"
                  onClick={copyCode}
                  className="h-8 px-3 rounded-md bg-background-100 border border-background-300 text-xs text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap flex items-center gap-1.5"
                >
                  <i className={copied ? 'ri-check-line text-primary-600' : 'ri-file-copy-line'}></i>
                  {copied ? '已复制' : '复制'}
                </button>
                <button
                  type="button"
                  onClick={downloadCode}
                  className="h-8 px-3 rounded-md bg-primary-500 text-background-50 text-xs hover:bg-primary-600 cursor-pointer whitespace-nowrap flex items-center gap-1.5 dark:text-foreground-950"
                >
                  <i className="ri-download-2-line"></i>
                  下载
                </button>
              </div>
            </div>
            <pre className="p-4 text-[12.5px] leading-relaxed text-foreground-800 overflow-auto max-h-[560px] font-mono whitespace-pre">
              {code}
            </pre>
          </div>
        </div>
      </div>
    </div>
  );
}