import { useState } from 'react';
import type { DragEvent } from 'react';
import { palette, paletteGroups, type PaletteItem } from '@/pages/builder/types';

interface ComponentPaletteProps {
  onAdd: (item: PaletteItem) => void;
}

export default function ComponentPalette({ onAdd }: ComponentPaletteProps) {
  const [activeGroup, setActiveGroup] = useState(paletteGroups[0]);

  const handleDragStart = (e: DragEvent, item: PaletteItem) => {
    e.dataTransfer.setData(
      'application/x-builder',
      JSON.stringify({ source: 'palette', type: item.type }),
    );
    e.dataTransfer.effectAllowed = 'copy';
  };

  return (
    <aside className="w-full lg:w-[248px] shrink-0 rounded-lg bg-background-50 border border-background-200 flex flex-col">
      <div className="px-4 py-3.5 border-b border-background-200">
        <h3 className="text-sm font-semibold text-foreground-950">组件库</h3>
        <p className="text-[11px] text-foreground-500 mt-0.5">拖拽或点击添加到画布</p>
      </div>

      <div className="flex flex-wrap gap-1 px-3 py-2.5 border-b border-background-200">
        {paletteGroups.map((g) => (
          <button
            key={g}
            type="button"
            onClick={() => setActiveGroup(g)}
            className={`px-2.5 py-1 rounded-full text-[11px] cursor-pointer whitespace-nowrap transition-colors ${
              activeGroup === g
                ? 'bg-primary-500 text-background-50 dark:text-foreground-950'
                : 'bg-background-100 text-foreground-600 hover:bg-background-200'
            }`}
          >
            {g}
          </button>
        ))}
      </div>

      <div className="flex-1 overflow-y-auto p-3 space-y-2">
        {palette
          .filter((item) => item.group === activeGroup)
          .map((item) => (
            <button
              key={item.type}
              type="button"
              draggable
              onDragStart={(e) => handleDragStart(e, item)}
              onClick={() => onAdd(item)}
              className="w-full flex items-center gap-3 rounded-md bg-background-50 border border-background-200 px-3 py-2.5 text-left hover:border-primary-300 hover:bg-background-100 cursor-grab active:cursor-grabbing transition-colors"
            >
              <span className="w-8 h-8 rounded-md bg-primary-100 text-primary-700 flex items-center justify-center shrink-0">
                <i className={`${item.icon} text-sm`}></i>
              </span>
              <span className="min-w-0">
                <span className="block text-xs font-medium text-foreground-900">{item.label}</span>
                <span className="block text-[10px] text-foreground-500 truncate">{item.description}</span>
              </span>
              <i className="ri-drag-move-2-line ml-auto text-foreground-300"></i>
            </button>
          ))}
      </div>

      <div className="px-4 py-3 border-t border-background-200">
        <div className="flex items-start gap-2 text-[10px] text-foreground-500 leading-relaxed">
          <i className="ri-information-line mt-0.5"></i>
          <span>支持从组件库拖入画布,也可在画布内拖拽调整顺序</span>
        </div>
      </div>
    </aside>
  );
}