import type { ColumnDef, TableDef } from '@/pages/generator/generatorCatalog';

export interface GenOps {
  list: boolean;
  create: boolean;
  update: boolean;
  delete: boolean;
  search: boolean;
  export: boolean;
}

function pascal(name: string) {
  return name
    .split(/[_\s-]+/)
    .map((s) => s.charAt(0).toUpperCase() + s.slice(1))
    .join('');
}

function tsType(col: ColumnDef) {
  const base = col.type === 'number' ? 'number' : col.type === 'boolean' ? 'boolean' : 'string';
  return col.primary ? base : `${base} | null`;
}

function sqlType(col: ColumnDef) {
  switch (col.type) {
    case 'number':
      return 'numeric';
    case 'boolean':
      return 'boolean';
    case 'date':
      return 'timestamptz';
    default:
      return 'text';
  }
}

function inputType(col: ColumnDef) {
  if (col.type === 'number') return 'number';
  if (col.type === 'date') return 'datetime-local';
  return 'text';
}

export interface PermissionSpec {
  code: string;
  name: string;
  type: 'menu' | 'button';
  parentCode: string | null;
}

/**
 * 根据选中的表与操作,推导出页面需要登记的权限码。
 * 生成的管理页代码会引用同一套权限码,确保「代码引用」与「权限表」始终一致。
 */
export function buildPermissionSpec(table: TableDef, ops: GenOps): PermissionSpec[] {
  const menuCode = `menu:${table.name}`;
  const specs: PermissionSpec[] = [
    { code: menuCode, name: `${table.label}管理`, type: 'menu', parentCode: null },
  ];
  if (ops.create) specs.push({ code: `${table.name}:create`, name: `新增${table.label}`, type: 'button', parentCode: menuCode });
  if (ops.update) specs.push({ code: `${table.name}:update`, name: `编辑${table.label}`, type: 'button', parentCode: menuCode });
  if (ops.delete) specs.push({ code: `${table.name}:delete`, name: `删除${table.label}`, type: 'button', parentCode: menuCode });
  if (ops.export) specs.push({ code: `${table.name}:export`, name: `导出${table.label}`, type: 'button', parentCode: menuCode });
  return specs;
}

/** 幂等的权限登记 SQL,复制执行后即可让权限表与页面代码对齐。 */
export function buildPermissionSql(table: TableDef, ops: GenOps): string {
  const specs = buildPermissionSpec(table, ops);
  const lines: string[] = [];
  lines.push('-- 权限点登记:与页面代码引用的权限码保持一致,避免「代码里有、数据库里却没有」的脱节');
  specs.forEach((s, idx) => {
    if (idx > 0) lines.push('');
    if (s.type === 'menu') {
      lines.push('INSERT INTO public.permissions (name, code, type)');
      lines.push(`SELECT '${s.name}', '${s.code}', 'menu'`);
      lines.push(`WHERE NOT EXISTS (SELECT 1 FROM public.permissions WHERE code = '${s.code}');`);
    } else {
      lines.push('INSERT INTO public.permissions (name, code, type, parent_id)');
      lines.push(`SELECT '${s.name}', '${s.code}', 'button', (SELECT id FROM public.permissions WHERE code = '${s.parentCode}')`);
      lines.push(`WHERE NOT EXISTS (SELECT 1 FROM public.permissions WHERE code = '${s.code}');`);
    }
  });
  return lines.join('\n');
}

export function buildTypes(table: TableDef, columns: ColumnDef[]) {
  const lines = [`export interface ${pascal(table.name)}Row {`];
  columns.forEach((c) => lines.push(`  ${c.name}: ${tsType(c)};`));
  lines.push('}');
  return lines.join('\n');
}

export function buildSql(table: TableDef, columns: ColumnDef[], ops?: GenOps) {
  const lines = [`CREATE TABLE public.${table.name} (`];
  const body = columns.map((c) => {
    if (c.primary) {
      const idType = c.type === 'number' ? 'bigserial' : 'uuid';
      const def = c.type === 'number' ? '' : ' DEFAULT gen_random_uuid()';
      return `  ${c.name} ${idType} PRIMARY KEY${def}`;
    }
    if (c.name === 'created_at') return `  ${c.name} timestamptz DEFAULT now()`;
    return `  ${c.name} ${sqlType(c)}`;
  });
  lines.push(body.join(',\n'));
  lines.push(');');
  lines.push('');
  lines.push(`ALTER TABLE public.${table.name} ENABLE ROW LEVEL SECURITY;`);
  lines.push(`CREATE POLICY ${table.name}_select ON public.${table.name} FOR SELECT TO authenticated USING (true);`);
  lines.push(
    `CREATE POLICY ${table.name}_write ON public.${table.name} FOR ALL TO authenticated USING (public.is_super_admin()) WITH CHECK (public.is_super_admin());`,
  );
  if (ops) {
    lines.push('');
    lines.push(buildPermissionSql(table, ops));
  }
  return lines.join('\n');
}

export function buildReact(table: TableDef, columns: ColumnDef[], ops: GenOps) {
  const typeName = `${pascal(table.name)}Row`;
  const componentName = `${pascal(table.name)}ManagePage`;
  const primary = columns.find((c) => c.primary) ?? columns[0];
  const editable = columns.filter((c) => !c.primary && c.name !== 'created_at');
  const searchable = editable.filter((c) => c.type === 'text');
  const display = columns.filter((c) => !c.primary);

  const L: string[] = [];
  const needsPerm = ops.create || ops.update || ops.delete;
  L.push('import { useCallback, useEffect, useMemo, useState } from "react";');
  L.push('import { supabase } from "@/lib/supabase";');
  L.push('import Modal from "@/components/base/Modal";');
  if (needsPerm) L.push('import { useAuth } from "@/contexts/AuthContext";');
  L.push('');
  L.push(buildTypes(table, columns));
  L.push('');
  L.push(`export default function ${componentName}() {`);
  L.push(`  const [rows, setRows] = useState<${typeName}[]>([]);`);
  L.push('  const [loading, setLoading] = useState(true);');
  L.push('  const [error, setError] = useState("");');
  if (ops.search) L.push('  const [keyword, setKeyword] = useState("");');
  if (ops.create || ops.update) {
    L.push('  const [formOpen, setFormOpen] = useState(false);');
    L.push(`  const [editing, setEditing] = useState<${typeName} | null>(null);`);
    L.push('  const [form, setForm] = useState<Record<string, string>>({});');
    L.push('  const [saving, setSaving] = useState(false);');
  }
  if (ops.delete) L.push(`  const [deleteTarget, setDeleteTarget] = useState<${typeName} | null>(null);`);
  if (needsPerm) {
    L.push('  const { hasPermission } = useAuth();');
    L.push(`  const canManage = hasPermission("menu:${table.name}");`);
    if (ops.create) L.push(`  const canCreate = canManage || hasPermission("${table.name}:create");`);
    if (ops.update) L.push(`  const canUpdate = canManage || hasPermission("${table.name}:update");`);
    if (ops.delete) L.push(`  const canDelete = canManage || hasPermission("${table.name}:delete");`);
  }
  L.push('');
  L.push('  const load = useCallback(async () => {');
  L.push('    setLoading(true);');
  L.push('    setError("");');
  L.push('    try {');
  L.push('      const { data, error: err } = await supabase');
  L.push(`        .from("${table.name}")`);
  L.push('        .select("*")');
  L.push('        .order("created_at", { ascending: false });');
  L.push('      if (err) throw err;');
  L.push(`      setRows((data as ${typeName}[]) ?? []);`);
  L.push('    } catch (err) {');
  L.push('      console.error(err);');
  L.push('      setError("数据加载失败,请重试");');
  L.push('    } finally {');
  L.push('      setLoading(false);');
  L.push('    }');
  L.push('  }, []);');
  L.push('');
  L.push('  useEffect(() => {');
  L.push('    load();');
  L.push('  }, [load]);');
  L.push('');

  if (ops.search && searchable.length > 0) {
    const cond = searchable
      .map((c) => `String(r.${c.name} ?? "").toLowerCase().includes(kw)`)
      .join(' || ');
    L.push('  const filtered = useMemo(() => {');
    L.push('    const kw = keyword.trim().toLowerCase();');
    L.push('    if (!kw) return rows;');
    L.push(`    return rows.filter((r) => ${cond});`);
    L.push('  }, [rows, keyword]);');
  } else {
    L.push('  const filtered = rows;');
  }
  L.push('');

  if (ops.create || ops.update) {
    L.push('  const openCreate = () => {');
    L.push('    setEditing(null);');
    L.push('    setForm({});');
    L.push('    setFormOpen(true);');
    L.push('  };');
    L.push('');
    L.push(`  const openEdit = (row: ${typeName}) => {`);
    L.push('    setEditing(row);');
    L.push('    setForm({');
    editable.forEach((c) => L.push(`      ${c.name}: String(row.${c.name} ?? ""),`));
    L.push('    });');
    L.push('    setFormOpen(true);');
    L.push('  };');
    L.push('');
    L.push('  const handleSubmit = async () => {');
    L.push('    setSaving(true);');
    L.push('    try {');
    L.push('      const payload: Record<string, unknown> = {');
    editable.forEach((c) => {
      if (c.type === 'number') L.push(`        ${c.name}: Number(form.${c.name}) || 0,`);
      else if (c.type === 'boolean') L.push(`        ${c.name}: form.${c.name} === "true",`);
      else L.push(`        ${c.name}: form.${c.name} ?? "",`);
    });
    L.push('      };');
    L.push('      if (editing) {');
    L.push(`        const { error: err } = await supabase.from("${table.name}").update(payload).eq("${primary.name}", editing.${primary.name});`);
    L.push('        if (err) throw err;');
    L.push('      } else {');
    L.push(`        const { error: err } = await supabase.from("${table.name}").insert(payload);`);
    L.push('        if (err) throw err;');
    L.push('      }');
    L.push('      setFormOpen(false);');
    L.push('      await load();');
    L.push('    } catch (err) {');
    L.push('      console.error(err);');
    L.push('      setError("保存失败,请检查权限后重试");');
    L.push('    } finally {');
    L.push('      setSaving(false);');
    L.push('    }');
    L.push('  };');
    L.push('');
  }

  if (ops.delete) {
    L.push('  const confirmDelete = async () => {');
    L.push('    if (!deleteTarget) return;');
    L.push('    try {');
    L.push(`      const { error: err } = await supabase.from("${table.name}").delete().eq("${primary.name}", deleteTarget.${primary.name});`);
    L.push('      if (err) throw err;');
    L.push('      setDeleteTarget(null);');
    L.push('      await load();');
    L.push('    } catch (err) {');
    L.push('      console.error(err);');
    L.push('      setError("删除失败,可能权限不足");');
    L.push('    }');
    L.push('  };');
    L.push('');
  }

  L.push('  return (');
  L.push('    <div className="space-y-4">');
  L.push('      <div className="flex flex-col md:flex-row md:items-center gap-3">');
  L.push(`        <h2 className="text-lg font-semibold text-foreground-950">${table.label}管理</h2>`);
  L.push('        <div className="md:ml-auto flex items-center gap-2">');
  if (ops.search) {
    L.push('          <input');
    L.push('            value={keyword}');
    L.push('            onChange={(e) => setKeyword(e.target.value)}');
    L.push('            placeholder="搜索…"');
    L.push('            className="h-9 px-3 rounded-md bg-background-50 border border-background-200 text-sm"');
    L.push('          />');
  }
  if (ops.create) {
    L.push('          <button type="button" onClick={openCreate} disabled={!canCreate} className="h-9 px-3.5 rounded-md bg-primary-500 text-background-50 text-sm whitespace-nowrap cursor-pointer disabled:opacity-50 dark:text-foreground-950">');
    L.push('            新增');
    L.push('          </button>');
  }
  L.push('        </div>');
  L.push('      </div>');
  L.push('');
  L.push('      {error ? <div className="px-3 py-2.5 rounded-md bg-accent-100 text-accent-900 text-sm">{error}</div> : null}');
  L.push('');
  L.push('      <div className="rounded-lg bg-background-50 border border-background-200 overflow-x-auto">');
  L.push('        <table className="w-full min-w-[640px] text-sm">');
  L.push('          <thead>');
  L.push('            <tr className="bg-background-100 text-left text-xs text-foreground-500">');
  display.forEach((c) => L.push(`              <th className="px-4 py-3 font-medium">${c.label}</th>`));
  if (ops.update || ops.delete) L.push('              <th className="px-4 py-3 font-medium text-right">操作</th>');
  L.push('            </tr>');
  L.push('          </thead>');
  L.push('          <tbody>');
  L.push('            {loading ? (');
  L.push('              <tr><td colSpan={99} className="px-4 py-10 text-center text-foreground-500">加载中…</td></tr>');
  L.push('            ) : filtered.length === 0 ? (');
  L.push('              <tr><td colSpan={99} className="px-4 py-10 text-center text-foreground-500">暂无数据</td></tr>');
  L.push('            ) : (');
  L.push('              filtered.map((row) => (');
  L.push(`                <tr key={String(row.${primary.name})} className="border-t border-background-200">`);
  display.forEach((c) => L.push(`                  <td className="px-4 py-3 text-foreground-800">{String(row.${c.name} ?? "-")}</td>`));
  if (ops.update || ops.delete) {
    L.push('                  <td className="px-4 py-3">');
    L.push('                    <div className="flex items-center justify-end gap-1">');
    if (ops.update) {
      L.push('                      <button type="button" onClick={() => openEdit(row)} disabled={!canUpdate} className="w-8 h-8 rounded-md hover:bg-background-200 text-foreground-500 cursor-pointer disabled:opacity-40">');
      L.push('                        <i className="ri-pencil-line"></i>');
      L.push('                      </button>');
    }
    if (ops.delete) {
      L.push('                      <button type="button" onClick={() => setDeleteTarget(row)} disabled={!canDelete} className="w-8 h-8 rounded-md hover:bg-secondary-200 text-foreground-500 cursor-pointer disabled:opacity-40">');
      L.push('                        <i className="ri-delete-bin-line"></i>');
      L.push('                      </button>');
    }
    L.push('                    </div>');
    L.push('                  </td>');
  }
  L.push('                </tr>');
  L.push('              ))');
  L.push('            )}');
  L.push('          </tbody>');
  L.push('        </table>');
  L.push('      </div>');

  if (ops.create || ops.update) {
    L.push('');
    L.push('      <Modal');
    L.push('        open={formOpen}');
    L.push('        title={editing ? "编辑" : "新增"}');
    L.push('        onClose={() => setFormOpen(false)}');
    L.push('        footer={(');
    L.push('          <>');
    L.push('            <button type="button" onClick={() => setFormOpen(false)} className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm cursor-pointer">取消</button>');
    L.push('            <button type="button" onClick={handleSubmit} disabled={saving} className="h-9 px-4 rounded-md bg-primary-500 text-background-50 text-sm cursor-pointer dark:text-foreground-950">{saving ? "保存中…" : "保存"}</button>');
    L.push('          </>');
    L.push('        )}');
    L.push('      >');
    L.push('        <div className="space-y-3.5">');
    editable.forEach((c) => {
      if (c.type === 'boolean') {
        L.push('          <label className="flex items-center gap-2 text-sm text-foreground-800">');
        L.push(`            ${c.label}`);
        L.push(`            <input type="checkbox" checked={form.${c.name} === "true"} onChange={(e) => setForm((p) => ({ ...p, ${c.name}: String(e.target.checked) }))} className="w-4 h-4 accent-primary-500 cursor-pointer" />`);
        L.push('          </label>');
      } else {
        L.push('          <div>');
        L.push(`            <label className="block text-xs font-medium text-foreground-700 mb-1.5">${c.label}</label>`);
        L.push(`            <input type="${inputType(c)}" value={form.${c.name} ?? ""} onChange={(e) => setForm((p) => ({ ...p, ${c.name}: e.target.value }))} className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm focus:outline-none focus:border-primary-400" />`);
        L.push('          </div>');
      }
    });
    L.push('        </div>');
    L.push('      </Modal>');
  }

  if (ops.delete) {
    L.push('');
    L.push('      <Modal');
    L.push('        open={Boolean(deleteTarget)}');
    L.push('        title="删除确认"');
    L.push('        onClose={() => setDeleteTarget(null)}');
    L.push('        footer={(');
    L.push('          <>');
    L.push('            <button type="button" onClick={() => setDeleteTarget(null)} className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm cursor-pointer">取消</button>');
    L.push('            <button type="button" onClick={confirmDelete} className="h-9 px-4 rounded-md bg-secondary-700 text-background-50 text-sm cursor-pointer">确认删除</button>');
    L.push('          </>');
    L.push('        )}');
    L.push('      >');
    L.push('        <p className="text-sm text-foreground-700">确定删除这条记录吗?此操作不可恢复。</p>');
    L.push('      </Modal>');
  }

  L.push('    </div>');
  L.push('  );');
  L.push('}');
  return L.join('\n');
}