import { useEffect, useRef, useState } from 'react';
import type { QuickScheme } from '@/pages/home/hooks/useQuickAccessSchemes';

interface QuickSchemeMenuProps {
  schemes: QuickScheme[];
  activeId: string;
  defaultId: string | null;
  activeName: string;
  currentCount: number;
  onSelect: (id: string) => void;
  onCreate: (name: string) => void;
  onRename: (id: string, name: string) => void;
  onDuplicate: (id: string) => void;
  onSetDefault: (id: string) => void;
  onCopyOrder: (id: string) => void;
  onDelete: (id: string) => void;
}

export default function QuickSchemeMenu({
  schemes,
  activeId,
  defaultId,
  activeName,
  currentCount,
  onSelect,
  onCreate,
  onRename,
  onDuplicate,
  onSetDefault,
  onCopyOrder,
  onDelete,
}: QuickSchemeMenuProps) {
  const [open, setOpen] = useState(false);
  const [creating, setCreating] = useState(false);
  const [newName, setNewName] = useState('');
  const [renamingId, setRenamingId] = useState<string | null>(null);
  const [renameValue, setRenameValue] = useState('');
  const [orderNotice, setOrderNotice] = useState('');
  const wrapRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) {
      setCreating(false);
      setNewName('');
      setRenamingId(null);
      setRenameValue('');
    }
  }, [open]);

  useEffect(() => {
    if (!open) return;
    const handler = (e: MouseEvent) => {
      if (wrapRef.current && !wrapRef.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, [open]);

  const submitCreate = () => {
    onCreate(newName);
    setCreating(false);
    setNewName('');
  };

  const submitRename = (id: string) => {
    onRename(id, renameValue);
    setRenamingId(null);
    setRenameValue('');
  };

  return (
    <div className="relative" ref={wrapRef}>
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        className="h-8 px-3 rounded-md bg-background-100 border border-background-300 text-xs text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5"
        aria-haspopup="true"
        aria-expanded={open}
      >
        <i className="ri-layout-grid-line text-primary-600"></i>
        <span className="max-w-[120px] truncate">{activeName}</span>
        <span className="text-[10px] text-foreground-400">{currentCount}</span>
        <i className={`ri-arrow-down-s-line transition-transform ${open ? 'rotate-180' : ''}`}></i>
      </button>

      {open ? (
        <div className="absolute right-0 z-30 mt-1.5 w-72 rounded-lg bg-background-50 border border-background-200 py-1.5 animate-fade-up">
          <p className="px-3 py-1.5 text-[11px] text-foreground-400">布局方案 · 可设为默认,登录后自动套用</p>
          <ul className="max-h-56 overflow-y-auto">
            {schemes.map((scheme) => {
              const on = scheme.id === activeId;
              if (renamingId === scheme.id) {
                return (
                  <li key={scheme.id} className="px-2.5 py-1.5">
                    <div className="flex items-center gap-1.5">
                      <input
                        autoFocus
                        value={renameValue}
                        onChange={(e) => setRenameValue(e.target.value)}
                        onKeyDown={(e) => {
                          if (e.key === 'Enter') submitRename(scheme.id);
                          if (e.key === 'Escape') setRenamingId(null);
                        }}
                        placeholder="方案名称"
                        className="flex-1 h-8 px-2 rounded-md bg-background-50 border border-primary-300 text-sm text-foreground-900 focus:outline-none"
                      />
                      <button
                        type="button"
                        onClick={() => submitRename(scheme.id)}
                        className="w-8 h-8 rounded-md bg-primary-500 text-background-50 flex items-center justify-center cursor-pointer dark:text-foreground-950"
                        aria-label="确认重命名"
                      >
                        <i className="ri-check-line"></i>
                      </button>
                    </div>
                  </li>
                );
              }
              return (
                <li key={scheme.id} className="group px-1.5">
                  <div className="flex items-center gap-1 rounded-md hover:bg-background-100">
                    <button
                      type="button"
                      onClick={() => {
                        onSelect(scheme.id);
                        setOpen(false);
                      }}
                      className="flex-1 min-w-0 flex items-center gap-2 px-2 py-2 text-left cursor-pointer"
                    >
                      <i
                        className={`text-[15px] ${on ? 'ri-radio-button-line text-primary-600' : 'ri-checkbox-blank-circle-line text-foreground-300'}`}
                      ></i>
                      <span className="flex-1 min-w-0">
                        <span className="flex items-center gap-1.5">
                          <span className={`block text-sm truncate ${on ? 'text-foreground-950 font-medium' : 'text-foreground-800'}`}>
                            {scheme.name}
                          </span>
                          {scheme.id === defaultId ? (
                            <span className="shrink-0 text-[10px] px-1.5 py-0.5 rounded-full bg-accent-100 text-accent-900 inline-flex items-center gap-0.5">
                              <i className="ri-pushpin-2-fill text-[9px]"></i>
                              默认
                            </span>
                          ) : null}
                        </span>
                        <span className="block text-[10px] text-foreground-400">{scheme.items.length} 个入口</span>
                      </span>
                    </button>
                    <div
                      className={`flex items-center gap-0.5 pr-1 transition-opacity ${
                        scheme.id === defaultId ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'
                      }`}
                    >
                      <button
                        type="button"
                        onClick={(e) => {
                          e.stopPropagation();
                          onSetDefault(scheme.id);
                        }}
                        aria-label={scheme.id === defaultId ? '取消默认方案' : '设为默认方案'}
                        title={scheme.id === defaultId ? '取消默认方案' : '设为默认方案,登录后自动套用'}
                        className={`w-7 h-7 rounded-md flex items-center justify-center cursor-pointer ${
                          scheme.id === defaultId
                            ? 'text-accent-600 hover:bg-accent-100'
                            : 'text-foreground-400 hover:bg-background-200 hover:text-foreground-800'
                        }`}
                      >
                        <i className={scheme.id === defaultId ? 'ri-pushpin-2-fill text-sm' : 'ri-pushpin-2-line text-sm'}></i>
                      </button>
                      <button
                        type="button"
                        onClick={(e) => {
                          e.stopPropagation();
                          onCopyOrder(scheme.id);
                          setOrderNotice(`已将「${scheme.name}」的入口顺序应用到其他方案`);
                          window.setTimeout(() => setOrderNotice(''), 2600);
                        }}
                        disabled={schemes.length <= 1}
                        aria-label="把本方案入口顺序应用到其他方案"
                        title={schemes.length <= 1 ? '至少需要两个方案' : '把本方案入口顺序应用到其他方案'}
                        className="w-7 h-7 rounded-md flex items-center justify-center text-foreground-400 hover:bg-background-200 hover:text-foreground-800 disabled:opacity-30 disabled:cursor-not-allowed cursor-pointer"
                      >
                        <i className="ri-sort-asc text-sm"></i>
                      </button>
                      <button
                        type="button"
                        onClick={(e) => {
                          e.stopPropagation();
                          setRenamingId(scheme.id);
                          setRenameValue(scheme.name);
                        }}
                        aria-label="重命名"
                        title="重命名"
                        className="w-7 h-7 rounded-md flex items-center justify-center text-foreground-400 hover:bg-background-200 hover:text-foreground-800 cursor-pointer"
                      >
                        <i className="ri-pencil-line text-sm"></i>
                      </button>
                      <button
                        type="button"
                        onClick={(e) => {
                          e.stopPropagation();
                          onDuplicate(scheme.id);
                        }}
                        aria-label="复制方案"
                        title="复制方案"
                        className="w-7 h-7 rounded-md flex items-center justify-center text-foreground-400 hover:bg-background-200 hover:text-foreground-800 cursor-pointer"
                      >
                        <i className="ri-file-copy-line text-sm"></i>
                      </button>
                      <button
                        type="button"
                        onClick={(e) => {
                          e.stopPropagation();
                          onDelete(scheme.id);
                        }}
                        disabled={schemes.length <= 1}
                        aria-label="删除方案"
                        title={schemes.length <= 1 ? '至少保留一个方案' : '删除方案'}
                        className="w-7 h-7 rounded-md flex items-center justify-center text-foreground-400 hover:bg-accent-100 hover:text-accent-700 disabled:opacity-30 disabled:cursor-not-allowed cursor-pointer"
                      >
                        <i className="ri-delete-bin-6-line text-sm"></i>
                      </button>
                    </div>
                  </div>
                </li>
              );
            })}
          </ul>
          <div className="border-t border-background-200 mt-1 pt-1 px-1.5">
            {orderNotice ? (
              <p className="mx-1 mb-1 px-2 py-1.5 rounded-md bg-primary-50 text-primary-800 text-[11px] flex items-center gap-1.5">
                <i className="ri-check-line"></i>
                {orderNotice}
              </p>
            ) : null}
            {creating ? (
              <div className="flex items-center gap-1.5 px-1 py-1.5">
                <input
                  autoFocus
                  value={newName}
                  onChange={(e) => setNewName(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter') submitCreate();
                    if (e.key === 'Escape') setCreating(false);
                  }}
                  placeholder="新方案名称,如「日常运营」"
                  className="flex-1 h-8 px-2 rounded-md bg-background-50 border border-primary-300 text-sm text-foreground-900 focus:outline-none"
                />
                <button
                  type="button"
                  onClick={submitCreate}
                  className="w-8 h-8 rounded-md bg-primary-500 text-background-50 flex items-center justify-center cursor-pointer dark:text-foreground-950"
                  aria-label="创建方案"
                >
                  <i className="ri-check-line"></i>
                </button>
              </div>
            ) : (
              <button
                type="button"
                onClick={() => setCreating(true)}
                className="w-full flex items-center gap-2 px-2 py-2 rounded-md text-sm text-primary-700 hover:bg-primary-50 cursor-pointer"
              >
                <i className="ri-add-line"></i>
                新建方案(复制当前布局)
              </button>
            )}
          </div>
        </div>
      ) : null}
    </div>
  );
}