import { useState } from 'react';
import { DocHeading } from '@/pages/docs/components/DocPrimitives';

const faqs = [
  {
    q: '菜单能看见但点进去被拦截,或反过来?',
    a: '这通常是菜单权限码和路由守卫用的权限码不一致导致的。两者的权限码都来自 src/config/nav.tsx 里的 permission 字段,统一改这一处即可。新增角色时别忘了把对应 menu:/button: 权限勾上。',
  },
  {
    q: '为什么新注册的账号只有访客权限?',
    a: '出于安全考虑,新注册账号默认只授予最小权限角色(viewer 访客),避免越权访问。仅当系统还没有任何超级管理员时(全新部署),第一个注册的账号才会自动成为超管用于初始化;之后更高权限请由超管在「用户管理」里手动分配。',
  },
  {
    q: '数据前端能看到,但保存时报权限错误?',
    a: '多半是行级安全策略(RLS)限制。读取通常是登录即可,写入一般限超级管理员。请检查对应表的策略,确认当前角色有写权限,或让超管账号执行写操作。',
  },
  {
    q: '切换租户后列表没变化?',
    a: '页面需要通过 useTenant() 拿到当前租户 id,并在查询时用它过滤(如 .eq("tenant_id", currentTenantId))。只接入上下文但查询没带过滤条件时,数据不会自动隔离。',
  },
  {
    q: '想接入支付/邮件这类私密服务怎么办?',
    a: '优先检查平台是否已有对应的内置集成,有的话直接连接即可。没有则通过后端 Edge Function 中转:私密密钥放在后端环境变量,前端只调用自己的函数,绝不把密钥写进前端代码。',
  },
  {
    q: '新增页面后路由和菜单怎么加?',
    a: '两步:一是在 src/router/config.tsx 的受保护路由 children 里加一条;二是在 src/config/nav.tsx 对应分组里加菜单项并声明权限码。这样侧边栏、工作台导航和面包屑会自动同步。',
  },
];

export default function FaqSection() {
  const [open, setOpen] = useState<number | null>(0);

  return (
    <div className="space-y-7">
      <DocHeading id="faq" sub="接入过程中的高频问题,点开即可查看解答。">
        常见问题
      </DocHeading>

      <div className="space-y-2.5">
        {faqs.map((item, idx) => {
          const expanded = open === idx;
          return (
            <div key={item.q} className="rounded-lg border border-background-200 bg-background-50 overflow-hidden">
              <button
                type="button"
                onClick={() => setOpen(expanded ? null : idx)}
                className="w-full flex items-center gap-3 px-4 py-3.5 text-left cursor-pointer hover:bg-background-100/60 transition-colors"
              >
                <span className="w-6 h-6 rounded-md bg-secondary-100 text-secondary-900 flex items-center justify-center shrink-0">
                  <i className="ri-question-line text-[13px]"></i>
                </span>
                <span className="flex-1 text-sm font-medium text-foreground-950">{item.q}</span>
                <i
                  className={`ri-arrow-down-s-line text-foreground-400 transition-transform duration-200 ${
                    expanded ? 'rotate-180' : ''
                  }`}
                ></i>
              </button>
              {expanded ? (
                <div className="px-4 pb-4 pl-13 animate-fade-in">
                  <p className="text-[13px] text-foreground-600 leading-relaxed">{item.a}</p>
                </div>
              ) : null}
            </div>
          );
        })}
      </div>
    </div>
  );
}