interface HighlightTextProps {
  text: string;
  keyword: string;
  className?: string;
}

function escapeRegExp(input: string) {
  return input.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/** 在文本中把命中的关键字高亮出来(大小写不敏感) */
export default function HighlightText({ text, keyword, className }: HighlightTextProps) {
  const kw = keyword.trim();
  if (!kw) return <span className={className}>{text}</span>;

  const parts = text.split(new RegExp(`(${escapeRegExp(kw)})`, 'ig'));
  return (
    <span className={className}>
      {parts.map((part, index) =>
        part.toLowerCase() === kw.toLowerCase() ? (
          <mark key={index} className="bg-accent-100 text-accent-900 rounded px-0.5">
            {part}
          </mark>
        ) : (
          <span key={index}>{part}</span>
        ),
      )}
    </span>
  );
}