import { useMemo } from 'react';
import { marketPlugins, type MarketPlugin } from '@/pages/plugins/marketCatalog';

interface MarketMyPanelProps {
  favorites: string[];
  owned: string[];
  ownedAt: Record<string, string>;
  recentViews: string[];
  lastSyncedAt: string;
  onOpenDetail: (plugin: MarketPlugin) => void;
  onToggleFavorite: (code: string) => void;
  onGoView: (view: string) => void;
  onClearViews: () => void;
}

function formatRelative(iso: string): string {
  const time = new Date(iso).getTime();
  if (Number.isNaN(time)) return '';
  const diff = Date.now() - time;
  const min = Math.floor(diff / 60000);
  if (min < 1) return '刚刚';
  if (min < 60) return `${min} 分钟前`;
  const hour = Math.floor(min / 60);
  if (hour < 24) return `${hour} 小时前`;
  const day = Math.floor(hour / 24);
  if (day < 30) return `${day} 天前`;
  return new Date(iso).toLocaleDateString('zh-CN');
}

export default function MarketMyPanel({
  favorites,
  owned,
  ownedAt,
  recentViews,
  lastSyncedAt,
  onOpenDetail,
  onToggleFavorite,
  onGoView,
  onClearViews,
}: MarketMyPanelProps) {
  const favoriteSet = useMemo(() => new Set(favorites), [favorites]);

  const viewedPlugins = useMemo(
    () =>
      recentViews
        .map((code) => marketPlugins.find((p) => p.code === code))
        .filter((p): p is MarketPlugin => Boolean(p)),
    [recentViews],
  );

  // 最近浏览列表首位即「上次浏览」的插件
  const lastViewed = viewedPlugins[0] ?? null;

  const recentInstalls = useMemo(() => {
    return Object.entries(ownedAt)
      .filter(([, at]) => Boolean(at))
      .map(([code, at]) => {
        const plugin = marketPlugins.find((p) => p.code === code);
        return plugin ? { plugin, at } : null;
      })
      .filter((item): item is { plugin: MarketPlugin; at: string } => Boolean(item))
      .sort((a, b) => new Date(b.at).getTime() - new Date(a.at).getTime())
      .slice(0, 6);
  }, [ownedAt]);

  const favoritePlugins = useMemo(
    () => marketPlugins.filter((p) => favoriteSet.has(p.code)),
    [favoriteSet],
  );

  const stats = [
    {
      key: 'favorites',
      label: '我的收藏',
      value: favorites.length,
      icon: 'ri-star-line',
      tone: 'bg-accent-100 text-accent-800',
      view: 'favorites',
    },
    {
      key: 'owned',
      label: '已购插件',
      value: owned.length,
      icon: 'ri-shopping-bag-3-line',
      tone: 'bg-primary-100 text-primary-700',
      view: 'owned',
    },
    {
      key: 'recent',
      label: '最近安装',
      value: recentInstalls.length,
      icon: 'ri-history-line',
      tone: 'bg-secondary-200 text-secondary-900',
      view: '',
    },
    {
      key: 'viewed',
      label: '最近浏览',
      value: viewedPlugins.length,
      icon: 'ri-eye-line',
      tone: 'bg-secondary-200 text-secondary-900',
      view: '',
    },
  ];

  return (
    <div className="space-y-5">
      <div className="flex flex-wrap items-center gap-x-3 gap-y-1.5 rounded-lg border border-background-200 bg-background-50 px-3.5 py-2.5">
        <span className="inline-flex items-center gap-1.5 text-xs text-foreground-600">
          <i className="ri-refresh-line text-secondary-700"></i>
          后端数据最近同步于
          <span className="font-medium text-foreground-900">
            {lastSyncedAt ? formatRelative(lastSyncedAt) : '暂无记录'}
          </span>
        </span>
        <span className="sm:ml-auto inline-flex items-center gap-1 text-[11px] text-foreground-400">
          <i className="ri-shield-check-line"></i>
          收藏与已购按你的账号保存
        </span>
      </div>

      <section className="grid grid-cols-2 lg:grid-cols-4 gap-3">
        {stats.map((s) => (
          <button
            key={s.key}
            type="button"
            onClick={() => s.view && onGoView(s.view)}
            disabled={!s.view}
            className={`rounded-lg border border-background-200 bg-background-50 p-4 text-left ${
              s.view ? 'cursor-pointer hover:border-primary-300 hover:bg-primary-50/40 transition-colors' : 'cursor-default'
            }`}
          >
            <div className="flex items-center gap-2">
              <span className={`w-8 h-8 rounded-md flex items-center justify-center ${s.tone}`}>
                <i className={`${s.icon} text-sm`}></i>
              </span>
              <span className="text-xs text-foreground-500">{s.label}</span>
            </div>
            <p className="mt-2.5 text-2xl font-semibold text-foreground-950 font-label">{s.value}</p>
          </button>
        ))}
      </section>

      <section>
        <div className="flex items-center justify-between gap-3 mb-2.5">
          <h4 className="text-sm font-semibold text-foreground-950 inline-flex items-center gap-1.5">
            <i className="ri-eye-line text-secondary-700"></i>
            最近浏览
            {viewedPlugins.length > 0 ? (
              <span className="text-[11px] font-normal text-foreground-400">共 {viewedPlugins.length} 条</span>
            ) : null}
          </h4>
          {viewedPlugins.length > 0 ? (
            <button
              type="button"
              onClick={onClearViews}
              className="text-xs text-foreground-500 hover:text-accent-700 cursor-pointer whitespace-nowrap inline-flex items-center gap-1"
            >
              <i className="ri-delete-bin-6-line"></i>
              清空足迹
            </button>
          ) : (
            <span className="text-[11px] text-foreground-400">按最近打开顺序排列</span>
          )}
        </div>
        {lastViewed ? (
          <button
            type="button"
            onClick={() => onOpenDetail(lastViewed)}
            className="group w-full mb-2.5 flex items-center gap-3 rounded-lg border border-secondary-200 bg-secondary-50 px-3.5 py-2.5 text-left hover:border-secondary-400 cursor-pointer transition-colors"
          >
            <span className="w-8 h-8 rounded-full flex items-center justify-center bg-secondary-100 text-secondary-800 shrink-0">
              <i className="ri-history-line text-base"></i>
            </span>
            <span className="min-w-0 flex-1">
              <span className="block text-[11px] text-foreground-500">回到上次浏览</span>
              <span className="block text-sm font-medium text-foreground-950 truncate">
                {lastViewed.name}
                <span className="ml-1.5 text-[10px] font-label font-normal text-foreground-400">v{lastViewed.version}</span>
              </span>
            </span>
            <span className="shrink-0 inline-flex items-center gap-1 text-[11px] text-secondary-800 whitespace-nowrap">
              打开
              <i className="ri-arrow-right-s-line group-hover:translate-x-0.5 transition-transform"></i>
            </span>
          </button>
        ) : null}
        {viewedPlugins.length === 0 ? (
          <div className="rounded-lg border border-dashed border-background-300 py-8 text-center text-sm text-foreground-500">
            <i className="ri-eye-line text-2xl block mb-2"></i>
            还没有浏览记录,点插件卡片上的「详情」去看看
          </div>
        ) : (
          <div className="flex flex-wrap gap-2">
            {viewedPlugins.map((plugin) => (
              <span
                key={plugin.code}
                className="inline-flex items-center gap-1.5 pl-1.5 pr-2.5 py-1 rounded-full bg-background-100 border border-background-200"
              >
                <span className="w-6 h-6 rounded-full flex items-center justify-center bg-secondary-100 text-secondary-800 shrink-0">
                  <i className="ri-plug-2-line text-[12px]"></i>
                </span>
                <button
                  type="button"
                  onClick={() => onOpenDetail(plugin)}
                  className="text-xs text-foreground-800 cursor-pointer whitespace-nowrap inline-flex items-center gap-1"
                >
                  {plugin.name}
                  <span className="text-[10px] font-label text-foreground-400">v{plugin.version}</span>
                </button>
              </span>
            ))}
          </div>
        )}
      </section>

      <section>
        <div className="flex items-center justify-between gap-3 mb-2.5">
          <h4 className="text-sm font-semibold text-foreground-950 inline-flex items-center gap-1.5">
            <i className="ri-history-line text-primary-600"></i>
            最近安装记录
          </h4>
          <button
            type="button"
            onClick={() => onGoView('owned')}
            className="text-xs text-foreground-500 hover:text-foreground-800 cursor-pointer whitespace-nowrap inline-flex items-center gap-1"
          >
            查看全部已购
            <i className="ri-arrow-right-s-line"></i>
          </button>
        </div>
        {recentInstalls.length === 0 ? (
          <div className="rounded-lg border border-dashed border-background-300 py-10 text-center text-sm text-foreground-500">
            <i className="ri-download-cloud-2-line text-2xl block mb-2"></i>
            还没有安装记录,去「可安装」里挑一个吧
          </div>
        ) : (
          <ul className="rounded-lg border border-background-200 bg-background-50 divide-y divide-background-200">
            {recentInstalls.map(({ plugin, at }) => (
              <li key={plugin.code} className="flex items-center gap-3 px-3.5 py-3">
                <span className="w-8 h-8 rounded-md flex items-center justify-center bg-primary-100 text-primary-700 shrink-0">
                  <i className="ri-plug-2-line text-base"></i>
                </span>
                <div className="min-w-0 flex-1">
                  <div className="flex flex-wrap items-center gap-2">
                    <span className="text-sm font-medium text-foreground-950 truncate">{plugin.name}</span>
                    <span className="text-[10px] font-label text-foreground-400">
                      {plugin.code} · v{plugin.version}
                    </span>
                  </div>
                  <span className="text-[11px] text-foreground-500 inline-flex items-center gap-1 mt-0.5">
                    <i className="ri-time-line"></i>
                    安装于 {formatRelative(at)}
                  </span>
                </div>
                <button
                  type="button"
                  onClick={() => onOpenDetail(plugin)}
                  className="shrink-0 h-8 px-2.5 rounded-md bg-background-100 border border-background-300 text-xs text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap inline-flex items-center gap-1"
                >
                  <i className="ri-information-line"></i>
                  详情
                </button>
              </li>
            ))}
          </ul>
        )}
      </section>

      <section>
        <div className="flex items-center justify-between gap-3 mb-2.5">
          <h4 className="text-sm font-semibold text-foreground-950 inline-flex items-center gap-1.5">
            <i className="ri-star-line text-accent-600"></i>
            收藏的插件
          </h4>
          <button
            type="button"
            onClick={() => onGoView('favorites')}
            className="text-xs text-foreground-500 hover:text-foreground-800 cursor-pointer whitespace-nowrap inline-flex items-center gap-1"
          >
            查看全部收藏
            <i className="ri-arrow-right-s-line"></i>
          </button>
        </div>
        {favoritePlugins.length === 0 ? (
          <div className="rounded-lg border border-dashed border-background-300 py-8 text-center text-sm text-foreground-500">
            <i className="ri-star-line text-2xl block mb-2"></i>
            还没有收藏,点卡片右上角的星标就能收藏
          </div>
        ) : (
          <div className="flex flex-wrap gap-2">
            {favoritePlugins.map((plugin) => (
              <span
                key={plugin.code}
                className="inline-flex items-center gap-1.5 pl-2.5 pr-1.5 py-1 rounded-full bg-background-100 border border-background-200"
              >
                <button
                  type="button"
                  onClick={() => onOpenDetail(plugin)}
                  className="text-xs text-foreground-800 cursor-pointer whitespace-nowrap inline-flex items-center gap-1"
                >
                  {plugin.name}
                  <span className="text-[10px] font-label text-foreground-400">v{plugin.version}</span>
                </button>
                <button
                  type="button"
                  onClick={() => onToggleFavorite(plugin.code)}
                  aria-label="取消收藏"
                  title="取消收藏"
                  className="w-5 h-5 rounded-full flex items-center justify-center text-accent-600 hover:bg-accent-100 cursor-pointer"
                >
                  <i className="ri-star-fill text-[11px]"></i>
                </button>
              </span>
            ))}
          </div>
        )}
      </section>
    </div>
  );
}