import { useState } from 'react';
import Modal from '@/components/base/Modal';

interface OpenApiModalProps {
  open: boolean;
  spec: unknown;
  onClose: () => void;
}

export default function OpenApiModal({ open, spec, onClose }: OpenApiModalProps) {
  const [copied, setCopied] = useState(false);
  const json = JSON.stringify(spec, null, 2);

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(json);
      setCopied(true);
      setTimeout(() => setCopied(false), 1600);
    } catch (err) {
      console.error(err);
    }
  };

  const download = () => {
    const blob = new Blob([json], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'openapi.json';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  return (
    <Modal
      open={open}
      title="OpenAPI 3.0 预览"
      subtitle="符合 OpenAPI 3.0.3 规范,可直接导入 Swagger / Postman"
      width="max-w-3xl"
      onClose={onClose}
      footer={
        <>
          <button
            type="button"
            onClick={copy}
            className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5"
          >
            <i className={copied ? 'ri-check-line' : 'ri-file-copy-line'}></i>
            {copied ? '已复制' : '复制 JSON'}
          </button>
          <button
            type="button"
            onClick={download}
            className="h-9 px-4 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5 dark:text-foreground-950"
          >
            <i className="ri-download-2-line"></i>
            下载 openapi.json
          </button>
        </>
      }
    >
      <pre className="rounded-md border border-background-200 bg-background-50 px-3.5 py-3 text-xs leading-relaxed font-label text-foreground-800 overflow-x-auto max-h-[52vh]">
        {json}
      </pre>
    </Modal>
  );
}