export interface SdkVersion {
  key: string;
  label: string;
  tag: string;
  desc: string;
}

/** 框架主版本,用于切换不同版本下的片段写法 */
export const sdkVersions: SdkVersion[] = [
  {
    key: 'v2',
    label: '框架 v2.x',
    tag: '推荐',
    desc: '当前稳定版,统一单例客户端、maybeSingle 与 useAuth 写法',
  },
  {
    key: 'v1',
    label: '框架 v1.x',
    tag: '兼容',
    desc: '旧版接入方式,便于存量项目对照迁移',
  },
];

export const defaultSdkVersion = 'v2';

export interface SdkStack {
  key: string;
  label: string;
  tag: string;
  desc: string;
}

/** 技术栈,用于切换同一功能在不同前端框架下的写法 */
export const sdkStacks: SdkStack[] = [
  { key: 'react', label: 'React', tag: '默认', desc: '函数组件 + Hooks,对应框架内置页面写法' },
  { key: 'vue', label: 'Vue 3', tag: '组合式', desc: '组合式 API(setup):ref / watch / inject 写法' },
  { key: 'vanilla', label: '纯 JS', tag: '无框架', desc: '不依赖框架,原生模块与 DOM 事件写法' },
];

export const defaultSdkStack = 'react';

export interface SdkSnippet {
  id: string;
  title: string;
  desc: string;
  language: string;
  filename: string;
  code: string;
  /** 特定框架版本下的替代写法(键为版本 key),缺省表示各版本写法一致 */
  variants?: Record<string, string>;
  /** 特定技术栈下的替代写法(键为栈 key),缺省表示各技术栈写法一致 */
  stacks?: Record<string, string>;
  /** 特定技术栈下的文件名(如切换为 .vue / .js) */
  stackFilenames?: Record<string, string>;
}

/** 取某版本 + 技术栈下片段的实际代码 */
export function snippetCodeFor(
  snippet: SdkSnippet,
  version: string = defaultSdkVersion,
  stack: string = defaultSdkStack,
): string {
  if (stack !== defaultSdkStack) {
    return snippet.stacks?.[stack] ?? snippet.code;
  }
  if (version === defaultSdkVersion) return snippet.code;
  return snippet.variants?.[version] ?? snippet.code;
}

/** 取某技术栈下片段的文件名 */
export function snippetFilenameFor(
  snippet: SdkSnippet,
  stack: string = defaultSdkStack,
): string {
  return snippet.stackFilenames?.[stack] ?? snippet.filename;
}

/** 该片段在指定版本下是否有独立写法 */
export function snippetHasVariant(snippet: SdkSnippet, version: string): boolean {
  if (version === defaultSdkVersion) return true;
  return Boolean(snippet.variants?.[version]);
}

/** 该片段在指定技术栈下是否有独立写法 */
export function snippetHasStack(snippet: SdkSnippet, stack: string): boolean {
  if (stack === defaultSdkStack) return true;
  return Boolean(snippet.stacks?.[stack]);
}

