import { useEffect, useMemo, useState } from 'react';
import Modal from '@/components/base/Modal';
import type { QuickScheme } from '@/pages/home/hooks/useQuickAccessSchemes';

interface QuickAccessShareModalProps {
  open: boolean;
  schemes: QuickScheme[];
  activeId: string;
  validKeys: string[];
  labelOf: (key: string) => string;
  onImport: (name: string, keys: string[]) => void;
  onClose: () => void;
}

interface LayoutPayload {
  app: string;
  type: string;
  version: number;
  exportedAt: string;
  name: string;
  items: string[];
}

function buildPayload(name: string, keys: string[]): LayoutPayload {
  return {
    app: 'HuaanAdmin',
    type: 'quick-access-layout',
    version: 2,
    exportedAt: new Date().toISOString(),
    name,
    items: keys,
  };
}

/** 从粘贴内容里尽量解析出方案名与入口列表 */
function parsePayload(text: string): { name: string; items: unknown[] } | null {
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch (err) {
    console.error(err);
    return null;
  }
  if (Array.isArray(parsed)) {
    return { name: '', items: parsed };
  }
  if (parsed && typeof parsed === 'object') {
    const obj = parsed as { name?: unknown; items?: unknown };
    if (Array.isArray(obj.items)) {
      return { name: typeof obj.name === 'string' ? obj.name : '', items: obj.items };
    }
  }
  return null;
}

export default function QuickAccessShareModal({
  open,
  schemes,
  activeId,
  validKeys,
  labelOf,
  onImport,
  onClose,
}: QuickAccessShareModalProps) {
  const [tab, setTab] = useState<'export' | 'import'>('export');
  const [copied, setCopied] = useState(false);
  const [raw, setRaw] = useState('');
  const [exportId, setExportId] = useState(activeId);
  const [importName, setImportName] = useState('');
  const [feedback, setFeedback] = useState<{ tone: 'ok' | 'err'; text: string } | null>(null);

  useEffect(() => {
    if (open) {
      setExportId(activeId);
    } else {
      setTab('export');
      setRaw('');
      setFeedback(null);
      setCopied(false);
      setImportName('');
    }
  }, [open, activeId]);

  const exportScheme = useMemo(
    () => schemes.find((s) => s.id === exportId) ?? schemes[0],
    [schemes, exportId],
  );
  const exportKeys = exportScheme?.items ?? [];
  const exportText = useMemo(
    () => JSON.stringify(buildPayload(exportScheme?.name ?? '我的方案', exportKeys), null, 2),
    [exportScheme, exportKeys],
  );

  // 粘贴内容变化时,若还没手动命名,自动带出文件里的方案名
  useEffect(() => {
    if (tab !== 'import') return;
    const text = raw.trim();
    if (!text) return;
    const parsed = parsePayload(text);
    if (parsed && parsed.name && !importName.trim()) {
      setImportName(`${parsed.name} (导入)`);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [raw, tab]);

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(exportText);
      setCopied(true);
      window.setTimeout(() => setCopied(false), 1600);
    } catch (err) {
      console.error(err);
    }
  };

  const download = () => {
    try {
      const blob = new Blob([exportText], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      const safeName = (exportScheme?.name ?? 'layout').replace(/[^\w\u4e00-\u9fa5-]+/g, '-');
      a.download = `quick-access-${safeName}.json`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    } catch (err) {
      console.error(err);
    }
  };

  const applyImport = () => {
    const text = raw.trim();
    if (!text) {
      setFeedback({ tone: 'err', text: '请先粘贴布局 JSON 内容' });
      return;
    }
    const parsed = parsePayload(text);
    if (!parsed) {
      setFeedback({ tone: 'err', text: 'JSON 格式不正确,请检查后重试' });
      return;
    }
    const validSet = new Set(validKeys);
    const cleaned = Array.from(
      new Set(parsed.items.filter((k): k is string => typeof k === 'string')),
    ).filter((k) => validSet.has(k));
    const skipped = parsed.items.length - cleaned.length;
    if (cleaned.length === 0) {
      setFeedback({ tone: 'err', text: '导入的菜单都不在当前账号可访问范围内' });
      return;
    }
    const finalName = importName.trim() || parsed.name || '导入方案';
    onImport(finalName, cleaned);
    setFeedback({
      tone: 'ok',
      text:
        skipped > 0
          ? `已存为新方案「${finalName}」,共 ${cleaned.length} 个入口,跳过 ${skipped} 个不可用项`
          : `已存为新方案「${finalName}」,共 ${cleaned.length} 个入口`,
    });
    setRaw('');
    setImportName('');
  };

  return (
    <Modal
      open={open}
      title="共享快捷入口布局"
      subtitle="可导出某一套布局方案发给同事,对方导入后会存成自己的一套新方案"
      onClose={onClose}
      width="max-w-xl"
      footer={
        <button
          type="button"
          onClick={onClose}
          className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
        >
          关闭
        </button>
      }
    >
      <div className="flex items-center gap-1 p-1 rounded-full bg-background-100 border border-background-200 w-fit mb-4">
        {[
          { key: 'export' as const, label: '导出方案', icon: 'ri-upload-2-line' },
          { key: 'import' as const, label: '导入为新方案', icon: 'ri-download-2-line' },
        ].map((t) => (
          <button
            key={t.key}
            type="button"
            onClick={() => {
              setTab(t.key);
              setFeedback(null);
            }}
            className={`px-3.5 py-1.5 rounded-full text-xs cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5 transition-colors ${
              tab === t.key
                ? 'bg-background-50 text-foreground-950 font-medium'
                : 'text-foreground-600 hover:text-foreground-900'
            }`}
          >
            <i className={t.icon}></i>
            {t.label}
          </button>
        ))}
      </div>

      {tab === 'export' ? (
        <div className="space-y-3">
          <div>
            <p className="text-[11px] font-medium text-foreground-500 mb-1.5">选择要导出的方案</p>
            <div className="rounded-md border border-background-200 bg-background-50 max-h-40 overflow-y-auto divide-y divide-background-200">
              {schemes.map((scheme) => {
                const on = scheme.id === exportScheme?.id;
                return (
                  <button
                    key={scheme.id}
                    type="button"
                    onClick={() => setExportId(scheme.id)}
                    className={`w-full flex items-center gap-2.5 px-3 py-2.5 text-left cursor-pointer transition-colors ${
                      on ? 'bg-primary-50' : 'hover:bg-background-100'
                    }`}
                  >
                    <i
                      className={`text-[15px] ${on ? 'ri-radio-button-line text-primary-600' : 'ri-checkbox-blank-circle-line text-foreground-300'}`}
                    ></i>
                    <span className="min-w-0 flex-1">
                      <span className={`block text-sm truncate ${on ? 'text-primary-800 font-medium' : 'text-foreground-800'}`}>
                        {scheme.name}
                      </span>
                      <span className="block text-[10px] text-foreground-400">{scheme.items.length} 个入口</span>
                    </span>
                    {scheme.id === activeId ? (
                      <span className="shrink-0 text-[10px] px-1.5 py-0.5 rounded-full bg-secondary-100 text-secondary-900">
                        当前使用
                      </span>
                    ) : null}
                  </button>
                );
              })}
            </div>
          </div>
          <div className="flex flex-wrap items-center gap-2 text-xs text-foreground-600">
            <span className="inline-flex items-center gap-1">
              <i className="ri-layout-grid-line text-primary-600"></i>
              「{exportScheme?.name}」共 {exportKeys.length} 个入口
            </span>
            <span className="inline-flex items-center gap-1">
              <i className="ri-drag-move-2-line text-foreground-400"></i>
              导出内容包含入口顺序
            </span>
          </div>
          <textarea
            readOnly
            value={exportText}
            rows={9}
            className="w-full rounded-md border border-background-200 bg-background-100 px-3 py-2.5 font-label text-[12.5px] leading-relaxed text-foreground-800 resize-none focus:outline-none"
          />
          <div className="flex flex-wrap items-center gap-2">
            <button
              type="button"
              onClick={copy}
              className="h-9 px-3.5 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5 dark:text-foreground-950"
            >
              <i className={copied ? 'ri-check-line' : 'ri-file-copy-line'}></i>
              {copied ? '已复制' : '复制 JSON'}
            </button>
            <button
              type="button"
              onClick={download}
              className="h-9 px-3.5 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5"
            >
              <i className="ri-download-2-line"></i>
              下载文件
            </button>
          </div>
        </div>
      ) : (
        <div className="space-y-3">
          <p className="text-xs text-foreground-600 leading-relaxed">
            粘贴同事分享的布局 JSON(支持整份文件或直接的 items 数组)。导入不会覆盖你现有方案,而是**另存为一套新方案**,仅保留你有权限访问的菜单。
          </p>
          <textarea
            value={raw}
            onChange={(e) => {
              setRaw(e.target.value);
              setFeedback(null);
            }}
            rows={8}
            placeholder='{ "name": "日常运营", "items": ["monitor", "plugins"] }'
            className="w-full rounded-md border border-background-200 bg-background-50 px-3 py-2.5 font-label text-[12.5px] leading-relaxed text-foreground-800 resize-none focus:outline-none focus:border-primary-300"
          />
          <div>
            <label className="block text-[11px] font-medium text-foreground-500 mb-1.5" htmlFor="import-scheme-name">
              新方案名称
            </label>
            <div className="flex items-center gap-2 h-9 px-3 rounded-md bg-background-50 border border-background-200">
              <i className="ri-price-tag-3-line text-foreground-400 text-sm"></i>
              <input
                id="import-scheme-name"
                type="text"
                value={importName}
                onChange={(e) => setImportName(e.target.value)}
                placeholder="留空则自动命名为「导入方案」"
                className="flex-1 bg-transparent text-sm text-foreground-900 placeholder:text-foreground-400 focus:outline-none"
              />
            </div>
          </div>
          {feedback ? (
            <div
              className={`flex items-center gap-2 px-3 py-2 rounded-md text-xs ${
                feedback.tone === 'ok'
                  ? 'bg-primary-50 text-primary-800'
                  : 'bg-accent-100 text-accent-900'
              }`}
            >
              <i className={feedback.tone === 'ok' ? 'ri-checkbox-circle-line' : 'ri-error-warning-line'}></i>
              {feedback.text}
            </div>
          ) : null}
          <div className="rounded-md bg-background-100 border border-background-200 px-3 py-2.5">
            <p className="text-[11px] text-foreground-500 mb-1.5">可导入的菜单({validKeys.length})</p>
            <div className="flex flex-wrap gap-1.5">
              {validKeys.map((k) => (
                <span
                  key={k}
                  className="text-[10px] px-2 py-0.5 rounded-full bg-background-200 text-foreground-700"
                >
                  {labelOf(k)}
                </span>
              ))}
            </div>
          </div>
          <button
            type="button"
            onClick={applyImport}
            className="h-9 px-3.5 rounded-md bg-accent-500 text-background-50 text-sm hover:bg-accent-600 cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5 dark:text-foreground-950"
          >
            <i className="ri-check-double-line"></i>
            存为新方案
          </button>
        </div>
      )}
    </Modal>
  );
}