import { useEffect, type ReactNode } from 'react';

interface ModalProps {
  open: boolean;
  title: string;
  subtitle?: string;
  onClose: () => void;
  children: ReactNode;
  footer?: ReactNode;
  width?: string;
}

export default function Modal({
  open,
  title,
  subtitle,
  onClose,
  children,
  footer,
  width = 'max-w-lg',
}: ModalProps) {
  useEffect(() => {
    if (!open) return;
    const handler = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    document.addEventListener('keydown', handler);
    return () => document.removeEventListener('keydown', handler);
  }, [open, onClose]);

  if (!open) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div
        className="absolute inset-0 bg-foreground-950/40 animate-fade-in"
        onClick={onClose}
        aria-hidden="true"
      />
      <div className={`relative w-full ${width} rounded-lg bg-background-50 border border-background-200 animate-fade-up`}>
        <div className="flex items-start justify-between gap-4 px-5 py-4 border-b border-background-200">
          <div>
            <h3 className="text-base font-semibold text-foreground-950">{title}</h3>
            {subtitle ? <p className="mt-0.5 text-xs text-foreground-500">{subtitle}</p> : null}
          </div>
          <button
            type="button"
            onClick={onClose}
            className="shrink-0 w-8 h-8 flex items-center justify-center rounded-md text-foreground-500 hover:bg-background-100 hover:text-foreground-900 cursor-pointer"
            aria-label="关闭"
          >
            <i className="ri-close-line text-lg"></i>
          </button>
        </div>
        <div className="px-5 py-4 max-h-[65vh] overflow-y-auto">{children}</div>
        {footer ? (
          <div className="flex items-center justify-end gap-2 px-5 py-4 border-t border-background-200">
            {footer}
          </div>
        ) : null}
      </div>
    </div>
  );
}