import type { ReactNode } from 'react';
import { Navigate, useLocation } from 'react-router-dom';
import { useAuth } from '@/contexts/AuthContext';

export default function RequireAuth({ children }: { children: ReactNode }) {
  const { session, profile, loading, profileLoading, isPendingApproval } = useAuth();
  const location = useLocation();

  if (loading || profileLoading) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center gap-3 bg-background-100">
        <div className="w-9 h-9 rounded-full border-2 border-background-300 border-t-primary-500 animate-spin" />
        <p className="text-sm text-foreground-500">正在加载工作台…</p>
      </div>
    );
  }

  if (!session) {
    return <Navigate to="/auth" replace state={{ from: location.pathname }} />;
  }

  // Members (or accounts without an admin profile) must not reach the admin shell.
  if (!profile) {
    const isMember = session.user?.user_metadata?.account_type === 'member';
    return <Navigate to={isMember ? '/member' : '/auth'} replace />;
  }

  // 仅有访客权限的新账号:引导到「等待分配权限」提示页
  if (isPendingApproval) {
    return <Navigate to="/pending" replace />;
  }

  return <>{children}</>;
}