import { useCallback, useEffect, useMemo, useRef, useState, type ChangeEvent } from 'react';
import { supabase } from '@/lib/supabase';
import { useAuth } from '@/contexts/AuthContext';
import { useTenant } from '@/contexts/TenantContext';
import Modal from '@/components/base/Modal';
import { useDataScope, dataScopeLabel } from '@/hooks/useDataScope';
import { moveToRecycleBin } from '@/lib/recycleBin';
import { recordAuditLog } from '@/lib/auditLog';
import {
  buildDeptTree,
  flattenDeptTree,
  type DepartmentRow,
  type DeptNode,
} from '@/lib/departments';
import UserFormModal, {
  type RoleOption,
  type TenantOption,
  type UserFormValues,
} from '@/pages/system/users/components/UserFormModal';
import AssignRoleModal from '@/pages/system/users/components/AssignRoleModal';
import BatchAssignRoleModal, {
  type AssignMode,
  type BatchUser,
} from '@/pages/system/users/components/BatchAssignRoleModal';

interface ProfileRow {
  id: string;
  email: string | null;
  full_name: string | null;
  status: string | null;
  tenant_id: string | null;
  department: string | null;
  department_id: string | null;
  account_type: string | null;
  created_at: string | null;
}

interface UserRoleRow {
  user_id: string;
  role_id: string;
}

const DEMO_CLEANUP_DAYS = 7;

const avatarTones = [
  'bg-primary-100 text-primary-700',
  'bg-accent-100 text-accent-800',
  'bg-secondary-200 text-secondary-900',
  'bg-primary-200 text-primary-800',
];

function initials(name: string) {
  return name.slice(0, 1).toUpperCase();
}

function formatDate(iso: string | null) {
  if (!iso) return '—';
  const d = new Date(iso);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

export default function UsersPage() {
  const { hasPermission, hasRole, user } = useAuth();
  const { currentTenantId, currentTenant } = useTenant();
  const { scope: dataScope, department: myDepartment, departmentIds, userId: myUserId } = useDataScope();
  const canCreate = hasPermission('user:create');
  const canUpdate = hasPermission('user:update');
  const canDelete = hasPermission('user:delete');
  const canAssign = hasPermission('user:assign_role');
  const isSuperAdmin = hasRole('super_admin');

  const [profiles, setProfiles] = useState<ProfileRow[]>([]);
  const [roles, setRoles] = useState<RoleOption[]>([]);
  const [tenants, setTenants] = useState<TenantOption[]>([]);
  const [departmentRows, setDepartmentRows] = useState<DepartmentRow[]>([]);
  const [userRoles, setUserRoles] = useState<UserRoleRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');

  const [keyword, setKeyword] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [roleFilter, setRoleFilter] = useState('all');
  const [viewFilter, setViewFilter] = useState<'all' | 'pending'>('all');

  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [batchOpen, setBatchOpen] = useState(false);
  const [batchSaving, setBatchSaving] = useState(false);

  const [formOpen, setFormOpen] = useState(false);
  const [editing, setEditing] = useState<ProfileRow | null>(null);
  const [saving, setSaving] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState<ProfileRow | null>(null);
  const [assignTarget, setAssignTarget] = useState<ProfileRow | null>(null);
  const [assignSaving, setAssignSaving] = useState(false);
  const [importing, setImporting] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const cleanupRanRef = useRef(false);

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const [profRes, rolesRes, tenantsRes, urRes, deptRes] = await Promise.all([
        supabase.from('profiles').select('*').order('created_at', { ascending: false }),
        supabase.from('roles').select('id, name, code').order('created_at', { ascending: true }),
        supabase.from('tenants').select('id, name').order('created_at', { ascending: true }),
        supabase.from('user_roles').select('user_id, role_id'),
        supabase.from('departments').select('*').order('sort_order', { ascending: true }),
      ]);
      if (profRes.error) throw profRes.error;
      setProfiles((profRes.data as ProfileRow[]) ?? []);
      setRoles((rolesRes.data as RoleOption[]) ?? []);
      setTenants((tenantsRes.data as TenantOption[]) ?? []);
      setUserRoles((urRes.data as UserRoleRow[]) ?? []);
      setDepartmentRows((deptRes.data as DepartmentRow[]) ?? []);
    } catch (err) {
      console.error(err);
      setError('加载用户数据失败,请重试');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  useEffect(() => {
    if (!notice) return;
    const timer = setTimeout(() => setNotice(''), 3200);
    return () => clearTimeout(timer);
  }, [notice]);

  // 演示账号自动退场:超管进入用户管理时静默清理超过阈值的体验账号
  useEffect(() => {
    if (!isSuperAdmin || cleanupRanRef.current) return;
    cleanupRanRef.current = true;
    (async () => {
      try {
        const { data, error: fnErr } = await supabase.functions.invoke('cleanup-demo-accounts', {
          body: { maxAgeDays: DEMO_CLEANUP_DAYS },
        });
        if (fnErr) return;
        const deleted = (data as { deleted?: number } | null)?.deleted ?? 0;
        if (deleted > 0) {
          setNotice(`已自动清理 ${deleted} 个超过 ${DEMO_CLEANUP_DAYS} 天未使用的演示账号`);
          await load();
        }
      } catch (err) {
        console.error('cleanup demo accounts failed', err);
      }
    })();
  }, [isSuperAdmin, load]);

  const roleById = useMemo(() => {
    const map = new Map<string, string>();
    roles.forEach((r) => map.set(r.id, r.name));
    return map;
  }, [roles]);

  const viewerRoleId = useMemo(
    () => roles.find((r) => r.code === 'viewer')?.id ?? null,
    [roles],
  );

  const superAdminRoleId = useMemo(
    () => roles.find((r) => r.code === 'super_admin')?.id ?? null,
    [roles],
  );

  const tenantById = useMemo(() => {
    const map = new Map<string, string>();
    tenants.forEach((t) => map.set(t.id, t.name));
    return map;
  }, [tenants]);

  const deptList = useMemo<DeptNode[]>(
    () => flattenDeptTree(buildDeptTree(departmentRows)),
    [departmentRows],
  );

  const deptById = useMemo(() => {
    const map = new Map<string, string>();
    deptList.forEach((d) => map.set(d.id, d.name));
    return map;
  }, [deptList]);

  const rolesByUser = useMemo(() => {
    const map = new Map<string, string[]>();
    userRoles.forEach((ur) => {
      const list = map.get(ur.user_id) ?? [];
      list.push(ur.role_id);
      map.set(ur.user_id, list);
    });
    return map;
  }, [userRoles]);

  // 仅有访客角色(或没有角色)且非演示账号 → 等待管理员分配权限
  const isPendingUser = useCallback(
    (p: ProfileRow) => {
      if (p.account_type === 'demo') return false;
      const ids = rolesByUser.get(p.id) ?? [];
      if (ids.length === 0) return true;
      return ids.length === 1 && ids[0] === viewerRoleId;
    },
    [rolesByUser, viewerRoleId],
  );

  // 范围(租户/数据权限)内的用户,供「待分配」统计使用
  const scopedProfiles = useMemo(() => {
    return profiles.filter((p) => {
      const matchTenant = currentTenantId === 'all' || p.tenant_id === currentTenantId;
      const matchScope =
        dataScope === 'all' ||
        (dataScope === 'self'
          ? p.id === myUserId
          : Boolean(p.department_id) && departmentIds.includes(p.department_id as string));
      return matchTenant && matchScope;
    });
  }, [profiles, currentTenantId, dataScope, departmentIds, myUserId]);

  const pendingCount = useMemo(
    () => scopedProfiles.filter((p) => isPendingUser(p)).length,
    [scopedProfiles, isPendingUser],
  );

  const filtered = useMemo(() => {
    return scopedProfiles.filter((p) => {
      const kw = keyword.trim().toLowerCase();
      const matchKw =
        !kw ||
        (p.full_name ?? '').toLowerCase().includes(kw) ||
        (p.email ?? '').toLowerCase().includes(kw);
      const matchStatus = statusFilter === 'all' || (p.status ?? 'active') === statusFilter;
      const matchRole =
        roleFilter === 'all' || (rolesByUser.get(p.id) ?? []).includes(roleFilter);
      const matchView = viewFilter === 'all' || isPendingUser(p);
      return matchKw && matchStatus && matchRole && matchView;
    });
  }, [scopedProfiles, keyword, statusFilter, roleFilter, viewFilter, rolesByUser, isPendingUser]);

  const batchUsers = useMemo<BatchUser[]>(
    () =>
      scopedProfiles.map((p) => ({
        id: p.id,
        name: p.full_name || p.email || '未命名',
        email: p.email,
        departmentId: p.department_id,
        departmentName: p.department_id ? deptById.get(p.department_id) ?? null : p.department,
        tenantId: p.tenant_id,
        tenantName: p.tenant_id ? tenantById.get(p.tenant_id) ?? null : null,
      })),
    [scopedProfiles, deptById, tenantById],
  );

  const allFilteredSelected =
    filtered.length > 0 && filtered.every((p) => selectedIds.includes(p.id));

  const toggleSelectAll = () => {
    if (allFilteredSelected) {
      setSelectedIds((prev) => prev.filter((id) => !filtered.some((p) => p.id === id)));
    } else {
      setSelectedIds((prev) => Array.from(new Set([...prev, ...filtered.map((p) => p.id)])));
    }
  };

  const toggleSelect = (id: string) => {
    setSelectedIds((prev) => (prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id]));
  };

  const openCreate = () => {
    setEditing(null);
    setFormOpen(true);
  };

  const openEdit = (p: ProfileRow) => {
    setEditing(p);
    setFormOpen(true);
  };

  // 按差异增量保存角色:只增补缺失的、只删除被移除的。
  // 避免「先清空再写入」导致超管编辑自己时先删掉自己的超管身份、后续写入被数据库拒绝(自我锁死)。
  const saveUserRoles = async (userId: string, nextRoleIds: string[]) => {
    const current = rolesByUser.get(userId) ?? [];
    // 保护最后一名超级管理员:无论改的是谁,只要移除后系统将不再有任何超管就拦截
    if (
      superAdminRoleId &&
      current.includes(superAdminRoleId) &&
      !nextRoleIds.includes(superAdminRoleId)
    ) {
      const otherHolders = userRoles.filter(
        (ur) => ur.role_id === superAdminRoleId && ur.user_id !== userId,
      ).length;
      if (otherHolders === 0) {
        throw new Error('系统至少需要保留一名超级管理员,无法移除最后一位超级管理员的角色');
      }
    }
    const toAdd = nextRoleIds.filter((id) => !current.includes(id));
    const toRemove = current.filter((id) => !nextRoleIds.includes(id));
    if (toAdd.length > 0) {
      const { error: insErr } = await supabase
        .from('user_roles')
        .upsert(
          toAdd.map((rid) => ({ user_id: userId, role_id: rid })),
          { onConflict: 'user_id,role_id' },
        );
      if (insErr) throw insErr;
    }
    if (toRemove.length > 0) {
      const { error: delErr } = await supabase
        .from('user_roles')
        .delete()
        .eq('user_id', userId)
        .in('role_id', toRemove);
      if (delErr) throw delErr;
    }
  };

  const handleQuickAssign = async (roleIds: string[]) => {
    if (!assignTarget) return;
    setAssignSaving(true);
    try {
      await saveUserRoles(assignTarget.id, roleIds);
      setNotice(`已为 ${assignTarget.full_name || assignTarget.email} 更新角色分配`);
      setAssignTarget(null);
      await load();
    } catch (err) {
      console.error(err);
      setError((err as { message?: string })?.message || '分配角色失败,请检查权限后重试');
      setAssignTarget(null);
    } finally {
      setAssignSaving(false);
    }
  };

  const handleBatchAssign = async (userIds: string[], roleIds: string[], mode: AssignMode) => {
    if (userIds.length === 0 || roleIds.length === 0) return;
    setBatchSaving(true);
    try {
      for (const uid of userIds) {
        const current = rolesByUser.get(uid) ?? [];
        const next = mode === 'replace' ? roleIds : Array.from(new Set([...current, ...roleIds]));
        await saveUserRoles(uid, next);
      }
      setNotice(
        `已为 ${userIds.length} 位用户${mode === 'replace' ? '重新分配' : '追加'}角色`,
      );
      setBatchOpen(false);
      setSelectedIds([]);
      await load();
    } catch (err) {
      console.error(err);
      setError('批量分配角色失败,请检查权限后重试');
      setBatchOpen(false);
    } finally {
      setBatchSaving(false);
    }
  };

  const initialValues: UserFormValues | null = editing
    ? {
        full_name: editing.full_name ?? '',
        email: editing.email ?? '',
        status: editing.status ?? 'active',
        tenant_id: editing.tenant_id ?? '',
        department_id: editing.department_id ?? '',
        roleIds: rolesByUser.get(editing.id) ?? [],
      }
    : null;

  const handleSubmit = async (values: UserFormValues) => {
    setSaving(true);
    try {
      const deptName = values.department_id ? deptById.get(values.department_id) ?? null : null;
      if (editing) {
        const { error: updErr } = await supabase
          .from('profiles')
          .update({
            full_name: values.full_name,
            email: values.email,
            status: values.status,
            tenant_id: values.tenant_id || null,
            department: deptName,
            department_id: values.department_id || null,
          })
          .eq('id', editing.id);
        if (updErr) throw updErr;

        if (canAssign) {
          await saveUserRoles(editing.id, values.roleIds);
        }
        setNotice('用户信息已更新');
        await recordAuditLog({
          action: '修改用户信息',
          module: '用户管理',
          detail: `修改用户「${values.full_name || values.email}」的信息与角色`,
        });
      } else {
        const newId = crypto.randomUUID();
        const { error: insErr } = await supabase.from('profiles').insert({
          id: newId,
          full_name: values.full_name,
          email: values.email,
          status: values.status,
          tenant_id: values.tenant_id || null,
          department: deptName,
          department_id: values.department_id || null,
          account_type: 'admin',
        });
        if (insErr) throw insErr;
        if (values.roleIds.length > 0) {
          await supabase
            .from('user_roles')
            .insert(values.roleIds.map((rid) => ({ user_id: newId, role_id: rid })));
        }
        setNotice('用户创建成功');
        await recordAuditLog({
          action: '新增用户',
          module: '用户管理',
          detail: `新增用户「${values.full_name || values.email}」`,
        });
      }
      setFormOpen(false);
      setEditing(null);
      await load();
    } catch (err) {
      console.error(err);
      setError((err as { message?: string })?.message || '保存失败,请检查权限后重试');
    } finally {
      setSaving(false);
    }
  };

  const toggleStatus = async (p: ProfileRow) => {
    const next = (p.status ?? 'active') === 'active' ? 'disabled' : 'active';
    const { error: err } = await supabase.from('profiles').update({ status: next }).eq('id', p.id);
    if (err) {
      setError('状态更新失败');
      return;
    }
    setNotice(next === 'active' ? '已启用该用户' : '已停用该用户');
    await recordAuditLog({
      action: next === 'active' ? '启用用户' : '停用用户',
      module: '用户管理',
      level: 'warn',
      detail: `${next === 'active' ? '启用' : '停用'}用户「${p.full_name || p.email}」`,
    });
    await load();
  };

  const confirmDelete = async () => {
    if (!deleteTarget) return;
    // 不允许删除当前登录的账号(否则会把自己踢下线)
    if (user?.id && deleteTarget.id === user.id) {
      setError('不能删除当前登录的账号');
      setDeleteTarget(null);
      return;
    }
    // 保护最后一名超级管理员:不允许删除系统里最后一位超管的账号
    const targetRoleIds = rolesByUser.get(deleteTarget.id) ?? [];
    if (superAdminRoleId && targetRoleIds.includes(superAdminRoleId)) {
      const otherHolders = userRoles.filter(
        (ur) => ur.role_id === superAdminRoleId && ur.user_id !== deleteTarget.id,
      ).length;
      if (otherHolders === 0) {
        setError('系统至少需要保留一名超级管理员,无法删除最后一位超级管理员');
        setDeleteTarget(null);
        return;
      }
    }
    try {
      // 调用后端函数彻底删除:登录账号 + 资料 + 角色关联,删除后不会再被自动重建
      const { data, error: fnErr } = await supabase.functions.invoke('delete-account', {
        body: { userId: deleteTarget.id },
      });
      if (fnErr) throw fnErr;
      const result = data as { error?: string; deleted?: boolean } | null;
      if (result?.error) throw new Error(result.error);
      // 删除成功后再写入回收站,避免删除失败时留下无法还原的脏记录
      await moveToRecycleBin({
        module: 'user',
        itemId: deleteTarget.id,
        itemName: deleteTarget.full_name || deleteTarget.email || '未命名',
        snapshot: {
          id: deleteTarget.id,
          email: deleteTarget.email,
          full_name: deleteTarget.full_name,
          status: deleteTarget.status ?? 'active',
          tenant_id: deleteTarget.tenant_id,
          department: deleteTarget.department,
          department_id: deleteTarget.department_id,
          account_type: deleteTarget.account_type ?? 'admin',
          _roles: targetRoleIds,
        },
      });
      setNotice('用户已彻底删除(含登录账号),可在回收站还原资料');
      await recordAuditLog({
        action: '删除用户',
        module: '用户管理',
        level: 'warn',
        detail: `彻底删除用户「${deleteTarget.full_name || deleteTarget.email}」的登录账号与资料`,
      });
      setDeleteTarget(null);
      await load();
    } catch (err) {
      console.error(err);
      setError((err as { message?: string })?.message || '删除失败,可能权限不足');
      setDeleteTarget(null);
    }
  };

  const exportCsv = () => {
    const header = ['full_name', 'email', 'status', 'department', 'tenant'];
    const body = filtered.map((p) => [
      p.full_name ?? '',
      p.email ?? '',
      p.status ?? 'active',
      p.department_id ? deptById.get(p.department_id) ?? '' : p.department ?? '',
      p.tenant_id ? tenantById.get(p.tenant_id) ?? '' : '',
    ]);
    const csv = [header, ...body]
      .map((line) => line.map((cell) => `"${String(cell).replace(/"/g, '""')}"`).join(','))
      .join('\n');
    const blob = new Blob(['\ufeff' + csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `users_${new Date().toISOString().slice(0, 10)}.csv`;
    a.click();
    URL.revokeObjectURL(url);
    setNotice(`已导出 ${filtered.length} 条用户数据`);
    void recordAuditLog({
      action: '导出用户',
      module: '用户管理',
      detail: `导出 ${filtered.length} 条用户数据`,
    });
  };

  const handleImportFile = async (e: ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setImporting(true);
    setError('');
    try {
      const text = await file.text();
      const lines = text.split(/\r?\n/).filter((l) => l.trim());
      if (lines.length < 2) throw new Error('文件为空或缺少数据行');
      const parseLine = (line: string) => {
        const cells: string[] = [];
        let cur = '';
        let inQuotes = false;
        for (let i = 0; i < line.length; i += 1) {
          const ch = line[i];
          if (ch === '"') {
            if (inQuotes && line[i + 1] === '"') {
              cur += '"';
              i += 1;
            } else {
              inQuotes = !inQuotes;
            }
          } else if (ch === ',' && !inQuotes) {
            cells.push(cur);
            cur = '';
          } else {
            cur += ch;
          }
        }
        cells.push(cur);
        return cells.map((c) => c.trim());
      };
      const header = parseLine(lines[0]).map((h) => h.toLowerCase());
      const idx = {
        name: header.indexOf('full_name') >= 0 ? header.indexOf('full_name') : header.indexOf('name'),
        email: header.indexOf('email'),
        status: header.indexOf('status'),
        department: header.indexOf('department'),
      };
      if (idx.email < 0) throw new Error('CSV 缺少 email 列');
      const toInsert: Record<string, unknown>[] = [];
      for (let i = 1; i < lines.length; i += 1) {
        const cells = parseLine(lines[i]);
        const email = idx.email >= 0 ? cells[idx.email] ?? '' : '';
        const name = idx.name >= 0 ? cells[idx.name] ?? '' : '';
        if (!name && !email) continue;
        const deptRaw = idx.department >= 0 ? cells[idx.department]?.trim() ?? '' : '';
        const matchedDept = deptList.find((d) => d.name === deptRaw) ?? null;
        toInsert.push({
          id: crypto.randomUUID(),
          full_name: name || email.split('@')[0],
          email,
          status: idx.status >= 0 && cells[idx.status] === 'disabled' ? 'disabled' : 'active',
          department: matchedDept?.name ?? (deptRaw || null),
          department_id: matchedDept?.id ?? null,
          account_type: 'admin',
        });
      }
      if (toInsert.length === 0) throw new Error('未解析到有效数据行');
      const { error: insErr } = await supabase.from('profiles').insert(toInsert);
      if (insErr) throw insErr;
      setNotice(`导入成功,共新增 ${toInsert.length} 位用户`);
      await recordAuditLog({
        action: '导入用户',
        module: '用户管理',
        detail: `从 CSV 导入 ${toInsert.length} 位用户`,
      });
      await load();
    } catch (err) {
      console.error(err);
      setError(err instanceof Error ? err.message : '导入失败,请检查 CSV 格式');
    } finally {
      setImporting(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  return (
    <div className="space-y-4">
      <div className="flex flex-col md:flex-row md:items-center gap-3">
        <div>
          <h2 className="text-lg font-semibold text-foreground-950">用户管理</h2>
          <p className="text-sm text-foreground-500 mt-0.5">
            共 {profiles.length} 位用户,按角色与租户进行权限分配
            {currentTenant ? ` · 当前仅显示「${currentTenant.name}」` : ''}
          </p>
        </div>
        <div className="md:ml-auto flex flex-wrap items-center gap-2">
          <div className="flex items-center gap-2 h-9 px-3 rounded-md bg-background-50 border border-background-200 w-full sm:w-56">
            <i className="ri-search-line text-foreground-400 text-sm"></i>
            <input
              type="text"
              value={keyword}
              onChange={(e) => setKeyword(e.target.value)}
              placeholder="搜索姓名或邮箱"
              className="flex-1 bg-transparent text-sm text-foreground-900 placeholder:text-foreground-400 focus:outline-none"
            />
          </div>
          <select
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
            className="h-9 px-3 rounded-md bg-background-50 border border-background-200 text-sm text-foreground-800 focus:outline-none cursor-pointer"
          >
            <option value="all">全部状态</option>
            <option value="active">正常</option>
            <option value="disabled">已停用</option>
          </select>
          <select
            value={roleFilter}
            onChange={(e) => setRoleFilter(e.target.value)}
            className="h-9 px-3 rounded-md bg-background-50 border border-background-200 text-sm text-foreground-800 focus:outline-none cursor-pointer"
          >
            <option value="all">全部角色</option>
            {roles.map((r) => (
              <option key={r.id} value={r.id}>
                {r.name}
              </option>
            ))}
          </select>
          <button
            type="button"
            onClick={exportCsv}
            className="h-9 px-3 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap flex items-center gap-1.5"
          >
            <i className="ri-download-2-line"></i>
            导出
          </button>
          <button
            type="button"
            onClick={() => fileInputRef.current?.click()}
            disabled={!canCreate || importing}
            className="h-9 px-3 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 disabled:opacity-40 cursor-pointer whitespace-nowrap flex items-center gap-1.5"
          >
            <i className="ri-upload-2-line"></i>
            {importing ? '导入中…' : '导入'}
          </button>
          <input
            ref={fileInputRef}
            type="file"
            accept=".csv,text/csv"
            onChange={handleImportFile}
            className="hidden"
          />
          <button
            type="button"
            onClick={openCreate}
            disabled={!canCreate}
            className="h-9 px-3.5 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 disabled:opacity-50 disabled:cursor-not-allowed cursor-pointer whitespace-nowrap flex items-center gap-1.5 dark:text-foreground-950"
          >
            <i className="ri-add-line"></i>
            新增用户
          </button>
        </div>
      </div>

      {notice ? (
        <div className="flex items-center gap-2 px-3 py-2.5 rounded-md bg-primary-50 text-primary-800 text-sm animate-fade-up">
          <i className="ri-checkbox-circle-line"></i>
          {notice}
        </div>
      ) : null}
      {error ? (
        <div className="flex items-center justify-between gap-3 px-3 py-2.5 rounded-md bg-accent-100 text-accent-900 text-sm">
          {error}
          <button type="button" onClick={load} className="text-xs underline cursor-pointer whitespace-nowrap">
            重试
          </button>
        </div>
      ) : null}

      <div className="flex items-center gap-2 text-xs text-foreground-500">
        <i className="ri-shield-keyhole-line"></i>
        当前数据权限:
        <span className="text-foreground-800 font-medium">{dataScopeLabel[dataScope] ?? '全部数据'}</span>
        {dataScope !== 'all' && myDepartment ? <span>· 部门:{myDepartment}</span> : null}
        {dataScope === 'dept_and_sub' && departmentIds.length > 1 ? (
          <span>· 含 {departmentIds.length - 1} 个下级部门</span>
        ) : null}
      </div>

      <div className="flex flex-wrap items-center gap-2.5">
        <div className="inline-flex p-1 rounded-full bg-background-200/70">
          <button
            type="button"
            onClick={() => setViewFilter('all')}
            className={`px-4 py-1.5 text-sm rounded-full cursor-pointer whitespace-nowrap flex items-center gap-1.5 ${
              viewFilter === 'all' ? 'bg-background-50 text-foreground-950 font-medium' : 'text-foreground-600'
            }`}
          >
            全部用户
            <span className="text-[11px] text-foreground-500">{scopedProfiles.length}</span>
          </button>
          <button
            type="button"
            onClick={() => setViewFilter('pending')}
            className={`px-4 py-1.5 text-sm rounded-full cursor-pointer whitespace-nowrap flex items-center gap-1.5 ${
              viewFilter === 'pending' ? 'bg-background-50 text-foreground-950 font-medium' : 'text-foreground-600'
            }`}
          >
            <i className="ri-user-follow-line text-[13px]"></i>
            待分配权限
            <span
              className={`text-[11px] px-1.5 py-0.5 rounded-full ${
                pendingCount > 0 ? 'bg-accent-500 text-background-50 dark:text-foreground-950' : 'text-foreground-500'
              }`}
            >
              {pendingCount}
            </span>
          </button>
        </div>
        <span className="text-xs text-foreground-500 flex items-center gap-1.5">
          <i className="ri-timer-flash-line"></i>
          演示账号超过 {DEMO_CLEANUP_DAYS} 天自动清理
        </span>
      </div>

      {selectedIds.length > 0 ? (
        <div className="flex flex-wrap items-center gap-3 px-4 py-3 rounded-lg bg-primary-50 border border-primary-200 animate-fade-up">
          <span className="w-6 h-6 rounded-full bg-primary-500 text-background-50 flex items-center justify-center text-xs shrink-0 dark:text-foreground-950">
            <i className="ri-check-line"></i>
          </span>
          <span className="text-sm text-foreground-800">
            已选 <span className="font-medium text-primary-700">{selectedIds.length}</span> 位用户
          </span>
          <span className="text-xs text-foreground-500 hidden sm:inline">
            可一次为同部门或同租户的多位用户分配同一组角色
          </span>
          <div className="ml-auto flex items-center gap-2">
            <button
              type="button"
              onClick={() => setSelectedIds([])}
              className="h-8 px-3 rounded-md bg-background-50 border border-background-300 text-xs text-foreground-700 hover:bg-background-100 cursor-pointer whitespace-nowrap"
            >
              清空选择
            </button>
            <button
              type="button"
              onClick={() => setBatchOpen(true)}
              disabled={!canAssign}
              className="h-8 px-3 rounded-md bg-primary-500 text-background-50 text-xs hover:bg-primary-600 disabled:opacity-50 disabled:cursor-not-allowed cursor-pointer whitespace-nowrap flex items-center gap-1.5 dark:text-foreground-950"
            >
              <i className="ri-shield-check-line"></i>
              批量分配角色
            </button>
          </div>
        </div>
      ) : null}

      <div className="rounded-lg bg-background-50 border border-background-200 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full min-w-[840px] text-sm">
            <thead>
              <tr className="bg-background-100 text-left text-xs text-foreground-500">
                <th className="pl-4 pr-2 py-3 font-medium w-10">
                  <input
                    type="checkbox"
                    checked={allFilteredSelected}
                    onChange={toggleSelectAll}
                    aria-label="全选"
                    className="w-4 h-4 rounded border-background-300 accent-primary-500 cursor-pointer"
                  />
                </th>
                <th className="px-4 py-3 font-medium">用户</th>
                <th className="px-4 py-3 font-medium">角色</th>
                <th className="px-4 py-3 font-medium">所属部门</th>
                <th className="px-4 py-3 font-medium">所属租户</th>
                <th className="px-4 py-3 font-medium">状态</th>
                <th className="px-4 py-3 font-medium">创建时间</th>
                <th className="px-4 py-3 font-medium text-right">操作</th>
              </tr>
            </thead>
            <tbody>
              {loading ? (
                [0, 1, 2, 3, 4].map((n) => (
                  <tr key={n} className="border-t border-background-200">
                    <td colSpan={8} className="px-4 py-3">
                      <div className="h-8 rounded-md bg-background-100 animate-pulse-soft" />
                    </td>
                  </tr>
                ))
              ) : filtered.length === 0 ? (
                <tr className="border-t border-background-200">
                  <td colSpan={8} className="px-4 py-12 text-center text-foreground-500">
                    <i
                      className={`${
                        viewFilter === 'pending' ? 'ri-user-follow-line' : 'ri-user-search-line'
                      } text-2xl block mb-2`}
                    ></i>
                    {viewFilter === 'pending' ? '太棒了,没有待分配权限的账号' : '没有匹配的用户'}
                  </td>
                </tr>
              ) : (
                filtered.map((p, idx) => {
                  const roleIds = rolesByUser.get(p.id) ?? [];
                  const name = p.full_name || p.email || '未命名';
                  const status = p.status ?? 'active';
                  const isDemo = p.account_type === 'demo';
                  const pending = isPendingUser(p);
                  const selected = selectedIds.includes(p.id);
                  return (
                    <tr
                      key={p.id}
                      className={`border-t border-background-200 ${
                        selected ? 'bg-primary-50/60' : 'hover:bg-background-100/60'
                      }`}
                    >
                      <td className="pl-4 pr-2 py-3">
                        <input
                          type="checkbox"
                          checked={selected}
                          onChange={() => toggleSelect(p.id)}
                          aria-label={`选择 ${name}`}
                          className="w-4 h-4 rounded border-background-300 accent-primary-500 cursor-pointer"
                        />
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex items-center gap-3">
                          <span
                            className={`w-9 h-9 rounded-full flex items-center justify-center text-sm font-semibold shrink-0 ${
                              avatarTones[idx % avatarTones.length]
                            }`}
                          >
                            {initials(name)}
                          </span>
                          <div className="min-w-0">
                            <div className="flex items-center gap-1.5 flex-wrap">
                              <p className="text-foreground-950 truncate">{name}</p>
                              {isDemo ? (
                                <span className="inline-flex items-center gap-0.5 text-[10px] px-1.5 py-0.5 rounded-full bg-accent-100 text-accent-900 whitespace-nowrap">
                                  <i className="ri-eye-line"></i>
                                  演示
                                </span>
                              ) : null}
                              {pending ? (
                                <span className="inline-flex items-center gap-0.5 text-[10px] px-1.5 py-0.5 rounded-full bg-secondary-100 text-secondary-900 whitespace-nowrap">
                                  <i className="ri-time-line"></i>
                                  待分配
                                </span>
                              ) : null}
                            </div>
                            <p className="text-xs text-foreground-500 truncate">{p.email}</p>
                          </div>
                        </div>
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex flex-wrap gap-1.5">
                          {roleIds.length === 0 ? (
                            <span className="text-xs text-foreground-400">未分配</span>
                          ) : (
                            roleIds.map((rid) => (
                              <span
                                key={rid}
                                className="text-[11px] px-2 py-0.5 rounded-full bg-secondary-100 text-secondary-900"
                              >
                                {roleById.get(rid) ?? '未知角色'}
                              </span>
                            ))
                          )}
                        </div>
                      </td>
                      <td className="px-4 py-3 text-foreground-700">
                        {p.department_id ? deptById.get(p.department_id) ?? '—' : p.department ?? '—'}
                      </td>
                      <td className="px-4 py-3 text-foreground-700">
                        {p.tenant_id ? tenantById.get(p.tenant_id) ?? '—' : '—'}
                      </td>
                      <td className="px-4 py-3">
                        <span
                          className={`inline-flex items-center gap-1.5 text-[11px] px-2 py-1 rounded-full ${
                            status === 'active'
                              ? 'bg-primary-100 text-primary-800'
                              : 'bg-background-200 text-foreground-600'
                          }`}
                        >
                          <span
                            className={`w-1.5 h-1.5 rounded-full ${
                              status === 'active' ? 'bg-primary-500' : 'bg-foreground-400'
                            }`}
                          />
                          {status === 'active' ? '正常' : '已停用'}
                        </span>
                      </td>
                      <td className="px-4 py-3 text-foreground-600 font-label text-xs">
                        {formatDate(p.created_at)}
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex items-center justify-end gap-1">
                          <button
                            type="button"
                            onClick={() => setAssignTarget(p)}
                            disabled={!canAssign}
                            title="一键分配角色"
                            className="w-8 h-8 flex items-center justify-center rounded-md text-primary-600 hover:bg-primary-50 disabled:opacity-40 cursor-pointer"
                          >
                            <i className="ri-shield-user-line"></i>
                          </button>
                          <button
                            type="button"
                            onClick={() => openEdit(p)}
                            disabled={!canUpdate && !canAssign}
                            title="编辑"
                            className="w-8 h-8 flex items-center justify-center rounded-md text-foreground-500 hover:bg-background-200 hover:text-foreground-900 disabled:opacity-40 cursor-pointer"
                          >
                            <i className="ri-pencil-line"></i>
                          </button>
                          <button
                            type="button"
                            onClick={() => toggleStatus(p)}
                            disabled={!canUpdate}
                            title={status === 'active' ? '停用' : '启用'}
                            className="w-8 h-8 flex items-center justify-center rounded-md text-foreground-500 hover:bg-background-200 hover:text-foreground-900 disabled:opacity-40 cursor-pointer"
                          >
                            <i className={status === 'active' ? 'ri-forbid-2-line' : 'ri-play-circle-line'}></i>
                          </button>
                          <button
                            type="button"
                            onClick={() => setDeleteTarget(p)}
                            disabled={!canDelete || user?.id === p.id}
                            title={user?.id === p.id ? '不能删除当前登录账号' : '删除'}
                            className="w-8 h-8 flex items-center justify-center rounded-md text-foreground-500 hover:bg-secondary-200 hover:text-secondary-900 disabled:opacity-40 cursor-pointer"
                          >
                            <i className="ri-delete-bin-line"></i>
                          </button>
                        </div>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>

      <UserFormModal
        open={formOpen}
        editing={Boolean(editing)}
        initial={initialValues}
        roles={roles}
        tenants={tenants}
        departments={deptList}
        saving={saving}
        onClose={() => {
          setFormOpen(false);
          setEditing(null);
        }}
        onSubmit={handleSubmit}
      />

      <AssignRoleModal
        open={Boolean(assignTarget)}
        userName={assignTarget?.full_name || assignTarget?.email || '未命名用户'}
        userEmail={assignTarget?.email ?? null}
        roles={roles}
        currentRoleIds={assignTarget ? rolesByUser.get(assignTarget.id) ?? [] : []}
        saving={assignSaving}
        onClose={() => setAssignTarget(null)}
        onSubmit={handleQuickAssign}
      />

      <BatchAssignRoleModal
        open={batchOpen}
        users={batchUsers}
        roles={roles}
        initialSelected={selectedIds}
        saving={batchSaving}
        onClose={() => setBatchOpen(false)}
        onSubmit={handleBatchAssign}
      />

      <Modal
        open={Boolean(deleteTarget)}
        title="删除用户"
        onClose={() => setDeleteTarget(null)}
        footer={
          <>
            <button
              type="button"
              onClick={() => setDeleteTarget(null)}
              className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
            >
              取消
            </button>
            <button
              type="button"
              onClick={confirmDelete}
              className="h-9 px-4 rounded-md bg-secondary-700 text-background-50 text-sm hover:bg-secondary-800 cursor-pointer whitespace-nowrap"
            >
              确认删除
            </button>
          </>
        }
      >
        <p className="text-sm text-foreground-700">
          确定要删除用户
          <span className="font-medium text-foreground-950">
            {' '}
            {deleteTarget?.full_name || deleteTarget?.email}{' '}
          </span>
          吗?将同时删除其<b className="text-foreground-900">登录账号、资料与角色关联</b>。资料可在回收站还原,但登录账号不可恢复。
        </p>
      </Modal>
    </div>
  );
}