import { useEffect, useMemo, useState } from 'react';
import Modal from '@/components/base/Modal';
import type { RoleOption } from '@/pages/system/users/components/UserFormModal';

export interface BatchUser {
  id: string;
  name: string;
  email: string | null;
  departmentId: string | null;
  departmentName: string | null;
  tenantId: string | null;
  tenantName: string | null;
}

type GroupBy = 'custom' | 'department' | 'tenant';
export type AssignMode = 'append' | 'replace';

interface BatchAssignRoleModalProps {
  open: boolean;
  users: BatchUser[];
  roles: RoleOption[];
  initialSelected: string[];
  saving: boolean;
  onClose: () => void;
  onSubmit: (userIds: string[], roleIds: string[], mode: AssignMode) => void;
}

const groupOptions: { value: GroupBy; label: string; icon: string }[] = [
  { value: 'custom', label: '手动选择', icon: 'ri-cursor-line' },
  { value: 'department', label: '按部门', icon: 'ri-node-tree' },
  { value: 'tenant', label: '按租户', icon: 'ri-building-2-line' },
];

export default function BatchAssignRoleModal({
  open,
  users,
  roles,
  initialSelected,
  saving,
  onClose,
  onSubmit,
}: BatchAssignRoleModalProps) {
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [roleIds, setRoleIds] = useState<string[]>([]);
  const [groupBy, setGroupBy] = useState<GroupBy>('custom');
  const [groupKey, setGroupKey] = useState('');
  const [mode, setMode] = useState<AssignMode>('append');
  const [keyword, setKeyword] = useState('');

  useEffect(() => {
    if (open) {
      setSelectedIds(initialSelected);
      setRoleIds([]);
      setGroupBy('custom');
      setGroupKey('');
      setMode('append');
      setKeyword('');
    }
  }, [open, initialSelected]);

  const deptGroups = useMemo(() => {
    const map = new Map<string, string>();
    users.forEach((u) => {
      if (u.departmentId) map.set(u.departmentId, u.departmentName ?? '未命名部门');
    });
    return Array.from(map, ([id, name]) => ({ id, name })).sort((a, b) =>
      a.name.localeCompare(b.name),
    );
  }, [users]);

  const tenantGroups = useMemo(() => {
    const map = new Map<string, string>();
    users.forEach((u) => {
      if (u.tenantId) map.set(u.tenantId, u.tenantName ?? '未命名租户');
    });
    return Array.from(map, ([id, name]) => ({ id, name })).sort((a, b) =>
      a.name.localeCompare(b.name),
    );
  }, [users]);

  const applyGroup = (nextGroupBy: GroupBy, key: string) => {
    setGroupBy(nextGroupBy);
    setGroupKey(key);
    if (!key) return;
    const ids = users
      .filter((u) =>
        nextGroupBy === 'department' ? u.departmentId === key : u.tenantId === key,
      )
      .map((u) => u.id);
    setSelectedIds(ids);
  };

  const toggleUser = (id: string) => {
    setSelectedIds((prev) =>
      prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id],
    );
  };

  const toggleRole = (id: string) => {
    setRoleIds((prev) => (prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id]));
  };

  const visibleUsers = useMemo(() => {
    const kw = keyword.trim().toLowerCase();
    if (!kw) return users;
    return users.filter(
      (u) =>
        u.name.toLowerCase().includes(kw) || (u.email ?? '').toLowerCase().includes(kw),
    );
  }, [users, keyword]);

  const allVisibleSelected =
    visibleUsers.length > 0 && visibleUsers.every((u) => selectedIds.includes(u.id));

  const toggleAllVisible = () => {
    if (allVisibleSelected) {
      setSelectedIds((prev) => prev.filter((id) => !visibleUsers.some((u) => u.id === id)));
    } else {
      setSelectedIds((prev) => Array.from(new Set([...prev, ...visibleUsers.map((u) => u.id)])));
    }
  };

  const groupList = groupBy === 'department' ? deptGroups : tenantGroups;

  return (
    <Modal
      open={open}
      title="批量分配角色"
      subtitle="一次为同部门或同租户的多位用户分配同一组角色"
      width="max-w-2xl"
      onClose={onClose}
      footer={
        <>
          <span className="mr-auto text-xs text-foreground-500 self-center">
            已选 {selectedIds.length} 位用户 · {mode === 'append' ? '追加' : '替换'} {roleIds.length} 个角色
          </span>
          <button
            type="button"
            onClick={onClose}
            className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
          >
            取消
          </button>
          <button
            type="button"
            onClick={() => onSubmit(selectedIds, roleIds, mode)}
            disabled={saving || selectedIds.length === 0 || roleIds.length === 0}
            className="h-9 px-4 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 disabled:opacity-50 disabled:cursor-not-allowed cursor-pointer whitespace-nowrap flex items-center gap-1.5 dark:text-foreground-950"
          >
            <i className={saving ? 'ri-loader-4-line animate-spin' : 'ri-shield-check-line'}></i>
            {saving ? '分配中…' : '确认分配'}
          </button>
        </>
      }
    >
      <div className="space-y-4">
        <div>
          <p className="text-xs font-medium text-foreground-700 mb-2">分配方式</p>
          <div className="inline-flex p-1 rounded-full bg-background-200/70">
            {(['append', 'replace'] as AssignMode[]).map((m) => (
              <button
                key={m}
                type="button"
                onClick={() => setMode(m)}
                className={`px-4 py-1.5 text-sm rounded-full cursor-pointer whitespace-nowrap ${
                  mode === m ? 'bg-background-50 text-foreground-950 font-medium' : 'text-foreground-600'
                }`}
              >
                {m === 'append' ? '追加角色' : '替换全部角色'}
              </button>
            ))}
          </div>
        </div>

        <div>
          <p className="text-xs font-medium text-foreground-700 mb-2">快速圈选范围</p>
          <div className="flex flex-wrap items-center gap-2">
            <div className="inline-flex p-1 rounded-full bg-background-200/70">
              {groupOptions.map((g) => (
                <button
                  key={g.value}
                  type="button"
                  onClick={() => applyGroup(g.value, '')}
                  className={`inline-flex items-center gap-1.5 px-3 py-1.5 text-xs rounded-full cursor-pointer whitespace-nowrap ${
                    groupBy === g.value
                      ? 'bg-background-50 text-foreground-950 font-medium'
                      : 'text-foreground-600'
                  }`}
                >
                  <i className={g.icon}></i>
                  {g.label}
                </button>
              ))}
            </div>
            {groupBy !== 'custom' ? (
              <select
                value={groupKey}
                onChange={(e) => applyGroup(groupBy, e.target.value)}
                className="h-9 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-800 focus:outline-none cursor-pointer"
              >
                <option value="">
                  {groupBy === 'department' ? '选择部门…' : '选择租户…'}
                </option>
                {groupList.map((g) => (
                  <option key={g.id} value={g.id}>
                    {g.name}
                  </option>
                ))}
              </select>
            ) : null}
          </div>
          {groupBy !== 'custom' && groupKey ? (
            <p className="mt-2 text-[11px] text-foreground-500 flex items-center gap-1">
              <i className="ri-information-line"></i>
              已自动选中该{groupBy === 'department' ? '部门' : '租户'}下的全部用户,可在下方继续微调。
            </p>
          ) : null}
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
          <div>
            <div className="flex items-center gap-2 h-9 px-3 rounded-md bg-background-50 border border-background-200">
              <i className="ri-search-line text-foreground-400 text-sm"></i>
              <input
                type="text"
                value={keyword}
                onChange={(e) => setKeyword(e.target.value)}
                placeholder="搜索用户姓名或邮箱"
                className="flex-1 bg-transparent text-sm text-foreground-900 placeholder:text-foreground-400 focus:outline-none"
              />
            </div>
            <div className="mt-2 flex items-center justify-between px-1">
              <span className="text-[11px] text-foreground-500">共 {visibleUsers.length} 位用户</span>
              <button
                type="button"
                onClick={toggleAllVisible}
                className="text-[11px] text-primary-600 hover:text-primary-700 cursor-pointer whitespace-nowrap"
              >
                {allVisibleSelected ? '取消全选' : '全选当前'}
              </button>
            </div>
            <div className="mt-1 max-h-[300px] overflow-y-auto space-y-1.5 pr-1">
              {visibleUsers.length === 0 ? (
                <p className="py-8 text-center text-sm text-foreground-500">没有匹配的用户</p>
              ) : (
                visibleUsers.map((u) => {
                  const active = selectedIds.includes(u.id);
                  return (
                    <button
                      key={u.id}
                      type="button"
                      onClick={() => toggleUser(u.id)}
                      className={`w-full flex items-center gap-2.5 rounded-md border px-3 py-2 text-left cursor-pointer transition-colors ${
                        active
                          ? 'bg-primary-50 border-primary-400'
                          : 'bg-background-50 border-background-200 hover:border-background-300'
                      }`}
                    >
                      <span
                        className={`w-[18px] h-[18px] rounded flex items-center justify-center shrink-0 border ${
                          active
                            ? 'bg-primary-500 border-primary-500 text-background-50 dark:text-foreground-950'
                            : 'border-background-300'
                        }`}
                      >
                        {active ? <i className="ri-check-line text-[10px]"></i> : null}
                      </span>
                      <span className="min-w-0 flex-1">
                        <span className="block text-sm text-foreground-950 truncate">{u.name}</span>
                        <span className="block text-[11px] text-foreground-500 truncate">
                          {u.departmentName ?? '未指定部门'} · {u.tenantName ?? '未指定租户'}
                        </span>
                      </span>
                    </button>
                  );
                })
              )}
            </div>
          </div>

          <div>
            <p className="text-xs font-medium text-foreground-700 mb-2">分配角色</p>
            <div className="max-h-[360px] overflow-y-auto space-y-2 pr-1">
              {roles.map((role) => {
                const active = roleIds.includes(role.id);
                return (
                  <button
                    key={role.id}
                    type="button"
                    onClick={() => toggleRole(role.id)}
                    className={`w-full flex items-center gap-3 rounded-md border px-3.5 py-2.5 text-left cursor-pointer transition-colors ${
                      active
                        ? 'bg-primary-50 border-primary-400'
                        : 'bg-background-50 border-background-200 hover:border-background-300'
                    }`}
                  >
                    <span
                      className={`w-5 h-5 rounded-md flex items-center justify-center shrink-0 border ${
                        active
                          ? 'bg-primary-500 border-primary-500 text-background-50 dark:text-foreground-950'
                          : 'border-background-300'
                      }`}
                    >
                      {active ? <i className="ri-check-line text-xs"></i> : null}
                    </span>
                    <span className="min-w-0 flex-1">
                      <span className="block text-sm text-foreground-950 truncate">{role.name}</span>
                      {role.code ? (
                        <span className="block text-[11px] text-foreground-500 font-label truncate">
                          {role.code}
                        </span>
                      ) : null}
                    </span>
                  </button>
                );
              })}
            </div>
          </div>
        </div>

        <p className="flex items-start gap-1.5 text-[11px] text-foreground-500">
          <i className="ri-alert-line mt-0.5"></i>
          {mode === 'replace'
            ? '替换模式会清空所选用户现有的全部角色,再写入本次勾选的角色。'
            : '追加模式会保留用户现有角色,仅补充本次勾选的角色。'}
        </p>
      </div>
    </Modal>
  );
}