export type FieldType = 'text' | 'number' | 'boolean' | 'date' | 'select';

export interface ColumnDef {
  name: string;
  label: string;
  type: FieldType;
  primary?: boolean;
  options?: string[];
}

export interface TableDef {
  name: string;
  label: string;
  path: string;
  icon: string;
  columns: ColumnDef[];
}

