import Modal from '@/components/base/Modal';

export interface DetailRow {
  label: string;
  value: string;
  mono?: boolean;
}

interface LogDetailModalProps {
  open: boolean;
  title: string;
  badge?: { text: string; className: string };
  rows: DetailRow[];
  onClose: () => void;
}

export default function LogDetailModal({ open, title, badge, rows, onClose }: LogDetailModalProps) {
  return (
    <Modal
      open={open}
      title={title}
      subtitle="日志详情"
      onClose={onClose}
      footer={
        <button
          type="button"
          onClick={onClose}
          className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
        >
          关闭
        </button>
      }
    >
      {badge ? (
        <span className={`inline-flex mb-4 text-[11px] px-2 py-0.5 rounded-full ${badge.className}`}>
          {badge.text}
        </span>
      ) : null}
      <dl className="divide-y divide-background-200">
        {rows.map((row) => (
          <div key={row.label} className="flex items-start gap-4 py-2.5">
            <dt className="w-20 shrink-0 text-xs text-foreground-500 pt-0.5">{row.label}</dt>
            <dd
              className={`flex-1 text-sm text-foreground-900 break-all ${
                row.mono ? 'font-label text-xs' : ''
              }`}
            >
              {row.value || '—'}
            </dd>
          </div>
        ))}
      </dl>
    </Modal>
  );
}