import type { RouteObject } from "react-router-dom";
import NotFound from "@/pages/NotFound";
import Home from "@/pages/home/page";
import AuthPage from "@/pages/auth/page";
import AdminLayout from "@/components/feature/AdminLayout";
import RequireAuth from "@/components/feature/RequireAuth";
import UsersPage from "@/pages/system/users/page";
import RolesPage from "@/pages/system/roles/page";
import PermissionsPage from "@/pages/system/permissions/page";
import DashboardPage from "@/pages/dashboard/page";
import LogsPage from "@/pages/system/logs/page";
import AccountPage from "@/pages/settings/account/page";
import PluginsPage from "@/pages/plugins/page";
import TenantsPage from "@/pages/system/tenants/page";
import BuilderPage from "@/pages/builder/page";
import ApiDocsPage from "@/pages/api-docs/page";
import SystemSettingsPage from "@/pages/settings/system/page";
import DocsPage from "@/pages/docs/page";
import GeneratorPage from "@/pages/generator/page";
import DynamicCrudPage from "@/pages/generated/DynamicCrudPage";
import RecycleBinPage from "@/pages/system/recycle-bin/page";
import ConfigCenterPage from "@/pages/settings/config/page";
import MediaLibraryPage from "@/pages/settings/media/page";
import I18nManagerPage from "@/pages/settings/i18n/page";
import NotificationCenterPage from "@/pages/settings/notifications/page";
import DepartmentsPage from "@/pages/system/departments/page";
import MembersAdminPage from "@/pages/system/members/page";
import TasksPage from "@/pages/system/tasks/page";
import MemberAuthPage from "@/pages/member/auth/page";
import MemberLayout from "@/pages/member/components/MemberLayout";
import MemberHomePage from "@/pages/member/page";
import MemberProfilePage from "@/pages/member/profile/page";
import RequireMember from "@/components/feature/RequireMember";
import PendingApprovalPage from "@/pages/pending/page";

const routes: RouteObject[] = [
  {
    path: "/auth",
    element: <AuthPage />,
  },
  {
    path: "/pending",
    element: <PendingApprovalPage />,
  },
  {
    path: "/member/login",
    element: <MemberAuthPage />,
  },
  {
    path: "/member",
    element: (
      <RequireMember>
        <MemberLayout />
      </RequireMember>
    ),
    children: [
      { index: true, element: <MemberHomePage /> },
      { path: "profile", element: <MemberProfilePage /> },
    ],
  },
  {
    path: "/",
    element: (
      <RequireAuth>
        <AdminLayout />
      </RequireAuth>
    ),
    children: [
      { index: true, element: <Home /> },
      { path: "dashboard", element: <DashboardPage /> },
      { path: "account", element: <AccountPage /> },
      { path: "system/users", element: <UsersPage /> },
      { path: "system/departments", element: <DepartmentsPage /> },
      { path: "system/members", element: <MembersAdminPage /> },
      { path: "system/tasks", element: <TasksPage /> },
      { path: "system/roles", element: <RolesPage /> },
      { path: "system/permissions", element: <PermissionsPage /> },
      { path: "system/tenants", element: <TenantsPage /> },
      { path: "system/logs", element: <LogsPage /> },
      { path: "system/recycle-bin", element: <RecycleBinPage /> },
      { path: "plugins", element: <PluginsPage /> },
      { path: "builder", element: <BuilderPage /> },
      { path: "generator", element: <GeneratorPage /> },
      { path: "generated/:slug", element: <DynamicCrudPage /> },
      { path: "api-docs", element: <ApiDocsPage /> },
      { path: "settings", element: <SystemSettingsPage /> },
      { path: "settings/config", element: <ConfigCenterPage /> },
      { path: "settings/media", element: <MediaLibraryPage /> },
      { path: "settings/i18n", element: <I18nManagerPage /> },
      { path: "settings/notifications", element: <NotificationCenterPage /> },
      { path: "docs", element: <DocsPage /> },
    ],
  },
  {
    path: "*",
    element: <NotFound />,
  },
];

export default routes;