import { useCallback, useEffect, useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import { supabase } from '@/lib/supabase';
import { useAuth } from '@/contexts/AuthContext';
import { memberLevelMeta, type MemberRow } from '@/pages/member/types';

const levelThresholds = [
  { key: 'standard', min: 0, next: 'silver', nextAt: 3000 },
  { key: 'silver', min: 3000, next: 'gold', nextAt: 6000 },
  { key: 'gold', min: 6000, next: 'platinum', nextAt: 10000 },
  { key: 'platinum', min: 10000, next: null, nextAt: 10000 },
];

function daysSince(iso: string | null) {
  if (!iso) return 0;
  return Math.max(1, Math.floor((Date.now() - new Date(iso).getTime()) / 86400000));
}

export default function MemberHomePage() {
  const { user } = useAuth();
  const [member, setMember] = useState<MemberRow | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  const load = useCallback(async () => {
    if (!user) return;
    setLoading(true);
    setError('');
    try {
      const { data, error: err } = await supabase
        .from('members')
        .select('*')
        .eq('id', user.id)
        .maybeSingle();
      if (err) throw err;
      setMember((data as MemberRow) ?? null);
    } catch (err) {
      console.error(err);
      setError('加载会员信息失败,请重试');
    } finally {
      setLoading(false);
    }
  }, [user]);

  useEffect(() => {
    load();
  }, [load]);

  const meta = memberLevelMeta(member?.level ?? null);
  const points = member?.points ?? 0;

  const progress = useMemo(() => {
    const current = levelThresholds.find((l) => l.key === (member?.level ?? 'standard')) ?? levelThresholds[0];
    if (!current.next) return { pct: 100, remain: 0, nextLabel: '已达最高等级' };
    const span = current.nextAt - current.min;
    const done = Math.max(0, points - current.min);
    const pct = Math.min(100, Math.round((done / span) * 100));
    return {
      pct,
      remain: Math.max(0, current.nextAt - points),
      nextLabel: memberLevelMeta(current.next).label,
      nextKey: current.next,
    };
  }, [member?.level, points]);

  return (
    <div className="space-y-5">
      <div className="rounded-lg bg-gradient-to-br from-accent-500 to-accent-600 p-5 md:p-6 text-background-50">
        <div className="flex flex-col sm:flex-row sm:items-center gap-4">
          <span className="w-16 h-16 rounded-full bg-background-50/20 flex items-center justify-center text-2xl shrink-0">
            <i className={meta.icon}></i>
          </span>
          <div className="min-w-0 flex-1">
            <div className="flex items-center gap-2 flex-wrap">
              <h1 className="text-xl font-semibold">{member?.nickname || '会员'}</h1>
              <span className="text-[11px] px-2 py-0.5 rounded-full bg-background-50/20">{meta.label}</span>
            </div>
            <p className="mt-1 text-sm text-background-50/85">{member?.email}</p>
            <p className="mt-0.5 text-xs text-background-50/75">
              加入于 {member?.joined_at ? new Date(member.joined_at).toLocaleDateString() : '—'} · 已陪伴 {daysSince(member?.joined_at)} 天
            </p>
          </div>
          <Link
            to="/member/profile"
            className="shrink-0 inline-flex items-center gap-1.5 h-9 px-4 rounded-md bg-background-50 text-accent-700 text-sm hover:bg-background-100 cursor-pointer whitespace-nowrap"
          >
            <i className="ri-user-settings-line"></i>
            编辑资料
          </Link>
        </div>
      </div>

      {error ? (
        <div className="flex items-center justify-between gap-3 px-3 py-2.5 rounded-md bg-accent-100 text-accent-900 text-sm">
          {error}
          <button type="button" onClick={load} className="text-xs underline cursor-pointer whitespace-nowrap">
            重试
          </button>
        </div>
      ) : null}

      <section className="grid grid-cols-1 sm:grid-cols-3 gap-3 md:gap-4">
        <div className="rounded-lg bg-background-50 border border-background-200 p-4">
          <div className="flex items-center gap-2">
            <span className="w-8 h-8 rounded-md flex items-center justify-center bg-primary-100 text-primary-700">
              <i className="ri-copper-coin-line"></i>
            </span>
            <span className="text-xs text-foreground-500">我的积分</span>
          </div>
          <p className="mt-2.5 text-2xl font-semibold text-foreground-950 font-label">
            {loading ? '—' : points.toLocaleString()}
          </p>
        </div>
        <div className="rounded-lg bg-background-50 border border-background-200 p-4">
          <div className="flex items-center gap-2">
            <span className="w-8 h-8 rounded-md flex items-center justify-center bg-accent-100 text-accent-800">
              <i className="ri-vip-crown-line"></i>
            </span>
            <span className="text-xs text-foreground-500">会员等级</span>
          </div>
          <p className="mt-2.5 text-2xl font-semibold text-foreground-950">{loading ? '—' : meta.label}</p>
        </div>
        <div className="rounded-lg bg-background-50 border border-background-200 p-4">
          <div className="flex items-center gap-2">
            <span className="w-8 h-8 rounded-md flex items-center justify-center bg-secondary-200 text-secondary-900">
              <i className="ri-calendar-check-line"></i>
            </span>
            <span className="text-xs text-foreground-500">会员天数</span>
          </div>
          <p className="mt-2.5 text-2xl font-semibold text-foreground-950 font-label">
            {loading ? '—' : daysSince(member?.joined_at)}
          </p>
        </div>
      </section>

      <section className="rounded-lg bg-background-50 border border-background-200 p-4 md:p-5">
        <div className="flex items-center justify-between gap-3">
          <h2 className="text-sm font-semibold text-foreground-950">等级成长进度</h2>
          <span className="text-xs text-foreground-500">
            {progress.nextLabel === '已达最高等级' ? progress.nextLabel : `距 ${progress.nextLabel} 还差 ${progress.remain} 积分`}
          </span>
        </div>
        <div className="mt-3 h-2 rounded-full bg-background-200 overflow-hidden">
          <div
            className="h-full rounded-full bg-gradient-to-r from-accent-400 to-accent-600 transition-all"
            style={{ width: `${progress.pct}%` }}
          />
        </div>
        <div className="mt-2 flex justify-between text-[11px] text-foreground-400 font-label">
          <span>普通</span>
          <span>白银</span>
          <span>黄金</span>
          <span>铂金</span>
        </div>
      </section>

      <section className="rounded-lg bg-background-50 border border-background-200 p-4 md:p-5">
        <h2 className="text-sm font-semibold text-foreground-950 mb-3">最近动态</h2>
        <ol className="space-y-3">
          {[
            { icon: 'ri-login-circle-line', tone: 'bg-primary-100 text-primary-700', title: '登录会员中心', time: '刚刚' },
            { icon: 'ri-copper-coin-line', tone: 'bg-accent-100 text-accent-800', title: `获得积分奖励 +${Math.max(10, Math.round(points / 40))}`, time: '今天' },
            { icon: 'ri-user-settings-line', tone: 'bg-secondary-200 text-secondary-900', title: '完善个人资料', time: '3 天前' },
            { icon: 'ri-vip-crown-line', tone: 'bg-primary-100 text-primary-700', title: `升级为 ${meta.label}`, time: '1 周前' },
          ].map((a, i) => (
            <li key={i} className="flex items-center gap-3">
              <span className={`w-8 h-8 rounded-md flex items-center justify-center shrink-0 ${a.tone}`}>
                <i className={`${a.icon} text-sm`}></i>
              </span>
              <span className="text-sm text-foreground-800 flex-1">{a.title}</span>
              <span className="text-[11px] text-foreground-400">{a.time}</span>
            </li>
          ))}
        </ol>
      </section>
    </div>
  );
}