import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { runEndpoint, type TryResult } from '@/pages/api-docs/apiRunner';
import { methodStyle, type EndpointDef } from '@/pages/api-docs/types';
import {
  deleteDebugCase,
  fetchDebugCases,
  importDebugCases,
  normalizeTags,
  type DebugCase,
  type SaveDebugCaseInput,
} from '@/pages/api-docs/debugCases';

interface DebugCasesDrawerProps {
  open: boolean;
  endpoints: EndpointDef[];
  onClose: () => void;
  onOpenEndpoint: (code: string) => void;
}

const methodFilters = ['全部', 'GET', 'POST', 'PUT', 'DELETE'];

function statusTone(status: number) {
  if (status >= 200 && status < 300) return 'bg-primary-100 text-primary-800';
  if (status >= 400 && status < 500) return 'bg-accent-100 text-accent-900';
  return 'bg-secondary-700 text-background-50';
}

function formatTime(iso: string | null) {
  if (!iso) return '';
  const d = new Date(iso);
  return `${d.getFullYear()}/${d.getMonth() + 1}/${d.getDate()} ${String(d.getHours()).padStart(2, '0')}:${String(
    d.getMinutes(),
  ).padStart(2, '0')}`;
}

export default function DebugCasesDrawer({
  open,
  endpoints,
  onClose,
  onOpenEndpoint,
}: DebugCasesDrawerProps) {
  const [cases, setCases] = useState<DebugCase[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [keyword, setKeyword] = useState('');
  const [methodFilter, setMethodFilter] = useState('全部');
  const [tagFilter, setTagFilter] = useState('全部');
  const [busyId, setBusyId] = useState<string | null>(null);
  const [results, setResults] = useState<Record<string, TryResult>>({});
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [batchRunning, setBatchRunning] = useState(false);
  const [batchSummary, setBatchSummary] = useState<{ ok: number; fail: number; total: number } | null>(null);
  const [importing, setImporting] = useState(false);
  const [toast, setToast] = useState('');
  const fileRef = useRef<HTMLInputElement>(null);

  const endpointByCode = useMemo(() => {
    const map = new Map<string, EndpointDef>();
    endpoints.forEach((ep) => map.set(ep.code, ep));
    return map;
  }, [endpoints]);

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const list = await fetchDebugCases();
      setCases(list);
    } catch (err) {
      console.error(err);
      setError('加载调试用例失败,请重试');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (open) load();
  }, [open, load]);

  useEffect(() => {
    if (!toast) return;
    const timer = setTimeout(() => setToast(''), 2800);
    return () => clearTimeout(timer);
  }, [toast]);

  const filtered = useMemo(() => {
    const kw = keyword.trim().toLowerCase();
    return cases.filter((c) => {
      const matchKw =
        !kw ||
        c.name.toLowerCase().includes(kw) ||
        (c.path ?? '').toLowerCase().includes(kw) ||
        (c.endpoint_code ?? '').toLowerCase().includes(kw);
      const matchMethod = methodFilter === '全部' || c.method === methodFilter;
      const matchTag = tagFilter === '全部' || (c.tags ?? []).includes(tagFilter);
      return matchKw && matchMethod && matchTag;
    });
  }, [cases, keyword, methodFilter, tagFilter]);

  const allTags = useMemo(() => {
    const set = new Set<string>();
    cases.forEach((c) => (c.tags ?? []).forEach((t) => set.add(t)));
    return Array.from(set).sort((a, b) => a.localeCompare(b));
  }, [cases]);

  const replay = async (c: DebugCase) => {
    const ep = endpointByCode.get(c.endpoint_code);
    if (!ep) return;
    setBusyId(c.id);
    setExpandedId(c.id);
    try {
      const res = await runEndpoint(ep, {
        pathParams: c.path_params ?? {},
        queryParams: c.query_params ?? {},
        body: c.body ?? '',
      });
      setResults((prev) => ({ ...prev, [c.id]: res }));
    } finally {
      setBusyId(null);
    }
  };

  const remove = async (c: DebugCase) => {
    setBusyId(c.id);
    try {
      await deleteDebugCase(c.id);
      setResults((prev) => {
        const next = { ...prev };
        delete next[c.id];
        return next;
      });
      await load();
    } catch (err) {
      console.error(err);
    } finally {
      setBusyId(null);
    }
  };

  const toggleSelect = (id: string) => {
    setSelected((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const selectedVisible = useMemo(
    () => filtered.filter((c) => selected.has(c.id)),
    [filtered, selected],
  );

  const allFilteredSelected = filtered.length > 0 && filtered.every((c) => selected.has(c.id));

  const toggleSelectAll = () => {
    setSelected((prev) => {
      const next = new Set(prev);
      if (allFilteredSelected) filtered.forEach((c) => next.delete(c.id));
      else filtered.forEach((c) => next.add(c.id));
      return next;
    });
  };

  const clearSelection = () => {
    setSelected(new Set());
    setBatchSummary(null);
  };

  const batchReplay = async () => {
    const targets = selectedVisible.filter((c) => endpointByCode.get(c.endpoint_code));
    if (targets.length === 0) return;
    setBatchRunning(true);
    setBatchSummary(null);
    let ok = 0;
    let fail = 0;
    const collected: Record<string, TryResult> = {};
    for (let i = 0; i < targets.length; i += 1) {
      const c = targets[i];
      const ep = endpointByCode.get(c.endpoint_code);
      if (!ep) continue;
      // sequential so the aggregate reflects real per-request outcomes
      try {
        const res = await runEndpoint(ep, {
          pathParams: c.path_params ?? {},
          queryParams: c.query_params ?? {},
          body: c.body ?? '',
        });
        collected[c.id] = res;
        if (res.ok) ok += 1;
        else fail += 1;
      } catch (err) {
        console.error(err);
        fail += 1;
      }
    }
    setResults((prev) => ({ ...prev, ...collected }));
    setBatchSummary({ ok, fail, total: targets.length });
    setBatchRunning(false);
  };

  const exportCases = () => {
    const source = selectedVisible.length > 0 ? selectedVisible : filtered;
    if (source.length === 0) {
      setToast('当前没有可导出的用例');
      return;
    }
    const payload = {
      version: 1,
      exported_at: new Date().toISOString(),
      cases: source.map((c) => ({
        name: c.name,
        endpoint_code: c.endpoint_code,
        method: c.method,
        path: c.path,
        resource: c.resource,
        action: c.action,
        path_params: c.path_params ?? {},
        query_params: c.query_params ?? {},
        body: c.body ?? '',
        tags: c.tags ?? [],
      })),
    };
    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `api-debug-cases-${Date.now()}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    setToast(`已导出 ${source.length} 条用例${selectedVisible.length > 0 ? '(仅选中的)' : ''}`);
  };

  const onImportFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    const input = e.target;
    if (!file) return;
    setImporting(true);
    try {
      const text = await file.text();
      let parsed: unknown;
      try {
        parsed = JSON.parse(text);
      } catch {
        throw new Error('文件不是合法的 JSON');
      }
      const rawList = Array.isArray(parsed)
        ? parsed
        : Array.isArray((parsed as { cases?: unknown })?.cases)
          ? (parsed as { cases: unknown[] }).cases
          : null;
      if (!rawList) throw new Error('文件缺少用例数组');
      const normalized: SaveDebugCaseInput[] = (rawList as Array<Record<string, unknown>>)
        .filter((x) => x && typeof x.name === 'string' && (x.endpoint_code || x.endpointCode))
        .map((x) => ({
          name: String(x.name),
          endpointCode: String(x.endpoint_code ?? x.endpointCode),
          method: String(x.method ?? 'GET'),
          path: String(x.path ?? ''),
          resource: String(x.resource ?? ''),
          action: String(x.action ?? ''),
          pathParams: (x.path_params ?? x.pathParams ?? {}) as Record<string, string>,
          queryParams: (x.query_params ?? x.queryParams ?? {}) as Record<string, string>,
          body: String(x.body ?? ''),
          tags: normalizeTags(x.tags ?? x.tag ?? []),
        }));
      if (normalized.length === 0) throw new Error('没有可导入的有效用例');
      await importDebugCases(normalized);
      setToast(`成功导入 ${normalized.length} 条用例`);
      await load();
    } catch (err) {
      console.error(err);
      setError(err instanceof Error ? err.message : '导入失败,请检查文件格式');
    } finally {
      input.value = '';
      setImporting(false);
    }
  };

  if (!open) return null;

  return (
    <div className="fixed inset-0 z-50 flex justify-end">
      <button
        type="button"
        aria-label="关闭"
        onClick={onClose}
        className="absolute inset-0 bg-foreground-950/40 cursor-default"
      />
      <aside className="relative w-full max-w-[560px] h-full bg-background-50 border-l border-background-200 flex flex-col animate-fade-up">
        <header className="flex items-start gap-3 px-4 md:px-5 py-4 border-b border-background-200">
          <span className="w-9 h-9 rounded-md flex items-center justify-center bg-primary-100 text-primary-700 shrink-0">
            <i className="ri-bookmark-3-line"></i>
          </span>
          <div className="min-w-0 flex-1">
            <h3 className="text-base font-semibold text-foreground-950">调试用例总览</h3>
            <p className="text-xs text-foreground-500 mt-0.5">
              集中查看所有接口保存的调试用例,可直接重放并查看真实响应
            </p>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="w-8 h-8 flex items-center justify-center rounded-md text-foreground-500 hover:bg-background-200 hover:text-foreground-900 cursor-pointer shrink-0"
          >
            <i className="ri-close-line"></i>
          </button>
        </header>

        <div className="px-4 md:px-5 py-3 border-b border-background-200 space-y-2.5">
          <div className="flex items-center gap-2">
            <div className="flex items-center gap-2 h-9 px-3 rounded-md bg-background-50 border border-background-200 flex-1">
              <i className="ri-search-line text-foreground-400 text-sm"></i>
              <input
                type="text"
                value={keyword}
                onChange={(e) => setKeyword(e.target.value)}
                placeholder="搜索用例名称 / 路径 / 权限码"
                className="flex-1 bg-transparent text-sm text-foreground-900 placeholder:text-foreground-400 focus:outline-none"
              />
            </div>
            <button
              type="button"
              onClick={load}
              title="刷新"
              className="w-9 h-9 flex items-center justify-center rounded-md bg-background-100 border border-background-300 text-foreground-700 hover:bg-background-200 cursor-pointer shrink-0"
            >
              <i className={loading ? 'ri-loader-4-line animate-spin' : 'ri-refresh-line'}></i>
            </button>
          </div>
          <div className="flex flex-wrap items-center gap-1.5">
            {methodFilters.map((m) => (
              <button
                key={m}
                type="button"
                onClick={() => setMethodFilter(m)}
                className={`h-7 px-2.5 rounded-full text-[11px] border cursor-pointer whitespace-nowrap transition-colors ${
                  methodFilter === m
                    ? 'bg-primary-500 text-background-50 border-primary-500 dark:text-foreground-950'
                    : 'bg-background-50 text-foreground-700 border-background-300 hover:bg-background-100'
                }`}
              >
                {m}
              </button>
            ))}
            <span className="ml-auto text-[11px] text-foreground-500">共 {filtered.length} 个用例</span>
          </div>
          {allTags.length > 0 ? (
            <div className="flex flex-wrap items-center gap-1.5">
              <span className="text-[11px] text-foreground-500 inline-flex items-center gap-1">
                <i className="ri-price-tag-3-line"></i>
                标签
              </span>
              <button
                type="button"
                onClick={() => setTagFilter('全部')}
                className={`h-7 px-2.5 rounded-full text-[11px] border cursor-pointer whitespace-nowrap transition-colors ${
                  tagFilter === '全部'
                    ? 'bg-secondary-500 text-background-50 border-secondary-500 dark:text-foreground-950'
                    : 'bg-background-50 text-foreground-700 border-background-300 hover:bg-background-100'
                }`}
              >
                全部
              </button>
              {allTags.map((t) => (
                <button
                  key={t}
                  type="button"
                  onClick={() => setTagFilter(t)}
                  className={`h-7 px-2.5 rounded-full text-[11px] border cursor-pointer whitespace-nowrap transition-colors ${
                    tagFilter === t
                      ? 'bg-secondary-500 text-background-50 border-secondary-500 dark:text-foreground-950'
                      : 'bg-background-50 text-foreground-700 border-background-300 hover:bg-background-100'
                  }`}
                >
                  #{t}
                </button>
              ))}
            </div>
          ) : null}
          <div className="flex flex-wrap items-center gap-2">
            <button
              type="button"
              onClick={toggleSelectAll}
              disabled={filtered.length === 0}
              className="h-8 px-2.5 rounded-md bg-background-100 border border-background-300 text-[11px] text-foreground-800 hover:bg-background-200 disabled:opacity-50 cursor-pointer whitespace-nowrap inline-flex items-center gap-1"
            >
              <i className={allFilteredSelected ? 'ri-checkbox-multiple-line' : 'ri-checkbox-blank-line'}></i>
              {allFilteredSelected ? '取消全选' : '全选当前'}
            </button>
            <button
              type="button"
              onClick={exportCases}
              disabled={filtered.length === 0}
              title="导出为 JSON 文件(已勾选则仅导出勾选项)"
              className="h-8 px-2.5 rounded-md bg-background-100 border border-background-300 text-[11px] text-foreground-800 hover:bg-background-200 disabled:opacity-50 cursor-pointer whitespace-nowrap inline-flex items-center gap-1"
            >
              <i className="ri-download-2-line"></i>
              导出 JSON
            </button>
            <button
              type="button"
              onClick={() => fileRef.current?.click()}
              disabled={importing}
              title="从 JSON 文件批量导入用例"
              className="h-8 px-2.5 rounded-md bg-background-100 border border-background-300 text-[11px] text-foreground-800 hover:bg-background-200 disabled:opacity-50 cursor-pointer whitespace-nowrap inline-flex items-center gap-1"
            >
              <i className={importing ? 'ri-loader-4-line animate-spin' : 'ri-upload-2-line'}></i>
              {importing ? '导入中…' : '导入 JSON'}
            </button>
            <input
              ref={fileRef}
              type="file"
              accept="application/json,.json"
              onChange={onImportFile}
              className="hidden"
            />
            {selectedVisible.length > 0 ? (
              <>
                <span className="text-[11px] text-foreground-600">已选 {selectedVisible.length} 条</span>
                <button
                  type="button"
                  onClick={batchReplay}
                  disabled={batchRunning}
                  className="h-8 px-3 rounded-md bg-primary-500 text-background-50 text-[11px] hover:bg-primary-600 disabled:opacity-60 cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5 dark:text-foreground-950"
                >
                  <i className={batchRunning ? 'ri-loader-4-line animate-spin' : 'ri-play-list-line'}></i>
                  {batchRunning ? '批量重放中…' : `批量重放 ${selectedVisible.length} 条`}
                </button>
                <button
                  type="button"
                  onClick={clearSelection}
                  disabled={batchRunning}
                  className="h-8 px-2.5 rounded-md bg-background-100 border border-background-300 text-[11px] text-foreground-700 hover:bg-background-200 disabled:opacity-50 cursor-pointer whitespace-nowrap"
                >
                  清空
                </button>
              </>
            ) : null}
          </div>
        </div>

        {batchSummary ? (
          <div className="px-4 md:px-5 py-2.5 border-b border-background-200">
            <div className="flex flex-wrap items-center gap-3 rounded-md bg-background-100 px-3 py-2.5">
              <span className="inline-flex items-center gap-1.5 text-xs text-foreground-700">
                <i className="ri-stack-line text-foreground-500"></i>
                批量重放完成,共 {batchSummary.total} 条
              </span>
              <span className="inline-flex items-center gap-1 text-xs px-2 py-0.5 rounded-full bg-primary-100 text-primary-800">
                <i className="ri-checkbox-circle-line"></i>
                成功 {batchSummary.ok}
              </span>
              <span className="inline-flex items-center gap-1 text-xs px-2 py-0.5 rounded-full bg-accent-100 text-accent-900">
                <i className="ri-error-warning-line"></i>
                失败 {batchSummary.fail}
              </span>
              <button
                type="button"
                onClick={() => setBatchSummary(null)}
                className="ml-auto text-[11px] text-foreground-500 hover:text-foreground-800 cursor-pointer whitespace-nowrap"
              >
                知道了
              </button>
            </div>
          </div>
        ) : null}

        {toast ? (
          <div className="px-4 md:px-5 py-2.5 border-b border-background-200">
            <div className="flex items-center gap-2 rounded-md bg-primary-50 px-3 py-2.5 text-xs text-primary-800 animate-fade-up">
              <i className="ri-checkbox-circle-line"></i>
              {toast}
            </div>
          </div>
        ) : null}

        <div className="flex-1 overflow-y-auto">
          {error ? (
            <div className="m-4 flex items-center justify-between gap-3 rounded-md bg-accent-100 border border-accent-200 px-4 py-3">
              <span className="text-sm text-accent-900">{error}</span>
              <button
                type="button"
                onClick={load}
                className="h-8 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-800 hover:bg-background-100 cursor-pointer whitespace-nowrap"
              >
                重试
              </button>
            </div>
          ) : loading ? (
            <div className="p-4 space-y-2.5">
              {[0, 1, 2, 3].map((n) => (
                <div key={n} className="h-16 rounded-md bg-background-100 animate-pulse-soft" />
              ))}
            </div>
          ) : filtered.length === 0 ? (
            <div className="py-20 text-center text-foreground-500">
              <i className="ri-bookmark-3-line text-3xl block mb-2"></i>
              {cases.length === 0 ? '还没有保存任何调试用例' : '没有匹配的用例'}
            </div>
          ) : (
            <ul className="divide-y divide-background-200">
              {filtered.map((c) => {
                const ep = endpointByCode.get(c.endpoint_code);
                const res = results[c.id];
                const expanded = expandedId === c.id;
                return (
                  <li key={c.id} className={`px-4 md:px-5 py-3.5 ${selected.has(c.id) ? 'bg-primary-50' : ''}`}>
                    <div className="flex items-center gap-2 flex-wrap">
                      <input
                        type="checkbox"
                        checked={selected.has(c.id)}
                        onChange={() => toggleSelect(c.id)}
                        aria-label={`选择用例 ${c.name}`}
                        className="w-4 h-4 accent-primary-500 cursor-pointer shrink-0"
                      />
                      <span className={`text-[10px] font-label px-1.5 py-0.5 rounded shrink-0 ${methodStyle[c.method ?? 'GET']}`}>
                        {c.method}
                      </span>
                      <span className="text-sm font-medium text-foreground-950 truncate">{c.name}</span>
                      <span className="ml-auto text-[11px] text-foreground-500 whitespace-nowrap">
                        {formatTime(c.created_at)}
                      </span>
                    </div>
                    <p className="mt-1 text-[11px] text-foreground-500 font-label truncate">
                      {c.path} · {c.endpoint_code}
                      {!ep ? ' · 接口已下线' : ''}
                    </p>
                    {c.tags && c.tags.length > 0 ? (
                      <div className="mt-1.5 flex flex-wrap gap-1">
                        {c.tags.map((t) => (
                          <button
                            key={t}
                            type="button"
                            onClick={() => setTagFilter(t)}
                            title={`按标签 #${t} 筛选`}
                            className="text-[10px] px-1.5 py-0.5 rounded-full bg-secondary-100 text-secondary-900 hover:bg-secondary-200 cursor-pointer"
                          >
                            #{t}
                          </button>
                        ))}
                      </div>
                    ) : null}

                    <div className="mt-2.5 flex flex-wrap items-center gap-1.5">
                      <button
                        type="button"
                        onClick={() => replay(c)}
                        disabled={busyId === c.id || !ep}
                        className="h-7 px-2.5 rounded-md bg-primary-500 text-background-50 text-[11px] hover:bg-primary-600 disabled:opacity-50 cursor-pointer whitespace-nowrap inline-flex items-center gap-1 dark:text-foreground-950"
                      >
                        <i className={busyId === c.id ? 'ri-loader-4-line animate-spin' : 'ri-play-line'}></i>
                        重放
                      </button>
                      <button
                        type="button"
                        onClick={() => onOpenEndpoint(c.endpoint_code)}
                        disabled={!ep}
                        className="h-7 px-2.5 rounded-md bg-background-100 border border-background-300 text-[11px] text-foreground-800 hover:bg-background-200 disabled:opacity-40 cursor-pointer whitespace-nowrap inline-flex items-center gap-1"
                      >
                        <i className="ri-external-link-line"></i>
                        打开接口
                      </button>
                      {res ? (
                        <button
                          type="button"
                          onClick={() => setExpandedId(expanded ? null : c.id)}
                          className="h-7 px-2.5 rounded-md bg-background-100 border border-background-300 text-[11px] text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap inline-flex items-center gap-1"
                        >
                          <i className={expanded ? 'ri-arrow-up-s-line' : 'ri-arrow-down-s-line'}></i>
                          {expanded ? '收起响应' : '查看响应'}
                        </button>
                      ) : null}
                      {res ? (
                        <span className={`text-[10px] font-label px-2 py-0.5 rounded ${statusTone(res.status)}`}>
                          {res.status} · {res.timeMs}ms
                        </span>
                      ) : null}
                      <button
                        type="button"
                        onClick={() => remove(c)}
                        disabled={busyId === c.id}
                        title="删除用例"
                        className="ml-auto w-7 h-7 flex items-center justify-center rounded-md text-foreground-500 hover:bg-secondary-200 hover:text-secondary-900 disabled:opacity-40 cursor-pointer shrink-0"
                      >
                        <i className="ri-delete-bin-line text-xs"></i>
                      </button>
                    </div>

                    {res && expanded ? (
                      <pre className="mt-2.5 px-3 py-2.5 rounded-md border border-background-200 bg-background-100/60 text-[11px] leading-relaxed font-label text-foreground-800 overflow-x-auto max-h-[280px]">
                        {JSON.stringify(res.data, null, 2)}
                      </pre>
                    ) : null}
                  </li>
                );
              })}
            </ul>
          )}
        </div>
      </aside>
    </div>
  );
}