import { useCallback, useEffect, useRef, useState } from 'react';
import Modal from '@/components/base/Modal';
import type { PluginRow } from '@/pages/plugins/types';

interface HotUpdateModalProps {
  open: boolean;
  plugin: PluginRow | null;
  onClose: () => void;
  onDone: (plugin: PluginRow) => void;
}

interface Step {
  key: string;
  label: string;
  icon: string;
  duration: number;
  logs: string[];
}

const buildSteps = (from: string, to: string): Step[] => [
  {
    key: 'check',
    label: '校验依赖与兼容性',
    icon: 'ri-shield-check-line',
    duration: 900,
    logs: [
      '> 解析 plugin.manifest.json (v' + to + ')',
      '> 检测宿主框架版本 >= 1.0.0 ... OK',
      '> 依赖树校验通过,无缺失项',
    ],
  },
  {
    key: 'download',
    label: '拉取更新包',
    icon: 'ri-download-2-line',
    duration: 1200,
    logs: [
      '> 连接插件仓库 registry.readdy.ai ... OK',
      '> 下载 ' + from + ' -> ' + to + ' (2.4 MB, 100%)',
      '> 校验 SHA-256 签名 ... 一致',
    ],
  },
  {
    key: 'backup',
    label: '备份当前版本',
    icon: 'ri-archive-2-line',
    duration: 800,
    logs: [
      '> 快照当前运行态 v' + from,
      '> 备份配置文件与数据表结构',
      '> 已写入 rollback 恢复点',
    ],
  },
  {
    key: 'install',
    label: '安装新版本',
    icon: 'ri-install-line',
    duration: 1300,
    logs: [
      '> 解压并落盘至 /plugins/hot/',
      '> 原子替换旧版本目录',
      '> 校验文件完整性 ... 全部通过',
    ],
  },
  {
    key: 'migrate',
    label: '迁移配置',
    icon: 'ri-database-2-line',
    duration: 1000,
    logs: [
      '> 读取历史配置并做 schema diff',
      '> 迁移 3 项配置,兼容 2 项旧配置',
      '> 无破坏性变更',
    ],
  },
  {
    key: 'reload',
    label: '热重载插件',
    icon: 'ri-loop-left-line',
    duration: 1100,
    logs: [
      '> 卸载旧模块实例(无需重启服务)',
      '> 装载新模块 v' + to + ' ... OK',
      '> 重新注册路由与钩子',
    ],
  },
  {
    key: 'health',
    label: '健康检查',
    icon: 'ri-pulse-line',
    duration: 900,
    logs: [
      '> 探活接口 /healthz ... 200',
      '> 依赖注入图重建完成',
      '> 插件运行正常,热更新成功',
    ],
  },
];

export default function HotUpdateModal({ open, plugin, onClose, onDone }: HotUpdateModalProps) {
  const [current, setCurrent] = useState(0);
  const [progress, setProgress] = useState(0);
  const [logs, setLogs] = useState<string[]>([]);
  const [finished, setFinished] = useState(false);
  const stepsRef = useRef<Step[]>([]);
  const timerRef = useRef<number | null>(null);
  const logRef = useRef<HTMLDivElement>(null);

  const stop = useCallback(() => {
    if (timerRef.current !== null) {
      window.clearInterval(timerRef.current);
      timerRef.current = null;
    }
  }, []);

  useEffect(() => {
    if (!open || !plugin) return undefined;
    const from = plugin.version ?? '0.0.0';
    const to = plugin.latest_version ?? from;
    const steps = buildSteps(from, to);
    stepsRef.current = steps;
    setCurrent(0);
    setProgress(0);
    setFinished(false);
    setLogs(['$ readdy plugin update --code ' + (plugin.code ?? '') + ' --to ' + to]);

    let idx = 0;
    let pct = 0;
    timerRef.current = window.setInterval(() => {
      const step = steps[idx];
      pct += 100 / (step.duration / 100);
      if (pct >= 100) {
        setLogs((prev) => [...prev, ...step.logs]);
        idx += 1;
        pct = 0;
        if (idx >= steps.length) {
          stop();
          setProgress(100);
          setCurrent(steps.length);
          setFinished(true);
          setLogs((prev) => [...prev, '✔ 热更新完成,插件已切换至最新版本,服务零中断']);
          return;
        }
      }
      setCurrent(idx);
      setProgress(Math.min(100, pct));
    }, 100);

    return stop;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, plugin]);

  useEffect(() => {
    if (logRef.current) {
      logRef.current.scrollTop = logRef.current.scrollHeight;
    }
  }, [logs]);

  const steps = stepsRef.current;
  const totalSteps = steps.length || 1;
  const overall = finished
    ? 100
    : Math.round(((current + progress / 100) / totalSteps) * 100);

  return (
    <Modal
      open={open}
      title="插件热更新"
      subtitle={plugin ? `${plugin.name} · ${plugin.version} → ${plugin.latest_version}` : ''}
      onClose={onClose}
      width="max-w-2xl"
      footer={
        <>
          <button
            type="button"
            onClick={() => {
              if (finished && plugin) onDone(plugin);
              onClose();
            }}
            className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
          >
            {finished ? '关闭' : '后台运行'}
          </button>
          {finished && plugin ? (
            <button
              type="button"
              onClick={() => {
                onDone(plugin);
                onClose();
              }}
              className="h-9 px-4 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 cursor-pointer whitespace-nowrap dark:text-foreground-950"
            >
              应用并完成
            </button>
          ) : (
            <span className="h-9 px-4 inline-flex items-center gap-2 rounded-md bg-primary-50 text-primary-800 text-sm whitespace-nowrap">
              <span className="w-2 h-2 rounded-full bg-primary-500 animate-pulse-soft" />
              更新进行中
            </span>
          )}
        </>
      }
    >
      <div className="space-y-5">
        <div>
          <div className="flex items-center justify-between mb-1.5">
            <span className="text-xs font-medium text-foreground-700">
              {finished ? '更新完成' : `正在执行:${steps[current]?.label ?? '准备中'}`}
            </span>
            <span className="text-xs font-label text-foreground-500">{overall}%</span>
          </div>
          <div className="h-2 rounded-full bg-background-200 overflow-hidden">
            <div
              className="h-full rounded-full bg-primary-500 transition-all duration-100"
              style={{ width: `${overall}%` }}
            />
          </div>
        </div>

        <ol className="grid grid-cols-1 sm:grid-cols-2 gap-x-4 gap-y-2.5">
          {steps.map((step, i) => {
            const done = finished || i < current;
            const active = !finished && i === current;
            return (
              <li key={step.key} className="flex items-center gap-2.5">
                <span
                  className={`w-7 h-7 rounded-full flex items-center justify-center shrink-0 text-xs ${
                    done
                      ? 'bg-primary-500 text-background-50'
                      : active
                        ? 'bg-accent-500 text-background-50'
                        : 'bg-background-200 text-foreground-500'
                  }`}
                >
                  <i className={done ? 'ri-check-line' : active ? 'ri-loader-4-line animate-spin' : step.icon}></i>
                </span>
                <span
                  className={`text-xs truncate ${
                    done || active ? 'text-foreground-900' : 'text-foreground-500'
                  }`}
                >
                  {step.label}
                </span>
              </li>
            );
          })}
        </ol>

        <div>
          <div className="flex items-center gap-1.5 mb-1.5">
            <i className="ri-terminal-box-line text-foreground-500 text-sm"></i>
            <span className="text-xs font-medium text-foreground-700">更新日志</span>
          </div>
          <div
            ref={logRef}
            className="h-40 overflow-y-auto rounded-md bg-foreground-950 px-3.5 py-3 font-label text-[11px] leading-relaxed text-background-200"
          >
            {logs.map((line, i) => (
              <div
                key={i}
                className={line.startsWith('✔') ? 'text-primary-300' : undefined}
              >
                {line}
              </div>
            ))}
          </div>
        </div>
      </div>
    </Modal>
  );
}