import { useEffect, useState } from 'react';
import Modal from '@/components/base/Modal';
import type { DeptNode } from '@/lib/departments';

export interface RoleOption {
  id: string;
  name: string;
  code: string | null;
}

export interface TenantOption {
  id: string;
  name: string;
}

export interface UserFormValues {
  full_name: string;
  email: string;
  status: string;
  tenant_id: string;
  department_id: string;
  roleIds: string[];
}

interface UserFormModalProps {
  open: boolean;
  editing: boolean;
  initial: UserFormValues | null;
  roles: RoleOption[];
  tenants: TenantOption[];
  departments: DeptNode[];
  saving: boolean;
  onClose: () => void;
  onSubmit: (values: UserFormValues) => void;
}

const emptyValues: UserFormValues = {
  full_name: '',
  email: '',
  status: 'active',
  tenant_id: '',
  department_id: '',
  roleIds: [],
};

export default function UserFormModal({
  open,
  editing,
  initial,
  roles,
  tenants,
  departments,
  saving,
  onClose,
  onSubmit,
}: UserFormModalProps) {
  const [values, setValues] = useState<UserFormValues>(emptyValues);
  const [error, setError] = useState('');

  useEffect(() => {
    if (open) {
      setValues(initial ?? emptyValues);
      setError('');
    }
  }, [open, initial]);

  const toggleRole = (roleId: string) => {
    setValues((prev) => ({
      ...prev,
      roleIds: prev.roleIds.includes(roleId)
        ? prev.roleIds.filter((id) => id !== roleId)
        : [...prev.roleIds, roleId],
    }));
  };

  const handleSubmit = () => {
    if (!values.full_name.trim()) {
      setError('请输入姓名');
      return;
    }
    if (!values.email.trim() || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email)) {
      setError('请输入正确的邮箱');
      return;
    }
    setError('');
    onSubmit(values);
  };

  return (
    <Modal
      open={open}
      title={editing ? '编辑用户' : '新增用户'}
      subtitle="设置基础信息并分配角色"
      onClose={onClose}
      footer={
        <>
          <button
            type="button"
            onClick={onClose}
            className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
          >
            取消
          </button>
          <button
            type="button"
            onClick={handleSubmit}
            disabled={saving}
            className="h-9 px-4 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 disabled:opacity-60 cursor-pointer whitespace-nowrap dark:text-foreground-950"
          >
            {saving ? '保存中…' : '保存'}
          </button>
        </>
      }
    >
      <div className="space-y-4">
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3.5">
          <div>
            <label className="block text-xs font-medium text-foreground-700 mb-1.5">姓名</label>
            <input
              type="text"
              value={values.full_name}
              onChange={(e) => setValues((p) => ({ ...p, full_name: e.target.value }))}
              placeholder="请输入姓名"
              className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400"
            />
          </div>
          <div>
            <label className="block text-xs font-medium text-foreground-700 mb-1.5">邮箱</label>
            <input
              type="email"
              value={values.email}
              onChange={(e) => setValues((p) => ({ ...p, email: e.target.value }))}
              placeholder="you@example.com"
              className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400"
            />
          </div>
          <div>
            <label className="block text-xs font-medium text-foreground-700 mb-1.5">所属部门</label>
            <select
              value={values.department_id}
              onChange={(e) => setValues((p) => ({ ...p, department_id: e.target.value }))}
              className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400 cursor-pointer"
            >
              <option value="">未指定</option>
              {departments.map((d) => (
                <option key={d.id} value={d.id}>
                  {'\u3000'.repeat(d.depth)}
                  {d.name}
                </option>
              ))}
            </select>
          </div>
          <div>
            <label className="block text-xs font-medium text-foreground-700 mb-1.5">所属租户</label>
            <select
              value={values.tenant_id}
              onChange={(e) => setValues((p) => ({ ...p, tenant_id: e.target.value }))}
              className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400 cursor-pointer"
            >
              <option value="">未指定</option>
              {tenants.map((t) => (
                <option key={t.id} value={t.id}>
                  {t.name}
                </option>
              ))}
            </select>
          </div>
          <div>
            <label className="block text-xs font-medium text-foreground-700 mb-1.5">状态</label>
            <select
              value={values.status}
              onChange={(e) => setValues((p) => ({ ...p, status: e.target.value }))}
              className="w-full h-10 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400 cursor-pointer"
            >
              <option value="active">正常</option>
              <option value="disabled">已停用</option>
            </select>
          </div>
        </div>

        <div>
          <label className="block text-xs font-medium text-foreground-700 mb-2">分配角色</label>
          <div className="flex flex-wrap gap-2">
            {roles.map((role) => {
              const active = values.roleIds.includes(role.id);
              return (
                <button
                  key={role.id}
                  type="button"
                  onClick={() => toggleRole(role.id)}
                  className={`inline-flex items-center gap-1.5 h-8 px-3 rounded-full text-xs border cursor-pointer whitespace-nowrap transition-colors ${
                    active
                      ? 'bg-primary-500 text-background-50 border-primary-500 dark:text-foreground-950'
                      : 'bg-background-50 text-foreground-700 border-background-300 hover:bg-background-100'
                  }`}
                >
                  {active ? <i className="ri-check-line"></i> : null}
                  {role.name}
                </button>
              );
            })}
          </div>
        </div>

        {error ? (
          <div className="flex items-start gap-2 px-3 py-2.5 rounded-md bg-accent-100 text-accent-900 text-xs">
            <i className="ri-error-warning-line mt-0.5"></i>
            <span>{error}</span>
          </div>
        ) : null}
      </div>
    </Modal>
  );
}