import { methodStyle, type EndpointDef } from '@/pages/api-docs/types';

interface EndpointListProps {
  endpoints: EndpointDef[];
  selectedId: string | null;
  onSelect: (id: string) => void;
  keyword: string;
  onKeyword: (value: string) => void;
  methodFilter: string;
  onMethodFilter: (value: string) => void;
}

const methodTabs = ['全部', 'GET', 'POST', 'PUT', 'DELETE'];

export default function EndpointList({
  endpoints,
  selectedId,
  onSelect,
  keyword,
  onKeyword,
  methodFilter,
  onMethodFilter,
}: EndpointListProps) {
  const groups = endpoints.reduce<Record<string, EndpointDef[]>>((acc, ep) => {
    if (!acc[ep.moduleLabel]) acc[ep.moduleLabel] = [];
    acc[ep.moduleLabel].push(ep);
    return acc;
  }, {});

  return (
    <div className="rounded-lg bg-background-50 border border-background-200 flex flex-col max-h-[calc(100vh-190px)]">
      <div className="p-3.5 border-b border-background-200 space-y-2.5">
        <div className="flex items-center gap-2 h-9 px-3 rounded-md bg-background-100 border border-background-200">
          <i className="ri-search-line text-foreground-400 text-sm"></i>
          <input
            type="text"
            value={keyword}
            onChange={(e) => onKeyword(e.target.value)}
            placeholder="搜索接口路径或名称"
            className="flex-1 bg-transparent text-sm text-foreground-900 placeholder:text-foreground-400 focus:outline-none"
          />
        </div>
        <div className="inline-flex flex-wrap gap-1 p-1 rounded-full bg-background-200/70">
          {methodTabs.map((m) => (
            <button
              key={m}
              type="button"
              onClick={() => onMethodFilter(m)}
              className={`px-2.5 py-1 text-[11px] rounded-full cursor-pointer whitespace-nowrap font-label ${
                methodFilter === m ? 'bg-background-50 text-foreground-950 font-medium' : 'text-foreground-600'
              }`}
            >
              {m}
            </button>
          ))}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-2.5 space-y-3">
        {Object.keys(groups).length === 0 ? (
          <div className="py-14 text-center text-foreground-500">
            <i className="ri-route-line text-2xl block mb-2"></i>
            <p className="text-sm">没有匹配的接口</p>
          </div>
        ) : (
          Object.entries(groups).map(([label, list]) => (
            <div key={label}>
              <div className="flex items-center gap-1.5 px-2 mb-1.5">
                <i className="ri-folders-line text-[13px] text-foreground-400"></i>
                <span className="text-[11px] font-medium text-foreground-400">{label}</span>
                <span className="text-[10px] text-foreground-400 font-label">({list.length})</span>
              </div>
              <ul className="space-y-1">
                {list.map((ep) => (
                  <li key={ep.id}>
                    <button
                      type="button"
                      onClick={() => onSelect(ep.id)}
                      className={`w-full text-left rounded-md px-2.5 py-2 cursor-pointer transition-colors ${
                        selectedId === ep.id
                          ? 'bg-primary-50 border border-primary-200'
                          : 'border border-transparent hover:bg-background-100'
                      }`}
                    >
                      <div className="flex items-center gap-2">
                        <span
                          className={`shrink-0 text-[10px] font-label px-1.5 py-0.5 rounded ${methodStyle[ep.method]}`}
                        >
                          {ep.method}
                        </span>
                        <span className="text-xs font-label text-foreground-800 truncate">{ep.path}</span>
                      </div>
                      <p className="mt-1 text-[11px] text-foreground-500 truncate">{ep.summary}</p>
                    </button>
                  </li>
                ))}
              </ul>
            </div>
          ))
        )}
      </div>
    </div>
  );
}