import type { ReactNode } from 'react';

interface DocHeadingProps {
  id: string;
  children: ReactNode;
  sub?: string;
}

export function DocHeading({ id, children, sub }: DocHeadingProps) {
  return (
    <div id={id} className="scroll-mt-24">
      <h3 className="text-base font-semibold text-foreground-950 font-heading">{children}</h3>
      {sub ? <p className="mt-1 text-sm text-foreground-500">{sub}</p> : null}
    </div>
  );
}

type CalloutTone = 'info' | 'tip' | 'warn';

const calloutStyle: Record<CalloutTone, { wrap: string; icon: string; tone: string }> = {
  info: { wrap: 'bg-primary-50 border-primary-200', icon: 'ri-information-line text-primary-600', tone: 'text-primary-900' },
  tip: { wrap: 'bg-accent-50 border-accent-200', icon: 'ri-lightbulb-line text-accent-700', tone: 'text-accent-900' },
  warn: { wrap: 'bg-secondary-50 border-secondary-200', icon: 'ri-alert-line text-secondary-700', tone: 'text-secondary-900' },
};

interface CalloutProps {
  tone?: CalloutTone;
  title: string;
  children: ReactNode;
}

export function Callout({ tone = 'info', title, children }: CalloutProps) {
  const s = calloutStyle[tone];
  return (
    <div className={`rounded-lg border px-4 py-3 ${s.wrap}`}>
      <div className="flex items-center gap-2">
        <i className={`${s.icon} text-[15px]`}></i>
        <span className={`text-sm font-medium ${s.tone}`}>{title}</span>
      </div>
      <div className="mt-1.5 text-sm text-foreground-700 leading-relaxed">{children}</div>
    </div>
  );
}

interface PropRow {
  name: string;
  type: string;
  desc: string;
  required?: boolean;
}

interface PropTableProps {
  rows: PropRow[];
  head?: string[];
}

export function PropTable({ rows, head = ['属性', '类型', '说明'] }: PropTableProps) {
  return (
    <div className="rounded-lg border border-background-200 overflow-hidden">
      <div className="overflow-x-auto">
        <table className="w-full text-sm">
          <thead>
            <tr className="bg-background-100 text-left">
              {head.map((h) => (
                <th key={h} className="px-3.5 py-2.5 text-xs font-medium text-foreground-600 whitespace-nowrap">
                  {h}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.map((row) => (
              <tr key={row.name} className="border-t border-background-200">
                <td className="px-3.5 py-2.5 align-top whitespace-nowrap">
                  <span className="font-label text-[12.5px] text-foreground-900">{row.name}</span>
                  {row.required ? <span className="ml-1.5 text-[10px] text-accent-700">必填</span> : null}
                </td>
                <td className="px-3.5 py-2.5 align-top whitespace-nowrap">
                  <span className="font-label text-[12px] text-primary-700">{row.type}</span>
                </td>
                <td className="px-3.5 py-2.5 align-top text-foreground-600">{row.desc}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

interface FeatureItem {
  icon: string;
  title: string;
  desc: string;
}

export function FeatureList({ items }: { items: FeatureItem[] }) {
  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
      {items.map((item) => (
        <div key={item.title} className="rounded-lg border border-background-200 bg-background-50 p-4">
          <span className="w-9 h-9 rounded-md flex items-center justify-center bg-primary-100 text-primary-700">
            <i className={`${item.icon} text-lg`}></i>
          </span>
          <p className="mt-3 text-sm font-medium text-foreground-950">{item.title}</p>
          <p className="mt-1 text-[13px] text-foreground-600 leading-relaxed">{item.desc}</p>
        </div>
      ))}
    </div>
  );
}