import { useCallback, useEffect, useMemo, useState } from 'react';
import { supabase } from '@/lib/supabase';
import { useAuth } from '@/contexts/AuthContext';
import { moveToRecycleBin } from '@/lib/recycleBin';
import { recordAuditLog } from '@/lib/auditLog';
import { useTenant, type TenantRow } from '@/contexts/TenantContext';
import Modal from '@/components/base/Modal';
import TenantFormModal, {
  planMeta,
  type TenantFormValues,
} from '@/pages/system/tenants/components/TenantFormModal';

function fmtDate(iso: string | null) {
  if (!iso) return '—';
  const d = new Date(iso);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

function QuotaBar({ label, used, total, unit }: { label: string; used: number; total: number; unit: string }) {
  const pct = total > 0 ? Math.min(100, Math.round((used / total) * 100)) : 0;
  const tone = pct >= 90 ? 'bg-secondary-600' : pct >= 70 ? 'bg-accent-500' : 'bg-primary-500';
  return (
    <div>
      <div className="flex items-center justify-between text-[11px] text-foreground-500 mb-1">
        <span>{label}</span>
        <span className="font-label">
          {used.toLocaleString()} / {total.toLocaleString()} {unit}
        </span>
      </div>
      <div className="h-1.5 rounded-full bg-background-200 overflow-hidden">
        <div className={`h-full rounded-full ${tone}`} style={{ width: `${pct}%` }} />
      </div>
    </div>
  );
}

export default function TenantsPage() {
  const { hasPermission } = useAuth();
  const canCreate = hasPermission('tenant:create');
  const canUpdate = hasPermission('tenant:update');
  const canDelete = hasPermission('tenant:delete');

  const { tenants, refreshTenants, currentTenantId, setCurrentTenantId, currentTenant } = useTenant();

  const [userCounts, setUserCounts] = useState<Record<string, number>>({});
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');

  const [keyword, setKeyword] = useState('');
  const [planFilter, setPlanFilter] = useState('all');

  const [formOpen, setFormOpen] = useState(false);
  const [editing, setEditing] = useState<TenantRow | null>(null);
  const [saving, setSaving] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState<TenantRow | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const { data, error: err } = await supabase.from('profiles').select('tenant_id');
      if (err) throw err;
      const counts: Record<string, number> = {};
      ((data as { tenant_id: string | null }[]) ?? []).forEach((row) => {
        if (row.tenant_id) counts[row.tenant_id] = (counts[row.tenant_id] ?? 0) + 1;
      });
      setUserCounts(counts);
      await refreshTenants();
    } catch (err) {
      console.error(err);
      setError('加载租户数据失败,请重试');
    } finally {
      setLoading(false);
    }
  }, [refreshTenants]);

  useEffect(() => {
    load();
  }, [load]);

  useEffect(() => {
    if (!notice) return;
    const timer = setTimeout(() => setNotice(''), 2600);
    return () => clearTimeout(timer);
  }, [notice]);

  const stats = useMemo(() => {
    const active = tenants.filter((t) => t.status === 'active').length;
    const totalSeats = tenants.reduce((s, t) => s + (t.seats ?? 0), 0);
    const usedSeats = tenants.reduce((s, t) => s + (t.seat_used ?? 0), 0);
    const apiUsed = tenants.reduce((s, t) => s + (t.api_used ?? 0), 0);
    return { total: tenants.length, active, totalSeats, usedSeats, apiUsed };
  }, [tenants]);

  const filtered = useMemo(
    () =>
      tenants.filter((t) => {
        const kw = keyword.trim().toLowerCase();
        const matchKw =
          !kw ||
          (t.name ?? '').toLowerCase().includes(kw) ||
          (t.code ?? '').toLowerCase().includes(kw) ||
          (t.owner ?? '').toLowerCase().includes(kw);
        const matchPlan = planFilter === 'all' || t.plan === planFilter;
        return matchKw && matchPlan;
      }),
    [tenants, keyword, planFilter],
  );

  const openCreate = () => {
    setEditing(null);
    setFormOpen(true);
  };
  const openEdit = (t: TenantRow) => {
    setEditing(t);
    setFormOpen(true);
  };

  const initialValues: TenantFormValues | null = editing
    ? {
        name: editing.name,
        code: editing.code ?? '',
        plan: editing.plan ?? 'standard',
        status: editing.status ?? 'active',
        seats: editing.seats ?? 10,
        owner: editing.owner ?? '',
        contact_email: editing.contact_email ?? '',
        expires_at: editing.expires_at ?? '',
        storage_quota_gb: editing.storage_quota_gb ?? 50,
        api_quota: editing.api_quota ?? 100000,
      }
    : null;

  const handleSubmit = async (values: TenantFormValues) => {
    setSaving(true);
    try {
      const payload = {
        name: values.name,
        code: values.code,
        plan: values.plan,
        status: values.status,
        seats: values.seats,
        owner: values.owner,
        contact_email: values.contact_email,
        expires_at: values.expires_at ? new Date(values.expires_at).toISOString() : null,
        storage_quota_gb: values.storage_quota_gb,
        api_quota: values.api_quota,
      };
      if (editing) {
        const { error: err } = await supabase.from('tenants').update(payload).eq('id', editing.id);
        if (err) throw err;
        setNotice('租户信息已更新');
        await recordAuditLog({
          action: '修改租户',
          module: '多租户管理',
          detail: `修改租户「${payload.name}」`,
        });
      } else {
        const { error: err } = await supabase
          .from('tenants')
          .insert({ ...payload, seat_used: 0, api_used: 0 });
        if (err) throw err;
        setNotice('租户创建成功');
        await recordAuditLog({
          action: '新增租户',
          module: '多租户管理',
          detail: `新增租户「${payload.name}」`,
        });
      }
      setFormOpen(false);
      setEditing(null);
      await load();
    } catch (err) {
      console.error(err);
      setError('保存失败,请检查权限后重试');
    } finally {
      setSaving(false);
    }
  };

  const toggleStatus = async (t: TenantRow) => {
    const next = t.status === 'active' ? 'disabled' : 'active';
    const { error: err } = await supabase.from('tenants').update({ status: next }).eq('id', t.id);
    if (err) {
      setError('状态更新失败');
      return;
    }
    setNotice(next === 'active' ? '已恢复该租户' : '已冻结该租户');
    await recordAuditLog({
      action: next === 'active' ? '恢复租户' : '冻结租户',
      module: '多租户管理',
      level: 'warn',
      detail: `${next === 'active' ? '恢复' : '冻结'}租户「${t.name}」`,
    });
    if (currentTenantId === t.id && next === 'disabled') {
      setCurrentTenantId('all');
    }
    await load();
  };

  const confirmDelete = async () => {
    if (!deleteTarget) return;
    try {
      const { error: err } = await supabase.from('tenants').delete().eq('id', deleteTarget.id);
      if (err) throw err;
      await moveToRecycleBin({
        module: 'tenant',
        itemId: deleteTarget.id,
        itemName: deleteTarget.name,
        snapshot: {
          id: deleteTarget.id,
          name: deleteTarget.name,
          code: deleteTarget.code,
          plan: deleteTarget.plan,
          status: deleteTarget.status,
          seats: deleteTarget.seats,
          owner: deleteTarget.owner,
          contact_email: deleteTarget.contact_email,
          expires_at: deleteTarget.expires_at,
          storage_quota_gb: deleteTarget.storage_quota_gb,
          api_quota: deleteTarget.api_quota,
          seat_used: deleteTarget.seat_used,
          api_used: deleteTarget.api_used,
        },
      });
      if (currentTenantId === deleteTarget.id) setCurrentTenantId('all');
      setNotice('租户已删除,可在回收站还原');
      await recordAuditLog({
        action: '删除租户',
        module: '多租户管理',
        level: 'warn',
        detail: `删除租户「${deleteTarget.name}」`,
      });
      setDeleteTarget(null);
      await load();
    } catch (err) {
      console.error(err);
      setError('删除失败,可能仍有用户关联该租户');
      setDeleteTarget(null);
    }
  };

  const statCards = [
    { label: '租户总数', value: stats.total, icon: 'ri-building-2-line', tone: 'bg-primary-100 text-primary-700' },
    { label: '正常运营', value: stats.active, icon: 'ri-checkbox-circle-line', tone: 'bg-accent-100 text-accent-800' },
    {
      label: '席位使用',
      value: `${stats.usedSeats}/${stats.totalSeats}`,
      icon: 'ri-group-line',
      tone: 'bg-secondary-200 text-secondary-900',
    },
    {
      label: 'API 调用',
      value: `${(stats.apiUsed / 1000).toFixed(0)}k`,
      icon: 'ri-bar-chart-2-line',
      tone: 'bg-primary-100 text-primary-700',
    },
  ];

  return (
    <div className="space-y-4">
      <div className="flex flex-col md:flex-row md:items-center gap-3">
        <div>
          <h2 className="text-lg font-semibold text-foreground-950">多租户管理</h2>
          <p className="text-sm text-foreground-500 mt-0.5">
            管理租户套餐、状态与资源配额,切换顶部租户即可按租户隔离查看数据
          </p>
        </div>
        <div className="md:ml-auto flex flex-wrap items-center gap-2">
          <div className="flex items-center gap-2 h-9 px-3 rounded-md bg-background-50 border border-background-200 w-full sm:w-52">
            <i className="ri-search-line text-foreground-400 text-sm"></i>
            <input
              type="text"
              value={keyword}
              onChange={(e) => setKeyword(e.target.value)}
              placeholder="搜索租户名称 / 标识"
              className="flex-1 bg-transparent text-sm text-foreground-900 placeholder:text-foreground-400 focus:outline-none"
            />
          </div>
          <select
            value={planFilter}
            onChange={(e) => setPlanFilter(e.target.value)}
            className="h-9 px-3 rounded-md bg-background-50 border border-background-200 text-sm text-foreground-800 focus:outline-none cursor-pointer"
          >
            <option value="all">全部套餐</option>
            {Object.entries(planMeta).map(([k, v]) => (
              <option key={k} value={k}>
                {v.label}
              </option>
            ))}
          </select>
          <button
            type="button"
            onClick={openCreate}
            disabled={!canCreate}
            className="h-9 px-3.5 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 disabled:opacity-50 cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5 dark:text-foreground-950"
          >
            <i className="ri-add-line"></i>
            新增租户
          </button>
        </div>
      </div>

      {currentTenant ? (
        <div className="flex flex-wrap items-center gap-3 px-4 py-3 rounded-lg bg-secondary-100 border border-secondary-200">
          <span className="w-8 h-8 rounded-md bg-secondary-200 text-secondary-900 flex items-center justify-center">
            <i className="ri-filter-3-line"></i>
          </span>
          <div className="text-sm text-secondary-900">
            当前数据隔离视角:
            <span className="font-medium"> {currentTenant.name}</span>
            <span className="text-xs text-foreground-600 ml-2">(仅展示该租户下的数据)</span>
          </div>
          <button
            type="button"
            onClick={() => setCurrentTenantId('all')}
            className="ml-auto h-8 px-3 rounded-md bg-background-50 border border-background-300 text-xs text-foreground-800 hover:bg-background-100 cursor-pointer whitespace-nowrap"
          >
            查看全部租户
          </button>
        </div>
      ) : (
        <div className="flex flex-wrap items-center gap-3 px-4 py-3 rounded-lg bg-background-50 border border-background-200">
          <span className="w-8 h-8 rounded-md bg-background-100 text-foreground-600 flex items-center justify-center">
            <i className="ri-global-line"></i>
          </span>
          <div className="text-sm text-foreground-700">
            当前视角:<span className="font-medium">全部租户</span>
            <span className="text-xs text-foreground-500 ml-2">
              (在顶部选择具体租户即可启用全局数据隔离)
            </span>
          </div>
        </div>
      )}

      {notice ? (
        <div className="flex items-center gap-2 px-3 py-2.5 rounded-md bg-primary-50 text-primary-800 text-sm animate-fade-up">
          <i className="ri-checkbox-circle-line"></i>
          {notice}
        </div>
      ) : null}
      {error ? (
        <div className="flex items-center justify-between gap-3 px-3 py-2.5 rounded-md bg-accent-100 text-accent-900 text-sm">
          {error}
          <button type="button" onClick={load} className="text-xs underline cursor-pointer whitespace-nowrap">
            重试
          </button>
        </div>
      ) : null}

      <section className="grid grid-cols-2 xl:grid-cols-4 gap-3 md:gap-4">
        {statCards.map((s) => (
          <div key={s.label} className="rounded-lg bg-background-50 border border-background-200 p-4">
            <div className="flex items-center gap-2">
              <span className={`w-8 h-8 rounded-md flex items-center justify-center ${s.tone}`}>
                <i className={`${s.icon} text-sm`}></i>
              </span>
              <span className="text-xs text-foreground-500">{s.label}</span>
            </div>
            <p className="mt-2.5 text-2xl font-semibold text-foreground-950 font-label">{s.value}</p>
          </div>
        ))}
      </section>

      {loading ? (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {[0, 1, 2, 3].map((n) => (
            <div key={n} className="h-52 rounded-lg bg-background-50 border border-background-200 animate-pulse-soft" />
          ))}
        </div>
      ) : filtered.length === 0 ? (
        <div className="rounded-lg bg-background-50 border border-background-200 py-16 text-center text-foreground-500">
          <i className="ri-building-2-line text-3xl block mb-2"></i>
          没有匹配的租户
        </div>
      ) : (
        <section className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {filtered.map((t) => {
            const plan = planMeta[t.plan ?? 'standard'] ?? planMeta.standard;
            const active = t.status === 'active';
            const isCurrent = currentTenantId === t.id;
            return (
              <article
                key={t.id}
                className={`rounded-lg bg-background-50 border p-4 md:p-5 ${
                  isCurrent ? 'border-primary-400' : 'border-background-200'
                }`}
              >
                <div className="flex items-start gap-3">
                  <div className="w-11 h-11 rounded-lg bg-primary-100 text-primary-700 flex items-center justify-center shrink-0">
                    <i className="ri-building-2-line text-xl"></i>
                  </div>
                  <div className="min-w-0 flex-1">
                    <div className="flex items-center gap-2">
                      <h3 className="text-sm font-semibold text-foreground-950 truncate">{t.name}</h3>
                      <span className={`shrink-0 text-[10px] px-2 py-0.5 rounded-full ${plan.tone}`}>
                        {plan.label}
                      </span>
                      {isCurrent ? (
                        <span className="shrink-0 text-[10px] px-1.5 py-0.5 rounded-full bg-primary-500 text-background-50">
                          当前
                        </span>
                      ) : null}
                    </div>
                    <div className="mt-0.5 flex flex-wrap items-center gap-2 text-[11px] text-foreground-500">
                      <span className="font-label">{t.code}</span>
                      <span>·</span>
                      <span className="inline-flex items-center gap-1">
                        <span className={`w-1.5 h-1.5 rounded-full ${active ? 'bg-primary-500' : 'bg-foreground-400'}`} />
                        {active ? '正常' : '已冻结'}
                      </span>
                      <span>·</span>
                      <span>负责人 {t.owner ?? '—'}</span>
                    </div>
                  </div>
                </div>

                <div className="mt-4 space-y-3">
                  <QuotaBar
                    label="席位"
                    used={userCounts[t.id] ?? t.seat_used ?? 0}
                    total={t.seats ?? 0}
                    unit="人"
                  />
                  <QuotaBar
                    label="API 调用"
                    used={t.api_used ?? 0}
                    total={t.api_quota ?? 0}
                    unit="次"
                  />
                </div>

                <div className="mt-3 flex items-center gap-3 text-[11px] text-foreground-500">
                  <span className="inline-flex items-center gap-1">
                    <i className="ri-hard-drive-2-line"></i>
                    {t.storage_quota_gb} GB 存储
                  </span>
                  <span className="inline-flex items-center gap-1">
                    <i className="ri-calendar-line"></i>
                    {fmtDate(t.expires_at)} 到期
                  </span>
                </div>

                <div className="mt-4 pt-3.5 border-t border-background-200 flex flex-wrap items-center gap-1.5">
                  <button
                    type="button"
                    onClick={() => setCurrentTenantId(isCurrent ? 'all' : t.id)}
                    className={`h-8 px-2.5 rounded-md text-xs cursor-pointer whitespace-nowrap inline-flex items-center gap-1 ${
                      isCurrent
                        ? 'bg-primary-100 text-primary-800'
                        : 'bg-background-100 border border-background-300 text-foreground-800 hover:bg-background-200'
                    }`}
                  >
                    <i className={isCurrent ? 'ri-checkbox-circle-line' : 'ri-login-box-line'}></i>
                    {isCurrent ? '已切换' : '切换查看'}
                  </button>
                  <button
                    type="button"
                    onClick={() => openEdit(t)}
                    disabled={!canUpdate}
                    className="h-8 px-2.5 rounded-md bg-background-100 border border-background-300 text-xs text-foreground-800 hover:bg-background-200 disabled:opacity-40 cursor-pointer whitespace-nowrap inline-flex items-center gap-1"
                  >
                    <i className="ri-pencil-line"></i>
                    编辑
                  </button>
                  <button
                    type="button"
                    onClick={() => toggleStatus(t)}
                    disabled={!canUpdate}
                    className="h-8 px-2.5 rounded-md bg-background-100 border border-background-300 text-xs text-foreground-800 hover:bg-background-200 disabled:opacity-40 cursor-pointer whitespace-nowrap inline-flex items-center gap-1"
                  >
                    <i className={active ? 'ri-forbid-2-line' : 'ri-play-circle-line'}></i>
                    {active ? '冻结' : '恢复'}
                  </button>
                  <button
                    type="button"
                    onClick={() => setDeleteTarget(t)}
                    disabled={!canDelete}
                    className="ml-auto h-8 w-8 rounded-md flex items-center justify-center text-foreground-500 hover:bg-secondary-200 hover:text-secondary-900 disabled:opacity-40 cursor-pointer"
                    aria-label="删除租户"
                  >
                    <i className="ri-delete-bin-line"></i>
                  </button>
                </div>
              </article>
            );
          })}
        </section>
      )}

      <TenantFormModal
        open={formOpen}
        editing={Boolean(editing)}
        initial={initialValues}
        saving={saving}
        onClose={() => {
          setFormOpen(false);
          setEditing(null);
        }}
        onSubmit={handleSubmit}
      />

      <Modal
        open={Boolean(deleteTarget)}
        title="删除租户"
        onClose={() => setDeleteTarget(null)}
        footer={
          <>
            <button
              type="button"
              onClick={() => setDeleteTarget(null)}
              className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
            >
              取消
            </button>
            <button
              type="button"
              onClick={confirmDelete}
              className="h-9 px-4 rounded-md bg-secondary-700 text-background-50 text-sm hover:bg-secondary-800 cursor-pointer whitespace-nowrap"
            >
              确认删除
            </button>
          </>
        }
      >
        <p className="text-sm text-foreground-700">
          确定删除租户
          <span className="font-medium text-foreground-950"> {deleteTarget?.name} </span>
          吗?删除后可在回收站还原,请先确认其下已无关联用户。
        </p>
      </Modal>
    </div>
  );
}