export interface MemberRow {
  id: string;
  email: string | null;
  nickname: string | null;
  phone: string | null;
  avatar_url: string | null;
  bio: string | null;
  level: string | null;
  status: string | null;
  points: number | null;
  joined_at: string | null;
  created_at: string | null;
}

export const memberLevels: Record<string, { label: string; tone: string; icon: string }> = {
  standard: { label: '普通会员', tone: 'bg-background-200 text-foreground-700', icon: 'ri-user-line' },
  silver: { label: '白银会员', tone: 'bg-secondary-200 text-secondary-900', icon: 'ri-medal-line' },
  gold: { label: '黄金会员', tone: 'bg-accent-100 text-accent-900', icon: 'ri-vip-diamond-line' },
  platinum: { label: '铂金会员', tone: 'bg-primary-100 text-primary-800', icon: 'ri-vip-crown-line' },
};

export const memberLevelKeys = ['standard', 'silver', 'gold', 'platinum'];

export function memberLevelMeta(level: string | null) {
  return memberLevels[level ?? 'standard'] ?? memberLevels.standard;
}