import CodeBlock from '@/pages/docs/components/CodeBlock';
import { Callout, DocHeading, PropTable } from '@/pages/docs/components/DocPrimitives';

export default function ApiSection() {
  return (
    <div className="space-y-7">
      <DocHeading id="api" sub="所有接口走统一的 REST 约定,认证由后端签发,前端通过 SDK 或标准 HTTP 调用。">
        API 调用与鉴权
      </DocHeading>

      <div>
        <h4 className="text-sm font-semibold text-foreground-950 mb-3">
          <a href="#api-auth" className="hover:text-primary-700">
            鉴权方式
          </a>
        </h4>
        <PropTable
          head={['请求头', '值', '说明']}
          rows={[
            { name: 'apikey', type: 'anon / service key', desc: '标识调用方应用,公开接口使用匿名公钥', required: true },
            { name: 'Authorization', type: 'Bearer <token>', desc: '登录后从会话获取的用户令牌', required: true },
            { name: 'Content-Type', type: 'application/json', desc: 'JSON 请求体时携带', required: false },
          ]}
        />
        <Callout tone="warn" title="私密密钥不下发前端">
          需要调用第三方私密服务(如支付、邮件)时,一律通过后端 Edge Function 中转,
          密钥存在后端环境变量里,前端只调用自己的函数,不接触原始密钥。
        </Callout>
      </div>

      <div>
        <h4 className="text-sm font-semibold text-foreground-950 mb-3">
          <a href="#api-fetch" className="hover:text-primary-700">
            Token 获取与 REST 调用
          </a>
        </h4>
        <CodeBlock
          language="ts"
          filename="获取会话令牌并发起请求"
          code={`import { supabase } from '@/lib/supabase';

// 1. 取当前会话令牌
const { data: { session } } = await supabase.auth.getSession();
const token = session?.access_token;

// 2. 携带令牌调用业务接口
const res = await fetch(\`\${import.meta.env.VITE_PUBLIC_SUPABASE_URL}/rest/v1/profiles\`, {
  headers: {
    apikey: import.meta.env.VITE_PUBLIC_SUPABASE_ANON_KEY,
    Authorization: \`Bearer \${token}\`,
    'Content-Type': 'application/json',
  },
});

const profiles = await res.json();`}
        />
      </div>

      <div>
        <h4 className="text-sm font-semibold text-foreground-950 mb-3">
          <a href="#api-sdk" className="hover:text-primary-700">
            数据查询(SDK)
          </a>
        </h4>
        <p className="text-sm text-foreground-700 leading-relaxed">
          绝大多数数据读取用 SDK 更简洁,且天然携带会话与行级安全策略(RLS)。
        </p>
        <CodeBlock
          language="ts"
          filename="查询与写入示例"
          code={`// 查询:带条件的列表
const { data, error } = await supabase
  .from('audit_logs')
  .select('id, user_name, action, module, level, created_at')
  .eq('level', 'error')
  .order('created_at', { ascending: false })
  .limit(20);

// 写入:插入一条记录
await supabase.from('audit_logs').insert({
  action: '导出报表',
  module: '日志审计',
  level: 'info',
});

// 实时:订阅数据变化
supabase
  .channel('metrics-live')
  .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'metrics' }, (payload) => {
    console.log('新指标:', payload.new);
  })
  .subscribe();`}
        />
      </div>

      <div>
        <h4 className="text-sm font-semibold text-foreground-950 mb-3">
          <a href="#api-fn" className="hover:text-primary-700">
            调用 Edge Function
          </a>
        </h4>
        <CodeBlock
          language="ts"
          filename="调用后端函数"
          code={`const { data, error } = await supabase.functions.invoke('create-payment', {
  body: { orderId: 'order_10001', amount: 12800, currency: 'USD' },
});

if (error) {
  console.error('调用失败', error);
} else {
  console.log('返回结果', data);
}`}
        />
      </div>

      <div>
        <h4 className="text-sm font-semibold text-foreground-950 mb-3">
          <a href="#api-resp" className="hover:text-primary-700">
            标准响应结构
          </a>
        </h4>
        <CodeBlock
          language="json"
          filename="响应示例"
          code={`{
  "code": "OK",
  "data": { "id": "order_10001", "status": "pending_payment" },
  "meta": { "message": "", "detail": null }
}`}
        />
        <Callout tone="info" title="响应判定约定">
          仅当 HTTP 状态为 2xx <strong>且</strong> 响应体 <span className="font-label">code === "OK"</span> 时才视为成功。
          失败信息优先读取 <span className="font-label">meta.message</span> 或 <span className="font-label">meta.detail</span>,
          并在当前页面展示,不要直接跳转。
        </Callout>
      </div>
    </div>
  );
}