import { useCallback, useEffect, useMemo, useState } from 'react';
import { supabase } from '@/lib/supabase';
import { useAuth } from '@/contexts/AuthContext';
import Modal from '@/components/base/Modal';
import { moveToRecycleBin } from '@/lib/recycleBin';
import { recordAuditLog } from '@/lib/auditLog';
import PluginCard from '@/pages/plugins/components/PluginCard';
import PluginDetailModal from '@/pages/plugins/components/PluginDetailModal';
import HotUpdateModal from '@/pages/plugins/components/HotUpdateModal';
import TemplateEditorModal from '@/pages/plugins/components/TemplateEditorModal';
import MarketplaceModal from '@/pages/plugins/components/MarketplaceModal';
import { buildInsertPayload, type MarketPlugin } from '@/pages/plugins/marketCatalog';
import { pluginCategories, type PluginRow } from '@/pages/plugins/types';

export default function PluginsPage() {
  const { hasPermission } = useAuth();
  const canManage = hasPermission('plugin:update');

  const [plugins, setPlugins] = useState<PluginRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const [busyId, setBusyId] = useState<string | null>(null);

  const [keyword, setKeyword] = useState('');
  const [category, setCategory] = useState('全部');
  const [statusFilter, setStatusFilter] = useState('all');

  const [detailTarget, setDetailTarget] = useState<PluginRow | null>(null);
  const [templateTarget, setTemplateTarget] = useState<PluginRow | null>(null);
  const [updateTarget, setUpdateTarget] = useState<PluginRow | null>(null);
  const [marketOpen, setMarketOpen] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState<PluginRow | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const { data, error: err } = await supabase
        .from('plugins')
        .select('*')
        .order('enabled', { ascending: false })
        .order('name', { ascending: true });
      if (err) throw err;
      setPlugins((data as PluginRow[]) ?? []);
    } catch (err) {
      console.error(err);
      setError('加载插件列表失败,请重试');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  useEffect(() => {
    if (!notice) return;
    const timer = setTimeout(() => setNotice(''), 2600);
    return () => clearTimeout(timer);
  }, [notice]);

  const installedMap = useMemo(() => {
    const map: Record<string, PluginRow> = {};
    plugins.forEach((p) => {
      if (p.code) map[p.code] = p;
    });
    return map;
  }, [plugins]);

  const stats = useMemo(
    () => ({
      total: plugins.length,
      enabled: plugins.filter((p) => p.enabled).length,
      updatable: plugins.filter((p) => p.has_update).length,
      categories: new Set(plugins.map((p) => p.category)).size,
    }),
    [plugins],
  );

  const filtered = useMemo(
    () =>
      plugins.filter((p) => {
        const kw = keyword.trim().toLowerCase();
        const matchKw =
          !kw ||
          (p.name ?? '').toLowerCase().includes(kw) ||
          (p.code ?? '').toLowerCase().includes(kw) ||
          (p.description ?? '').toLowerCase().includes(kw);
        const matchCat = category === '全部' || p.category === category;
        const matchStatus =
          statusFilter === 'all' ||
          (statusFilter === 'enabled' ? p.enabled : !p.enabled);
        return matchKw && matchCat && matchStatus;
      }),
    [plugins, keyword, category, statusFilter],
  );

  const installedCodes = useMemo(
    () => plugins.map((p) => p.code).filter((c): c is string => Boolean(c)),
    [plugins],
  );

  const marketInstalledMap = useMemo(() => {
    const map: Record<string, { enabled: boolean; name: string }> = {};
    plugins.forEach((p) => {
      if (p.code) map[p.code] = { enabled: Boolean(p.enabled), name: p.name };
    });
    return map;
  }, [plugins]);

  const installFromMarket = async (items: MarketPlugin[]) => {
    if (items.length === 0) return;
    setError('');
    try {
      // 已经存在于插件目录中的插件不再重复写入,只同步账号的「已购」标记
      const existing = new Set(installedCodes);
      const toInsert = items.filter((i) => !existing.has(i.code));
      if (toInsert.length > 0) {
        const { error: err } = await supabase.from('plugins').insert(toInsert.map(buildInsertPayload));
        if (err) throw err;
      }
      await load();
      setNotice(
        items.length === 1
          ? `「${items[0].name}」已加入插件中心`
          : `已加入 ${items.length} 个插件:${items.map((i) => i.name).join('、')}`,
      );
      await recordAuditLog({
        action: '安装插件',
        module: '插件中心',
        detail: `从市场安装 ${items.length} 个插件:${items.map((i) => i.name).join('、')}`,
      });
    } catch (err) {
      console.error(err);
      setError('安装失败,请检查权限后重试');
      throw err;
    }
  };

  const toggle = async (plugin: PluginRow) => {
    setBusyId(plugin.id);
    try {
      const { error: err } = await supabase
        .from('plugins')
        .update({ enabled: !plugin.enabled, updated_at: new Date().toISOString() })
        .eq('id', plugin.id);
      if (err) throw err;
      setPlugins((prev) =>
        prev.map((p) => (p.id === plugin.id ? { ...p, enabled: !p.enabled } : p)),
      );
      setNotice(plugin.enabled ? `已停用「${plugin.name}」` : `已启用「${plugin.name}」`);
      await recordAuditLog({
        action: plugin.enabled ? '停用插件' : '启用插件',
        module: '插件中心',
        level: 'warn',
        detail: `${plugin.enabled ? '停用' : '启用'}插件「${plugin.name}」`,
      });
    } catch (err) {
      console.error(err);
      setError('操作失败,请检查权限后重试');
    } finally {
      setBusyId(null);
    }
  };

  const finishUpdate = async (plugin: PluginRow) => {
    try {
      const { error: err } = await supabase
        .from('plugins')
        .update({
          version: plugin.latest_version,
          has_update: false,
          updated_at: new Date().toISOString(),
        })
        .eq('id', plugin.id);
      if (err) throw err;
      setPlugins((prev) =>
        prev.map((p) =>
          p.id === plugin.id ? { ...p, version: p.latest_version, has_update: false } : p,
        ),
      );
      setNotice(`「${plugin.name}」已热更新至 v${plugin.latest_version}`);
      await recordAuditLog({
        action: '插件热更新',
        module: '插件中心',
        detail: `「${plugin.name}」热更新至 v${plugin.latest_version}`,
      });
    } catch (err) {
      console.error(err);
      setError('更新版本号写入失败');
    }
  };

  const confirmDelete = async () => {
    if (!deleteTarget) return;
    try {
      const { error: err } = await supabase.from('plugins').delete().eq('id', deleteTarget.id);
      if (err) throw err;
      await moveToRecycleBin({
        module: 'plugin',
        itemId: deleteTarget.id,
        itemName: deleteTarget.name,
        snapshot: {
          id: deleteTarget.id,
          name: deleteTarget.name,
          code: deleteTarget.code,
          version: deleteTarget.version,
          latest_version: deleteTarget.latest_version,
          has_update: deleteTarget.has_update,
          description: deleteTarget.description,
          enabled: deleteTarget.enabled,
          category: deleteTarget.category,
          author: deleteTarget.author,
          downloads: deleteTarget.downloads,
          homepage: deleteTarget.homepage,
          dependencies: deleteTarget.dependencies,
          changelog: deleteTarget.changelog,
          config_schema: deleteTarget.config_schema,
          template: deleteTarget.template,
          installed_at: deleteTarget.installed_at,
        },
      });
      setNotice('插件已删除,可在回收站还原');
      await recordAuditLog({
        action: '删除插件',
        module: '插件中心',
        level: 'warn',
        detail: `删除插件「${deleteTarget.name}」`,
      });
      setDeleteTarget(null);
      await load();
    } catch (err) {
      console.error(err);
      setError('删除失败,请检查权限后重试');
      setDeleteTarget(null);
    }
  };

  const statCards = [
    { label: '插件总数', value: stats.total, icon: 'ri-plug-2-line', tone: 'bg-primary-100 text-primary-700' },
    { label: '已启用', value: stats.enabled, icon: 'ri-toggle-line', tone: 'bg-accent-100 text-accent-800' },
    { label: '可热更新', value: stats.updatable, icon: 'ri-refresh-line', tone: 'bg-secondary-200 text-secondary-900' },
    { label: '覆盖分类', value: stats.categories, icon: 'ri-apps-2-line', tone: 'bg-primary-100 text-primary-700' },
  ];

  return (
    <div className="space-y-4">
      <div className="flex flex-col md:flex-row md:items-center gap-3">
        <div>
          <h2 className="text-lg font-semibold text-foreground-950">插件管理中心</h2>
          <p className="text-sm text-foreground-500 mt-0.5">
            统一管理插件生命周期:安装、启停、依赖校验与运行时热更新
          </p>
        </div>
        <div className="md:ml-auto flex flex-wrap items-center gap-2">
          <button
            type="button"
            onClick={() => setMarketOpen(true)}
            className="h-9 px-3.5 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5 dark:text-foreground-950"
          >
            <i className="ri-store-2-line"></i>
            插件市场
          </button>
          <div className="flex items-center gap-2 h-9 px-3 rounded-md bg-background-50 border border-background-200 w-full sm:w-52">
            <i className="ri-search-line text-foreground-400 text-sm"></i>
            <input
              type="text"
              value={keyword}
              onChange={(e) => setKeyword(e.target.value)}
              placeholder="搜索插件名称或标识"
              className="flex-1 bg-transparent text-sm text-foreground-900 placeholder:text-foreground-400 focus:outline-none"
            />
          </div>
          <select
            value={category}
            onChange={(e) => setCategory(e.target.value)}
            className="h-9 px-3 rounded-md bg-background-50 border border-background-200 text-sm text-foreground-800 focus:outline-none cursor-pointer"
          >
            {pluginCategories.map((c) => (
              <option key={c} value={c}>
                {c === '全部' ? '全部分类' : c}
              </option>
            ))}
          </select>
          <select
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
            className="h-9 px-3 rounded-md bg-background-50 border border-background-200 text-sm text-foreground-800 focus:outline-none cursor-pointer"
          >
            <option value="all">全部状态</option>
            <option value="enabled">已启用</option>
            <option value="disabled">已停用</option>
          </select>
        </div>
      </div>

      {notice ? (
        <div className="flex items-center gap-2 px-3 py-2.5 rounded-md bg-primary-50 text-primary-800 text-sm animate-fade-up">
          <i className="ri-checkbox-circle-line"></i>
          {notice}
        </div>
      ) : null}
      {error ? (
        <div className="flex items-center justify-between gap-3 px-3 py-2.5 rounded-md bg-accent-100 text-accent-900 text-sm">
          {error}
          <button type="button" onClick={load} className="text-xs underline cursor-pointer whitespace-nowrap">
            重试
          </button>
        </div>
      ) : null}

      <section className="grid grid-cols-2 xl:grid-cols-4 gap-3 md:gap-4">
        {statCards.map((s) => (
          <div key={s.label} className="rounded-lg bg-background-50 border border-background-200 p-4">
            <div className="flex items-center gap-2">
              <span className={`w-8 h-8 rounded-md flex items-center justify-center ${s.tone}`}>
                <i className={`${s.icon} text-sm`}></i>
              </span>
              <span className="text-xs text-foreground-500">{s.label}</span>
            </div>
            <p className="mt-2.5 text-2xl font-semibold text-foreground-950 font-label">{s.value}</p>
          </div>
        ))}
      </section>

      {loading ? (
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
          {[0, 1, 2, 3, 4, 5].map((n) => (
            <div key={n} className="h-56 rounded-lg bg-background-50 border border-background-200 animate-pulse-soft" />
          ))}
        </div>
      ) : filtered.length === 0 ? (
        <div className="rounded-lg bg-background-50 border border-background-200 py-16 text-center text-foreground-500">
          <i className="ri-plug-2-line text-3xl block mb-2"></i>
          没有匹配的插件
        </div>
      ) : (
        <section className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
          {filtered.map((plugin) => (
            <PluginCard
              key={plugin.id}
              plugin={plugin}
              installedMap={installedMap}
              canManage={canManage}
              busy={busyId === plugin.id}
              onToggle={toggle}
              onDetail={setDetailTarget}
              onTemplate={setTemplateTarget}
              onUpdate={setUpdateTarget}
              onDelete={setDeleteTarget}
            />
          ))}
        </section>
      )}

      <PluginDetailModal
        open={Boolean(detailTarget)}
        plugin={detailTarget}
        installedMap={installedMap}
        onClose={() => setDetailTarget(null)}
      />

      <TemplateEditorModal
        open={Boolean(templateTarget)}
        plugin={templateTarget}
        onClose={() => setTemplateTarget(null)}
      />

      <HotUpdateModal
        open={Boolean(updateTarget)}
        plugin={updateTarget}
        onClose={() => setUpdateTarget(null)}
        onDone={finishUpdate}
      />

      <MarketplaceModal
        open={marketOpen}
        installedCodes={installedCodes}
        installedMap={marketInstalledMap}
        canManage={canManage}
        onClose={() => setMarketOpen(false)}
        onInstall={installFromMarket}
      />

      <Modal
        open={Boolean(deleteTarget)}
        title="删除插件"
        onClose={() => setDeleteTarget(null)}
        footer={
          <>
            <button
              type="button"
              onClick={() => setDeleteTarget(null)}
              className="h-9 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap"
            >
              取消
            </button>
            <button
              type="button"
              onClick={confirmDelete}
              className="h-9 px-4 rounded-md bg-secondary-700 text-background-50 text-sm hover:bg-secondary-800 cursor-pointer whitespace-nowrap"
            >
              确认删除
            </button>
          </>
        }
      >
        <p className="text-sm text-foreground-700">
          确定删除插件
          <span className="font-medium text-foreground-950"> {deleteTarget?.name} </span>
          吗?删除后可在回收站还原。
        </p>
      </Modal>
    </div>
  );
}