export const paletteGroups = ['基础', '布局', '数据', '表单'];

export function createBlock(paletteItem: PaletteItem): BuilderBlock {
  const id =
    typeof crypto !== 'undefined' && 'randomUUID' in crypto
      ? crypto.randomUUID()
      : `b_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
  return { id, type: paletteItem.type, props: { ...paletteItem.defaultProps } };
}

export function findPaletteItem(type: string): PaletteItem | undefined {
  return palette.find((p) => p.type === type);
}