import { useEffect, useState } from 'react';
import { Navigate, useNavigate } from 'react-router-dom';
import { useAuth } from '@/contexts/AuthContext';

export default function PendingApprovalPage() {
  const {
    session,
    profile,
    loading,
    profileLoading,
    isPendingApproval,
    refreshProfile,
    signOut,
  } = useAuth();
  const navigate = useNavigate();
  const [refreshing, setRefreshing] = useState(false);
  const [checkedAt, setCheckedAt] = useState<string>('');

  // 权限被分配后自动放行进入后台
  useEffect(() => {
    if (!loading && !profileLoading && session && !isPendingApproval) {
      navigate('/', { replace: true });
    }
  }, [loading, profileLoading, session, isPendingApproval, navigate]);

  // 定时静默检测权限变化(管理员分配后无需手动刷新)
  useEffect(() => {
    const timer = setInterval(() => {
      refreshProfile().catch(() => undefined);
    }, 25000);
    return () => clearInterval(timer);
  }, [refreshProfile]);

  if (loading || profileLoading) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center gap-3 bg-background-100">
        <div className="w-9 h-9 rounded-full border-2 border-background-300 border-t-primary-500 animate-spin" />
        <p className="text-sm text-foreground-500">正在检查账号权限…</p>
      </div>
    );
  }

  if (!session) {
    return <Navigate to="/auth" replace />;
  }

  const isMember = session.user?.user_metadata?.account_type === 'member';
  if (isMember) {
    return <Navigate to="/member" replace />;
  }

  if (!isPendingApproval) {
    return <Navigate to="/" replace />;
  }

  const displayName = profile?.full_name || profile?.email || '新账号';
  const initials = displayName.slice(0, 1).toUpperCase();

  const handleRefresh = async () => {
    setRefreshing(true);
    try {
      await refreshProfile();
      setCheckedAt(
        new Date().toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' }),
      );
    } finally {
      setRefreshing(false);
    }
  };

  const handleSignOut = async () => {
    await signOut();
    navigate('/auth', { replace: true });
  };

  const steps = [
    { icon: 'ri-user-add-line', title: '账号创建成功', desc: '你的登录账号已经可以使用' },
    { icon: 'ri-shield-user-line', title: '等待分配权限', desc: '管理员正在为你配置可访问的角色与菜单' },
    { icon: 'ri-rocket-2-line', title: '开通后即可进入', desc: '权限到位后会自动进入后台,无需重新登录' },
  ];

  return (
    <div className="min-h-screen flex items-center justify-center px-4 py-10 bg-background-100">
      <div className="w-full max-w-lg">
        <div className="flex items-center justify-center gap-2.5 mb-6">
          <div className="w-9 h-9 rounded-lg bg-primary-500 text-background-50 flex items-center justify-center dark:text-foreground-950">
            <i className="ri-flashlight-fill text-lg"></i>
          </div>
          <span className="text-base font-semibold font-heading text-foreground-950">HuaanAdmin</span>
        </div>

        <div className="rounded-lg bg-background-50 border border-background-200 overflow-hidden">
          <div className="px-6 pt-7 pb-6 text-center">
            <div className="mx-auto w-16 h-16 rounded-full bg-accent-100 text-accent-900 flex items-center justify-center">
              <i className="ri-hourglass-2-line text-3xl"></i>
            </div>
            <h1 className="mt-4 text-lg font-semibold text-foreground-950">
              你的账号正在等待管理员分配权限
            </h1>
            <p className="mt-2 text-sm text-foreground-600 leading-relaxed">
              账号已成功创建,目前仅有「访客」权限。请耐心等待管理员为你分配角色,开通后即可使用完整后台功能。
            </p>

            <div className="mt-5 inline-flex items-center gap-3 rounded-lg bg-background-100 border border-background-200 px-4 py-3">
              <span className="w-9 h-9 rounded-full bg-primary-100 text-primary-700 flex items-center justify-center text-sm font-semibold">
                {initials}
              </span>
              <span className="text-left min-w-0">
                <span className="block text-sm text-foreground-950 truncate max-w-[220px]">{displayName}</span>
                <span className="block text-xs text-foreground-500 truncate max-w-[220px]">
                  {profile?.email}
                </span>
              </span>
              <span className="text-[11px] px-2 py-0.5 rounded-full bg-secondary-200 text-secondary-900 whitespace-nowrap">
                访客
              </span>
            </div>
          </div>

          <div className="px-6 pb-6">
            <ul className="space-y-2.5">
              {steps.map((step, index) => (
                <li
                  key={step.title}
                  className="flex items-start gap-3 rounded-md border border-background-200 bg-background-50 px-3.5 py-3"
                >
                  <span className="w-8 h-8 rounded-md bg-background-100 text-foreground-600 flex items-center justify-center shrink-0">
                    <i className={`${step.icon} text-sm`}></i>
                  </span>
                  <span className="min-w-0">
                    <span className="flex items-center gap-2 text-sm font-medium text-foreground-900">
                      {step.title}
                      {index === 0 ? (
                        <i className="ri-checkbox-circle-fill text-primary-500 text-sm"></i>
                      ) : null}
                    </span>
                    <span className="block text-xs text-foreground-500 mt-0.5">{step.desc}</span>
                  </span>
                </li>
              ))}
            </ul>

            <div className="mt-5 flex flex-col sm:flex-row sm:items-center gap-2">
              <button
                type="button"
                onClick={handleRefresh}
                disabled={refreshing}
                className="flex-1 h-10 rounded-md bg-primary-500 text-background-50 text-sm font-medium hover:bg-primary-600 disabled:opacity-60 cursor-pointer whitespace-nowrap flex items-center justify-center gap-1.5 dark:text-foreground-950"
              >
                <i className={refreshing ? 'ri-loader-4-line animate-spin' : 'ri-refresh-line'}></i>
                {refreshing ? '正在检查…' : '刷新权限状态'}
              </button>
              <button
                type="button"
                onClick={handleSignOut}
                className="h-10 px-4 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap flex items-center justify-center gap-1.5"
              >
                <i className="ri-logout-box-r-line"></i>
                退出登录
              </button>
            </div>

            <p className="mt-3 text-center text-[11px] text-foreground-400">
              {checkedAt ? `最近检查时间 ${checkedAt} · ` : ''}系统会自动检测权限变化,通常无需手动刷新
            </p>
          </div>
        </div>

        <p className="mt-5 text-center text-[11px] text-foreground-400 leading-relaxed">
          如果你的账号迟迟未开通,请联系系统管理员在「用户管理」中为你分配角色
        </p>
      </div>
    </div>
  );
}