import { useEffect, useMemo, useState } from 'react';
import { supabase } from '@/lib/supabase';
import {
  formatDuration,
  formatTime,
  pipelineStatusMeta,
  stageStatusMeta,
  type PipelineRow,
} from '@/pages/settings/system/types';

export default function PipelineCard() {
  const [rows, setRows] = useState<PipelineRow[]>([]);
  const [selectedId, setSelectedId] = useState<number | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let active = true;
    (async () => {
      try {
        const { data, error } = await supabase
          .from('ci_pipelines')
          .select('*')
          .order('started_at', { ascending: false });
        if (error) throw error;
        const list = (data as PipelineRow[]) ?? [];
        if (active) {
          setRows(list);
          setSelectedId(list[0]?.id ?? null);
        }
      } catch (err) {
        console.error(err);
      } finally {
        if (active) setLoading(false);
      }
    })();
    return () => {
      active = false;
    };
  }, []);

  const stats = useMemo(() => {
    const success = rows.filter((r) => r.status === 'success').length;
    const running = rows.filter((r) => r.status === 'running').length;
    const failed = rows.filter((r) => r.status === 'failed' || r.status === 'queued').length;
    return { success, running, failed };
  }, [rows]);

  const selected = useMemo(
    () => rows.find((r) => r.id === selectedId) ?? rows[0] ?? null,
    [rows, selectedId],
  );

  return (
    <div className="rounded-lg bg-background-50 border border-background-200">
      <div className="flex items-center gap-2.5 px-4 md:px-5 py-3.5 border-b border-background-200">
        <span className="w-9 h-9 rounded-md bg-secondary-200 text-secondary-900 flex items-center justify-center">
          <i className="ri-git-branch-line text-lg"></i>
        </span>
        <div className="flex-1">
          <h3 className="text-sm font-semibold text-foreground-950">CI/CD 流水线</h3>
          <p className="text-xs text-foreground-500">构建、测试与部署阶段可视化</p>
        </div>
        <span className="shrink-0 text-[10px] px-2 py-0.5 rounded-full bg-secondary-100 text-secondary-900 whitespace-nowrap">
          演示数据
        </span>
        <div className="hidden sm:flex items-center gap-2 text-[11px]">
          <span className="inline-flex items-center gap-1 text-primary-700">
            <span className="w-1.5 h-1.5 rounded-full bg-primary-500" /> 成功 {stats.success}
          </span>
          <span className="inline-flex items-center gap-1 text-accent-700">
            <span className="w-1.5 h-1.5 rounded-full bg-accent-500" /> 运行 {stats.running}
          </span>
          <span className="inline-flex items-center gap-1 text-secondary-800">
            <span className="w-1.5 h-1.5 rounded-full bg-secondary-600" /> 异常 {stats.failed}
          </span>
        </div>
      </div>

      {loading ? (
        <div className="p-4 md:p-5 space-y-2.5">
          {[0, 1, 2].map((n) => (
            <div key={n} className="h-14 rounded-md bg-background-100 animate-pulse-soft" />
          ))}
        </div>
      ) : (
        <div className="flex flex-col lg:flex-row">
          <ul className="lg:w-[300px] shrink-0 divide-y divide-background-200 border-b lg:border-b-0 lg:border-r border-background-200 max-h-[300px] lg:max-h-[420px] overflow-y-auto">
            {rows.map((p) => {
              const meta = pipelineStatusMeta[p.status ?? 'success'] ?? pipelineStatusMeta.success;
              return (
                <li key={p.id}>
                  <button
                    type="button"
                    onClick={() => setSelectedId(p.id)}
                    className={`w-full text-left px-4 py-3 cursor-pointer transition-colors ${
                      selected?.id === p.id ? 'bg-primary-50' : 'hover:bg-background-100'
                    }`}
                  >
                    <div className="flex items-center gap-2">
                      <span className={`w-5 h-5 rounded-full flex items-center justify-center ${meta.tone}`}>
                        <i className={`${meta.icon} text-[11px] ${p.status === 'running' ? 'animate-spin' : ''}`}></i>
                      </span>
                      <span className="text-xs font-label text-foreground-700 truncate">{p.branch}</span>
                      <span className="ml-auto text-[10px] font-label text-foreground-400">{p.commit_sha}</span>
                    </div>
                    <p className="mt-1 text-xs text-foreground-800 truncate">{p.commit_message}</p>
                    <div className="mt-1 flex items-center gap-2 text-[10px] text-foreground-500">
                      <span>{p.author}</span>
                      <span>·</span>
                      <span>{formatTime(p.started_at)}</span>
                    </div>
                  </button>
                </li>
              );
            })}
          </ul>

          <div className="flex-1 p-4 md:p-5 min-w-0">
            {selected ? (
              <>
                <div className="flex flex-wrap items-center gap-2">
                  <span
                    className={`inline-flex items-center gap-1 text-[11px] px-2 py-0.5 rounded-full ${
                      (pipelineStatusMeta[selected.status ?? 'success'] ?? pipelineStatusMeta.success).tone
                    }`}
                  >
                    <i
                      className={`${
                        (pipelineStatusMeta[selected.status ?? 'success'] ?? pipelineStatusMeta.success).icon
                      } ${selected.status === 'running' ? 'animate-spin' : ''}`}
                    ></i>
                    {(pipelineStatusMeta[selected.status ?? 'success'] ?? pipelineStatusMeta.success).label}
                  </span>
                  <span className="text-xs text-foreground-700 font-label">{selected.repo}</span>
                  <span className="text-xs text-foreground-500">耗时 {formatDuration(selected.duration_seconds)}</span>
                </div>
                <p className="mt-2 text-sm text-foreground-900">{selected.commit_message}</p>
                <p className="mt-1 text-[11px] text-foreground-500 font-label">
                  {selected.branch} · {selected.commit_sha}
                </p>

                <div className="mt-5">
                  <p className="text-[11px] font-medium text-foreground-400 mb-3">流水线阶段</p>
                  <div className="flex flex-wrap items-start gap-y-4">
                    {(selected.stages ?? []).map((stage, idx) => {
                      const meta = stageStatusMeta[stage.status] ?? stageStatusMeta.queued;
                      const isLast = idx === (selected.stages?.length ?? 0) - 1;
                      return (
                        <div key={`${stage.name}-${idx}`} className="flex items-center">
                          <div className="flex flex-col items-center w-[84px]">
                            <span className={`w-9 h-9 rounded-full flex items-center justify-center ${meta.tone}`}>
                              <i className={`${meta.icon} ${stage.status === 'running' ? 'animate-spin' : ''}`}></i>
                            </span>
                            <span className="mt-1.5 text-[11px] text-foreground-800 text-center leading-tight">
                              {stage.name}
                            </span>
                            <span className="text-[10px] font-label text-foreground-400">
                              {stage.duration > 0 ? `${stage.duration}s` : '—'}
                            </span>
                          </div>
                          {!isLast ? (
                            <span
                              className={`w-6 md:w-10 h-0.5 mb-6 ${
                                stage.status === 'success' ? 'bg-primary-400' : 'bg-background-300'
                              }`}
                            />
                          ) : null}
                        </div>
                      );
                    })}
                  </div>
                </div>
              </>
            ) : (
              <p className="text-sm text-foreground-500 py-10 text-center">暂无流水线记录</p>
            )}
          </div>
        </div>
      )}
    </div>
  );
}