import { useMemo, useState } from 'react';
import {
  compareHighlights,
  compareRows,
  compareEdgeMeta,
  compareToneCls,
  compareFootnote,
} from '@/config/fastAdminCompare';

type CompareView = 'highlight' | 'table';

export default function FastAdminCompare() {
  const [view, setView] = useState<CompareView>('highlight');

  const summary = useMemo(() => {
    const lead = compareRows.filter((r) => r.edge === 'lead').length;
    const even = compareRows.filter((r) => r.edge === 'even').length;
    const gap = compareRows.filter((r) => r.edge === 'gap').length;
    return { lead, even, gap };
  }, []);

  return (
    <section className="rounded-lg bg-background-50 border border-background-200 p-4 md:p-5">
      <div className="flex flex-col md:flex-row md:items-center gap-3 mb-4">
        <div className="min-w-0">
          <div className="flex items-center gap-2">
            <span className="w-8 h-8 rounded-md bg-accent-100 text-accent-900 flex items-center justify-center shrink-0">
              <i className="ri-scales-3-line"></i>
            </span>
            <h3 className="text-sm font-semibold text-foreground-950">FastAdmin 对标能力对照</h3>
          </div>
          <p className="mt-1.5 text-xs text-foreground-500">
            HuaanAdmin 站在 React 技术栈上,把 FastAdmin 需要插件或二次开发的能力直接内置
          </p>
        </div>
        <div className="md:ml-auto flex items-center gap-1 h-9 px-1 rounded-full bg-background-100 border border-background-200 shrink-0">
          <button
            type="button"
            onClick={() => setView('highlight')}
            className={`h-7 px-3 rounded-full text-xs whitespace-nowrap cursor-pointer ${
              view === 'highlight' ? 'bg-background-50 text-foreground-950 shadow-sm' : 'text-foreground-600 hover:text-foreground-900'
            }`}
          >
            差异化亮点
          </button>
          <button
            type="button"
            onClick={() => setView('table')}
            className={`h-7 px-3 rounded-full text-xs whitespace-nowrap cursor-pointer ${
              view === 'table' ? 'bg-background-50 text-foreground-950 shadow-sm' : 'text-foreground-600 hover:text-foreground-900'
            }`}
          >
            逐项对照
          </button>
        </div>
      </div>

      {view === 'highlight' ? (
        <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-3">
          {compareHighlights.map((h) => (
            <div key={h.key} className="rounded-lg border border-background-200 p-4 hover:border-accent-300 transition-colors">
              <span className={`w-9 h-9 rounded-md flex items-center justify-center ${compareToneCls[h.tone]}`}>
                <i className={`${h.icon} text-lg`}></i>
              </span>
              <p className="mt-3 text-sm font-medium text-foreground-950">{h.title}</p>
              <p className="mt-1 text-xs text-foreground-500 leading-relaxed">{h.desc}</p>
            </div>
          ))}
        </div>
      ) : (
        <div className="overflow-x-auto">
          <div className="flex items-center gap-3 mb-3 text-[11px] text-foreground-500">
            <span className="inline-flex items-center gap-1">
              <span className="w-2 h-2 rounded-full bg-primary-500" /> 领先 {summary.lead}
            </span>
            <span className="inline-flex items-center gap-1">
              <span className="w-2 h-2 rounded-full bg-secondary-500" /> 相当 {summary.even}
            </span>
            <span className="inline-flex items-center gap-1">
              <span className="w-2 h-2 rounded-full bg-accent-500" /> 待补 {summary.gap}
            </span>
          </div>
          <table className="w-full min-w-[640px] text-sm border-collapse">
            <thead>
              <tr className="text-left text-[11px] text-foreground-500">
                <th className="font-medium py-2 pr-4 w-[140px]">能力维度</th>
                <th className="font-medium py-2 pr-4">HuaanAdmin</th>
                <th className="font-medium py-2 pr-4 text-foreground-400">FastAdmin</th>
                <th className="font-medium py-2 w-[64px] text-right">对比</th>
              </tr>
            </thead>
            <tbody>
              {compareRows.map((row) => (
                <tr key={row.dim} className="border-t border-background-200">
                  <td className="py-2.5 pr-4 text-foreground-700 whitespace-nowrap">{row.dim}</td>
                  <td className="py-2.5 pr-4 text-foreground-950">{row.huaan}</td>
                  <td className="py-2.5 pr-4 text-foreground-500">{row.fa}</td>
                  <td className="py-2.5 text-right">
                    <span className={`inline-block text-[10px] px-2 py-0.5 rounded-full whitespace-nowrap ${compareEdgeMeta[row.edge].cls}`}>
                      {compareEdgeMeta[row.edge].label}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      <p className="mt-4 text-[11px] text-foreground-400 flex items-center gap-1.5">
        <i className="ri-information-line"></i>
        {compareFootnote}
      </p>
    </section>
  );
}