import { findPaletteItem, type BuilderBlock } from '@/pages/builder/types';

interface PropertyPanelProps {
  block: BuilderBlock | null;
  blocks: BuilderBlock[];
  onUpdateProps: (id: string, key: string, value: string) => void;
  onSelect: (id: string) => void;
  onMove: (index: number, dir: -1 | 1) => void;
  onRemove: (id: string) => void;
}

export default function PropertyPanel({
  block,
  blocks,
  onUpdateProps,
  onSelect,
  onMove,
  onRemove,
}: PropertyPanelProps) {
  const item = block ? findPaletteItem(block.type) : null;

  return (
    <aside className="w-full lg:w-[280px] shrink-0 rounded-lg bg-background-50 border border-background-200 flex flex-col">
      <div className="px-4 py-3.5 border-b border-background-200">
        <h3 className="text-sm font-semibold text-foreground-950">属性配置</h3>
        <p className="text-[11px] text-foreground-500 mt-0.5">
          {block && item ? `正在编辑:${item.label}` : '选中画布组件后编辑属性'}
        </p>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-3.5">
        {!block || !item ? (
          <div className="flex flex-col items-center justify-center py-14 text-foreground-400 text-center">
            <i className="ri-cursor-line text-3xl mb-2"></i>
            <p className="text-xs">点击画布中的组件</p>
            <p className="text-[10px] mt-0.5">即可在此调整其属性</p>
          </div>
        ) : (
          <>
            <div className="flex items-center gap-2.5 rounded-md bg-background-100 border border-background-200 px-3 py-2.5">
              <span className="w-8 h-8 rounded-md bg-primary-100 text-primary-700 flex items-center justify-center">
                <i className={`${item.icon} text-sm`}></i>
              </span>
              <div>
                <p className="text-xs font-medium text-foreground-900">{item.label}</p>
                <p className="text-[10px] text-foreground-500 font-label">{block.type}</p>
              </div>
            </div>

            {item.fields.map((f) => {
              const value = block.props[f.key] ?? '';
              return (
                <div key={f.key}>
                  <label className="block text-[11px] font-medium text-foreground-700 mb-1.5">
                    {f.label}
                  </label>
                  {f.type === 'textarea' ? (
                    <textarea
                      value={value}
                      onChange={(e) => onUpdateProps(block.id, f.key, e.target.value)}
                      rows={3}
                      className="w-full px-3 py-2 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400 resize-none"
                    />
                  ) : f.type === 'select' && f.options ? (
                    <select
                      value={value}
                      onChange={(e) => onUpdateProps(block.id, f.key, e.target.value)}
                      className="w-full h-9 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none cursor-pointer"
                    >
                      {f.options.map((o) => (
                        <option key={o} value={o}>
                          {o}
                        </option>
                      ))}
                    </select>
                  ) : (
                    <input
                      type={f.type === 'number' ? 'number' : 'text'}
                      value={value}
                      onChange={(e) => onUpdateProps(block.id, f.key, e.target.value)}
                      className="w-full h-9 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-900 focus:outline-none focus:border-primary-400"
                    />
                  )}
                </div>
              );
            })}

            <button
              type="button"
              onClick={() => onRemove(block.id)}
              className="w-full h-9 rounded-md bg-background-100 border border-background-300 text-xs text-secondary-800 hover:bg-secondary-100 cursor-pointer whitespace-nowrap inline-flex items-center justify-center gap-1.5"
            >
              <i className="ri-delete-bin-line"></i>
              删除该组件
            </button>
          </>
        )}

        <div className="pt-3 border-t border-background-200">
          <p className="text-[11px] font-medium text-foreground-700 mb-2">页面结构</p>
          {blocks.length === 0 ? (
            <p className="text-[11px] text-foreground-400">画布为空</p>
          ) : (
            <ul className="space-y-1">
              {blocks.map((b, i) => {
                const meta = findPaletteItem(b.type);
                const active = block?.id === b.id;
                return (
                  <li
                    key={b.id}
                    className={`flex items-center gap-2 rounded-md px-2 py-1.5 cursor-pointer ${
                      active ? 'bg-primary-50 text-primary-700' : 'hover:bg-background-100 text-foreground-700'
                    }`}
                    onClick={() => onSelect(b.id)}
                  >
                    <span className="text-[10px] font-label text-foreground-400 w-4">{i + 1}</span>
                    <i className={`${meta?.icon ?? 'ri-square-line'} text-xs`}></i>
                    <span className="text-[11px] truncate flex-1">{meta?.label ?? b.type}</span>
                    <button
                      type="button"
                      onClick={(e) => {
                        e.stopPropagation();
                        onMove(i, -1);
                      }}
                      disabled={i === 0}
                      className="w-5 h-5 rounded flex items-center justify-center text-foreground-400 hover:text-foreground-900 disabled:opacity-30 cursor-pointer"
                      aria-label="上移"
                    >
                      <i className="ri-arrow-up-s-line text-xs"></i>
                    </button>
                    <button
                      type="button"
                      onClick={(e) => {
                        e.stopPropagation();
                        onMove(i, 1);
                      }}
                      disabled={i === blocks.length - 1}
                      className="w-5 h-5 rounded flex items-center justify-center text-foreground-400 hover:text-foreground-900 disabled:opacity-30 cursor-pointer"
                      aria-label="下移"
                    >
                      <i className="ri-arrow-down-s-line text-xs"></i>
                    </button>
                  </li>
                );
              })}
            </ul>
          )}
        </div>
      </div>
    </aside>
  );
}