import { supabase } from '@/lib/supabase';

export interface PermRef {
  name: string;
  code: string | null;
}

export interface RolePermissionChange {
  id: string;
  role_id: string;
  role_name: string | null;
  operator_name: string | null;
  before_count: number;
  after_count: number;
  added: PermRef[];
  removed: PermRef[];
  created_at: string | null;
}

async function resolveOperatorName(): Promise<string> {
  try {
    const { data } = await supabase.auth.getUser();
    const user = data.user;
    if (!user) return '系统';
    const { data: profile } = await supabase
      .from('profiles')
      .select('full_name, email')
      .eq('id', user.id)
      .maybeSingle();
    return (
      (profile?.full_name as string | undefined) ||
      (profile?.email as string | undefined) ||
      user.email ||
      '系统'
    );
  } catch {
    return '系统';
  }
}

/** 记录一次角色权限变更的前后对比(新增/移除了哪些权限点)。失败静默,不阻塞保存。 */
export async function recordRolePermissionChange(params: {
  roleId: string;
  roleName: string;
  beforeCount: number;
  afterCount: number;
  added: PermRef[];
  removed: PermRef[];
}): Promise<void> {
  try {
    const operatorName = await resolveOperatorName();
    const { error } = await supabase.from('role_permission_changes').insert({
      role_id: params.roleId,
      role_name: params.roleName,
      operator_name: operatorName,
      before_count: params.beforeCount,
      after_count: params.afterCount,
      added: params.added,
      removed: params.removed,
    });
    if (error) throw error;
  } catch (err) {
    console.error('recordRolePermissionChange failed', err);
  }
}

/** 读取某个角色的权限变更历史(最近的在前)。 */
export async function fetchRolePermissionChanges(
  roleId: string,
  limit = 30,
): Promise<RolePermissionChange[]> {
  const { data, error } = await supabase
    .from('role_permission_changes')
    .select('*')
    .eq('role_id', roleId)
    .order('created_at', { ascending: false })
    .limit(limit);
  if (error) throw error;
  return ((data as RolePermissionChange[]) ?? []).map((row) => ({
    ...row,
    added: (row.added as PermRef[]) ?? [],
    removed: (row.removed as PermRef[]) ?? [],
  }));
}