import { useCallback, useEffect, useMemo, useState } from 'react';
import { supabase } from '@/lib/supabase';
import EndpointList from '@/pages/api-docs/components/EndpointList';
import EndpointDetail from '@/pages/api-docs/components/EndpointDetail';
import OpenApiModal from '@/pages/api-docs/components/OpenApiModal';
import DebugCasesDrawer from '@/pages/api-docs/components/DebugCasesDrawer';
import {
  buildOpenApi,
  deriveEndpoint,
  methodStyle,
  type EndpointDef,
  type PermissionRow,
} from '@/pages/api-docs/types';

export default function ApiDocsPage() {
  const [endpoints, setEndpoints] = useState<EndpointDef[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [keyword, setKeyword] = useState('');
  const [methodFilter, setMethodFilter] = useState('全部');
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [openApiOpen, setOpenApiOpen] = useState(false);
  const [drawerOpen, setDrawerOpen] = useState(false);

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const { data, error: err } = await supabase
        .from('permissions')
        .select('id, name, code, type')
        .eq('type', 'api')
        .order('sort_order', { ascending: true });
      if (err) throw err;
      const derived = ((data as PermissionRow[]) ?? [])
        .map(deriveEndpoint)
        .filter((v): v is EndpointDef => Boolean(v));
      setEndpoints(derived);
      setSelectedId((prev) => prev ?? derived[0]?.id ?? null);
    } catch (err) {
      console.error(err);
      setError('加载接口资源失败,请重试');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  const filtered = useMemo(() => {
    const kw = keyword.trim().toLowerCase();
    return endpoints.filter((ep) => {
      const matchKw = !kw || ep.path.toLowerCase().includes(kw) || ep.summary.toLowerCase().includes(kw);
      const matchMethod = methodFilter === '全部' || ep.method === methodFilter;
      return matchKw && matchMethod;
    });
  }, [endpoints, keyword, methodFilter]);

  const selected = useMemo(
    () => filtered.find((ep) => ep.id === selectedId) ?? filtered[0] ?? null,
    [filtered, selectedId],
  );

  const stats = useMemo(() => {
    const modules = new Set(endpoints.map((ep) => ep.moduleLabel)).size;
    const byMethod = endpoints.reduce<Record<string, number>>((acc, ep) => {
      acc[ep.method] = (acc[ep.method] ?? 0) + 1;
      return acc;
    }, {});
    return { total: endpoints.length, modules, byMethod };
  }, [endpoints]);

  const spec = useMemo(() => buildOpenApi(endpoints), [endpoints]);

  return (
    <div className="space-y-4">
      <div className="flex flex-col md:flex-row md:items-center gap-3">
        <div>
          <h2 className="text-lg font-semibold text-foreground-950">RESTful API 文档</h2>
          <p className="text-sm text-foreground-500 mt-0.5">
            从权限资源点自动生成接口清单、请求/响应示例与 OpenAPI 规范,支持一键导出
          </p>
        </div>
        <div className="md:ml-auto flex flex-wrap items-center gap-2">
          <button
            type="button"
            onClick={() => setDrawerOpen(true)}
            className="h-9 px-3.5 rounded-md bg-background-100 border border-background-300 text-sm text-foreground-800 hover:bg-background-200 cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5"
          >
            <i className="ri-bookmark-3-line"></i>
            调试用例
          </button>
          <button
            type="button"
            onClick={() => setOpenApiOpen(true)}
            disabled={endpoints.length === 0}
            className="h-9 px-3.5 rounded-md bg-primary-500 text-background-50 text-sm hover:bg-primary-600 disabled:opacity-50 cursor-pointer whitespace-nowrap inline-flex items-center gap-1.5 dark:text-foreground-950"
          >
            <i className="ri-file-code-line"></i>
            预览 / 导出 OpenAPI
          </button>
        </div>
      </div>

      {error ? (
        <div className="flex items-center justify-between gap-3 rounded-lg bg-accent-100 border border-accent-200 px-4 py-3">
          <span className="text-sm text-accent-900">{error}</span>
          <button
            type="button"
            onClick={load}
            className="h-8 px-3 rounded-md bg-background-50 border border-background-300 text-sm text-foreground-800 hover:bg-background-100 cursor-pointer whitespace-nowrap"
          >
            重试
          </button>
        </div>
      ) : null}

      <section className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-3 md:gap-4">
        <div className="rounded-lg bg-background-50 border border-background-200 p-4">
          <div className="flex items-center gap-2">
            <span className="w-8 h-8 rounded-md flex items-center justify-center bg-primary-100 text-primary-700">
              <i className="ri-route-line text-sm"></i>
            </span>
            <span className="text-xs text-foreground-500">接口总数</span>
          </div>
          <p className="mt-2.5 text-2xl font-semibold text-foreground-950 font-label">{stats.total}</p>
        </div>
        <div className="rounded-lg bg-background-50 border border-background-200 p-4">
          <div className="flex items-center gap-2">
            <span className="w-8 h-8 rounded-md flex items-center justify-center bg-accent-100 text-accent-800">
              <i className="ri-folders-line text-sm"></i>
            </span>
            <span className="text-xs text-foreground-500">覆盖模块</span>
          </div>
          <p className="mt-2.5 text-2xl font-semibold text-foreground-950 font-label">{stats.modules}</p>
        </div>
        <div className="rounded-lg bg-background-50 border border-background-200 p-4 sm:col-span-2">
          <span className="text-xs text-foreground-500">请求方法分布</span>
          <div className="mt-3 flex flex-wrap items-center gap-2">
            {Object.keys(stats.byMethod).length === 0 ? (
              <span className="text-xs text-foreground-400">—</span>
            ) : (
              Object.entries(stats.byMethod).map(([m, count]) => (
                <span
                  key={m}
                  className={`inline-flex items-center gap-1.5 text-[11px] font-label px-2 py-1 rounded ${methodStyle[m]}`}
                >
                  {m}
                  <span className="font-semibold">{count}</span>
                </span>
              ))
            )}
          </div>
        </div>
      </section>

      {loading ? (
        <div className="grid grid-cols-1 lg:grid-cols-[340px_1fr] gap-4">
          <div className="h-[420px] rounded-lg bg-background-50 border border-background-200 animate-pulse-soft" />
          <div className="h-[420px] rounded-lg bg-background-50 border border-background-200 animate-pulse-soft" />
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-[340px_1fr] gap-4 items-start">
          <EndpointList
            endpoints={filtered}
            selectedId={selected?.id ?? null}
            onSelect={setSelectedId}
            keyword={keyword}
            onKeyword={setKeyword}
            methodFilter={methodFilter}
            onMethodFilter={setMethodFilter}
          />
          <EndpointDetail endpoint={selected} />
        </div>
      )}

      <OpenApiModal open={openApiOpen} spec={spec} onClose={() => setOpenApiOpen(false)} />
      <DebugCasesDrawer
        open={drawerOpen}
        endpoints={endpoints}
        onClose={() => setDrawerOpen(false)}
        onOpenEndpoint={(code) => {
          const ep = endpoints.find((e) => e.code === code);
          if (ep) setSelectedId(ep.id);
          setDrawerOpen(false);
        }}
      />
    </div>
  );
}