import { useEffect, useState } from 'react';
import { supabase } from '@/lib/supabase';
import { useAuth } from '@/contexts/AuthContext';
import { collectDescendantIds, fetchDepartments } from '@/lib/departments';

export type DataScope = 'all' | 'dept_and_sub' | 'dept' | 'self';

export const DATA_SCOPE_OPTIONS: { value: DataScope; label: string; desc: string }[] = [
  { value: 'all', label: '全部数据', desc: '可查看系统内所有数据' },
  { value: 'dept_and_sub', label: '本部门及以下', desc: '可查看本部门及其全部下级部门的数据' },
  { value: 'dept', label: '仅本部门', desc: '仅可查看本部门的数据' },
  { value: 'self', label: '仅本人', desc: '仅可查看本人名下的数据' },
];

export const dataScopeLabel: Record<string, string> = {
  all: '全部数据',
  dept_and_sub: '本部门及以下',
  dept: '仅本部门',
  self: '仅本人',
};

const ORDER: DataScope[] = ['all', 'dept_and_sub', 'dept', 'self'];

/**
 * Resolve the current user's effective data scope (broadest among their roles)
 * plus the department ids they are allowed to see.
 *
 * - all            → no department filter
 * - dept_and_sub   → the user's department + every descendant department
 * - dept           → only the user's own department
 * - self           → only rows owned by the user
 */
export function useDataScope() {
  const { user, roleCodes } = useAuth();
  const [scope, setScope] = useState<DataScope>('all');
  const [department, setDepartment] = useState<string | null>(null);
  const [departmentId, setDepartmentId] = useState<string | null>(null);
  const [departmentIds, setDepartmentIds] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let active = true;
    const run = async () => {
      if (!user) {
        if (active) {
          setScope('all');
          setDepartment(null);
          setDepartmentId(null);
          setDepartmentIds([]);
          setLoading(false);
        }
        return;
      }
      setLoading(true);
      try {
        const [profRes, urRes] = await Promise.all([
          supabase
            .from('profiles')
            .select('department, department_id')
            .eq('id', user.id)
            .maybeSingle(),
          supabase.from('user_roles').select('role_id').eq('user_id', user.id),
        ]);

        const roleIds = ((urRes.data as { role_id: string }[]) ?? []).map((r) => r.role_id);
        let scopes: string[] = [];
        if (roleIds.length > 0) {
          const { data: rolesData } = await supabase
            .from('roles')
            .select('data_scope')
            .in('id', roleIds);
          scopes = ((rolesData as { data_scope: string | null }[]) ?? []).map(
            (r) => r.data_scope ?? 'all',
          );
        }
        const broadest = ORDER.find((s) => scopes.includes(s)) ?? (scopes.length ? 'self' : 'all');
        const effective: DataScope = roleCodes.includes('super_admin') ? 'all' : broadest;

        const myDeptId = (profRes.data?.department_id as string | null) ?? null;
        const myDeptName = (profRes.data?.department as string | null) ?? null;

        let deptIds: string[] = [];
        if ((effective === 'dept' || effective === 'dept_and_sub') && myDeptId) {
          if (effective === 'dept') {
            deptIds = [myDeptId];
          } else {
            const all = await fetchDepartments();
            deptIds = collectDescendantIds(all, myDeptId);
          }
        }

        if (active) {
          setScope(effective);
          setDepartment(myDeptName);
          setDepartmentId(myDeptId);
          setDepartmentIds(deptIds);
        }
      } catch (err) {
        console.error('useDataScope failed', err);
        if (active) setScope('all');
      } finally {
        if (active) setLoading(false);
      }
    };
    run();
    return () => {
      active = false;
    };
  }, [user, roleCodes]);

  return {
    scope,
    department,
    departmentId,
    departmentIds,
    userId: user?.id ?? null,
    loading,
  };
}