import { supabase } from '@/lib/supabase';
import type { EndpointDef } from '@/pages/api-docs/types';

interface TableConfig {
  table: string;
  searchCol?: string;
}

/**
 * Maps the documented REST resource to the real backend table so the
 * "Try it out" panel can issue genuine requests and show genuine responses.
 */
const resourceTables: Record<string, TableConfig> = {
  users: { table: 'profiles', searchCol: 'full_name' },
  roles: { table: 'roles', searchCol: 'name' },
  permissions: { table: 'permissions', searchCol: 'name' },
  tenants: { table: 'tenants', searchCol: 'name' },
  plugins: { table: 'plugins', searchCol: 'name' },
  logs: { table: 'audit_logs', searchCol: 'action' },
  metrics: { table: 'metrics', searchCol: 'name' },
  orders: { table: 'order_headers', searchCol: 'status' },
};

export interface TryRequestInfo {
  method: string;
  url: string;
  headers: Record<string, string>;
  body: unknown | null;
}

export interface TryResult {
  ok: boolean;
  status: number;
  statusText: string;
  timeMs: number;
  request: TryRequestInfo;
  data: unknown;
  note?: string;
}

export interface TryInputs {
  pathParams: Record<string, string>;
  queryParams: Record<string, string>;
  body: string;
}

function parseBody(raw: string): { value: Record<string, unknown> | null; error: string | null } {
  if (!raw.trim()) return { value: null, error: null };
  try {
    const parsed = JSON.parse(raw);
    if (parsed && typeof parsed === 'object') return { value: parsed as Record<string, unknown>, error: null };
    return { value: null, error: '请求体必须是一个 JSON 对象' };
  } catch {
    return { value: null, error: '请求体不是合法的 JSON' };
  }
}

export async function runEndpoint(endpoint: EndpointDef, inputs: TryInputs): Promise<TryResult> {
  const started = performance.now();
  const queryPairs = Object.entries(inputs.queryParams).filter(([, v]) => v !== '' && v !== undefined);
  const queryStr = queryPairs.length
    ? `?${queryPairs.map(([k, v]) => `${k}=${encodeURIComponent(v)}`).join('&')}`
    : '';

  const url = `https://api.readdy.io${endpoint.path}${queryStr}`;

  const { data: sessionData } = await supabase.auth.getSession();
  const token = sessionData.session?.access_token ?? '';
  const headers: Record<string, string> = { 'Content-Type': 'application/json' };
  if (endpoint.auth) headers.Authorization = `Bearer ${token || '<未登录>'}`;

  const finish = (status: number, statusText: string, data: unknown, note?: string): TryResult => ({
    ok: status >= 200 && status < 300,
    status,
    statusText,
    timeMs: Math.round(performance.now() - started),
    request: { method: endpoint.method, url, headers, body: null },
    data,
    note,
  });

  try {
    // Auth endpoints operate on the live session rather than a table.
    if (endpoint.resource === 'auth') {
      if (endpoint.action === 'login') {
        if (!sessionData.session) {
          return finish(401, 'Unauthorized', {
            code: 'Unauthorized',
            data: null,
            meta: { message: '当前没有可用会话,请先在管理后台登录' },
          });
        }
        const session = sessionData.session;
        return finish(200, 'OK', {
          code: 'OK',
          data: {
            access_token: `${token.slice(0, 24)}…${token.slice(-6)}`,
            token_type: 'Bearer',
            expires_in: session.expires_in ?? 3600,
            user: {
              id: session.user.id,
              email: session.user.email,
              role: 'authenticated',
            },
          },
          meta: { message: '' },
        }, '返回的是当前真实登录会话的令牌信息(已脱敏)。');
      }
      return finish(200, 'OK', {
        code: 'OK',
        data: null,
        meta: { message: '登出为真实会话动作,请在右上角菜单执行,以免调试时中断当前登录。' },
      });
    }

    const config = resourceTables[endpoint.resource];
    if (!config) {
      return finish(501, 'Not Implemented', {
        code: 'NotImplemented',
        data: null,
        meta: { message: `资源 ${endpoint.resource} 暂未接入真实数据表,仅提供文档示例` },
      });
    }

    const { value: body, error: bodyError } = parseBody(inputs.body);
    if (bodyError) {
      return finish(400, 'Bad Request', {
        code: 'InvalidParameter',
        data: null,
        meta: { message: bodyError },
      });
    }

    const id = inputs.pathParams.id ?? '';

    switch (endpoint.action) {
      case 'list': {
        const page = Math.max(1, Number(inputs.queryParams.page) || 1);
        const pageSize = Math.min(100, Math.max(1, Number(inputs.queryParams.page_size) || 20));
        const keyword = (inputs.queryParams.keyword ?? '').trim();

        let query = supabase.from(config.table).select('*', { count: 'exact' });
        if (keyword && config.searchCol) query = query.ilike(config.searchCol, `%${keyword}%`);
        query = query.order('created_at', { ascending: false }).range((page - 1) * pageSize, page * pageSize - 1);

        const { data, error, count } = await query;
        if (error) throw error;
        const rows = data ?? [];
        return finish(200, 'OK', {
          code: 'OK',
          data: rows,
          meta: { page, page_size: pageSize, total: count ?? rows.length, message: '' },
        }, `真实查询 ${config.table} 表,本页返回 ${rows.length} 行,共 ${count ?? rows.length} 行。`);
      }
      case 'detail': {
        if (!id) {
          return finish(400, 'Bad Request', { code: 'InvalidParameter', data: null, meta: { message: '缺少路径参数 id' } });
        }
        const { data, error } = await supabase.from(config.table).select('*').eq('id', id).maybeSingle();
        if (error) throw error;
        if (!data) return finish(404, 'Not Found', { code: 'NotFound', data: null, meta: { message: `未找到 id=${id} 的记录` } });
        return finish(200, 'OK', { code: 'OK', data, meta: { message: '' } });
      }
      case 'create': {
        if (!body) {
          return finish(400, 'Bad Request', { code: 'InvalidParameter', data: null, meta: { message: '缺少请求体' } });
        }
        const { data, error } = await supabase.from(config.table).insert(body).select().maybeSingle();
        if (error) throw error;
        return finish(201, 'Created', { code: 'OK', data, meta: { message: '创建成功' } });
      }
      case 'update': {
        if (!id) {
          return finish(400, 'Bad Request', { code: 'InvalidParameter', data: null, meta: { message: '缺少路径参数 id' } });
        }
        if (!body) {
          return finish(400, 'Bad Request', { code: 'InvalidParameter', data: null, meta: { message: '缺少请求体' } });
        }
        const { data, error } = await supabase.from(config.table).update(body).eq('id', id).select().maybeSingle();
        if (error) throw error;
        return finish(200, 'OK', { code: 'OK', data, meta: { message: '更新成功' } });
      }
      case 'delete': {
        if (!id) {
          return finish(400, 'Bad Request', { code: 'InvalidParameter', data: null, meta: { message: '缺少路径参数 id' } });
        }
        const { error } = await supabase.from(config.table).delete().eq('id', id);
        if (error) throw error;
        return finish(200, 'OK', { code: 'OK', data: null, meta: { message: '删除成功' } });
      }
      case 'enable':
      case 'disable': {
        if (!id) {
          return finish(400, 'Bad Request', { code: 'InvalidParameter', data: null, meta: { message: '缺少路径参数 id' } });
        }
        if (config.table !== 'plugins') {
          return finish(200, 'OK', {
            code: 'OK',
            data: null,
            meta: { message: `${endpoint.moduleLabel} 不支持启用/停用调试` },
          });
        }
        const { data, error } = await supabase
          .from(config.table)
          .update({ enabled: endpoint.action === 'enable' })
          .eq('id', id)
          .select()
          .maybeSingle();
        if (error) throw error;
        return finish(200, 'OK', { code: 'OK', data, meta: { message: '' } });
      }
      case 'export': {
        const { data, error } = await supabase.from(config.table).select('*').limit(50);
        if (error) throw error;
        const rows = data ?? [];
        return finish(200, 'OK', {
          code: 'OK',
          data: { rows, row_count: rows.length, format: inputs.queryParams.format || 'csv' },
          meta: { message: '调试模式下直接返回前 50 行数据,生产环境会转为文件下载链接。' },
        });
      }
      default:
        return finish(501, 'Not Implemented', {
          code: 'NotImplemented',
          data: null,
          meta: { message: `动作 ${endpoint.action} 暂未接入真实调试` },
        });
    }
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    return finish(400, 'Request Failed', {
      code: 'RequestFailed',
      data: null,
      meta: { message, detail: message },
    }, '请求未通过(常见原因:行级安全策略限制了写入,或字段与表结构不匹配)。');
  }
}